-- Records of document_segments
-- ----------------------------
INSERT INTO `document_segments` VALUES ('1955803400209526785', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '员工手册范本 员工手册范本（精选33篇） 员工手册范本 篇1 　　第一章 工作时间 　　第一条 总则 　　公司依据设置工作岗位的要求，实行《中华人民共和国劳动法》、《中华人民共和国劳动合同法》之标准工时工作制、不定时工作制、综合计算工时工作制来设定各岗位的上班时间。 　　其次条 上班时间 　　公司员工根本工作时间：周一至周五为8小时/天，超过局部按加班计。上班卡在规定的时间前15分钟内打卡有效，下班卡在下班时间后的15分钟内打卡有效。部门加班时间，依据各部门工作状况由各负责人详细而确定，公司不做统一安排。 　　第三条 休息及加班待遇 　　1、每周至少保证一个休息日，一般状况下安排在星期日，详细依据生产实际状况确定。 　　2、员工加班完全遵循自愿原则，且必需事先申报获得批准，否则不计算加班待遇。 　　3、员工的加班待遇依下述方法处理： 　　1)员工正常工作日，加班时薪按根本工资的百分之一百五十计算。 　　2)因工作需要公休假日加班，可在30天内安排补休(或者支付根本工资的百分之两百加班费)，详细补休或支付加班费由部门主管/经理与有关人员商讨确定。并通知员工及书面联络行政部作相应的考勤记录(填写调休单)。', 508, NULL, '[\"加班\", \"员工\", \"工作\", \"时间\", \"计算\", \"公司\", \"确定\", \"根本\", \"状况\", \"详细\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:22', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:22', '0');
INSERT INTO `document_segments` VALUES ('1955803400272441345', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　3)公司安排员工在法定节假日加班，支付法定节假日加班工资，按根本工资的百分之三百计算。 　　其次章 考勤制度 　　第一条 主题内容及适用范围 　　1、考勤是本公司治理工作的根底，是计发工资奖金、劳保福利等待遇的主要依据，为了确保出勤的精确统计，维持公司正常的工作秩序，各级人员都必需予以高度重视。 　　2、本制度适用于公司各部门。 　　其次条 考勤方式及对象 　　1、公司均使用IC卡进展打卡考勤。 　　2、公司体职(员)工为考勤对象。 　　3、市场业务人员在公司上班应照常打卡，出差的人员凭《上班人员外出单》记录考勤。 　　第三条 工作时间 　　开料车间、生产一车间上班时间为：上午8：00—11：40，下午13：10—17：20，晚上18：20开头加班;生产二车间、生产三车间及其它全部部门上班时间：上午8：00—12：00，下午13：30—17：30，晚上18：30开头加班;外贸业务人员上班时间：上午8：30—12：00，下午13：30—18：00。公司的某些特别岗位可依据工作岗位性质调整上班时间和休息时间，必需报行政部审批并备案。 　　第四条 打卡治理', 484, NULL, '[\"公司\", \"考勤\", \"工作\", \"上班时间\", \"卡\", \"加班\", \"工资\", \"人员\", \"必需\", \"业务人员\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:22', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:22', '0');
INSERT INTO `document_segments` VALUES ('1955803400360521730', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　第四条 打卡治理 　　1、代人或授人打卡者，一经发觉即予以记大过处分，再次发觉即予以开除。 　　2、行政部负责考勤制度的执行与考勤的`治理工作，考勤结果直接与工资挂勾。 　　3、不得擅自更改考勤记录，违者记小过一次。 　　4、员工在打卡时，应自觉遵守秩序排队打卡。 　　5、因卡机消失故障而不能正常打卡，由人事部门登记上下班时间。 　　6、因公出差若估计会影响正常打卡者，须填写《签卡申请表》，经规定的审批人审批后，由本部门文员于每周六下午交至行政部，作为考勤的依据。如因特急事而无法预先填单者，可事先电话知会人事部门，待出差返回后准时补卡。补卡时间为每周六下午。 　　7、因公外出当天不能来回的为出差。出差人员须提前填写《因公出差申请表》，经部门经理初核，主管副总/总监审核，行政部批准;并交行政部备案，否则作缺勤处理。 　　第五条 请假流程 　　1、员工请假必需填写《请假申请单》，并在批准后交行政部备案，未在行政部备案的请假无效，强行请假作旷工处理。 　　2、请假三天(含)以下由部门主管初核，行政部批准;请假三天以上由部门主管初核，部门经理复核，总经办批准。并交行政部备案。', 493, NULL, '[\"卡\", \"行政\", \"出差\", \"请假\", \"因公\", \"交\", \"考勤\", \"填写\", \"批准\", \"部门\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:22', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:22', '0');
INSERT INTO `document_segments` VALUES ('1955803400410853378', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　3、员工请产假必需提前三十天向行政部申请，并附医院或当地政府相关证明。 　　4、凡请假员工，假期未满上班或超假必需到行政部办理销假或续假手续。未办理销假手续者假期内上班不计工资，超假但未办理续假手续者以旷工论。 　　5、职员请假与其年终奖直接挂勾，根据肯定比例进展扣除。 　　第六条 缺勤处理 　　1、迟到、早退者，迟到、早退5--20分钟内记警告一次，月度累计迟到、早退3次(含3次)以上扣除当月全勤奖，每个月考勤有迟到、早退记录，将不能获得年度的晋职、晋级资格。 　　2、当月遗忘打卡超过二次(含)以上，没有合理理由的;迟到或早退30分钟(含)以上的;没有事先请假或请假未经批准擅离工作岗位的，以旷工论。 　　3、无故不上班或有意不打卡者作旷工处理，当日旷工0.5-2小时以内的计半天旷工，2-4小时以内的计全天旷工。旷工扣当天工资总数并进展相关的行政惩罚，旷工一天扣除三天薪资，依此类推。连续旷工三天或全年累计旷工达七天者作自动离职处理，将予以解除劳动合同，不计发当月工资，不做任何经济补偿。 　　第七条 加班治理 　　1、公司提倡高效运作，员工的本职工作应于正常上班时间内完成，不得有意拖延。', 502, NULL, '[\"旷工\", \"请假\", \"早退\", \"迟到\", \"行政\", \"当月\", \"员工\", \"扣除\", \"工资\", \"处理\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:22', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:22', '0');
INSERT INTO `document_segments` VALUES ('1955803400461185026', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　第七条 加班治理 　　1、公司提倡高效运作，员工的本职工作应于正常上班时间内完成，不得有意拖延。 　　2、实际加班时间应与考勤纪录相符，加班工资计算以考勤纪录为准。如有加班考勤纪录而实际并未加班的，视情节轻重对相关责任人进展大过惩罚。 　　3、员工加班需提前半天提出申请，具体填写《加班申请单》，经部门经理审核，主管(副)总经理/总监批准后交行政部备案，未经批准而擅自加班的，公司不予计算加班费。如加班时间与所填报时间不符的，部门主管需在次日上午补填《加班申请单》，经相关负责人审批后交行政部备案。 　　4、如确因工作需要，符合以下条件并经过相关领导审批的，可计为加班： 　　1)在休息日或法定节假日内，公司由于生产、业务等缘由要求员工加班的。 　　2)必需利用休息日、法定节假日进展物资盘点、对帐或不影响日常工作而在休息日、法定节假日召开会议的。 　　3)由于发生严峻自然灾难或其他灾难，为避开公司财物患病损失而进展抢救的。 　　4)突发性、不属于正常工作范围内的工作而必需通过延时工作或利用休息日、法定节假日完成工作的。 　　5、以下状况不属于加班：', 479, NULL, '[\"加班\", \"公司\", \"工作\", \"员工\", \"节假日\", \"进展\", \"休息日\", \"相关\", \"时间\", \"需\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:22', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:22', '0');
INSERT INTO `document_segments` VALUES ('1955803400515710977', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　5、以下状况不属于加班： 　　1)凡属正常工作范围之内，但因个人工作效率必需在正常工作时间之外连续上班的。 　　2)因工作需要出席社交场合的。 　　3)因公差旅期间。 　　4)加班时的就餐时间。 　　5)业务销售人员的业务时间。 员工手册范本 篇2 　　一、形象意识 　　员工必须具备强烈的形象意识，从基本做起，塑造良好形象。 　　二、员工仪容、仪表、着装要求 　　员工衣着应当符合金融机构形象及部门形象。原则上，员工穿着及修饰应稳重大方、整齐清爽、干净利落，周一至周日工作时间一律统一穿着公司制服。以下条款供参考： 　　(一)员工衣着要求得体、协调、整洁、悦目； 　　(二)上衣、裤子等最好相配，衣服平整，符合时节； 　　(三)西装左胸前口袋不放手帕以外的任何东西，禁止两手下垂插入下口袋中； 　　(四)男士长袖衬衫要塞在裤腰内，袖子最好不卷起，长裤有腰攀，应穿上腰带或背带，头型为短平头； 　　(五)女士宜化淡妆，勿戴过多头饰，裙装应配过膝长袜，领口过低过短的\'衣服不宜穿着。 　　三、社交、谈吐', 452, NULL, '[\"员工\", \"时间\", \"应\", \"工作\", \"形象\", \"衣服\", \"口袋\", \"短\", \"穿着\", \"加班\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:22', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:22', '0');
INSERT INTO `document_segments` VALUES ('1955803400570236930', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　三、社交、谈吐 　　(一)在与他人交谈中，请讲普通话，交谈中善于倾听，不随便打断他人谈话，不鲁莽提问，不问及他人隐私，不要言语纠缠不休或语带讽刺，更勿出言不逊，恶语伤人； 　　(二)与客户交谈诚恳、热情、不卑不亢，语言流利、准确，业务之外，注意话题健康、客观；采用迎送礼节，主动端茶送水。 　　(三)与同行交谈，注意措辞分明，谦虚谨慎，维护公司形象，不互相倾轧，客观正派，不泄露商业机密。 　　四、举止、行为 　　(一)遵守考勤制度，准时上下班，不迟到、不早退；病事假需及时申请或通知部门主管，填报请假单； 　　(二)上班时间不吸烟，保持良好的精神状态，精力充，精神饱满，乐观进； 　　(三)对待上司要尊重，对待同事要热情，处理工作要保持头脑冷静，提倡微笑服务； 　　(四)开诚布公，坦诚相待，平等尊重，团结协作，不将个人喜好带进工作中，不拉帮结派，党同伐异； 　　(五)热情接待每一位来宾，不以貌取人，不盛气凌人，与客人约见要准时，如另有客人来访需等待时，应主动端茶道歉； 　　(六)保持良好坐姿、行姿，切勿高声呼叫他人； 　　(七)出入会议室或上司办公司室，主动敲门示意，进入房间随手关门。 　　员工日常活动行为准则', 512, NULL, '[\"交谈\", \"主动\", \"中\", \"需\", \"勿\", \"工作\", \"公司\", \"保持良好\", \"尊重\", \"客观\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:22', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:22', '0');
INSERT INTO `document_segments` VALUES ('1955803400616374274', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　(七)出入会议室或上司办公司室，主动敲门示意，进入房间随手关门。 　　员工日常活动行为准则 　　员工上班时间要始终以饱满的热情，尽心尽责，真诚协作，高效、快捷地向顾客提供最佳服务。员工应具备优良的道德品质，有错必改，不得文过饰非、阳奉阴违、诬陷他人。 　　一、电话 　　(一)员工电话行为应符合规范，注意控制语气、语态、语调，语言亲切、简练、有礼、客气； 　　(二)及时接听，勿让铃声超过3声，迟接电话须表示歉意； 　　(三)使用代表企业的规范用语问好，例如“您好，信用社\"、“您好，xx办公室\"等； 　　(四)仔细、耐心倾听对方讲话，决不要打断对方解释； 　　(五)准确记录，转告电话内容，主动帮助解决顾客要求，及时转告并敦促同事回复电话； 　　(六)谈话结束，表示谢意，等对方先挂电话； 　　(七)工作时间与业务无关电话应简短扼要，工作期间禁止接听电话，如有急事，由管理人员转告。 　　二、工作证、胸牌 　　(一)由单位发给工作证或者胸牌，员工要随时携带工作证。员工在工作时，必须佩戴胸牌； 　　(二)工作证、胸牌如有遗失、被窃，应立即向部门报告，经部门领导签字，可到办公室补领，如因长久磨损，应及时以旧换新。', 509, NULL, '[\"员工\", \"电话\", \"应\", \"转告\", \"及时\", \"工作\", \"主动\", \"办公室\", \"胸\", \"工作证\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:22', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:22', '0');
INSERT INTO `document_segments` VALUES ('1955803400679288833', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '员工手册范本 篇3 　　1.制定目的 　　标准本公司员工离职作业流程，确保离职交接工作顺畅进展。 　　2.适用范围 　　公司三职等(含)以下员工的离职作业。 　　3.治理部门 　　人力资源部为本制度的.治理部门。 　　4.内容 　　4.1离职类型及申请要求 　　4.1.1辞职：自动请辞离职 　　(1) 三职等(含)以上须提前一个月申请 　　(2) 一、二职等须提前10天申请 　　4.1.2辞退：辞退离职 　　因故被辞退者，公司应事先通知员工，由其直属主管或部门经理提出申请。 　　4.2离职程序 　　4.2.1员工辞职，由本人向人力资源部索取《员工离职申请单》，并按《员工离职申请单》上所列事项具体填妥后，亲自持单向单上所列各部门办理手续。 　　4.2.2若属辞退情形，则由其直属主管或部门经理向人力资源部索取《员工离职申请单》，并在《员工离职申请单》上“离职缘由”栏内“公司因素”的“其它”项中注明缘由，其余交由员工本人持单向单上所列各部门办理手续。 　　4.2.3离职流程：离职申请→直接主管、上级主管签批→本部门手续办理→人力资源部手续办理→财务部手续办理→(副)总经理签核→离厂 　　4.4离职移交 员工手册范本 篇4 　　员工手册', 522, NULL, '[\"离职\", \"员工\", \"公司\", \"申请\", \"部门\", \"主管\", \"人力资源部\", \"辞退\", \"列\", \"职\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:22', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:22', '0');
INSERT INTO `document_segments` VALUES ('1955803400738009090', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　4.4离职移交 员工手册范本 篇4 　　员工手册 　　20xx年5月第一版 　　20xx年3月第一次修订 　　20xx年3月第二次修订 　　20xx年3月第三次修订 　　20xx年6月第四次修订 　　20xx年4月第五次修订 　　20xx年12月第六次修订 　　20xx年2月第七次修订 《公司图书管理制度》、《工装管理制度》、《公司激励制度》、《员工薪酬制定标准》、《20xx年年度目标设定与业绩考评表》 　　目录 　　第一章 欢迎词 　　第二章 企业文化 　　第三章 作为企业的一份子 　　第四章 规章制度总则 　　第五章 行为准则规范 　　第一节 办公环境 　　第二节 工作纪律 　　第三节 电话管理制度 　　第四节 传真机、打印机、书籍、办公用品管理 　　第五节 印签、证件管理 　　第六节 电脑管理制度 　　第七节 着装管理制度 　　第八节 保密制度 　　第九节 公司图书管理制度 　　第十节 工装管理制度 　　第六章 文件管理制度 　　第一节 公文、合同、客户档案管理 　　第二节 公司外发资料管理办法 　　第三节 电脑中文件的管理制度 　　第四节 文件的格式说明 　　第五节 电子邮件管理制度 　　第七章 人事制度 　　第一节 总则 　　第二节 招聘与录用 　　第三节 试用期管理办法 　　第四节', 557, NULL, '[\"节\", \"管理制度\", \"管理\", \"公司\", \"三节\", \"xx\", \"员工\", \"总则\", \"制度\", \"文件\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:22', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:22', '0');
INSERT INTO `document_segments` VALUES ('1955803400809312257', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　第七章 人事制度 　　第一节 总则 　　第二节 招聘与录用 　　第三节 试用期管理办法 　　第四节 员工的内部职位变动 　　第五节 人事档案管理办法 　　第六节 员工的解聘、辞退和辞职管理办法 　　第七节 考勤管理办法 　　第八章 财务制度 　　第一节 付款请求 　　第二节 工资、奖金与提成 　　第三节 费用报销 　　第九章 公司激励制度 　　第一节 奖励办法 　　第二节 绩效考核规定 　　附1：《新员工入职培训计划》 　　附2：《员工离职手续清单》 　　附3：《企业组织架构&岗位职责》 　　附4：《员工薪酬制定标准》 　　附5：《20xx年年度目标设定与业绩考评表》 　　第一章 欢迎词 　　亲爱的同事： 　　热情并真诚得欢迎您加入北京XX有限公司! 　　本手册旨在帮助您尽快熟悉和了解公司的情况，以便顺利地开展工作。它将让您更加方便和完整得了解到公司的各项规章制度。 　　本手册作为指南，如果您在阅读完后，对其中的内容有任何疑问，请您与您的经理或人事部联系，并且公司中的所有同事都会很高兴为您服务。', 456, NULL, '[\"节\", \"公司\", \"员工\", \"附\", \"办法\", \"管理\", \"同事\", \"本手册\", \"了解\", \"三节\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:22', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:22', '0');
INSERT INTO `document_segments` VALUES ('1955803400876421121', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　公司员工手册是公司将各项规章规范化、明朗化、制度化的文件，目的是使公司业务蒸蒸日上，员工有合理、健康的工作环境，发展与发挥个人的所长或潜能。同时，公司将依照环境需要、业务的发展方向以及员工的反馈，对该手册作出适度调整，并通知所有员工。 　　您加入公司，是对我们工作的一种肯定。由于您的加入，我们有更大的信心去面临未来的各种挑战。希望您以此为家，让我们同呼吸、共命运、共同努力来创造公司美好的明天! 　　总经理： 　　第二章 企业文化 　　【LOGO释义】 　　¨ 标志设计 　　¨ 标志主体形象像是一座俯瞰的城市 　　¨ 灰色环城处上下左右 　　----------------------------------------------------------------------------------------------------------------------【核心价值观】 　　忠于自我 关注本质 追求完美 创造卓越 　　【企业愿景】 　　做医院品牌生命力的缔造者、维护者和传承者 　　【企业使命】 　　提供专业高端服务 成就医院卓越品牌 　　【企业经营管理理念】 　　业精于专，功于勤 　　【企业服务理念】 　　诚信为本 品质保障', 530, NULL, '[\"企业\", \"公司\", \"员工\", \"服务\", \"创造\", \"卓越\", \"品牌\", \"发展\", \"医院\", \"工作\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:22', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:22', '0');
INSERT INTO `document_segments` VALUES ('1955803400930947073', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '成就医院卓越品牌 　　【企业经营管理理念】 　　业精于专，功于勤 　　【企业服务理念】 　　诚信为本 品质保障 专心专注 科学规范 　　【企业人才观】 　　创造发展平台 尽情施展才华 　　第三章 作为企业的一份子 　　一. 必须具有健康的生活方式和审美取向。 　　二. 永远不要说谎。我们喜欢为人诚实、对待客户诚实以及对消费者诚实的人。 　　三. 工作辛勤、坦诚、客观、认真和正直的人在企业会受到所有人的喜爱。我们厌恶不思进取、办事耍手腕、阿谀奉承、盛气凌人、胆小怕事和浮夸炫耀的人。 　　四. 有强烈的求知欲和快速的学习能力。喜欢阅读和思考，要博学，要让你的每一个客户都觉得你是专家。坚持读书，要永远走在你周围人的前面，追赶别人和被别人追赶会造就两种不同的气度。 　　五. 工作要有主动性。这和把工作准时做完不是一回事。这种主动性是卓越和平庸的分界线。 　　六. 学会做计划，应该每日主动与你的上司沟通，不要等待他来追你。 　　七. 用你强烈的责任感用心深入细节。在我们所处的行业里，用心做出来的东西，和不用心做出来的东西有着天壤之别。 　　八. 工作是实现自我的一种方式，透过一个人的工作方式和成果，是欣赏和了解这个人最好的办法。 　　九.', 522, NULL, '[\"企业\", \"工作\", \"做\", \"方式\", \"强烈\", \"永远\", \"会\", \"卓越\", \"喜欢\", \"理念\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:23', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:23', '0');
INSERT INTO `document_segments` VALUES ('1955803400981278721', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　八. 工作是实现自我的一种方式，透过一个人的工作方式和成果，是欣赏和了解这个人最好的办法。 　　九. 保持工作环境和电脑中文件的整洁。它能反映出你是否严谨有序、有计划和条理，乱七八糟的办公室会产生一种懒散的气氛，会搞丢或者不能在一手时间找到重要文件。 　　十. 应乐于分享经验与学习成果，带动团队与公司的成长。信息公开化，资源共享。同时，公司资源也是公司财产的一部份，对外保密，任何人不能利用它谋取私利。 　　十一. 组织结构合理，分工合作，责任清晰，最佳排挡才能有最佳作品。 　　十二. 公司资源，尤其是你的时间和精力，不做无谓的耗费。 　　十三. 公司是一个目标一致的整体，全体同仁互相配合、众志成城，不断提升服务与产品的质量;使我们在品质上、价格上、时效上、盈利性上，处于同业领先地位。 　　企业的项目/市场/销售人员 　　一. 在企业，优秀的客户经理首先是优秀的品牌形象管理专家。 　　二. 要善于并敢于表达自己。讲清楚。让客户听懂，而不是自以为清楚就可以。在每一次沟通中，必须为了清晰表达要点而努力提高语言的精确度和无障碍程度。 　　三.', 476, NULL, '[\"公司\", \"表达\", \"中\", \"清晰\", \"成果\", \"时间\", \"资源\", \"工作\", \"企业\", \"会\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:23', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:23', '0');
INSERT INTO `document_segments` VALUES ('1955803401065164802', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　三. 倾听客户的看法。我们通常急于表达自己的看法，急迫希望客户接受，或者认为这是我们的专业而忽略听客户的看法。听客户没有讲出来的话，深入理解客户的意图。 　　四. 赢得客户的尊重很重要。客户需要你的专业，你的判断。如果你没有观点，他将会像对待垃圾一样对待你。尊重一旦丧失，很难重新得回。如果你的同事和上司认为你得到客户的尊重，他们将很乐意帮助你。如果他们认为你对你的客户仅是一个消息传递员，他们对你的工作不会给予支持。 　　五. 少看连续剧，多看新闻和财经节目，培养自己观察和审视问题的能力。 　　六. 要重视学习商务礼仪，着装、握手、微笑、言谈举止，点滴之间流露出来的专业素养会为你赢得客户的尊重。 　　七. 不要以轻视和敌对的态度对待客户。要和客户交朋友，把自己当成是他们当中的一员，切身处地的为客户着想。但并不意味着你要一味的讨好和迁就。 　　八. 不必总想着去揽那种很大很大的客户，因为一旦揽上了这样的客户，你就不得不战战兢兢的过日子了。如果我们被吓得失魂落魄，就失掉了提出坦率意见的勇气。 　　九. 要重视每一个小单子和小客户，不然所谓专业精神将荡然无存，你也就相应失去发展的机遇与品质。 　　十.', 506, NULL, '[\"客户\", \"专业\", \"尊重\", \"会\", \"认为\", \"重视\", \"没有\", \"看法\", \"赢得\", \"相应\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:23', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:23', '0');
INSERT INTO `document_segments` VALUES ('1955803401115496449', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '要重视每一个小单子和小客户，不然所谓专业精神将荡然无存，你也就相应失去发展的机遇与品质。 　　十. 对待每个客户如同潜在客户，对待每个潜在客户如同现有客户。 　　十一. 时刻保持聪慧敏锐的判断力、坚韧不拔的毅力、专业专注的学习精神和追求卓越的进取心。 　　企业的设计队伍 　　一. “要求自我”，在任何设计过程中的小细节，都应追求达到完美境界; 　　二. 永远不要对自己作品感到满足，比你强的人和公司就在周围，他们随时准备给予你狠狠一击。你能做的只有：不断提高自己，使生命力更加旺盛。 　　三. 好的设计师必须懂得生活，要以博学的方式，去阅览整个世界，充实你的视界，懂得体验世上一切美好时尚的东西，这样才懂得如何去提升客户和产品的品位层次，了解受众的心理，做出更好的设计。 　　四. 珍惜个人的名誉，它将胜于一切。设计作品的署名制将增加你的荣誉感和责任感。 　　五. 不要设计出人们没有需要而且不实用的东西，但如果它的确是有需要又实用的东西，在设计时不要犹豫，让它变得更美丽。 　　六.', 443, NULL, '[\"设计\", \"客户\", \"懂得\", \"东西\", \"作品\", \"追求\", \"专业\", \"精神\", \"更\", \"聪慧\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:23', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:23', '0');
INSERT INTO `document_segments` VALUES ('1955803401165828098', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　六. 我们要做的是为品牌树起明确突出的个性，而且把这种个性坚持到底。在压力面前坚持统一的风格，的确是很需要点勇气的。胡乱更改你的设计是极其容易的事情，但是，荣誉和肯定只颁给对塑造协调一致的品牌形象有远见而且能持之以恒的设计团队。 　　七. 要有强烈的学习和创新精神，谦虚好学，不懂就问。不能不懂装懂，一知半解。学习要有悟性，不能死记硬背、照猫画虎。 　　八. 不要想快速形成个人风格已得到他人认同，设计者的基础如果建设不稳，愈想快速建立风格，也愈被快速淘汰。当你为自己贴上标签之后，想要逃脱就相当困难了。对客户来说也是不公平的。 　　九. 主动、创新，除非是你真心肯定的好作品，否则绝对不要提给客户。 　　十. 永远记住，你是一个懂设计，爱设计的人。用设计吃饭，你比别人更有资格。 　　企业的管理人员 　　一. 不要背弃理想。做一个有理想的人，自然也会成就一个有理想的公司。 　　二. 在现实与理想面前，要学会平衡和忍让。 　　三. 做远景规划与做回顾同样重要，不切实际的臆想和急功近利的做法都是致命的。 　　四. 不盲目扩张，这样可以做一些自己喜欢的客户的项目，也因此会做得更有质量，有了质量才会有更多的好客户。 　　五.', 514, NULL, '[\"做\", \"设计\", \"客户\", \"快速\", \"肯定\", \"创新\", \"面前\", \"学习\", \"不要\", \"理想\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:23', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:23', '0');
INSERT INTO `document_segments` VALUES ('1955803401216159746', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　五. 不要依赖任何人。小公司的体制是靠强压和拼命才能锻炼出来的，寄生和依赖智慧让自己在风向有所变化的时候死得很惨。 　　六. 精通财务。要做到心中有数，但不可以成为守财奴。懂得投入，才会有产出，准确的投资与再投入是下一步发展的基石。 　　七. 不要在税务等方面动大脑筋，商业化与国家化进程的家甚至会让你遇到更为严格的财务与经营审查，除非你永远只想徘徊在下游。 　　八. 尽早建立一套客观的，符合自己公司的管理制度，否则你会在同样的问题上浪费同样的时间。 　　九. 不要以为自己是机器，别人就一定也是机器，和谐的工作频率会造就和谐的工作环境，你公司的气质将由此诞生。 　　十. 设计公司是有品格的，十年做小，一朝做大的时候，你所有的努力必将得到验证。 　　第四章 规章制度总则 　　为规范公司的工作纪律，保障公司的经营管理健康、有序的进行，根据国家有关规定，结合公司具体情况，制定本条例。 　　员工违反公司规章制度，给公司的经营、管理和声誉造成不良影响和经济损失，可视情节予以行政处分和行政处理，给公司造成经济损失者，可追究经济赔偿;涉嫌触犯法律者，依法追究法律责任。行政处分、行政处理和追究经济赔偿可单独执行，也可合并执行。 　　2', 518, NULL, '[\"公司\", \"会\", \"经营\", \"不要\", \"财务\", \"规章制度\", \"投入\", \"工作\", \"经济损失\", \"经济\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:23', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:23', '0');
INSERT INTO `document_segments` VALUES ('1955803401262297090', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　2 行政处分(通报批评、警告、撤职以及其它法律法规规定的行政处分方式); 　　2 行政处理(辞退、除名以及其它法律法规规定的行政处理方式)。 　　本总则适用于，但不限于下述违反公司有关管理规定的行为： 　　第一条 不维护公司利益、不遵守公司的各项规章制度; 　　第二条 不严守甚至窃取公司机密;不保护公司知识产权; 　　第三条 不能保质保量完成职责范围的各项工作;未尽职履行岗位职责和权限、失职、渎职或滥用职权者;工作态度恶劣，工作质量低下，给公司造成不良影响或经济损失者; 　　第四条 不服从领导安排;无正当理由拒不服从公司组织调动和工作安排者; 　　第五条 从事非劳动合同约定工作者，包括在外兼职、独资或合伙经营公司者; 　　第六条 利用公司资源牟取个人利益者，在采购或业务中私吞回扣者;在工作中，尤其是在寻价、报价、谈判、合同签订、支付、结算、验收、收发货、索赔等关键环节违章操作，给公司造成不良影响或不可挽回的经济损失直接责任者; 　　第七条 出差或休假、未经批准不按预定时间返回者;迟到、早退、无故旷工者。每月5次以上迟到、早退者视为严重违反规章制度;连续旷工三天以上立即予以辞退或除名处理; 　　第八条', 509, NULL, '[\"公司\", \"工作\", \"规定\", \"违反\", \"安排\", \"规章制度\", \"法律法规\", \"旷工\", \"造成\", \"经济损失\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:23', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:23', '0');
INSERT INTO `document_segments` VALUES ('1955803401312628738', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　第八条 由于个人过失给公司造成各种形式的拖欠款的直接责任者; 　　第九条 在工作中，违规操作或不负责任、损坏设备工具;浪费材料、能源，造成经济损失者;对公物贪污浪费、不珍惜爱护;利用公司财产从事与工作无关的事，如打印、复印、打私人电话、干私活; 　　第十条 工作时间从事工作无关之事，如睡觉、闲谈、玩游戏、上网聊天、听音乐、看盘、在网上下载与工作无关的东西、阅读与工作无关的杂志报纸等; 　　第十一条 擅自刻制或使用公章、法人章、; 　　第十二条 对同事采取恐吓、胁迫、人身攻击或诋毁名誉等行为者，以及造谣惑众、 无理取闹、影响工作秩序和社会秩序者; 　　第十三条 不维持工作场所的整洁卫生。 　　第五章 行为准则规范 　　第一节 办公环境 　　第一条 维护办公室的良好环境是每位员工的职责和义务;员工应自觉保持工作场所的整洁卫生，办公物品摆放整齐，时刻保持干净、整洁、亮丽的环境; 　　第二条 员工可自备午餐，但必须至指定区用餐，办公区域严禁用餐;用餐完毕后，应将垃圾立即倒入楼道内垃圾箱，并及时做好用餐环境的通风换气工作; 　　第三条', 471, NULL, '[\"工作\", \"无关\", \"环境\", \"办公\", \"用餐\", \"整洁\", \"员工\", \"造成\", \"浪费\", \"公司\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:23', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:23', '0');
INSERT INTO `document_segments` VALUES ('1955803401379737601', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　第三条 每日清洁工作包括：9点上班之前务必开窗换气、将个人工位擦拭干净、用洁厕剂清理坐便和马桶;每日离开公司前整理个人桌面，倒掉个人桌面的垃圾盒和客厅、卫生间的垃圾桶; 　　第四条 每周清洁工作包括：扫地、拖地、用去污粉清理水池和坐便、用洁厕剂清理马桶、擦拭所有工位和机器;每周五下班之前完成; 　　第五条 不允许在办公场所的非指定区域吸烟。抽烟的唯一地点是小阳台，抽烟的同志每天务必倒烟灰缸，并及时做到吸烟区的换气通风; 　　第六条 用完卫生间和厨房的水池后保持它和周边环境的清洁和卫生; 　　第七条 坐便严禁蹲便或脚踏;用完坐便保持它的干净。 　　第二节 工作纪律 　　第一条 办公场所务必保持安静，禁止喧哗，同事间交谈以不干扰他人为限，勿打瞌睡; 　　第二条 上班时间应提高工作效率，减少个人电话和聊天; 　　第三条 工作时间内不得做与工作无关之事;工作时间请勿阅读与工作内容无关的书报杂志;互联网只限于因工作需要使用，不得下载任何游戏、投资及股票类软件;MSN、QQ等聊天软件只限工作需要时使用，不得用于私人聊天;不得随意漫游互联网从事与工作无关的事宜; 　　第四条', 489, NULL, '[\"工作\", \"个人\", \"务必\", \"坐便\", \"聊天\", \"保持\", \"清洁\", \"之前\", \"卫生间\", \"吸烟\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:23', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:23', '0');
INSERT INTO `document_segments` VALUES ('1955803401430069250', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　第四条 员工下班后及时离开公司，不得在公司逗留、聊天，做个人事情。最后离开公司的员工应确保门、窗、电脑、灯、水、煤气、空调、热水器均关闭。 　　第三节 电话管理制度 　　第一条 为树立良好的公司形象，员工在接打电话时，应礼貌亲切、职业干练、对答清晰、通话简短而适度。并以饱满的热情去接听电话。因为对方会通过你的语气能感受到你的热情，感受到公司的职业形象; 　　第二条 选择通讯方式和时间要适当。选取通讯方式以他人方便为宜，在一般情况下，能够拨打对方固定电话时，不拨打对方手机。拨打工作电话时，尽量不占用他人的休息时间; 　　第三条 电话中表述问题应简洁明了，如内容较多，应首先询问对方是否方便。通话时保持语音语调的清晰和轻柔，语言和语气应体现对对方的尊重。电话听筒要轻拿轻放，挂断电话应以长者和尊者为先; 　　第四条 接听总机“84832676” ：在电话铃响两声内接起电话说“您好，企业”，了解对方来电意图后迅速准确转接到所找员工的座位。标准用语为：“。。。好的，这件事情由XX部门(人名)负责，我现在把您的电话转接过去，请稍候; 　　第五条', 474, NULL, '[\"电话\", \"应\", \"公司\", \"时\", \"员工\", \"转接\", \"方便\", \"通话\", \"清晰\", \"形象\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:23', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:23', '0');
INSERT INTO `document_segments` VALUES ('1955803401476206593', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　第五条 对于不明身份的来电，应避免随意告知领导和同事的相关信息;遇到打错的电话，应客气提醒对方，切忌简单生硬; 　　第六条 接听个人分机：在电话铃响两声内接起电话说“您好，‘报上个人姓名’”; 　　第七条 如遇周围同事不在座位上，当其电话响时要及时代接，尽量不要超过两声。并询问对方是否需要留言，如要留言，请记下对方的姓名、单位、电话、事宜，然后告知对方会尽快转告该同事与他联系; 　　第八条 不允许电话聊天，私人电话限制在3分钟之内;原则上不允许拨打私人外地电话，如确有特殊情况，需向主管请示，得到批准后需简明扼要、尽快结束通话; 　　第九条 每月公司将根据集团电话之自动计费系统会对各分机电话的通话时间和费用情况作相关统计，如发现私人电话过多和个人私自拨打长途电话的情况，公司将予以警告; 　　第十条 使用手机短信功能处理公务时应注意署名，在接到短信后应及时回复; 　　第十一条 上班时间如果外出，应时刻注意保持通讯畅通，公司电话应第一时间接通，不得欠费停机或关掉手机。 　　第四节 传真机、打印机、书籍、办公用品管理 　　第一条 公司提倡无纸办公，员工需最大程度的使用网上邻居、电子邮件等网上手段与公司内外沟通; 　　第二条', 517, NULL, '[\"电话\", \"公司\", \"应\", \"情况\", \"同事\", \"需\", \"私人\", \"时\", \"使用\", \"个人\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:23', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:23', '0');
INSERT INTO `document_segments` VALUES ('1955803401564286978', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '公司提倡无纸办公，员工需最大程度的使用网上邻居、电子邮件等网上手段与公司内外沟通; 　　第二条 公司传真应保证24小时畅通，为提高工作效率、降低办公成本，收传真时应详细询问对方接收人姓名、传真内容，内容不祥、或与公司业务无关的传真不予接收;严禁为个人目的使用公司传真设备; 　　第三条 收到传真后，应将传真件及时递交收件人，传真未注明收件人的，根据其内容通知有关部门，务必尽快将传真送达收件人; 　　第四条 没有特殊情况不允许使用彩色喷墨打印机打印各类文件、规章制度和资料，更不允许将公司的办公设备为个人使用。如有特殊情况需要打印，用于公司内部的文件一律使用两面打印、使用单黑打印，以主人翁的意识积极控制公司成本，不允许有任何浪费行为; 　　第五条 公用书籍、杂志、报刊、资料只能在公司办公区域内阅读，非经主管批准，不得外带出公司;如需借阅要提前登记，借阅的图书资料要妥善保管，不得遗失、损坏，要按时归还，一次最多借阅2本; 　　第六条', 418, NULL, '[\"公司\", \"传真\", \"使用\", \"收\", \"办公\", \"允许\", \"打印\", \"成本\", \"应\", \"公司传真\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:23', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:23', '0');
INSERT INTO `document_segments` VALUES ('1955803401631395841', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　第六条 全体员工对待一切公物需贯彻节约节俭的原则，珍惜爱护。个人使用的公物(包括电脑、通讯工具、文件柜、办公用品等)应由使用人妥善保管，如有遗失，照价赔偿;如有损失，应由使用人负责及时联系有关部门维修。借用他人用品应做到借后必还，不损坏、不遗失。 　　第五节 印签、证件管理 　　第一条 公司印签(公章、法人章、)由专人负责保管，印签保管人员必须具有较高的法律意识，坚持原则、秉公办事; 　　第二条 建立使用印签/证件的登记手续，凡各种文件、证明或其他物品需要加盖公司印签时，须经总经理批准后，方予使用。 　　第三条 加盖公司印签的各类文件在使用后应及时归还公司负责人;作废文件应第一时间销毁。 　　第六节 电脑管理制度 　　第一条 电脑使用管理 　　1. 未经许可，任何人不得私自更换电脑硬件和安装软件，拒绝使用来历不明的软件和光盘;因工作需要需安装办公软件、更换或安装电脑硬件时，必须向洪波申请后由专人进行操作; 　　2. 严禁安装及使用游戏软件：包含网络游戏、单机版游戏、WINDOWS自带游戏等; 　　3. 严禁下载黑客攻击工具、病毒传播软件等; 　　4. 严禁登陆黄色或其他非法网站; 　　5. 严格按规定程序开启和关闭电脑; 　　6. 严禁删除/安装个人电脑软件： 　　(1)', 546, NULL, '[\"使用\", \"严禁\", \"安装\", \"印签\", \"电脑\", \"公司\", \"软件\", \"应\", \"文件\", \"保管\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:23', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:23', '0');
INSERT INTO `document_segments` VALUES ('1955803401685921793', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　4. 严禁登陆黄色或其他非法网站; 　　5. 严格按规定程序开启和关闭电脑; 　　6. 严禁删除/安装个人电脑软件： 　　(1) 包含修改IP地址、删除系统软件、删除网管所安装的办公软件等， 　　(2) 网络管理员将不定期对电脑软件安装情况进行检查，如有未经批准擅自安装的情况将根据其可能对网络或电脑造成的影响酌情给予50元~200元罚款的处罚。 　　7. 严禁打开电脑主机机箱、拆除键盘、鼠标、网线等硬件设备; 　　8. 不得下载任何游戏、投资及股票类软件;MSN、QQ等聊天软件只限工作需要时使用，不得用于私人聊天;不得随意漫游互联网从事与工作无关的事宜; 　　第二条 电脑维护 　　1. 公司由专人负责电脑系统的维护; 　　2. 电脑发生故障时，使用者作简易处理仍不能排除的，应立即报告部门负责人，并将故障问题提交详细书面说明; 　　3. 电脑维修过程中，首先确保对重要文件进行拷贝，做到不遗失; 　　4. 对重大电脑软件、硬件损失事故，公司将列入专案处理，并追求事故原因; 　　5. 凡因个人使用不当所造成的电脑维护费用和损失，使用者将承担一切责任并照价赔偿。 　　第三条 电脑病毒的防治 　　1.', 505, NULL, '[\"电脑\", \"电脑软件\", \"软件\", \"安装\", \"严禁\", \"故障\", \"损失\", \"进行\", \"硬件\", \"工作\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:23', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:23', '0');
INSERT INTO `document_segments` VALUES ('1955803401732059138', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　第三条 电脑病毒的防治 　　1. 每台机器均安装正版杀毒软件，开机时务必开启上毒软件，并保证每周定期杀毒一次，每周病毒库更新一次;及时关注电脑病毒防护情况和提示，避免电脑病毒侵袭; 　　2. 未经许可，任何人不得携软件使用，如因工作需要，必需引入使用的软件，须首先防止病毒传染; 　　3. 电脑出现病毒，应第一时间离开网上邻居;操作人员不能杀除的，须立即报上级主管; 　　4. 建立双备份制度，对重要资料除在电脑储存外，还应及时刻录光盘，以防遭病毒破坏而遗失。 　　第七节 着装管理制度 　　第一条 为树立和保持企业作为优秀设计公司的良好形象，员工在上班时间应保持良好的职业形象。个人仪表应整洁得体。时刻保持饱满、良好的精神状态; 　　第二条 周一至周四着正装、或淡雅的职业装或商务休闲装，不得穿牛仔服、运动服、运动鞋，或其他有碍观瞻的奇装异服;周五如安排客户来访或需外出拜访客户，则应着职业装; 　　第三条 男士不穿奇装异服，不袒胸露背;女士衣着大方得体、端庄典雅，不允许在工作时间衣着暴露，不化浓妆、不擦抹浓烈香水; 　　第四条 在公司上班时可穿拖鞋，但不宜穿行走时响声过大的鞋，脚步轻柔。 　　第八节 保密制度 　　第一条', 516, NULL, '[\"应\", \"杀\", \"穿\", \"时\", \"电脑病毒\", \"公司\", \"保持\", \"及时\", \"须\", \"得体\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:23', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:23', '0');
INSERT INTO `document_segments` VALUES ('1955803401790779394', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　第四条 在公司上班时可穿拖鞋，但不宜穿行走时响声过大的鞋，脚步轻柔。 　　第八节 保密制度 　　第一条 公司本着平等、自愿的原则建立相关保密制度，对于涉及“知识产权”、“专利”、“商标”、“著作权”、“职务开发结果”、“商业秘密”、“技术信息”、“经营信息”等内容的工作，公司将有权要求员工与公司签订《知识产权及其保密协议》。双方将根据《知识产权及其保密协议》履行职责、承担义务。双方如有违约情况发生，将根据《知识产权及其保密协议》承担违约责任并向对方支付违约金，赔偿由于该种违约行为给对方造成的经济损失，违约金的数额将根据《知识产权及其保密协议》中有关条款执行。具体内容详见《知识产权及其保密协议》; 　　第二条 为了保护公司利益，防止商业秘密泄露事件的发生，根据国家有关保密工作的规定，结合我公司的实际情况，特制订保密制度; 　　第三条 保密总则： 　　不该说的机密，绝对不说;不该问的机密，绝对不问; 　　不该看的机密，绝对不看;不该记录的机密，绝对不记录; 　　不在私人通信中涉及公司机密。 　　第四条 以下作为公司内部资料，绝对不得以任何形式擅自带出公司或扩散： 　　1. 公司机构设置、内部分工、人事安排和职务任免事项; 　　2.', 523, NULL, '[\"公司\", \"知识\", \"产权\", \"保密\", \"保密制度\", \"协议\", \"违约\", \"绝对\", \"职务\", \"中\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:23', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:23', '0');
INSERT INTO `document_segments` VALUES ('1955803401836916737', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　1. 公司机构设置、内部分工、人事安排和职务任免事项; 　　2. 公司的工作流程和管理措施; 　　3. 准备公布但尚未公布的统计数字; 　　4. 销售指标和规章制度; 　　5. 业务档案、正式文件和内部参阅的各种资料; 　　6. 项目文件及设计方案; 　　7. 各种印章(含印模)和证件; 　　8. 客户资料及各类合同。 　　第五条 电脑数据的保密 　　1. 员工应主动保护公司机密、公司使用的系统软件禁止私自拷贝和向外扩散; 　　2. 电脑网络中，数据授权使用范围不同，不得越权使用数据; 　　3. 未经允许不得删除电脑中共享的数据。 　　第六条 其他保密条款 　　1. 各种经打印输出的报表，应妥善保管，废表应及时妥善销毁; 　　2. 员工调离公司时，不得将本公司的软硬件及客户资料带走。 　　3. 对外谈判中应严格遵守对外谈判守则和外事纪律，内外有别。特别要注意保守公司机密，严防被对方套取情况; 　　4. 涉及公司机构、人事变动和职务任免事项，未经正式批准任何人不得公开扩散; 　　5. 利用计算机网络向其他单位或个人传递信息时，严禁将属于公司的保密信息随意传递、拷贝或扩散。 　　第九节 公司图书管理规定 　　第一条 总则 　　1. 为规范公司图书管理工作，特制定本规定。 　　2.', 548, NULL, '[\"公司\", \"数据\", \"应\", \"中\", \"保密\", \"使用\", \"正式\", \"扩散\", \"拷贝\", \"未经\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:23', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:23', '0');
INSERT INTO `document_segments` VALUES ('1955803401891442690', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　第九节 公司图书管理规定 　　第一条 总则 　　1. 为规范公司图书管理工作，特制定本规定。 　　2. 本规定所称图书是指公司为满足各部门工作需要而购置的图书资料，包括各类工具书、期刊、杂志及相关学术著作等。 　　3. 本公司图书的管理，除另有规定外，均依本规定办理。 　　4. 本公司图书由图书管理员负责管理，并于每周清点一次。 　　第二条 图书购置 　　1. 需购置图书(杂志)的品种和数量，应广泛征求有关部门的意见，由图书管理员汇总，总经理审阅后审批。 　　2. 凡个人提出购买图书资料的应先征得本部门经理同意，并报总经理批准后方可办理。 　　3. 有关人员在购回图书后，应及时送至图书管理员处验收归档，并由管理员签字后，方可按照正常批示程序到财务报销。 　　第三条 图书保管 　　1. 新购图书应按顺序编号，将书名、出版社名称、购买日期、数量、金额及其他有关资料详细登记于\"本公司图书登记总簿\"并填制编号标签贴于书籍处并在首页盖《图书管理专用章》。 　　2. 图书管理员对所保管的图书资料，应做到防潮、防霉、防蛀;对损坏的图书资料应及时修补，保证其完整性;对各类期刊要按年度装订成册。 　　第四条 图书借阅 　　1. 借书人以本公司员工为限。 　　2.', 532, NULL, '[\"图书\", \"公司\", \"应\", \"图书资料\", \"管理员\", \"管理\", \"购买\", \"方可\", \"总经理\", \"期刊\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:23', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:23', '0');
INSERT INTO `document_segments` VALUES ('1955803401941774337', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　第四条 图书借阅 　　1. 借书人以本公司员工为限。 　　2. 公司员工因工作需要，可借阅各类图书，但必须按照本规定第五条规定办理。 　　3. 专业性强的工具书和参考图书，概不得外借。 　　4. 一般书报杂志可随意阅览，阅毕应归回原外，不得擅自携出公司。 　　5. 员工所借之图书，如遇清点或公务上需参考时得随时通知收回，借书人不得拒绝。 　　6. 公司员工在解雇、辞职时，须将所借图书归还。 　　第五条 借还书手续 　　1. 员工借阅图书，应根据类别在对应存放处拿取，并在归还时按照编号放回原处。 　　2. 所有公共书籍借阅时间不得超过一周，周五下班前务必归还，如需续借，于下一周再领取 　　第六条 处罚 　　1. 员工借出图书不得批改、圈点、画线、折角、涂写，如有破损或遗失等情况，一律照原图书版本购赔或照原价加倍赔偿。 　　2. 员工借书期限届满，经通知仍不还书者，或遇清点期而仍不还者，除未还书前得停止其借书权外， 并需每日缴纳10元滞纳金，直至归还日。 　　第七条 附则 　　本规定20xx年12月21日实施。 　　第十节 工装管理规定 　　第一条 员工工装的购置由公司行政部统一数量后做出计划，经总经理批准后方可购置。 　　第二条 购置工装的费用由公司统一支付，工装由个人妥善保管。 　　第三条', 555, NULL, '[\"图书\", \"员工\", \"归还\", \"公司\", \"借阅\", \"借书\", \"需\", \"时\", \"规定\", \"工装\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:23', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:23', '0');
INSERT INTO `document_segments` VALUES ('1955803402017271809', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　第二条 购置工装的费用由公司统一支付，工装由个人妥善保管。 　　第三条 除以公司名义参加活动或外出办事之外的时间不得穿着工装，穿着工装时必须保持工装的干净、平整，如有破损、污渍或丢失由员工进行赔偿。 　　第四条 员工离职时须把干净整洁的工装交到行政部，由行政部检查是否符合回收标准。如不符合，员工需按折价赔偿。 　　第六章 文件管理办法 　　第一节 公文、合同、客户档案管理 　　第五条 公司的档案管理工作遵循规范化、制度化、科学化; 　　第六条 合同、客户付款凭证等重要文件需及时交于公司负责人处统一保管，员工不得擅自留存、更不得擅自复印、扫描和其他任何形式的备份; 　　第七条 每个项目收尾时，必须将项目文件、客户资料等所有资料交于专人处统一保管，要安全保密，不得随意堆放，严防毁损、散失，如出现问题视情况追究有关人员责任。 　　第二节 公司外发资料管理办法 　　第一条 公司外发资料指印刷版本的公司资料和电子版本的公司介绍、项目建议书、报价等; 　　第二条 公司资料的使用规定 　　1) 公司会对所有能够外发的文件进行不定期的更新，项目人员需按公司统一要求对外发送最新文件，不得外发任何其他版本和格式的资料; 　　2)', 514, NULL, '[\"公司\", \"工装\", \"文件\", \"统一\", \"资料\", \"员工\", \"项目\", \"需\", \"保管\", \"外\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:23', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:23', '0');
INSERT INTO `document_segments` VALUES ('1955803402105352193', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　2) 外发资料须经过公司审批，任何人不得随意发送任何公司资料。 　　第三条 我方在对外提供资料时，须遵循以下流程： 　　第一步：初步接洽的客户，首先由前台登记对方单位、人名、职务及联系方式; 　　第二步：前台核实确认身份后，将《客户信息登记表.pdf》或《医院导向系统应用导入前实施环境调查表.pdf》以传真或邮件形式发给对方，请对方自行打印、填写，并发回传真; 　　我方接洽人员在发送传真时需登记发送《客户信息登记表》纪录; 　　第四步：前台收到对方发回的传真后，根据项目类别和所属区域转交相应项目人员; 　　第五步：项目人员通过《企业医院数据库》检索是否有交集并跟进联系，根据需要发送相关公司资料。 　　第四条 报价方案的使用规定 　　1) 目前公司对外公开报价有《医院VI设计套餐报价单-北京企业)》、《医院标识系统规划设计报价单-北京企业)》、《医院VI成品印刷报价单-北京企业)》等三个文件;其中《医院VI成品印刷报价单-北京企业》仅发给老客户; 　　2) 若客户在收到套餐报价后，需定制个性化报价方案，项目负责人需填写《医院VI定制价格与内容明细-北京企业.ex.》，在公司统一报价完毕后，再外发给客户; 　　3)', 515, NULL, '[\"医院\", \"客户\", \"报价\", \"公司\", \"企业\", \"传真\", \"发送\", \"北京\", \"-\", \"项目\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:23', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:23', '0');
INSERT INTO `document_segments` VALUES ('1955803402159878145', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　3) 未经公司允许，任何人不得擅自报价。 　　第五条 资料的发送 　　1) 公司资料或者报价必须由指定的项目负责人通过公司指定邮箱发送，同时抄送至，且保存在邮件服务器上，具体规定见第五节《电子邮件管理制度》;禁用qq或msn发送报价及任何项目方案; 　　2) 公司资料、报价方案、项目方案、合同等文件的外发格式一律为.pdf格式，任何人不得外发任何其他格式的文件; 　　3) 邮件(传真)发送成功后，项目负责人须于当日内以电话或短信形式告知对方。 　　第三节 电脑中文件的管理制度 　　第一条 所有公司的重要文档保存在本地硬盘的D、E分区上; 　　第二条 保持机器内部文件的整齐有序，员工个人必须建立清晰明确的文件管理系统，按照大项类别、客户名称、项目名称、文件类型等进行清晰的分类; 　　第三条 每月必须整理文件夹，及时清理不需要的过期文件和垃圾文件，保持文件的时效性; 　　第四条 每次项目最终完成，设计师需按项目名称将设计文件进行光盘刻录予以备份，并交由设计总监统一保管;保管时须按照序号整理光盘，时间、内容、命名准确清晰; 　　第五条 公司将派专人不定期对员工电脑中文件管理情况进行检查，经提醒两次以上不合格者酌情每次处于50元罚款。 　　第四节', 529, NULL, '[\"文件\", \"公司\", \"项目\", \"发送\", \"进行\", \"必须\", \"邮件\", \"光盘\", \"保存\", \"清晰\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:23', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:23', '0');
INSERT INTO `document_segments` VALUES ('1955803402210209794', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　第四节 文件的格式说明 　　第一条 文件页面设置。统一规定为：“页边距”上下左右各为2厘米;行间距为单倍行距;页脚采用公司统一规定(如下示意)，不可自行添加或修改。 　　第二条 字体、大小。中文：宋体10号;英文：Arial 10号。 　　第三条 规范页脚。 　　对外： 　　第四条 文件名称的定义。 　　1. 文件名由5部分组成：客户名称+项目名称+文件内容+创建时间+创建人姓名; 　　2. 所有名称、姓名也可以用统一规定的缩略名代替; 　　3. 公司内部文件需加“创建人姓名”，外发文件则不加;对内文件命名示意：《北大医院VI项目总结20xx.6.1-Lisa》，对外文件命名示意：《北大医院VI设计方案初稿20xx.6.1》; 　　第五条 公司外发的每类项目方案均有统一的文件模版，每次编写文档在模版中进行。格式不得任意变更。 　　第五节 电子邮件管理制度 　　第一条 公司内部管理制度、文件传送、日常联系采用电子邮件方式，提倡无纸办公; 　　第二条 定期删除垃圾邮件，保存邮件到您的电脑上;(网管需要定期清理服务器数据，所以建议您使用OUTLOOK等软件把邮件接收到本地电脑上); 　　第三条', 503, NULL, '[\"文件\", \"邮件\", \"公司\", \"统一\", \"示意\", \"规定\", \"定期\", \"对外\", \"采用\", \"姓名\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:23', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:23', '0');
INSERT INTO `document_segments` VALUES ('1955803402264735745', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　第三条 发送电子邮件，发件人在主题和附言中应简单明了写清内容，留下发件人的姓名、单位，使用附件时应加以提醒;使用群发时注意称谓和内容的恰当得体; 　　第四条 邮件主题规范： 　　1. 外发邮件主题由4部分组成，客户名称+项目名称+邮件目的+“来自北京企业”;如：“吉林省中医院画册设计项目中文文字请确认-来自北京企业”; 　　2. 内发邮件主题由2部分组成，邮件目的+发件人姓名;如：“赴吉林省中医院差旅报销申请Lisa”; 　　第五条 发送合同、报价等保密邮件时，发件人必须带签名模板，务必在个人签名模板之下增加保密条款; 　　第六条 邮件签名规范模板示意如下 　　第七条 员工收到电子邮件后要在一个工作日内处理并回复，如遇到特殊问题不能给发件人准确地答复，也必须告知对方已收到邮件，并尽快答复; 　　第八条 如员工姓名在“收件人”一栏，必须回复发件人;如员工姓名在“抄送人”一栏，不必一定回复，可依据实际情况和信件内容酌情而定。 　　第七章 人事制度 　　第一节 总则 　　第一条 本制度是根据《劳动法》及政府有关政策法规并结合本公司实际情况而制定; 　　第二条 本公司员工有关招聘、录用、职务变更、离职等事项，悉依本制度办理; 　　第三条', 524, NULL, '[\"邮件\", \"发件人\", \"员工\", \"内容\", \"姓名\", \"主题\", \"回复\", \"时\", \"必须\", \"制度\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:23', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:23', '0');
INSERT INTO `document_segments` VALUES ('1955803402315067393', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　第二条 本公司员工有关招聘、录用、职务变更、离职等事项，悉依本制度办理; 　　第三条 对本制度未尽事项，公司在国家有关法规允许的范围内有可能进行修改、补充或废除，届时将通报全体员工。 　　第二节 招聘与录用 　　第一条 公司录用员工采取社会公开招聘的方式择优录用; 　　第二条 招聘流程： 　　1. 用人部门提出职位空缺申请，并提交职位说明书由总经理审批; 　　2. 经总经理审批后，交由人事部招聘; 　　3. 人事部经过初步面试后，复试由申请部门进行; 　　4. 通过复试后，人事部核查该员工以往工作记录，确认无误后通知新员工入职，组织入职培训。 　　第三节 试用期管理办法 　　第一条 员工被聘用后，正常情况将有两个月的试用期; 　　第二条 在试用期内，员工所在部门的主管及人事部将对该员工进行考核，以确定是否胜任本职工作，并对员工做出如下决定： 　　A：正式聘用 B：延长试用期 C：不予聘用 　　第三条 在试用期内，员工有权选择本公司是否适合个人的发展，有权随时提出辞职。 　　第四节 员工的内部职位变动 　　第一条 员工的内部职位变动包括： 　　A：升职 B：降职 C：岗位调整 　　第二条 员工发生内部职位变动时，人事部均要以公告形式通知全体同仁。 　　第五节 人事档案管理办法', 547, NULL, '[\"员工\", \"人事部\", \"招聘\", \"职位\", \"公司\", \"试用期\", \"节\", \"进行\", \"部门\", \"职\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:23', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:23', '0');
INSERT INTO `document_segments` VALUES ('1955803402386370562', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　第二条 员工发生内部职位变动时，人事部均要以公告形式通知全体同仁。 　　第五节 人事档案管理办法 　　第一条 员工入职时，须提供该员工的简历、身份证复印件、学历复印件、一寸照片一张、《员工入职登记表》存放人事部;同时，该员工的《薪酬通知书》存入财务部; 　　第二条 公司与员工解除劳动合同后，员工的档案应由该员工办理转移手续。 　　第六节 员工的解聘、辞退和辞职管理办法 　　第一条 员工的解聘、辞退和辞职按《劳动合同》有关条款的规定办理; 　　第二条 转正后员工本人因有特殊情况需要辞职，应提前一个月提出辞呈，经批准后，方可办理解除劳动合同手续。未依规定擅自离职者，公司可扣其薪资，以示处罚; 　　第三条 员工的解聘、辞退和辞职须得到公司总经理批准后方可办理; 　　第四条 员工的解聘、辞退和辞职须及时办理移交手续，填写《员工离职手续清单》，由本部门负责人和人事部共同办理; 　　第五条 财务部依据员工离职手续清单为员工结算薪资，于最近发薪日一并发给离职员工。 　　第七节 考勤管理办法 　　第一条 工作时间 　　1. 公司实行每周五天工作制，并执行法定假日及休假制度; 　　2. 工作时间为周一至周五的9：00-17：30(法定节假日及公司规定的假日除外);', 533, NULL, '[\"员工\", \"公司\", \"办理\", \"离职\", \"人事部\", \"手续\", \"辞职\", \"节\", \"规定\", \"解聘\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:23', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:23', '0');
INSERT INTO `document_segments` VALUES ('1955803402453479425', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　2. 工作时间为周一至周五的9：00-17：30(法定节假日及公司规定的假日除外); 　　3. 午餐时间为45分钟，可在12：00-13：00之间选择。 　　第二条 迟到 　　1. 每月迟到不得多于两次(即：9:10-9:30之间)，第三次起每次扣50元; 　　2. 迟到30分钟以上(即：9:30之后)，每次扣100元。 　　第三条 旷工 　　1. 未经请假无故不来上班的，按旷工处理，扣发半日工资; 　　2. 累计旷工4个小时(含)扣发一日全部工资; 　　3. 连续旷工一天扣发双倍日工资，并给予书面警告; 　　4. 每月旷工超过两天扣发当月工资，并给予除名处分。 　　5. 考勤管理、统计方法 　　公司采用指纹打卡机进行考勤记录。员工早晚各打卡一次，作为当日出勤依据。如员工外出、出差需提前通知考勤管理员，考勤管理员负责登记记录。月末最后一个工作日由考勤员依据打卡机记录和外出、出差登记以及《请假申请单》三项数据统计当月考勤。 　　第四条 请假制度 　　1. 任何病、事假需提前一天直接向部门主管提交《请假申请单》，并将部门主管签字后的《请假申请单》上交人事部方能休假。委托他人代请、短信请假均无效; 　　2.', 510, NULL, '[\"请假\", \"考勤\", \"旷工\", \"-\", \"工资\", \"公司\", \"打卡机\", \"申请单\", \"扣发\", \"当月\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:23', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:23', '0');
INSERT INTO `document_segments` VALUES ('1955803402512199681', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　2. 有急事或急病时需及时电话通知人事部，并于事后第一时间补交《请假申请单》。委托他人代请、短信请假均无效; 　　3. 遇到塞车、路上发生紧急情况，要迟到者需及时向人事部负责人电话告知。委托他人代请、短信请假均无效。 　　第五条 病假 　　因病请假超过一天以上，扣发当日全部工资。并要求提供医院的诊断证明或病假条，否则按旷工处理; 　　第六条 事假 　　1. 用工作时间处理个人私事的，按事假处理; 　　2. 事假扣发当日全部工资; 　　3. 年累计事假不得超过6天，否则扣除结算当月的全部薪资。 　　第七条 年假 　　1. 根据员工司龄年限确定年休假期限;每年的休假限次年3月31日前使用，不能累计或者折现;可按应休假天数抵扣当年病假或事假; 　　2. 有以下情况之一者，当年不得享受年休假：累计事假十天以上者;累计病假二十天以上者;产假休满九十天者; 　　企业工龄一年 　　6天/年 　　连续休假不得 　　超过两周 　　企业工龄二年 　　7天/年 　　企业工龄三年 　　8天/年 　　企业工龄四年 　　9天/年 　　企业工龄五~九年 　　10天/年 　　第八条 婚假 　　正式员工婚假三天;符合晚婚条件的(男满25周岁，女满23周岁)婚假10天; 　　员工在公司只可享受婚假一次。 　　第九条 产假', 553, NULL, '[\"休假\", \"事假\", \"累计\", \"员工\", \"病假\", \"超过\", \"满\", \"请假\", \"及时\", \"电话\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:23', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:23', '0');
INSERT INTO `document_segments` VALUES ('1955803402558337025', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　员工在公司只可享受婚假一次。 　　第九条 产假 　　女员工(正式员工)产假九十天(含产前、产后两部分)。 　　第十条 哺乳假 　　自小孩出生至一周岁，女员工(正式员工)每天享有一小时喂奶时间。此假不能累计不能折现。次假可选择推迟一小时上班或提前一小时下班的方式来休。 　　第十一条 丧假 　　正式员工因直系亲属、岳父母、公婆丧亡者，可请丧假3天。 　　第十二条 加班 　　1. 公司不鼓励员工加班; 　　2. 对于必须需要加班的同事，事先需经部门负责人审批; 　　3. 加班时间一次超过8小时(含8小时)以上者，折假一天; 　　4. 加班时符合制度的车费、餐费可报销。 　　第十三条 考勤表编制 　　公司由专人负责编制考勤表，考勤表内容包括：正常工作日、迟到、早退、矿工、年假、病假、事假、其他休假等，每月5日(遇节假日提前)将上月的考勤明细交财务部，以便核算工资。 　　第十四条 其他 　　1. 其他假期均按国家有关规定实行; 　　2. 员工续假，需要重新报批，否则视为旷工; 　　3. 年假、婚假、产假和丧假均只发放基本工资。 　　第八章 财务制度 　　第一节 付款请求 　　第一条 付款请求的目的及用途', 506, NULL, '[\"员工\", \"加班\", \"假\", \"丧假\", \"考勤\", \"小时\", \"正式\", \"均\", \"公司\", \"日\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:23', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:23', '0');
INSERT INTO `document_segments` VALUES ('1955803402671583233', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　第八章 财务制度 　　第一节 付款请求 　　第一条 付款请求的目的及用途 　　公司采购物品或劳务向第三方支付货款或劳务款时。应提前向公司申请，结算方式应尽量采用支票支付，如一次性付款金额超过(含)1,000元，以支票或转账方式支付，为确保如期领到款项，请至少提前3个工作日申请，特殊情况，可具体处理;如一次性付款金额低于1,000元，可以现金方式付款。无论采用何种方式付款，均应提供正规发票。 　　第二条 付款请求申请程序 　　1. 提前填好《付款请求》，请尽可能把内容填写详细，特别是“费用用途”一栏; 　　2. 先由部门负责人签字，后请总经理审批; 　　3. 附上支持单据，例如：报价单，发票，或第三方的付款请求等; 　　4. 财务部确认及现金/支票准备完毕后，通知申请人领取; 　　5. 申请人在得到通知后，与第三方联络结清款项事宜并提供发票; 　　6. 如果部门负责人或者总经理外出，可以采用电话口头询问、电子邮件等形式批准确认。但事后需要补签。特殊情况，具体处理。 　　第二节 工资制度 　　第一条 每月工资于次月10日发放;当月15日之后入职的员工，工资于隔月10日连同次月工资一同发放。 　　第二条 员工工资由基本工资和岗位工资两部分构成，不同级别/岗位的员工工资不同;', 544, NULL, '[\"付款\", \"工资\", \"请求\", \"请\", \"支付\", \"发票\", \"方式\", \"支票\", \"申请\", \"采用\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:23', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:23', '0');
INSERT INTO `document_segments` VALUES ('1955803402755469314', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　第二条 员工工资由基本工资和岗位工资两部分构成，不同级别/岗位的员工工资不同; 　　第三条 依照业务需要和员工个人的表现，公司有权在劳动合同期限内调整员工的职位，并根据职位变化相应调整员工的岗位工资; 　　第四条 试用期工作未满3个工作日的，不予发放任何薪酬。 　　第三节 费用报销 　　第一条 公司无论何种费用报销，均应提供正规发票(经税务局认可，与实际情况相符)，并经由相应权限的主管审核批准后，方能予以报销。否则，未能提供正规发票，公司将不予报销该项费用，由该申请人自行承担费用。 　　第二条 报销方法 　　1. 于每月25~30日将交通费、手机费及其它需要报销的票据粘贴好，认真书写《支出凭单》，经核实无误，并由总经理审批签字后连同本月工资一并发放; 　　2. 每月申报一次。当月内发生的费用，请尽量在其申报期内上报，不要滞后。 　　第三条 外勤交通费 　　1. 日常业务外出、采购、参加培训、参观等，均应尽量以公车、地铁为主;如遇特殊紧急情况需乘坐出租车时应说明原因，并事先征得主管同意。包括：临时、紧急事件、采购、搬运重物或数量大的物品、提取大额现金或重要文件、偏远地方，公共交通极不方便; 　　2.', 508, NULL, '[\"报销\", \"费用\", \"公司\", \"员工\", \"采购\", \"主管\", \"尽量\", \"岗位\", \"业务\", \"需要\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:23', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:23', '0');
INSERT INTO `document_segments` VALUES ('1955803402847744001', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　2. 公司所组织的各项活动，包括部门员工内部和与外来人员联谊、交流活动，除通知可报销的，往返车费一律自负; 　　3. 员工可报销节假日加班超过4小时或工作日晚间加班超过21点的加班车费; 　　4. 员工因公外出统一在行政部领用公交卡并认真填写登记表，如特殊紧急情况乘坐出租车，应在发票背面填写清楚地点及所进行的业务，无涂改; 　　5. 员工报销交通费用时，应根据实际乘车情况如实填写报销单据，如有伪造车程单据、私用公报等情况，将给予严肃处理。 　　第四条 公司电话费 　　由公司统一支付。员工可直接拨打座机电话。联系外地客户和业务时一律拨打IP(190)电话;员工不允许打私人长途电话，如遇特殊情况需向主管申请，获批准后通话时间不得超过5分钟。 　　第五条 手机话费 　　公司部分岗位的员工经过批准后，每月可以报销部分手机话费。员工手机费报销是公司业务的需要，是使公司领导、同事、客户与随时能与该员工联系，在工作时间内，员工不应出现关机、不接电话、手机未冲值等情况，否则不予报销。 　　第六条 邮寄费', 452, NULL, '[\"员工\", \"报销\", \"情况\", \"公司\", \"填写\", \"业务\", \"手机\", \"超过\", \"特殊\", \"客户\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:23', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:23', '0');
INSERT INTO `document_segments` VALUES ('1955803402931630081', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　第六条 邮寄费 　　公司日常业务需要邮寄时，国内邮件均应尽量以平信、印刷品、挂号信为主;有特殊情况需发特快专递时，应经主管审批后，方能邮寄;国外信函一律经主管审批后，方能邮寄。如未经主管审批私自邮寄，将视同私人信件，公司不予支付相应费用。 　　第七条 书籍、杂志、资料费 　　公司员工如业务需要购买书籍、资料等，须先经主管批准后才允许购买。购买后，交由公司登记并统一保管;如未经批准购买的，不予报销该项费用。 　　第八条 交际应酬费 　　各部门交际应酬费、业务联系费、礼品费，先由部门负责人批准后，再经总经理审核，如遇临时情况未经审批就已经宴请，在事后征得部门负责人或总经理同意方可报销，否则不予报销该费用。 　　第九条 加班费 　　员工经主管批准后的加班，周一至周五加班时间超过21点，公司可报销交通费用，同时可报销15元的加班餐费，均需提供正式发票。周六或周日加班可换取同等时间的倒休。 　　第十条 差旅费报销手续 　　1. 出差人员应于出差返回3天内，填写《差旅费报销单》，将差旅票据按顺序和类别粘贴整齐，在每张票据后面注明票据用途及时间，并附《出差申请单》。经本部门经理、财务出纳与行政审核、总经理签字批准后报销; 　　2.', 518, NULL, '[\"报销\", \"公司\", \"批准\", \"主管\", \"加班\", \"时间\", \"费用\", \"审批\", \"邮寄\", \"未经\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:23', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:23', '0');
INSERT INTO `document_segments` VALUES ('1955803403019710466', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　2. 财务部应在收到出差人员报销单据后的7个工作日当中，及时审核报销; 　　3. 实际出差任务、行程或时间与《出差申请单》中申请不一致的，由出差人员详细说明情况，再予以报批。 　　第四节 差旅费用报销 　　(自20xx年6月1日起执行) 　　第一条 全国按出差目的地分为三类地区： 　　l A类地区：京、沪、粤地区的省级城市 　　l B类地区：除京、沪、粤外的省级城市 　　l C类地区：A、B类地区对应的市、县级城市 　　第二条 员工出差时“差旅补贴”包含餐费，实行包干发放;“住宿标准”实行限额内实报实销，超出部分自理;“路程交通费用”实行实报实销。具体标准为： 　　餐补(天) 　　住宿(天) 　　飞机 　　火车 　　轮船 　　长途汽车 　　出租车 　　地铁 　　公交 　　总经理 　　实报实销 　　实报实销 　　实报实销 　　实报实销 　　部门总监 　　A类地区100元;B、C类地区80元 　　A类地区300元;B、C类地区200元 　　普通舱 　　硬卧， 　　动车为二等座 　　普通舱 　　实报实销 　　原则上不提倡坐出租车，特殊情况需事前申请。 　　实报实销 　　部门经理(主管) 　　A类地区90元;B、C类地区70元 　　A类地区200元;B、C类地区160元 　　—— 　　其他员工', 553, NULL, '[\"出差\", \"实报实销\", \"地区\", \"报销\", \"实行\", \"A\", \"B\", \"情况\", \"人员\", \"申请\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:23', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:23', '0');
INSERT INTO `document_segments` VALUES ('1955803403103596546', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　A类地区90元;B、C类地区70元 　　A类地区200元;B、C类地区160元 　　—— 　　其他员工 　　A类地区80元;B、C类地区60元 　　A类地区180元;B、C类地区150元 　　—— 　　第三条 差旅补贴的三餐标准为： 　　【100元】(早)20、(中)40、(晚)40;【90元】(早)15、(中)35、(晚)40;【80元】(早)10、(中)30、(晚)40;【70元】(早)10、(中)30、(晚)30;【60元】(早)10、(中)25、(晚)25。 　　第四条 出差补助天数的计算方法： 　　【出发日补助计算】以有效报销车票或飞机票的准确开车或起飞时间为准：上午9：00前出发的，可享受全天补助;9：00-12：00之间出发的，可享受午餐和晚餐补助;12：00后出发的，则享受晚餐补助; 　　【返回日补助计算】以有效报销车票或飞机票的准确抵达时间为准：上午12：00前抵京的，可享受早餐补助;12：00后抵京的，可享受早餐和午餐补助;18：00后抵京的，则享受全天补助; 　　第五条 出差期间若需业务招待费等开支的，须事先向主管经理申请并有额度限制的批示; 　　第六条', 497, NULL, '[\"补助\", \"出发\", \"享受\", \"出差\", \"计算\", \"全天\", \"上午\", \"前\", \"地区\", \"为准\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:23', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:23', '0');
INSERT INTO `document_segments` VALUES ('1955803403221037057', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　第五条 出差期间若需业务招待费等开支的，须事先向主管经理申请并有额度限制的批示; 　　第六条 住宿标准：原则上按照标准实施，若需要关系公司形象的出差(如商业谈判、签署合同等)需要入住三星级酒店及以上的，事前需要主管经理及CEO的特批。单次长时间出差(原则上30天以上)或多人次出差，而客户方不提供住宿的，应选择最经济的驻点，费用不超出100元/天，也可考虑在当地租房; 　　第七条 出差交通工具的选择：原则上部门总监及以上职务的可乘坐飞机，且坐车时间在8小时以内的，应选择火车或汽车作为交通工具。其余员工出差应优先选择乘坐火车或汽车; 　　第八条 乘坐飞机的特殊情况规定：(1)业务紧急，必须乘飞机;(2)路途长，乘火车时间超过30小时;(3)机票打折幅度大，折后机票价格(含机场建设费和燃油附加费)比火车硬卧下铺票价不超过50元。遇以上特殊情况，须经主管经理及CEO批准方可; 　　第九条 机票由公司行政部门统一购买，若遇 特殊紧急情况需个人购票的，报销时按打折后的实际价格填写，如有弄虚作假，一经发现将加倍扣还，并作严肃处理; 　　第十条', 473, NULL, '[\"出差\", \"火车\", \"选择\", \"特殊\", \"主管\", \"经理\", \"时间\", \"原则\", \"需要\", \"应\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:23', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:23', '0');
INSERT INTO `document_segments` VALUES ('1955803403309117441', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　第十条 若行政部门已订好火车票或机票，因个人原因不能按时乘坐时，产生的一切费用由个人承担; 　　第十一条 如果出差期间由客户单位提供食宿的，不再给予报销，不得自行安排，否则费用自理;如果客户单位只提供住宿，则仍然按标准报销差旅补贴; 　　第十二条 如果出差期间未住酒店，而自己解决住宿的(如住在亲戚、朋友或家里)，按住宿标准给予50%的奖励，同时仍然享受差旅补贴; 　　第十三条 如果出差期间遇上当地因展会期间住宿费用上浮的，标准也相对应可以酌情上浮，但上浮标准不得超过原来的50%; 　　第十四条 公司统一组织去外地参加展会或活动，期间由公司统一安排食宿，如自行另外安 排食宿，费用自理; 　　第十五条 两人同时出差去同一个地方的，同性别的要求住同一房间。如自行单独住宿的，费用自理; 　　第十六条 员工乘出差之便，事先经主管经理及CEO批准就近回家探亲或旅游的，其绕道费等多开支部分由员工自理。员工出差期间，非因工作需要产生的一切费用，均由个人自理; 　　第十七条 出差香港、中国台湾、国外等报销标准依具体情况另行制定。 员工手册范本 篇5', 474, NULL, '[\"出差\", \"期间\", \"标准\", \"自理\", \"费用\", \"住宿\", \"员工\", \"个人\", \"报销\", \"食宿\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:23', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:23', '0');
INSERT INTO `document_segments` VALUES ('1955803403397197825', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　第十七条 出差香港、中国台湾、国外等报销标准依具体情况另行制定。 员工手册范本 篇5 　　导购的服务并不只是销售的一个环节，而应该是完善周到的一系列服务过程：如何引导顾客选购商品，与顾客沟通如何融洽，销售方式如何才能到位，顺畅，从点到面演绎服务优美乐章，给予顾客最佳的购物感觉 　　销售前：整理货品，清洁店堂，准备好店内音乐，保持最佳的状态迎接顾客的光临，做好准备工作后，则选择面对客流的位置笑迎顾客 　　1.信心：信心是一种无形的品质，不是吃一片药就能得到，但可以被开发出来，是对未来重要的投资。 　　2.爱心：要视同顾客为亲人，朋友，要用你的服务让顾客感受得到。 　　3.耐心：在进行销售时，在把握顾客可否购买的前提下，一定要十分耐心，周到有一种韧劲。 　　4.恒心：不甘失败，要一件一件的继续努力。 　　5.抓住顾客的心：掌握顾客的心理动态，下一步想要做什么，需要什么。 　　1.寻找对象：找出希望对其推销服装的人。 　　2.了解情况：了解顾客真正需要什么，并判断出他们的购买能力。 　　3.展示产品并说明：选择最恰当的时机战士产品的最大优点，使顾客想要试穿。同时还要用简洁的语言介绍服装面料，板型的优点。', 508, NULL, '[\"顾客\", \"销售\", \"服务\", \"准备\", \"得到\", \"周到\", \"购买\", \"耐心\", \"选择\", \"想要\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:23', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:23', '0');
INSERT INTO `document_segments` VALUES ('1955803403535609857', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　4.答疑解难并试穿：克服任何阻碍购买的因素和问题，并迅速更换试穿服装的种类。 　　5.购买：顾客交款的时刻。 　　6.继续跟进：进行多次推销，或培养顾客对品牌的忠诚度。 　　7.建立档案：办理会员卡，请顾客留言，建立客户档案。 　　◆在这个阶段，要了解顾客需求—主动提出问题并仔细聆听，了解顾客的需要后就能鉴别顾客类型—专家型、新手型，对顾客进行开放式问答，让顾客说话，便于了解顾客更多的需求，观察顾客的身体语言，以判断其是否有购买的欲望，仔细聆听，给予顾客希望，并最后确认顾客的需要 　　◆在接触顾客的同时也就是主动接受购买信号，现在的消费者喜欢自由的购物气氛，因为当我们与顾客打完招呼后，应先留一定空间给顾客，让顾客在没有压力的环境下自由选择，当然我们的目光一定要留意顾客，随意接受顾客的购物信号，通过眼睛观察，耳朵聆听，嘴巴询问等途径来发现顾客的需要，而不是总站在顾客身边 　　◆在购买心理的留意、兴趣、联想、欲望、比较、信任、决定、满足', 424, NULL, '[\"顾客\", \"购买\", \"聆听\", \"需要\", \"了解\", \"欲望\", \"问题\", \"进行\", \"一定\", \"留意\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:23', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:23', '0');
INSERT INTO `document_segments` VALUES ('1955803403623690241', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　◆在购买心理的留意、兴趣、联想、欲望、比较、信任、决定、满足 　　八个阶段中，当顾客对商品表示“兴趣”时便接近，这就是接近的理想时机，巧妙的接近，掌握顾客的心理，加以适当的说明和建议，引导顾客进入正面的”联想“，就比较容易唤起顾客的购买”欲望“，但是要准备把握顾客的心理过程发展这一阶段有赖于导购员长期的观察和体验 　　1、当顾客注视某一商品时 　　当顾客仔细观察某一商品时，就是对该商品产生了”注意“和“兴趣”，而且可能很快地会将心理过程转移到”联想“阶段，所以一定要把握时间，开始接触应注意几点： 　　A与顾客打招呼时，最好站在顾客的正面或侧面 　　B在顾客打招呼时，其语言不能仅限于几句口头语上，应做更进一步的表达 　　C当顾客的心理进入”联想“阶段时，千万不能说出破坏意境的语言：“光临”等，而是讲一些帮助顾客联想的话来引导，例如：“这个款式是现在最流行” 　　2、当顾客用手触商品时 　　顾客以手接触商品，表示顾客已经对此商品产生了兴趣，并且加以确定是不是自己想的，此时正是导购接近并询问“感觉如何”的好时机。但若在顾客接触商品的瞬间就询问，会吓到顾客，应隔一段时间之后，再以温和的声音询问', 502, NULL, '[\"顾客\", \"联想\", \"时\", \"商品\", \"阶段\", \"兴趣\", \"心理\", \"询问\", \"接触\", \"接近\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:23', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:23', '0');
INSERT INTO `document_segments` VALUES ('1955803403690799105', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　3、当顾客表现出寻找商品的状态时 　　遇到这样的状况，应尽早亲切的回应顾客：“有什么需要我为您服务呢?”，并请顾客将他寻找目标的要求说给自己听，并迅速做出反应，为顾客拿取商 　　4、当与顾客的视线相遇 　　顾客在购买上需要建议时，大多会寻找导购，因此，导购要把握这个机会，以微笑说”光临“并立刻走向顾客 　　5、当顾客与同伴交谈时这种情形正是顾客对商品产生兴趣的明显行为，此时，多半会与同伴交谈讨论，如果导购上前说明和建议，也许特别容易产生效果 　　6、当顾客将手提袋放下时 　　这也是对商品注意而产生兴趣的行动之一，导购应自信地对顾客说”光临，这是我们新上市的款式，共有x种款色“，说这些时，要在顾客放下手提袋一段时间后，再接近较好 　　7、当顾客探视橱窗商品时 　　若和前六项比较，此时可能会有些过早，但在众多竞争对手的专卖店商业街上，要有”先下手为强“的精神，尽早接近顾客，引导顾客进店，顾客一般是很难拒绝导购的诚意，但要把握好度，不要让顾客反感 　　8、当顾客匆匆入店，四处寻找时', 446, NULL, '[\"顾客\", \"时\", \"说\", \"购\", \"导\", \"商品\", \"会\", \"寻找\", \"产生\", \"建议\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:23', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:23', '0');
INSERT INTO `document_segments` VALUES ('1955803403741130754', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　8、当顾客匆匆入店，四处寻找时 　　顾客匆匆进入店铺，像在寻找什么商品时，表明顾客此时需要快速完成购买过程并买到所要的商品，导购应当立即迎上前去，询问顾客需要，高效地帮助顾客找到所要商品，记得：动作要快 　　9、当顾客取下商品仔细打量并在自己脚上试穿时 　　这是应该及时肯定顾客的选择，应该此时顾客已经产生兴趣，在心中开始联想、衡量、考虑，而这次需要肯定他的选择使其更有信心购买，但不要过于过于唐突，自然地走近顾客，用赞赏的口吻道：“你真有眼光，这是现在最热销的商品……” 　　10、当顾客直接拿商品询问价钱时 　　这是代表顾客对商品本身满意，只是在顾及自己的购买能力，此时，导购应该转移顾客的顾虑，将价格问题转向商品性能上，可以告诉顾客该商品的畅销程度以及某种有价值的特性 　　◆当已经接近顾客时，就要根据当时的具体情况主动与顾客攀谈起来，但要找到一个恰当的切入点，一旦发现顾客发出购买信号，就立刻主动上前提供服务推荐商品', 414, NULL, '[\"顾客\", \"商品\", \"时\", \"购买\", \"需要\", \"应该\", \"上前\", \"主动\", \"导\", \"购\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:23', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:23', '0');
INSERT INTO `document_segments` VALUES ('1955803403787268097', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　◆推荐商品是将顾客的需求与商品的益处联系起来，让顾客舒心的接受你的建议，注意要实事求是，不能夸大其辞，避免使用不确定语言：如“大概、可能、也许……”首先推荐顾客想要的商品，试穿商品，尽可能让顾客触摸商品，感受到商品的价值，并信任产品的质量 　　◆在推荐的过程中，你要详细的向顾客介绍商品，让顾客更多地了解商品，刺激其购买欲望的产生，所以在推荐商品时，导购应将商品拿在手上给顾客展示介绍，并让顾客接触到商品，全面地了解到商品的价值 　　◆当顾客选好商品后，应建议顾客亲自感受一下，试穿商品， 　　鞋品，则拿出备好的一次性的袜子，这样既卫生又让顾客感觉服务的周到 　　◆询问顾客适合的尺码，迅速为顾客拿取他需要的商品，半蹲跪式进行服务 　　◆在店里人多的时候，试穿商品时，应注意拿取商品的双数，以免丢失 　　◆顾客一般会比较不同商品的感觉，这时需要做到的就是耐心服务，尽量满足其需要，不要有不耐烦的表情。 　　◆在帮助顾客的同时，要尽量把是商品的特性，优点和好处再次一一介绍给顾客，并对顾客的选择加以肯定，此时，他正在亲身感受', 463, NULL, '[\"顾客\", \"商品\", \"推荐\", \"服务\", \"需要\", \"试穿\", \"介绍\", \"注意\", \"建议\", \"感觉\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:23', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:23', '0');
INSERT INTO `document_segments` VALUES ('1955803403841794049', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　商品和比较商品的感觉，而你的肯定会增加其信心，从而促进他的选择，从而达成销售，例如：“你看鞋穿上去感觉真的很好，你很有眼光，这鞋比较适合您的风格，而且这是今天最流行的款式……” 　　◆试穿的过程也就是真正体现出你亲善服务的过程，服务质量的高低最直观的体现在试穿过程中，所以，让顾客120%的满意就需要你耐心，热心和细心，多做一点，主动一点，耐心一点，一定会得到顾客的回应 　　◆附加销售的目的是在于为顾客着想，关心顾客 　　◆在顾客购买某商品后，导购可以适时向顾客推荐相关的商品，但切记，不可使顾客有强制购买的感觉，否则他会对你之前服务的真诚度表示怀疑，如果发现顾客有不悦的情绪或遭到顾客拒绝，就立刻停止连带推荐 　　◆附加销售一般可以为： 　　购主打商品，可推荐相关商品 　　例如：购正价鞋，可以推荐特价鞋品 　　购鞋品,可以推荐护理用品或则包 　　◆要记得我们的服务是为了让顾客满意，满足其需求，因此在进行连带销售时要从顾客的利益出发，例如：“我感觉你买的这双鞋很适合您的风格，如果能配一个包效果还要好一些等……”，从顾客的角度为其着想，自然的促进销售', 480, NULL, '[\"顾客\", \"销售\", \"鞋\", \"服务\", \"感觉\", \"推荐\", \"会\", \"商品\", \"过程\", \"购\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:23', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:23', '0');
INSERT INTO `document_segments` VALUES ('1955803403892125698', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　◆可以借助促销活动进行连带销售，例如：“白领丽人，近期我们专卖在进行满送活动，您今天只要再加就能得到赠送…这样不更加实惠吗?” 　　◆促销技巧的高低往往能在连带销售环节展示出来，一名资深而优秀的导购能使顾客满意的听取他的建议，而如果还没有把握顾客心理，就建议不要随意进行连带销售 　　◆当顾客进行决定前是会经过再一番考虑的，需不需要，划不划算，当顾客考虑时，导购应及时再次肯定他的选择，如果几位顾客相互讨论，意见趋于一致时，导购可以在一旁旁听，不要插嘴，听听顾客商量的结果，然后再纠正其想法，例如：其中的一个顾客说：“我上次买的就是这种皮面的，一下就烂掉了……”，此时，导购应自信的答复顾客：“你放心，同一种的材料也会优劣之分的，我们商品在质量上有“三包”规定的，绝对保证商品质量，同时，我们的商品都是选用的优质材质以保证品质，你绝对可以放心选购……” 　　◆在顾客做最后购买决定时，导购只有建议的权力，没有替顾客做决定的权力，如果为顾客做了决定，如果回去后顾客有一点不满意，往往会把责任推卸到导购身上，要求退货或换货 　　◆在顾客决定购买时，导购应主动讲解一些相关的商品保养知识以后介绍相关的售后服务', 503, NULL, '[\"顾客\", \"导\", \"购\", \"再\", \"商品\", \"决定\", \"会\", \"时\", \"进行\", \"连带\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:23', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:23', '0');
INSERT INTO `document_segments` VALUES ('1955803403946651650', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　◆在顾客决定购买时，导购应主动讲解一些相关的商品保养知识以后介绍相关的售后服务 　　◆当顾客决定购买时，应该再次确定顾客的需求，并适度的赞许顾客，当顾客决定购买时，迅速并准确地给顾客开票或者指引顾客明确的交款处，在等待顾客交款时，将商品的包装好，等待顾客回来。 　　◆为了建立良好、稳固的顾客关系，沟通新顾客，留下老顾客，建顾客档案是店铺与顾客长久联系的一项重要环节。为顾客提供档案服务，争取顾客自愿填写顾客资料卡，在需要的时候及时与顾客取得联系，例如：‘真的很抱歉，你需要的那个款式已经断码了，麻烦您留下联系方法，到货后我立即通知您……“，在方便顾客购物的同时，对于老顾客，建立详细的资料档案，经常与他们联系，如：节假日问候，新品上市等，这些能让顾客感受到服务的细致之处，同时又是店铺留住顾客的巧妙一招，坚持对顾客诚信周到的服务，长期保留、维护顾客信息资源，同时也可以根据顾客资料了解消费群体的消费特征以及服务所需达到的目标。 　　◆商品单价确认 　　商品折扣确认 　　商品数量和总价确认 　　应收顾客金额、信用卡付款数额确认 　　顾客付款金额确认，收银员要”唱收唱付“ 　　收银台收款确认', 498, NULL, '[\"顾客\", \"商品\", \"服务\", \"确认\", \"时\", \"联系\", \"档案\", \"留下\", \"决定\", \"购买\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:23', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:23', '0');
INSERT INTO `document_segments` VALUES ('1955803403996983297', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　应收顾客金额、信用卡付款数额确认 　　顾客付款金额确认，收银员要”唱收唱付“ 　　收银台收款确认 　　应回找顾客金额、信用卡，销售票据确认 　　收银员可以适时的称赞顾客选购的商品 　　◆送客是最后的服务机会，若马虎粗糙，就无法再弥补，顾客离开如果带着不满情绪，他是不会再次光临的，对于刚入店的顾客却还有机会 　　◆欢送顾客时依然保持微笑的表情，顾客留下宝贵的意见和建议 　　◆切记，送别顾客的招呼比进来时更为重要，也许有些顾客只是随便逛逛或者是没有选中中意的商品，如果你在他离开是冷落了他，他会觉得你服务的目的是只是为了销售，服务就不够真诚，所以，不管是在店内已经消费还是没有消费的顾客，只要是离开店时都应该说一声：”下次光临“ 　　◆PCA原则：PleaseComeAgain,再次光临，80%的营业额是由 　　20%的老顾客创造的，因此要用优质完善的服务用心维护这20%的\' 　　老顾客，吸引新顾客加入这20%的队伍里，让更多的人再次光临白领丽人 　　◆将顾客送到门口，同时鞠躬道：“谢谢惠顾，下次光临”，亲切，有礼貌地目送顾客离去，这样送客方式必定能打动顾客的心。 员工手册范本 篇6 　　第一章总则', 505, NULL, '[\"顾客\", \"光临\", \"服务\", \"%\", \"离开\", \"再次\", \"确认\", \"商品\", \"收银\", \"下次\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:23', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:23', '0');
INSERT INTO `document_segments` VALUES ('1955803404110229505', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '员工手册范本 篇6 　　第一章总则 　　1.1薪酬管理宗旨 　　1.1.1 本制度是公司关于薪酬的纲领性文件，公司所有与薪酬相关的制度、活动和行为都必须遵照并服从于本制度。 　　1.1.2 本制度旨在为员工提供公平、合理的劳动报酬，以最大程度发挥薪酬的激励作用。 　　1.2 薪酬管理原则 　　1.2.1 合法原则。严格按照国家相关法律法规设计薪酬体系(最低保障工资、加班工资及社会保险等)。 　　1.2.2 价值导向原则。根据公司发展要求以及各岗位对公司价值贡献的大小，进行薪酬分配。 　　1.2.3 市场化原则。参照深圳当地劳动力市场工资和行业状况指导价合理确定薪酬标准。 　　1.2.4 体现员工能力差异原则。薪酬与其个人能力挂钩，相同岗位的员工，能力不同，薪酬不同。 　　1.2.5 绩效导向原则。薪酬与其工作业绩挂钩，相同岗位的员工，工作业绩不同，薪酬不同。 　　1.2.6 与公司经济效益和支付能力相结合原则。薪酬水平的确定必须保证公司有合理利润积累。 　　1.3薪酬分配依据 　　公司薪酬分配的依据是：岗位价值、员工能力、工作绩效和市场水平。 　　1.4 适用范围 　　本手册适用于公司除生产一线员工、副总经理、部门总经理、公司总经理以外的其它所有员工。 　　第二章薪酬体系 　　2.1 薪酬体系 　　该手册适用范围内所有员工的薪酬体系均为结构工资制。 　　2.2 薪酬结构 　　2.2.1', 602, NULL, '[\"酬\", \"薪\", \"公司\", \"员工\", \"原则\", \"合理\", \"能力\", \"价值\", \"工资\", \"岗位\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:23', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:23', '0');
INSERT INTO `document_segments` VALUES ('1955803404160561153', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　第二章薪酬体系 　　2.1 薪酬体系 　　该手册适用范围内所有员工的薪酬体系均为结构工资制。 　　2.2 薪酬结构 　　2.2.1 公司的薪酬结构包括岗位工资、年度奖金、加班工资、津贴和保险五大部分。津贴包括住房补贴、膳食津贴、话费津贴；保险包括医疗保险、工伤保险、养老保险、生育保险。 　　2.2.2 岗位工资 　　1)岗位工资是指每个不同岗位的基础工资，岗位工资是员工薪酬构成的基本组成部分。 　　2)岗位工资按月发放，即员工年度岗位工资/12 　　2.2.3 年度奖金。年度奖金是根据公司、部门和员工的业绩而计付的工资，首先根据部门绩效考核结果得出部门年度实得奖金，然后根据部门内员工年度考核结果对部门年度实得奖金进行分配。 　　1)部门年度奖金总额计算办法： 　　部门年度实得奖金总额(B)= A ×部门年度岗位工资总额 　　a)A =部门年度考核分数/100=(公司年度考核分数+部门总经理年度业绩考核分数)/100(0≤A≤0.2) 　　2)员工年度实得奖金计算办法： 　　(员工标准年度奖金/12)×实际服务时间×员工绩效考核分数员工年度实得奖金= ×B∑(员工标准年度奖金/12)×实际服务时间×员工绩效考核分数 　　a)B =部门年度实得奖金总额；', 535, NULL, '[\"员工\", \"年度\", \"工资\", \"岗位\", \"奖金\", \"部门\", \"包括\", \"酬\", \"薪\", \"实\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:23', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:23', '0');
INSERT INTO `document_segments` VALUES ('1955803404210892801', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '×B∑(员工标准年度奖金/12)×实际服务时间×员工绩效考核分数 　　a)B =部门年度实得奖金总额； 　　b)如员工在发放年终奖之前离职，将不享受年终奖。如为新入职员工，将按照其当年在公司的服务时间(入职时间不迟于10月1日，10月1日之后入职的不享受年终奖)以一定的比例分配。 　　2.2.4 加班工资 　　1)加班工资是公司为员工超过规定的劳动时间而计付的工资，根据工作需要，符合公司相关制度规定的员工加班将付给其加班工资。 　　2)如当月加班预计超过36个小时，则需要部门经理提出，并经部门总经理审批后，报人力资源部备案。 　　3)公司采用加班时数上限封顶，每月加班时数在36小时之内的.，按公司规定支付加班工资；超过36小时(含36小时)由部门安排调休，调休一个月内有效，不做累计；同时，岗位工资在6000元及以上的员工，加班只能安排一个月内调休，不做累计。 　　4)与生产直接相关需要倒班的岗位，按实际发生加班时数计算，但如果岗位工资与加班工资之和超过6000元的，超出部分不计加班费，由部门安排调休，调休一个月内有效。 　　5)加班采用分级审批，具体如下： 　　6)加班工资计算办法： 　　2.2.5津贴', 509, NULL, '[\"加班\", \"工资\", \"员工\", \"公司\", \"部门\", \"时间\", \"需要\", \"超过\", \"小时\", \"入\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:23', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:23', '0');
INSERT INTO `document_segments` VALUES ('1955803404261224449', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　5)加班采用分级审批，具体如下： 　　6)加班工资计算办法： 　　2.2.5津贴 　　1)住房补贴。公司免费为职员提供住宿，职员也可根据自己实际情况申请外宿，公司将给予一定数额的补助。具体标准如下： 　　2)膳食津贴。公司为所有员工提供膳食，员工可自由选择是否在公司饭堂就餐。外宿职员可享受104.5元膳食津贴，内宿者可享受在240元膳食津贴。 　　3)话费津贴。需经常使用个人移动电话联系工作者，为不致影响正常工作，公司给予一定的话费津贴；享受话费津贴人员每天从早上8：00至晚上10：00必须保持开机状态，某些岗位人员根据工作需要应每天保持24小时开机。如果实际因公支出话费超过规定标准，根据实际话费清单报销超出部分。 　　2.2.6 社会保险 　　1)社会保险。按照国家规定，公司为员工缴纳养老保险、医疗保险、工伤保险和生育保险。 　　2)社会保险缴纳基数以深圳当地相关政策执行。 　　第三章薪酬确定 　　3.1岗位价值评估 　　3.1.1岗位价值评估的目的是通过一定的评估模型，将所有岗位在公司内部的重要程度进行排名。岗位价值评估是解决内部公平性的重要手段。', 485, NULL, '[\"公司\", \"津贴\", \"话费\", \"岗位\", \"实际\", \"一定\", \"社会保险\", \"膳食\", \"具体\", \"工作\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:23', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:23', '0');
INSERT INTO `document_segments` VALUES ('1955803404315750402', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　3.1.2岗位价值评估结果是设计岗位薪酬层级关系图的重要依据。《薪酬层级关系图》见附件。 　　3.1.3当公司进行重大组织调整的时候，必须重新对所有岗位的价值进行评估。 　　3.1.4每隔2～3年，公司将进行一次岗位价值评估，从而保证岗位价值的科学性和合理性。 　　3.2员工薪酬层级定位 　　员工评价与定位是保证员工能力与薪酬水平相平衡的关键环节，员工评价的依据是岗位任职资格。 　　3.3薪酬水平确定 　　3.3.1公司总体薪酬水平的确定的依据是同期市场水平和企业自身的支付能力。 　　3.3.2 20xx～20xx年各层级基本年薪见附件1 　　3.3.3基本年薪=年度岗位工资+年度奖金。 　　3.4薪酬总额预算 　　人力资源部在每年1月30日前对上年度薪酬系统的具体实施情况及薪酬总额的发放情况进行总结分析，在此基础上完成《年度薪酬预算报告》的编制工作，并以绝密文件的形式提交给公司总经理审批。 　　第四章薪酬实施 　　4.1薪酬计算与发放 　　4.1.1实行结构制工资员工薪酬构成为：岗位工资、年度奖金、加班工资、津贴福利和社会保险。 　　4.1.2岗位工资=年度岗位工资/12', 496, NULL, '[\"酬\", \"薪\", \"岗位\", \"年度\", \"公司\", \"进行\", \"员工\", \"层级\", \"水平\", \"工资\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:23', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:23', '0');
INSERT INTO `document_segments` VALUES ('1955803404370276354', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　4.1.2岗位工资=年度岗位工资/12 　　4.1.3年度奖金。实行结构制工资员工的年度奖金是根据员工本人的业绩状况和公司业绩状况决定的，具体见2.2.3. 　　4.2薪酬变动和调整 　　4.2.1薪酬水平调整。公司根据自身盈利状况和外部市场变化因素，每2～3年调整一次薪酬水平。 　　4.2.2员工个人薪酬层级的调整分为两种：常规性调整和非常规调整。员工薪酬层级调整分为层级晋升、层级不变动、层级降低三种。常规性调整是指由人力资源部每年4月份根据员工上年度考核结果进行的调整。非常规调整是指因为员工试用期满、职位变化、受到公司特别嘉奖或处分等其他原因所进行的薪酬层级的调整。具体调整细则见6.2. 　　4.3薪酬管理权限 　　4.4员工薪酬定位 　　4.4.1新员工在试用期内可按该岗位最低层级薪酬的80%，转正后由直接上级和人力资源部根据岗位任职资格进行评估定位。 　　4.4.2员工跨层级晋升时，在试用期内享受新岗位最低层级薪酬的80%(新岗位最低层级薪酬的80%低于原岗位的标准薪酬，按原岗位薪酬计发)，转正后由直接上级和人力资源部根据岗位任职资格进行评估定位。', 487, NULL, '[\"员工\", \"薪\", \"酬\", \"调整\", \"岗位\", \"层级\", \"进行\", \"状况\", \"试用期\", \"人力资源部\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:23', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:23', '0');
INSERT INTO `document_segments` VALUES ('1955803404420608002', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　4.4.3当员工被降职时，按照降职后的新岗位由人力资源部重新进行评估，确定其薪酬层级。 　　4.4.4当员工因为工作关系(公司需要)发生平调时，采取就高不就低的原则确定其薪酬层级。 　　4.4.5当员工因不称职而发生平调时，由人力资源部按照岗位任职资格进行评估定位。 　　4.5工资发放相关规定 　　4.5.1工资发放时间 　　1)岗位工资的发放时间：员工岗位工资发放采用当月考勤，下月发放的方式，发放时间为每月15号左右(节假日顺延)。 　　2)年度奖金发放时间：下年度4月份发放。 　　4.5.2个人所得税和保险：个人所得税依据国家有关部门的规定执行，职员以其基本工资的百分之六十计，如金额超过1600元/月，个人所得税和保险在工资发放时由财务部按国家规定代扣代缴。 　　4.5.3工资的保密性：所有数据对外部企业或竞争对手来说，都是严格保密的。对于薪酬外泄的、或相互打听工资而造成负面影响的，一经核实，对当事人视情节严重程度予以行政处罚。 　　4.5.4当员工对自己工资产生疑义时，可以直接向人力资源部提出复核。 　　第五章附则', 469, NULL, '[\"工资\", \"发放\", \"员工\", \"规定\", \"人力资源部\", \"薪\", \"酬\", \"岗位\", \"时\", \"个人所得税\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:23', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:23', '0');
INSERT INTO `document_segments` VALUES ('1955803404470939649', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　4.5.4当员工对自己工资产生疑义时，可以直接向人力资源部提出复核。 　　第五章附则 　　5.1本手册自20xx年5月1日起正式实施，与薪酬相关的其它规定、制度同时作废。 　　5.2本手册由人力资源部起草，并负责监督实施。 　　5.3本手册最终解释权属人力资源部。 员工手册范本 篇7 　　公司员工手册 　　公司员工手册范本目录 　　一、公司的八项基本原则……………………………………………………………3 　　二、聘用规定…………………………………………………………………………4 　　三、入职规定…………………………………………………………………………4 　　四、工资报酬…………………………………………………………………………5 　　五、工作时间及法定假期……………………………………………………………5 　　六、福利………………………………………………………………………………6 　　七、合同解除…………………………………………………………………………8 　　八、工作纪律…………………………………………………………………………9 　　九、财务管理…………………………………………………………………………11', 509, NULL, '[\"人力资源部\", \"规定\", \"本手册\", \"实施\", \"工资\", \"工作\", \"员工\", \"公司\", \"时间\", \"报酬\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:23', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:23', '0');
INSERT INTO `document_segments` VALUES ('1955803404525465601', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　九、财务管理…………………………………………………………………………11 　　十、奖罚规定…………………………………………………………………………13 　　标准企业员工手册|公司员工手册范本 　　一. 公司的八项基本原则 　　1.1客户原则 　　客户永远是对的—名人员工在与客户交往时一定要牢牢切记!客户是名人的衣食父母,须绝对尊重,尽心服务。名人员工无论对待任何客户，必须耐心、友善、诚恳、负责任，珍惜客户的每一分钱。名人员工必须时刻保持危机感，齐心协力地用更好的服务全力争取客户。 　　1.2实效原则 　　“做实效的网站”是名人网络的公司的使命。名人的一切活动必须永远围绕做实效的事情这一标准进行;做实效的事情必须深入名人员工心中;做实效的事情必须成为名人员工的行为准则。 　　1.3敬业原则 　　敬业精神—敬业乐业是名人网络人的必备素质。名人网络人对人对事必须有责任感。名人网络人对每一项业务必须充满激情，激发智慧，勤奋工作，不断创新，决不言输，做到更好。 　　1.4团队原则', 443, NULL, '[\"名人\", \"必须\", \"员工\", \"客户\", \"原则\", \"实效\", \"网络\", \"做\", \"公司\", \"服务\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:23', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:23', '0');
INSERT INTO `document_segments` VALUES ('1955803404621934594', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　1.4团队原则 　　团队精神—协作、沟通、配合、协调一致地达成团队的共同目标，团队的利益高于一切，是名人网络人的行为准则。名人所有员工都是名人大团队中的一员，人格平等，分工合作，维护团队利益，为团队的集体荣誉共同奋斗不惜。 　　1.5文明原则 　　名人网络人是文化人，有教养的、文明的人。名人特别强调诚实正直，尊重他人，心胸开阔，坦诚相处，互帮互助。名人倡导礼貌行为，待人接物，必具礼貌态度，用礼貌语言，采取礼貌行为。 　　1.6勤俭原则 　　勤俭节约是中华民族的美德。名人网络人应尊重人的智慧、爱惜财物、决不浪费。一点一滴的财力、物力、人力的浪费和损害公私财物都是可耻的行为。 　　1.7环境原则 　　名人网络是每一位员工共有的事业空间，任何个人偏好或行为均不得影响他人的工作状态、创作气氛及身心健康，不得有损公共环境。工作时间聊天睡觉，室内吸烟，桌面乱扔乱放杂物等行为一律禁止。 　　1. 8事业原则 　　名人网络人将互联网业看作是一种事业，而不仅仅是当作一种职业。名人网络人必须努力学习、相互吸取、取长补短、积极进取、不断提升，逐步提高自身的素质修养。 　　二. 聘用规定', 491, NULL, '[\"名人\", \"行为\", \"网络\", \"原则\", \"团队\", \"事业\", \"环境\", \"财物\", \"尊重\", \"工作\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:23', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:23', '0');
INSERT INTO `document_segments` VALUES ('1955803404668071937', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　二. 聘用规定 　　2.1按本员工手册中的条款和条件，公司聘用员工，员工接受聘用。 　　2.2受聘者必须如实填写“员工登记表”的每一项内容(女员工须将个人的婚姻状况、生育计划如实反映，作为公司聘用安排的参考)并贴上照片，入职时连同身份证、学历、有关职称等复印件(交验原件)及履历交行政人事部处理存档。 　　2.3员工受聘期间，分别按试用期和聘用合同规定领取薪金。 　　2.4员工应把全部工作时间和精力完全投入并努力履行其职责。 　　2.5公司根据需要分配各员工的工作并保留随时调整的权利。 　　三. 入职规定 　　3.1培训 　　3.1.1新员工入职时由行政人事部安排新员工入职培训，行政人事部负责公司架构、制度、守则及一般工作程序的讲解培训;运营部负责公司运作流程的讲解培训。 　　3.1.2部门经理(或主管总监)负责部门的工作程序、作业操作规范及其职位描述的培训。 　　3.1.3公司负责为员工提供适当的在职专业技能培训。 　　3.2试用转正 　　3.2.1所有新员工，试用期最多为三个月，具体由公司视其工作表现或其实际需要而定。 　　3.2.2试用期满考核', 483, NULL, '[\"员工\", \"公司\", \"工作\", \"培训\", \"聘用\", \"负责\", \"试用期\", \"职\", \"人事部\", \"入\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:23', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:23', '0');
INSERT INTO `document_segments` VALUES ('1955803404726792194', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　3.2.2试用期满考核 　　3.2.2.1试用期结束时，试用期新员工按照公司规定的试用期考核办法办理考核手续，如果公司认为试用人员合格，则通知试用人员转为正式员工，双方签订正式聘用合同，合同期由入职本公司之日起计。 　　3.2.2.2试用期满考核办理程序：试用新员工提出试用期满考核申请，经总监同意签批后→去行政人事部领取试用期考核表并认真填写→交行政人事部安排考核面试→总监签署考核意见→总经理审批→行政人事部行文书面通知结果。 　　3.2.3如果试用人员在试用期内被证明不符合录用条件，公司须在三个月内通知试用人员不被聘用及其理由。 　　四. 工资报酬 　　4.1工资 　　4.1.1公司将按双方签订的聘用合同规定支付给员工月薪。 　　4.1.2员工工资按月支付，发薪日为下月10日。 　　4.2加班 　　4.2.1公司有权要求员工加班工作，实际加班工时作为当月的工作业绩和季度团队奖历分配的依据之一。 　　4.2.2员工加班超过晚上10∶00时，可另报销回家单程的士车费，但不能与其他因公市内交通费填在同一张报销单上。', 464, NULL, '[\"公司\", \"员工\", \"试用期\", \"考核\", \"试用\", \"加班\", \"人员\", \"行政\", \"人事部\", \"聘用\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:23', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:23', '0');
INSERT INTO `document_segments` VALUES ('1955803404781318146', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　办理程序：填写报销单→部门总监签字→行政人事部经理审核→财务部会计签字→总经理签字→出纳处报销。 　　4.2.3专业部门员工加班，由品牌部统一填写“加班单”，并报行政人事部备案。员工加班时间超过晚上8点以后，每超过一小时，第二天上班时间可延后一小时，凌晨二点以后，可于第二天下午1∶40上班。但须于晚上加班完毕前安排好自己的所有工作，写出说明贴于公司告示牌上，以便查找资料和安排后序工作。 　　4.3双薪 　　4.3.1作为奖励，在本公司工作一年以上的员工年终可享受双薪。 　　4.3.2工龄六个月以上的员工，即当年6月31日以前(包括6月31日)入职且当年12月31日在岗上班的员工，不足12个月者，则年终双薪按实际工作期限折算。 　　4.3.3在本公司工龄六个月以下的员工，即当年6月31日以后入职的员工，不享受当年双薪。 　　4.3.4双薪按员工年终当月的基本薪金计算，并以公历年度为准，只计当年。 　　4.4所得税 　　4.4.1员工领取工资和奖金、各种补贴等其它报酬，有义务向国家缴纳个人所得税。公司按照国家税法规定，代税务部门每月从个人薪金中，扣除该员工的个人所得税款，由公司每月统一向税务局缴纳。', 507, NULL, '[\"员工\", \"公司\", \"工作\", \"加班\", \"当年\", \"部门\", \"年终\", \"以后\", \"上班\", \"薪金\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:23', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:23', '0');
INSERT INTO `document_segments` VALUES ('1955803404831649793', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　4.5升职、加薪或降职 　　3.5.1在公司业务发展需要的情况下，将从内部提升任何适合的人员至更重要的岗位。在考虑提升候选人时，主要考虑员工的敬业精神、专业能力、工作成绩、团队精神、行为操守、文化修养等。 　　4.5.2凡在本公司连续工龄满一年的员工，根据敬业精神、工作责任心、工作能力、团队精神、工作成绩，公司考评和考核面试后，视其情况可以升职者升职，不能升职者可以增加基本工资5-10%;或者降薪、降职。 　　3.5.3公司将定期对各职位员工进行职位考核，凡因敬业精神、专业能力不胜任或工作态度欠佳而不适应工作需要者，公司将进行适当调整以至降职使用。 　　4.6 团队奖励： 　　4.6.1 公司内组建几个二级团队，公司对二级团队按季度实行与毛收入挂钩的奖励办法。具体办法按公司当时的有关文件规定执行。 　　4.6.2二级团队内部员工的季度奖金分配，按照员工的敬业精神、团队精神、工作能力、工作业绩进行分配。 　　4.6.3员工的试用期无奖金，不参加团队奖历的分配，试用期满转正以后期间，可以参加团队奖励的分配。 　　4.6.4季度末以前离职的员工，不再参加当季度团队奖励的分配。 　　五. 工作时间及法定假期 　　5.1工作时间', 519, NULL, '[\"公司\", \"员工\", \"团队\", \"工作\", \"分配\", \"奖励\", \"敬业精神\", \"降职\", \"进行\", \"季度\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:23', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:23', '0');
INSERT INTO `document_segments` VALUES ('1955803404886175746', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　五. 工作时间及法定假期 　　5.1工作时间 　　5.1.1公司现行工作时间周工作制，每周工作六天，从周一至周六。 　　5.1.2工作日的上班时间为：8∶30-12∶00，14∶30-18∶00。(冬季与夏季之间工时相差不超过半个小时) 　　5.2法定假日 　　5.2.1按国家的统一规定执行。当前执行1999年9月18日国务院修定发布的《全国年节及纪念日放假办法》第二条全体公民放假的节日：新年1天(1月1日);春节，放假3天(农历正月初一、初二、初三);劳动节，放假3天(5月1日、2日、3日);国庆节，放假3天(10月1日、2日、3日)。以上法定假日为有薪假期。 　　5.3其他假期 　　5.3.1员工有权请病假、事假，请假手续参看本员工手册第8.1.7、8.1.8条规定。 　　5.3.2婚假：有薪婚假期限根据政府当时规定执行。员工请婚假必须向行政部出示其结婚证书。 　　5.3.3产假：产假期限根据政府当时规定执行。员工在本公司工作两年以上可享受带薪产假(只享受基本工资);工龄两年以下的，产假为无薪假期。产假期及以后该员工的岗位，由公司另行安排。', 481, NULL, '[\"员工\", \"日\", \"放假\", \"规定\", \"执行\", \"产假\", \"薪\", \"假期\", \"工作\", \"公司\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:23', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:23', '0');
INSERT INTO `document_segments` VALUES ('1955803404940701698', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　5.3.4丧假：员工直系亲属(指员工的父母、配偶、子女，除次以外均不属直系亲属)死亡可享受有薪丧假。丧假期限根据政府当时规定执行。 　　5.3.5以上5.3条的各种假期包括公休假日在内。 　　六. 福利 　　6.1办理调入徐州 　　6.1.1 在公司连续工作二年以上，各方面表现出色，并符合国家有关规定的员工，个人提出办理调动的书面申请。 　　6.1.2经公司审查属实后，上报政府有关部门审批办理调动手续。 　　6.2旅游 　　6.2.1旅游:凡符合以下条件之一者,可享受公司提供一次海南旅游机会(全程五天,包签证、住宿及来回交通费)。①主管或部门总监助理以上，其它部门经理以上职务：在本公司连续工作一年半以上;②主管或部门总监助理以上、创作部指导助理以上，其它部门经理以上职务：在公司连续工作两年以上;③其它员工：在本公司连续工作三年以上。 　　6.2.2符合海南旅条件的员工由行政人事部负责安排，行政人事部与该员工部门总监和该员工沟通后，协调好工作，妥善安排好出游时间，保证海南旅顺利进行。只能出游海南，不能以其它形式替代。 　　6.3带薪假期', 476, NULL, '[\"员工\", \"公司\", \"部门\", \"海南\", \"工作\", \"办理\", \"连续\", \"总监\", \"规定\", \"政府\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:23', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:23', '0');
INSERT INTO `document_segments` VALUES ('1955803404995227649', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　6.3带薪假期 　　6.3.1凡在本公司连续工作一年以上的员工(不分职务)，从第二年起，可享受连续一周(包括公休假日在内)带薪假期(简称年假)。休假安排必须遵守如下条款： 　　6.3.2休假时间的安排必须以服从工作需要为原则。 　　6.3.3休假要在自身岗位工作安排妥善的前提下，提前半个月向公司申请，并经总经理批准。 　　6.3.4年假一般应安排在公司春节前后放长假期间一次使用。 　　6.3.5当年已参加公司安排海南游的，不得重复享受带薪假期。 　　6.3.6假期不能跨年度累积，当年因工作需要不能休假的，按日基本工资计算补发工资。 　　6.4医疗保险 　　6.4.1员工(不分职务)在试用期满转正后，均享受本公司提供参加徐州市基本医疗保险福利。参保办法现按深府[1996]122号《徐州市基本医疗保险暂行规定》执行。(行政人事部备查)。如政府有调整，按调整的新办法执行。 　　6.4.2员工转正后，由公司统一为员工缴交基本医疗保险费。员工缴费月工资最高限额4500元。', 439, NULL, '[\"公司\", \"安排\", \"员工\", \"工作\", \"医疗保险\", \"享受\", \"基本\", \"休假\", \"假期\", \"带薪\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:23', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:23', '0');
INSERT INTO `document_segments` VALUES ('1955803405045559298', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　6.4.2员工转正后，由公司统一为员工缴交基本医疗保险费。员工缴费月工资最高限额4500元。 　　6.4.3具有徐州市常住户口的员工的综合医疗保险费，按其月工资额的7%由公司承担缴交，员工个人承担缴交2%，总共9%。个人缴交部份在工资内扣除，由公司统一缴交徐州市社会医疗保险局。 　　6.4.4具有徐州市暂住户口的员工住院医疗保险费由公司按其月工资额的2%缴交，个人不负担。 　　6.5基本养老保险 　　6.5.1员工在试用期满转正后，均享受本公司提供参加徐州市基本养老保险福利。参保办法现按徐府(1996)123号《徐州市基本养老保险暂行规定》执行。(《规定》在行政人事部查)。 　　6.5.2员工转正后，由公司统一为员工缴交基本养老保险费。员工缴费月工资最限额4500元。 　　6.5.3持有徐州市常住户口的员工的基本养老保险费，按其月工资额的14%由公司承担缴纳;员工个人承担缴交月工资额的5%，共计19%。个人缴交部分在工资内扣除，由公司统一缴交徐州市社会保险局。', 438, NULL, '[\"员工\", \"徐州市\", \"基本\", \"公司\", \"交\", \"缴\", \"月工资\", \"养老保险\", \"%\", \"个人\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:23', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:23', '0');
INSERT INTO `document_segments` VALUES ('1955803405137833985', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　6.5.4持有徐州市暂住户口的员工基本养老保险费，按其月工资额的7%由公司承担缴纳;员工个人承担缴交月工资额的3%，共计19%。个人缴交部分在工资内扣除，由公司统一缴交徐州市社会保险局。 　　6.6午餐补贴 　　6.6.1员工在本公司任职期间，分月按实际上班工作日期发放中餐补贴。 　　6.6.2每位员工在徐州上班的每个工作日午餐补贴标准为人民币4元。 　　6.7晚餐补贴 　　6.7.1员工因工作需要晚上加班，加班时间超过下8时以后，每次晚餐补贴人民币10元。 　　6.7.2专业部门员工晚餐补贴根据品牌部填写的加班和行政部实际考勤都同时具备的情况单按月发放，行政、财务部门员工晚餐补贴根据主管副总经理签字的加班单按月发放。 　　6.8住房补贴 　　6.8.1员工试用期满转正后，均享受住房补贴。 　　6.8.2住房补贴标准如下： 　　主管或部门总监助理以上、其他部门经理以上：人民币200元/月 　　员工：人民币100元/月 　　6.9办理暂住证 　　6.9.1 凡徐州市以外户口的员工,由公司统一办理暂住证.', 459, NULL, '[\"员工\", \"补贴\", \"公司\", \"加班\", \"晚餐\", \"发放\", \"人民币\", \"缴\", \"交\", \"徐州市\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:24', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:24', '0');
INSERT INTO `document_segments` VALUES ('1955803405192359937', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　员工：人民币100元/月 　　6.9办理暂住证 　　6.9.1 凡徐州市以外户口的员工,由公司统一办理暂住证. 　　6.9.2员工在本公司连续工作满半年以上，再次办理暂住证的费用由公司承担。在本公司连续工龄不满半年的员工，需由公司办理暂住证费用自理。 　　七. 合同解除 　　7.1合同解除程序(公司称甲方，员工称乙方) 　　7.1.1甲方辞退乙方，须由乙方所在部门的主管总监填写辞退审批表交总经理签字，然后由该部门主管总监会同行政部、财务部与乙方办理离职前的交接手续，行政部经理根据签名齐全的审批表，向乙方开出解除聘用合同通知书，乙方在通知书上签名后方可领回本月工资。 　　7.1.2乙方辞职，须填写辞职审批表，向本部主管总监提出本人签名的书面申请，由本部主管总监签意见转交总经理审批签字，然后在甲乙双方商定的期限内，由该部门主管总监安排乙方与有关人员进行工作交接，交接清楚总监签字后，乙方向行政部、财务部交还财物，最后行政部经理根据签名齐全的审批表，再向乙方开出解除聘用合同通知书，乙方在通知书上签名后方可领回本月工资。 　　7.2有下列情况之一，甲方可以随时解除劳动合同： 　　7.2.1在试用期被证明不符合录用条件的;', 515, NULL, '[\"乙方\", \"总监\", \"办理\", \"主管\", \"解除\", \"公司\", \"签名\", \"审批表\", \"员工\", \"签字\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:24', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:24', '0');
INSERT INTO `document_segments` VALUES ('1955803405242691585', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　7.2有下列情况之一，甲方可以随时解除劳动合同： 　　7.2.1在试用期被证明不符合录用条件的; 　　7.2.2严重违反劳动纪律或公司规章制度，影响工作、生产的; 　　7.2.3严重失职、营私舞弊，泄露公司商业机密，对公司利益造成重大损害的; 　　7.2.4被依法追究刑事责任的; 　　7.2.5不服从工作安排的。 　　7.3有下列情况之一，甲方可以解除劳动合同，但应提前十日以书面通知乙方。 　　7.3.1乙方不能胜任工作。经过培训或者调整工作岗位，仍不能胜任工作的; 　　7.3.2劳动合同订立所依据的客观情况发生重大变化，致使原劳动合同无法履行，经当事人协商不能就变更劳动合同达成协议的。 　　7.4乙方解除劳动合同，应提前三十日以书面通知甲方。 　　7.5在下列情况下，乙方可以随时解除合同。 　　7.5.1试用期内，但工作不满15个工作日者不予结算工资; 　　7.5.2甲方违反国家有关法律、法规，侵犯乙方合法权益。 　　7.6经济赔偿、补偿', 428, NULL, '[\"工作\", \"劳动合同\", \"乙方\", \"甲方\", \"公司\", \"违反\", \"不能\", \"重大\", \"严重\", \"试用期\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:24', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:24', '0');
INSERT INTO `document_segments` VALUES ('1955803405297217538', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　7.5.2甲方违反国家有关法律、法规，侵犯乙方合法权益。 　　7.6经济赔偿、补偿 　　7.6.1按照7.3、7.5解除劳动合同，甲方按照乙方在本公司的连续工作年限计算经济补偿发放给乙方：每满一年，发给员工一个月的基本工资;满半年不满一年的，按一年计发;不满半年的发该员工半个月的基本工资。 　　7.6.2乙方违反本手册规定，擅自离职造成甲方损失的，必须赔偿损失。 　　八.工作纪律 　　8.1考勤管理规范 　　8.1.1员工每日到公司上班必须先亲自打卡报到，下班时打好卡方可离开。 　　8.1.2员工须自觉遵守打卡考勤规定，严禁委托他人打卡。 　　8.1.3.1.凡属昨天下班未打卡的员工，行政人事部将用专册登记并通知该员工处理下班未打卡的原因，由该员工送其总监签字证明。如该员工在一个工作日内未处理昨日下班未打卡的问题，将对该员工的下班未打卡作为漏打卡处罚处理。', 385, NULL, '[\"员工\", \"卡\", \"乙方\", \"下班\", \"未\", \"甲方\", \"公司\", \"规定\", \"必须\", \"工作\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:24', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:24', '0');
INSERT INTO `document_segments` VALUES ('1955803405347549185', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　8.1.4加班：员工因工作需要加班，必须填写“加班单”，由部门总监签字。员工加班时间超过晚上8点以后，每超过一小时，第二天上班时间可延后一小时，凌晨二点以后，可于第二天下午1∶40上班。但须于晚上加班完毕前安排好自己的所有工作，写出说明贴于公司告示牌上，以便查找资料和安排后序工作。 　　8.1.5外出：员工因公外出，须直接向主管领导报告，并在公告栏上填写去向表。员工上班后中途因私有急事外出，须向部门主管总监报告去向，经批准，交待手头工作，并向行政部递交签批后的请假手续。方可外出，否则作旷工处理。主管总监以上职务因私事外出，须向总经理报告去向，经批准后办理请假手续。 　　8.1.6.病假：员工请病假，须在当日一上班即向部门总监请假，同时通知公司行政部，事后向行政部补交区级以上医院证明和病历，登记考勤。员工可享受每月2天的带薪病假(以月为准)。请病假不能提交区以上医院证明和病历的，按事假处理。若员工连续病假超过30天，公司将不再保留其任职岗位之工作，该员工将被视为自动辞职。', 443, NULL, '[\"员工\", \"工作\", \"外出\", \"病假\", \"总监\", \"上班\", \"公司\", \"请假\", \"部门\", \"去向\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:24', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:24', '0');
INSERT INTO `document_segments` VALUES ('1955803405410463745', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　8.1.7.员工请事假，须提前一天填写请假申请单，经部门主管总监签字同意，交待清楚手头工作，可请事假两天。两天以上一十五天以内需经总经理书面批准。一十五天以上事假,公司不予批准, 将被视为该员工自动辞职。员工应将经批准签字后的请假申请单交行政经理登记考勤，方可离开。未取得上述批准而缺勤者，将被视为旷工。事假无薪。假期已满，未按时上班的超假期按旷工处理。 　　8.1.9.连续旷工三天或一年内累计旷工七天者，解除劳动合同。 　　8.2礼仪管理规范 　　8.2.1员工应着公司统一制作的工作服上班。员工上班时间佩带公司胸牌。胸牌要佩带在左胞上方位置。员工上班不得穿拖鞋、短裤。员工要爱护和妥善保管胸牌，丢失要赔偿工本费10元/枝。佩带胸牌由行政人事部负责检查管理。行政人事部发现员工未佩带胸牌第一次给予提醒警告并记录在案，督促其立即佩带。若不及时佩带或第二次发现未佩带胸牌，记录在册并由该员工签字，纪录在员工的日常考核成绩中。', 414, NULL, '[\"员工\", \"佩带\", \"牌\", \"未\", \"胸\", \"事假\", \"签字\", \"批准\", \"上班\", \"旷工\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:24', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:24', '0');
INSERT INTO `document_segments` VALUES ('1955803405460795393', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　8.2.2员工工作服由公司统一制作，按成本价在员工工资中分二月扣出。凡在公司连续工龄满半年以上的退给工作服一半的价款，连续工龄满一年的再退给其工作服另一半的价款。连续工龄不满半年解除合同者不退工作服价款。 　　8.2.3个人仪表端庄。男性需仪容整洁及注意个人卫生;女性要求化淡妆，服装仪容大方得体。 　　8.2.4个人电话礼仪 　　8.2.4.1电话铃响应立即接听，以不超过三声为原则。 　　8.2.4.2拿起话筒应先讲“你好，名人网络”再报自己姓名。 　　8.2.4.4讲电话时，声音应温和清晰，切勿嬉戏及高声谈笑。 　　8.2.4.4打电话前，应先整理谈话内容，接听电话时，应记录来电重点及覆诵，力求事半功倍，减少电话占用时间(注意长话短说，节约开支)。 　　8.2.4.5当拨错电话时，勿马上将电话挂掉，应向对方说声“对不起”后，再挂掉电话重拨。 　　8.2.4.6通话结束时，应等对方挂完电话后，再轻轻放下听筒。 　　8.2.5代接电话礼仪 　　8.2.5.1部门同事不在而其电话铃响时，应立即代为接听，并留下对方的姓名电话号码及留言，待其本人回来时，如实转达。', 487, NULL, '[\"电话\", \"时\", \"再\", \"应\", \"工作服\", \"仪容\", \"注意\", \"应先\", \"接听\", \"挂\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:24', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:24', '0');
INSERT INTO `document_segments` VALUES ('1955803405511127042', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　8.2.5.2凡接到非自己承办事务的电话时，必须在辨别其性质后，婉转告诉对方，并立即将电话转接至承办部门或人员，同时向承办人说明事由后，方可放下听筒。 　　8.2.5.3当有事外出或离开位子时，须先告知同事，如有来电或访客时，代为留言或处理。 　　8.3环境管理规范 　　8.3.1员工应自觉将各自位置卫生搞好。 　　8.3.2员工须自备茶杯，不准使用公司一次性茶杯，节约开支。 　　8.3.3员工不得在办公范围内抽烟，需抽烟请到消防楼梯间。 　　8.3.4不得在墙壁及屏风围板上张贴纸张。 　　8.3.5不得在公司公众环境乱丢杂物。 　　8.3.6员工餐后一次性饭盒请自觉放在楼梯间垃圾回收桶内。 　　8.4秩序管理规范 　　8.4.1接待外单位人员应在公司接待室或会议室，洽谈室内接待。非工作需要不得随意让外来人员进入工作场地。 　　8.4.2员工工作时间接听私人电话应尽量简短，小声，以免影响业务电话的正常流通和工作环境的安静。', 419, NULL, '[\"员工\", \"电话\", \"时\", \"公司\", \"环境\", \"人员\", \"接待\", \"应\", \"间\", \"自觉\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:24', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:24', '0');
INSERT INTO `document_segments` VALUES ('1955803405561458690', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　8.4.2员工工作时间接听私人电话应尽量简短，小声，以免影响业务电话的正常流通和工作环境的安静。 　　8.4.3员工使用公司公用设施或服务(如长途电话、传真、会客室、会议室、图书资料、打字、手提电脑、投影仪、数码像机、摄像机等)，应遵守行政部门规定，使用前办理申请手续，使用后及时清理或归还。 　　8.4.4员工因公接待使用会议室、会客室、洽谈室后，使用人员应立即清理室内卫生，保持室内整洁，以便接待其他客户使用。 　　8.4.5养成勤俭节约的良好习惯，员工下班时应关闭自己已不使用的电脑、电源;最后离开公司的员工，应检查电脑、电灯、空调排风扇等是否关闭，锁好大门方可离开。 　　8.4.6员工需用办公用品，统一到行政部按规定登记领用，注意爱惜节约，不得损毁和浪费。 　　8.5行为规范 　　8.5.1员工要自觉遵守中华人民共和国法律、法规和本公司的规章制度，作奉公守法的公民。 　　8.5.2工作时间内员工不得在办公范围内喧闹、聊天。不得无故串岗。 　　8.5.3工作时间员工不得睡觉、吃东西。不得打牌、不得用公司的电脑打游戏、观看业务资料以外的其它影喋。', 481, NULL, '[\"员工\", \"使用\", \"公司\", \"应\", \"工作\", \"电脑\", \"时间\", \"业务\", \"规定\", \"关闭\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:24', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:24', '0');
INSERT INTO `document_segments` VALUES ('1955803405607596033', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　8.5.4员工讲话要使用礼貌用语，对内、外均不得讲粗话，使用污蔑性字眼。 　　8.5.5员工不得在公司处理私人事务，不得利用公司文具、通讯、电脑等设施和用品谋取个人便利。 　　8.5.6员工不得利用工作之便贪污或收受回佣。 　　8.5.7员工受聘期间，不得在外兼职或炒单。 　　8.5.8员工不得对外口头泄露公司内部情况、经营机密或未经许可向外单位人员提供本公司业务资料及电脑软件。 　　8.5.9员工薪酬保密，员工个人不得向他人通报收入情况，公司只接受个人本身薪酬之查询。 　　8.6安全管理规范 　　8.6.1公司全体员工都要树立安全防范意识，做好安全防范工作是每员工应尽的责任和义务，在公司内共同创造出一个安全，祥和安定的工作环境。 　　8.6.2防盗、防窃 　　8.6.2.1外来人员的管理。来访的客户，行政人事部和有关业务部人员要及时作好接待工作，及时作出妥善的安排。各类维修服务的人员进入公司，行政部要安排佩带公司统一的标识牌。员工私人的客人来访，请在接待处或会议室接待。 　　8.6.2.2 谢绝推销人员和送餐人员进入公司工作场地，行政部要把好入口关，其余员工也要及时协助制止推销人员和送餐人员 进入公司工作场地。', 516, NULL, '[\"员工\", \"公司\", \"工作\", \"人员\", \"安全\", \"行政\", \"及时\", \"来访\", \"管理\", \"外\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:24', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:24', '0');
INSERT INTO `document_segments` VALUES ('1955803405695676417', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '进入公司工作场地。 　　8.6.2.3中午午休时间，行政人事部要安排好前台值班人员，做好防范工作，认真执行好以上同点规定。 　　8.6.2.4下午下班以后，因工作需要加班的员工，要关好公司的大门，进出使用按键锁。完工离开公司时，关闭所有电脑电源和电灯及其他电器电源，锁好大门，方可离开，以防偷盗事件发生。 　　8.6.2.5员工要保管好公司财物和私人的用品。手机要随身带，不要乱丢乱放，贵重物品要锁好，以防丢失。 　　8.6.3消防管理 　　8.6.3.1公司按规定统一配置一定数量灭火器。由行政人事部按公司区域分配到各部门负责管理。行政人事部每月负责检查一次灭火器的管理情况。公司员工都应学会灭火器的使用办法。 　　8.6.3.2员工在公司办公范围内不能吸烟。如因接待客户需要，在会议室吸烟，烟灰和烟头应丢烟灰缸内，并用水熄灭。 　　8.7保密制度 　　8.7.1 定义 　　8.7.1.1公司秘密是指一切关系公司安全和利益，在一定时间内限一定范围的人员知悉的事项。 　　8.7.1.2所有公司职员都有义务和责任保守公司秘密。 　　8.7.2公司秘密的范围 　　8.7.2.1公司经营、发展战略中的秘密事项。', 505, NULL, '[\"公司\", \"员工\", \"行政\", \"人事部\", \"锁\", \"范围\", \"秘密\", \"一定\", \"灭火器\", \"应\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:24', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:24', '0');
INSERT INTO `document_segments` VALUES ('1955803405746008066', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　8.7.2公司秘密的范围 　　8.7.2.1公司经营、发展战略中的秘密事项。 　　8.7.2.2公司就经营发展作出的重大决策中的秘密义务的事项。 　　8.7.2.3公司对外活动中的秘密事项以及对外承担保密义务的事项。 　　8.7.2.4维护公司安全和侵犯公司利益的经济犯罪中的秘密事项。 　　8.7.2.5其他公司秘密(如高级领导的合同等。 　　8.7.3 密级分类 　　8.7.3.1 绝密:本公司生存、经营、人事有重大利益关系的情况，主要包括： 　　8.7.3.1.1公司股份构成、策划方案、成本、利润率、投资情况及其载体、来源及价格。 　　8.7.3.1.2总体发展战略、营销策略、商务谈判内容及材料，正式合同和协议书。 　　8.7.3.1.3公司其他重大决策。 　　8.7.3.2 机密：与本公司生存、经营、人事有重要利益关系的事项。主要包括： 　　8.7.3.2.1尚未确定的公司重要人事调整及安排情况。 　　8.7.3.2.2公司与外部高层人士、同业人员来往情况及其载体。 　　8.7.3.2.3公司薪金制度，财务专用印签、密码、月、季年度销售利润情况及其载体，微机开启密码、软盘内容及存放位置。 　　8.7.3.2.4公司重要领导住所、及电话号码。', 533, NULL, '[\"公司\", \"情况\", \"事项\", \"载体\", \"秘密\", \"重要\", \"经营\", \"重大\", \"密码\", \"发展\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:24', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:24', '0');
INSERT INTO `document_segments` VALUES ('1955803405796339714', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　8.7.3.2.4公司重要领导住所、及电话号码。 　　8.7.3.2.5获得竞争对方情况的方法、渠道及公司相应对策。 　　8.7.3.3 秘密：与本公司生存、经营、人事有较大利益关系的情况。 　　8.7.3.3.1客户层次调查情况，市场潜力调查预测情况及其载体。 　　8.7.3.1.2广告企划方案，营销企划方案。 　　8.7.3.1.3广告年度、季度提资情况、广告、刊、布形式及地域。 　　8.7.4 各密级内容知晓范围 　　8.7.4.1绝密级 董事会成员、监事会成员与绝密内容有直接关系的工作人员。 　　8.7.4.2机密级 公司主管(经理)以上干部，与机密内容有直接关系的工作人员。 　　8.7.4.3秘密级 公司部门负责人以上干部，与秘密内容直接关系的工作人员。 　　8.7.5 保密措施 　　8.7.5.1保密工作在董事会直接领导下，由董事长(办)实施，制定相应制度、规定、 　　对保密以下进行检查、督导、具体核实。 　　8.7.5.2公司员工必须有保密意识，做到不该看的不看，不该问的不问，不该说的不说。 　　8.7.5.3严禁在公司电话、传真机上交谈，传递保密事项。 　　8.7.5.4保密事项之载体要由专人保管，不得让无关人员查阅，不得交由他人代管。', 536, NULL, '[\"公司\", \"保密\", \"情况\", \"关系\", \"内容\", \"密级\", \"直接\", \"广告\", \"载体\", \"相应\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:24', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:24', '0');
INSERT INTO `document_segments` VALUES ('1955803405850865666', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　8.7.5.4保密事项之载体要由专人保管，不得让无关人员查阅，不得交由他人代管。 　　8.7.5.5涉及保密内容材料的发放，必须经主管领导批准签字，且限在保密员之间进行，并将发放情况详细登记。 　　8.7.5.6借阅保密事项载体必须经借阅方，提供领导签字批准，保密员登记，借阅人员不得摘抄、复印，向无关人员透露，确需摘抄、复印时，要经提供方领导签字。 　　8.7.5.7保密事项内容，不得在办公室内悬挂张贴。 　　8.7.6 奖罚 　　8.7.6.1公司所有员工有权对违反保密制度的行为予以抵制、举报。 　　8.7.6.2公司所有员工不得对上述抵制、举报行为进行打击、报复、刁难。 　　8.7.6.3公司对上述抵制举报行为将视情况予以表彰，奖励，奖励为物质奖励、精神奖励、申请有关部门处理。 　　九.财务管理 　　9.1借支规定 　　9.1.1因工作需要借支须填写借支单，经主管总监签字，总经理签批后方可借支。 　　9.1.2公司不批准私人借支。 　　9.1.3借支时间一般不得超过7天，特殊情况应事先说明。 　　9.2报销规定 　　9.2.1一般报销规定：', 481, NULL, '[\"借支\", \"情况\", \"公司\", \"签字\", \"保密\", \"批准\", \"领导\", \"人员\", \"借阅\", \"进行\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:24', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:24', '0');
INSERT INTO `document_segments` VALUES ('1955803405897003009', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　9.2报销规定 　　9.2.1一般报销规定： 　　9.2.1.1各类报销单均须在取得正式发票的前提下，由经手人填写清楚用途，并有经手人和部门总监的签名，送至财务部审核签名后，方能送至总经理室签批。有正式发票、经手人、管总监、财务部、总经理签名并写清用途的报销单方可报销。 　　9.2.1.2 报销时间不得超过账目发生后的八天，特殊情况须作说明。 　　9.2.1.3总经理签批报销单时间为每周三、五下午5：00-6：00，财务报销时间为每天下午4:00-6:00 　　9.2.2 购买设备、物品的报销： 　　9.2.2.1技术部设计资料图书、光盘的购买计划按公司的月控制额执行，其他设备物品的购买要事先申报公司购置计划。 　　9.2.2.2各部门需购买设备物品，经办人须事先填写购买申请单，经主管总监签名，总经理审批后方可借支购买。报账时须提供申请单作为依据，按9.2.1程序办理报账。 　　9.2.3 交通费报销： 　　外出工作车费报销以专线公车票价为标准，因特殊情况需乘坐的士的，事先应填写《乘坐的士申请表》，经主管总监和总经理批准后方可报销。 　　9.2.4 应酬报销： 　　9.2.4.1 因业务需要请客应酬，各部门或个人须事先填写应酬费申请单，并请示总经理批准，作为报销单据。 　　9.2.4.2', 554, NULL, '[\"报销\", \"总经理\", \"购买\", \"须\", \"总监\", \"部门\", \"填写\", \"事先\", \"申请单\", \"签名\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:24', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:24', '0');
INSERT INTO `document_segments` VALUES ('1955803405947334657', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　9.2.4.1 因业务需要请客应酬，各部门或个人须事先填写应酬费申请单，并请示总经理批准，作为报销单据。 　　9.2.4.2 请客应酬的基本开支标准和参加陪客人员的控制：外地客户来深需请客应酬的，由总经理带队三人以上，有公司由总经理或总监总共不超过5人作陪，人均开销标准控制在100元以内。总经理职务以下人员带队三人以上的客人由本公司总监带2人参加作陪，人均开销控制在80元以内。外地客人三人以下由总监按排2人作陪，人均开销在控制在80元以内。 　　9.2.4.3本地客户来公司一般安排工作餐，工作费用人均控制在10元。品牌部负责安排好，填写报销单，总监签字，总经理批准报销。 　　9.3媒介购买支款规定 　　9.3.1媒介部根据品牌部AE下达的媒介购买任务单，由AE提供的公司与客户签定的合同或确认书复印件，经财务确认已收到客户广告发布款后，填写媒介购买确认书，经AE、媒介执行、客户总监签字，媒介员填写好支票领用单，将以上资料一并报送总经理签字批准。 　　9.3.2财务部根据总经理签批的支票领用单及其附件，审核其价格无误，审批程序符合规定时，方可开出支票。', 483, NULL, '[\"总经理\", \"客户\", \"填写\", \"公司\", \"单\", \"总监\", \"应酬\", \"控制\", \"媒介\", \"请客\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:24', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:24', '0');
INSERT INTO `document_segments` VALUES ('1955803405997666305', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　9.3.3媒介部持支票购买媒体后，要取得媒体的正式发票，于当日内送交财务部查收。 　　9.4出差规定 　　9.4.1本规定适合员工因公远程出差使用。远程出差指超出深圳市范围以外，且当日不能返回。 　　9.4.2出差人员的交通费标准：员工因公远程出差，原则上交通工具为长途汽车及火车硬卧、轮船二等仓位以下。如因工作需要乘坐飞机的，须事先向主管总监申请，并经总经理批准后方可实施。 　　9.4.3出差人员的住宿标准： 　　9.4.3.1国外出差住宿标准另行规定。 　　9.4.3.2在一般情况下，选择三星级及三星以下宾馆。 　　9.4.3.3同性别二人以上一起出差，应合住房间，住宿费标准为上述一人费用增加30%。 　　9.4.3.4住宿费凭发票报销，超出本职位标准部分自理。 　　9.4.3.5表中直辖市是指北京、上海、天津、重庆，经济特区是指深圳、珠海。 　　9.4.3.6省会是指各省自治区首府城市，沿海城市是指大连、咸临、秦皇岛、烟台、连云港、青岛、温州、泉州、北海、湛江。 　　9.4.4出差人员的餐费标准： 　　9.4.4.1出差到各地，在公司或接待方提供午餐和晚餐的情况下，应主动扣除餐贴。', 502, NULL, '[\"出差\", \"标准\", \"指\", \"人员\", \"情况\", \"以下\", \"发票\", \"当日\", \"超出\", \"因公\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:24', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:24', '0');
INSERT INTO `document_segments` VALUES ('1955803406047997953', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　9.4.4.1出差到各地，在公司或接待方提供午餐和晚餐的情况下，应主动扣除餐贴。 　　9.4.4.2在外地一固定地方连续出差超过15天以上者，不分职务每天餐费补贴30元。 　　9.4.4.3餐费补贴由本人填写支付证明单，按财务规定程序批准后报销。 　　十.奖罚规定 　　10.1员工工作效率、工作态度、工作质量等表现突出，可获荣誉和物质奖励。 　　10.1.1对公司管理及业务运作有合理化建议，并经实施有显著成功。 　　10.1.2工作投入，在本职岗位上有出色表现。 　　10.1.3爱护公司，为公司开源节流作出显著贡献。 　　10.1.4工作细致，发现自身岗位以外的差错，及时采取措施，防止事故的发生。 　　10.2员工工作表现和行为不能达到公司要求，将受到处分和罚款。 　　10.2.1违反本员工手册的管理规定，被处以黄牌警告者。(三次兰牌警告，记黄牌警告一次，黄牌警告一次者给予口头严重警告处分，累积两次者取消本年度的升职机会，三次以上者给予辞退。) 　　10.2.2违反操作规程，责任心差造成不良后果。 　　10.2.3不听从主管领导的工作安排。 　　10.2.4业务学习不认真，本职工作不努力。 　　十一. 解释权', 514, NULL, '[\"工作\", \"公司\", \"员工\", \"规定\", \"表现\", \"以上者\", \"处分\", \"违反\", \"管理\", \"岗位\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:24', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:24', '0');
INSERT INTO `document_segments` VALUES ('1955803406094135297', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　10.2.4业务学习不认真，本职工作不努力。 　　十一. 解释权 　　本手册自x年x月x日起执行。 　　本手册解释权归行政人事部。 员工手册范本 篇8 　　员工手册 　　(简化版) 　　起草部门：公司办公室 时间：20xx年2月25日 　　目 录 　　第一章 总则 　　第二章 作息安排 　　第三章 考勤制度 　　第四章 室内规范 　　第五章 行政规定 　　第六章 会议规定 　　第七章 安全规定 　　第八章 印信管理 　　第九章 档案管理 　　第十章 财务规定 　　第十一章 用人制度 　　第十二章 培训办法 　　第十三章 机构设置 　　第十四章 业务规范 　　第十五章 报销制度 　　第十六章 薪酬制度 　　第十七章 奖罚制度 　　第十八章 补充说明 　　第一章 总 则 　　第一条 为规范员工行为，全面提升公司整体服务水平、环境适应能力及市场竞争能力，使公司健康而正高效地运行，特制定本管理制度。 　　第二章 作息安排 　　第一条 工作时间采用大小周方式，大周一至周五上午8:30-12:00下午13：30-17：30，小周采用周一至周六上午8:30-12:00下午13：30-17：30因季节或其它原因需要调整时由办公室另行通知。 　　第二条', 527, NULL, '[\"规范\", \"制度\", \"员工\", \"时间\", \"行政\", \"规定\", \"作息\", \"安排\", \"公司\", \"解释权\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:24', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:24', '0');
INSERT INTO `document_segments` VALUES ('1955803406186409985', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　第二条 周日全天和国家法定节假日休息。期间如需加班，公司将根据工作情况安排适时调休。 　　第三章 考勤制度 　　为加强公司规范管理以制度化，达成全年预期目标，提升经营绩效，特制定本规章。现公司根据实际情况制定以下规定。 　　工作时间：周一至周五(上午8:30---12:00，下午13:30---17:30)，周六(上午8:30---12:00)工作时间为五天半制。销售部实施大小休制度。 　　打卡次数：一日两次，即早上上班打卡一次，下午下班打卡一次。 　　打卡时间：打卡时间为上班到岗时间和下班离岗时间，每迟到、早退1分钟扣除5元。 　　销售人员外出办事应和公司行政或销售总监汇报方可外出。 　　销售人员请假应提前一天填写请假单，有销售总监或总经理签字，交由公司行政方可有效，否则按旷工处理。 　　销售人员因临时有事应电话告知销售总监或总经理，待假若结束补填请假单交由公司行政。 　　请假应提前书写《请假条》并当面交上级批复。特殊情况不能当面请假应向直接上级致电说明，请假期满报到后须及时补写《请假条》，由上级签字后交办公室存档。', 468, NULL, '[\"公司\", \"销售\", \"请假\", \"时间\", \"情况\", \"上级\", \"工作\", \"人员\", \"行政\", \"总监\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:24', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:24', '0');
INSERT INTO `document_segments` VALUES ('1955803406249324546', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　请假一日内(含一日)由直接上级批准。超过一日，需经直接上级签字后报由总经理签字批准。 　　一个月累计迟到三次，开除且不发放当月工资。 　　工作时间做与工作无关事情，发现一次扣除50元。 　　工作时间串岗聊天、流星与工作无关网页者，发现一次扣除50元。 　　第十二条 因公不能按时报到或提前离岗须向直接上级及时说明。 　　第四章 待客规范 　　第一条 办公室行政人员负责来访客人的接待、引见、服务和送别。 　　第二条 客人来访时应主动起身迎接。接待时要礼貌大方、热情周到。经过简单沟通后应及时告知相关人员具体接待。 　　第三条 客人落座后，应主动递送茶水;客人离开时，应主动送别;客人离开后，应及时收拾整理。 　　第四条 办公用品要注意经常维护，尽量避免人为损坏。 　　第五条 上班时间禁止上网私自聊天、打游戏、从事和工作无关的事情。 　　第六条 禁止正常工作时间在办公室大声喧哗、吵闹或大声播放音乐;禁止在办公室吸烟、喝酒、随地吐痰。 　　第八条 办公场所人人都需保持个人工作区域整洁干净，不得随意丢放垃圾、污垢或碎屑。 　　第五章 行政规定 　　第一条', 479, NULL, '[\"工作\", \"及时\", \"禁止\", \"办公室\", \"应\", \"客人\", \"接待\", \"时间\", \"直接\", \"上级\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:24', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:24', '0');
INSERT INTO `document_segments` VALUES ('1955803406295461890', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '办公场所人人都需保持个人工作区域整洁干净，不得随意丢放垃圾、污垢或碎屑。 　　第五章 行政规定 　　第一条 下级必须服从直接上级管理。对上级的安排持有异见可向上级的直接上级投诉。对上级裁决不满可向上级的直接上级申诉。错误指挥或错误判断上级指挥经上级裁决后，有责任方应承担由此造成的一切后果。 　　第二条 直接上级缺席或不服从公司统一管理时，由直接上级的上级负责管理指挥和协助。 　　第三条 公司员工每个月进行一次述职，办公室负责具体安排。 　　第四条 副总经理是公司行政工作的常务执行人。办公室协助执行。 　　第六章 会议规定 　　第一条 领导召开会议要改进作风、缩减时间、提高质量、注重实效。员工参加会议要准时到席、调整手机、禁止吸烟、做好笔记。 　　第二条 办公室具体负责公司全体员工会议的通知、组织、主持和会议笔记。 　　第三条 部门和小组会议由部门或小组负责人召集、主持和笔记。 　　第六章 安全规定 　　第一条 公司要求所有管理人员要在日常工作中加强员工安全教育，时常提醒员工注意个人人身、财产和公司财物安全。 　　第二条 员工要自觉遵守国家安全方面的法律法规，遵照公司要求和上级嘱托，时刻注意对个人人身、财产和公司财物安全的防范。', 521, NULL, '[\"公司\", \"上级\", \"员工\", \"会议\", \"直接\", \"工作\", \"安全\", \"规定\", \"个人\", \"笔记\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:24', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:24', '0');
INSERT INTO `document_segments` VALUES ('1955803406349987842', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　第三条 公司交给个人使用的钥匙不得随意转交他人;未经财务部负责人同意，不得随意将公司物品外带或外借。 　　第四条 禁止在无技术保障的情况下安装、拆卸、维修公司办公用品，特别是带电产品。 　　第五条 员工个人财物应随身携带，不得随意搁置在集体办公场所。 　　第六条 公司要求的保密事项未经公司许可不得随意向他人泄露。 　　第八章 印信管理 　　第一条 财务部负责公司印章和合同管理。印章要严格保管，规范使用，未经总经理同意任何人不得随意外带。 　　第二条 公司正式文件和合同需经财务部经理最后审核后加盖公章。未经总经理同意，空白合同不得随意盖章。 　　第三条 业务外出可携带空白合同。因业务急需可向副总申请领取空白盖章合同。个人携带空白盖章合同不超过24小时。 　　第四条 签定空白盖章合同时增订条款，须及时向副总经理汇报。 　　第五条 空白盖章合同签定后，应及时送交财务部进一步核查，无误后交由办公室统一建档。 　　第九章 档案管理 　　第一条 办公室具体负责档案管理。内容主要包括：规章制度、行政执行手续、会议笔记、人力资源资料、业务资料、工作报告、计划、客户资料、来函来文、合同、活动影像等各种书面和音像资料。 　　第二条', 515, NULL, '[\"合同\", \"随意\", \"公司\", \"财务\", \"空白\", \"未经\", \"盖章\", \"业务\", \"应\", \"同意\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:24', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:24', '0');
INSERT INTO `document_segments` VALUES ('1955803406412902402', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　第二条 档案管理要分门别类，统一存放，避免损坏和丢失。 　　第三条 档案借阅应严格按照阅读权限和保密规定，未经副总经理同意不得随意向公司以外的人员借阅。 阅读档案应抓紧时间，当天阅读当天交还保管。 　　第十章 财务规定 　　第一条 公司所有财务支出需直接报经总经理批准。 　　第二条 一般情况下大额款项可安排银行转帐。需要收、支现金时由财务部直接安排。 　　第三条 财务部经理有权根据公司实际情况对财务执行作出详细规定，经总经理批准后作为本制度附件颁布执行。 　　第十一章 用人制度 　　第一条 公司的大门时刻向人才开放是公司人力资源建设的长期方针。公司将通过人力资源市场、媒体、网络、专业人才推荐机构公开招贤纳士，同时鼓励员工随时通过关系积极发现并引进人才。 　　第二条 新人进入公司后，需进行一周时间(连续七天)的观察。观察期结束后，一经录用，一周观察期计入第一个月试用期并补发工资。 　　第三条 所有新人一经录用，需进入三个月的试用期。试用合格进入正式聘用期，并签定《劳动合同》。 　　第四条 新人试用期间表现突出可提前结束试用。进入正式聘用后，享受公司正式员工待遇。 　　第五条', 495, NULL, '[\"公司\", \"规定\", \"进入\", \"新人\", \"财务\", \"需\", \"阅读\", \"试用\", \"情况\", \"正式\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:24', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:24', '0');
INSERT INTO `document_segments` VALUES ('1955803406463234050', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　第四条 新人试用期间表现突出可提前结束试用。进入正式聘用后，享受公司正式员工待遇。 　　第五条 公司随时引进新人加盟，通过周期性的培养和选拔，以保证团队竞争优势快速提升。 　　第六条 员工辞职应至少提前三十天向总经理递交《辞职报告》，经总经理批准并安排工作交接后方可离职。 　　第十二章 培训办法 　　第一条 公司要求人人独当一面，重视团队共同成长，通过坚持不断的培训学习，提高每一位员工的综合素质和服务能力。 　　第二条 所有公司员工必须接受公司提供的各种培训。新人进入公司至少要接受三天的岗位专业培训，随后的培训由各部门和公司统一安排。培训要讲求实效，长期坚持。 　　第十三章 业务规范 　　第一条 市场划分：国内及国外，国内包括大陆全境含港澳台，国外是除港澳台外的其它国家。 　　第二条 人员分配：销售总监协同销售主管负责业务开发和客户维护。 　　第三条 销售业务：销售团队内鼓励大家相互PK，加强相互帮助、共同协作，共同成长。 　　第四条', 425, NULL, '[\"公司\", \"培训\", \"员工\", \"团队\", \"销售\", \"新人\", \"业务\", \"坚持\", \"至少\", \"进入\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:24', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:24', '0');
INSERT INTO `document_segments` VALUES ('1955803406526148610', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　第三条 销售业务：销售团队内鼓励大家相互PK，加强相互帮助、共同协作，共同成长。 　　第四条 销售人员要每日登记工作情况，输入电脑存档。内容主要包括拜访客户名称、地址、联系电话、拜访时间、交谈情况和客户简单分析等内容。业务人员可根据业务需要按此要求进一步完善。销售总监和销售主管负责日常抽查和具体情况询问。 　　第七条 销售人员要每周汇报一份业务报告：使用统一样式表格。内容包括上周客户拜访情况(客户名称、地址、电话、接待人、负责人和简要拜访情况)、拜访量统计、回访量统计、本周拜访重点等内容。业务人员可根据业务需要按此要求进一步完善。《上周业务报告》在每周一上午9：00前上交销售总监，每周二上午9：00前呈交总经理，后交由办公室统一建档。 　　第八条', 329, NULL, '[\"销售\", \"情况\", \"拜访\", \"业务\", \"内容\", \"客户\", \"人员\", \"上周\", \"报告\", \"统一\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:24', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:24', '0');
INSERT INTO `document_segments` VALUES ('1955803406576480257', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　第八条 每月业务计划：使用统一样式表格。内容包括上月客户拜访总量统计、回访量统计、目标客户名单、重要意向客户名单、拜访情况分析、个例分析和本月客户拜访方向、新客户开发计划、目标客户回访计划、意向客户签约计划及培训要求等内容。业务人员可根据业务需要按此要求进一步完善。《本月业务计划》在当月第一个工作日上午9：00前上交销售总监，当月第二个工作日上午9：00前呈交总经理，后交由办公室统一建档。 　　第十条 日常业务例会：销售部每周一为周例会时间，主要讨论本周销售计划及销售部门相关业务事宜，每周六上午十一点后为周末总结例会，主要讨论下周工作计划及本周客户跟进情况， 客户反馈信息等事宜。所有销售部员工必须提前十分钟到公司。公司另有安排时遵照办公室通知执行。 　　第十一条 业务培训：公司重视员工培训，重视团队共同成长，坚持通过持续不断和形式多样的培训，全面提高团队业务素质和服务水平。办公室协助负责业务培训的具体安排。 　　第十二条 业务合同管理：合同填写后需经销售总监和公司财务联合审查，增加特殊条款需经总经理审查。然后由财务部盖章。签订后交由办公室存档。 　　第十三条', 488, NULL, '[\"业务\", \"计划\", \"销售\", \"客户\", \"办公室\", \"培训\", \"拜访\", \"上午\", \"总经理\", \"员工\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:24', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:24', '0');
INSERT INTO `document_segments` VALUES ('1955803406626811906', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　第十三条 业务资料建档：所有业务拜访资料、客户材料等统一由办公室负责建档保管。总经理有权随时调阅。 　　第十四条 业务款收取：本人是个人主导业务收款的主要责任人。收取现金必须要由财务部经理委托的人员陪同。私吞业务款或有意致使业务外流，扣发本人当月全部工资并由本人承担一切损失。 　　第十五条 业务争议裁决：业务裁决要遵循先入为主、深入为重的公平和大局原则。裁决的具体办法是以个人业务报告为依据，同一客户个人最先拜访并连续跟踪回访两次即可判定为个人业务。出现业务争议需首先由直接上级进行裁决。 　　第十五章 薪酬制度 　　第一条 公司薪酬制度坚持按劳取酬、评功论赏，利润分享、共同受益的原则，在充分保障个人利益的同时，也重视增加行政、后勤等其他服务人员的收入，以充分体现公司每个协作体系的利益平衡与和谐发展，维护团队的团结协作与共同成长。 　　第二条 每月基本工资=基本保底工资+岗位绩效工资+提成+奖金+加班费+全勤奖。不同岗位的工资和考核标准不同，具体按照公司书面通知执行。 　　第三条', 446, NULL, '[\"业务\", \"工资\", \"个人\", \"裁决\", \"公司\", \"共同\", \"协作\", \"人员\", \"原则\", \"岗位\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:24', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:24', '0');
INSERT INTO `document_segments` VALUES ('1955803406714892290', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　第三条 所有人员达不到当月岗位绩效要求实发基本保底工资。业务岗位绩效考核与其当月基本任务挂钩，连续第三个月完不成基本任务，实发当月50%基本保底工资，并由直接上级负责劝退。 　　第四条 员工试用期间无津贴，进入正式聘用后接受综合考核享受津贴。每月综合考核办法由办公室颁布执行。 　　第五条 公司有权根据团队和业务发展情况对提成制度进行调整， 财务部每月号间负责发放上月工资，并遵照国家有关规定负责扣缴个人所得税。 　　第十六章 业务招待及出差报销管理制度 　　业务招待费用管理： 　　1、业务招待要强调必要性、目的性、正对性、经济性和实效性原则，做到少花钱，多办事，杜绝铺张浪费。招待费用开支，实行严格控制，分级管理，事前报告，限额开支的管理办法。 　　2、业务招待须由经办人事前详尽如实填写《业务费用报销单》，并按管理权由总经理审批。每次的业务招待费500元以上的需报总经理审批，未经批准的业务招待费用不予报销。 　　第二条 出差制度管理', 422, NULL, '[\"业务\", \"招待费\", \"负责\", \"工资\", \"招待\", \"基本\", \"当月\", \"报销\", \"津贴\", \"管理\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:24', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:24', '0');
INSERT INTO `document_segments` VALUES ('1955803406769418241', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　第二条 出差制度管理 　　1、出差实行事前计划，书面报告，时候汇报，按管理权限审批，费用限额报销的管理办法。出差人员需要事前详尽如实填写《出差申请书》，出差人员凭领导审批的“出差申请书”到财务部门办理借款。借款单由总经理批示后方可借款。 　　2、出差回公司一周内上交《出差报告书》报送总经理做出考评，对重大事情应开会商讨。 　　3、对没有办理出差申请的，以违纪处理，其发生的一切费用自理。需要延长出差时间的经报总经理同意后方可，擅自停留者除费用自理外，按公司有关制度处分。 　　第三条 出差费用 　　1、采用包干制：一类城市为：350元/天;二类、三类城市为：260元/天(包干费用包括：每天发生的住宿，市内交通，生活补贴费用)。出行交通一般要求规定乘坐长途火车，轮船或省际，城际大巴(报销票据必须是国际税务合法凭据)，特殊业务处理需要乘坐航班的必须通过总经理批准。 　　2、公司到外地参加展会及公司组织的团队活动，由公司统一提供食、宿、交通工具和到外地参加培训学习的员工，(不发放补助) 　　第十七章 奖罚制度 　　第一条 迟到、早退第一次全勤奖扣除，第二次开始每次乐捐20元。 　　第二条', 498, NULL, '[\"出差\", \"费用\", \"总经理\", \"公司\", \"需要\", \"交通\", \"制度\", \"乘坐\", \"必须\", \"报销\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:24', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:24', '0');
INSERT INTO `document_segments` VALUES ('1955803406819749889', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　第十七章 奖罚制度 　　第一条 迟到、早退第一次全勤奖扣除，第二次开始每次乐捐20元。 　　第二条 旷工半日罚款元，旷工一日按其当月实际工资罚款。 　　第三条 每月累计旷工三日或三次立即辞退并扣发当月全部工资。 　　第四条 当月累计请假超过一日，停发请假期间基本工资。 　　第五条 违反本制度中其它任意一项规定，由直接主管负责面谈。因违反制度造成个人和公司利益损害的应承担全部责任。处罚由办公室负责处理。 　　第六条 公司定期对优秀和具有突出贡献的员工实行奖励。优秀员工享受 　　第十八章 补充说明 　　第一条 本制度是公司于20xx年制度建设的过渡版本，由总经理签 字批准后颁布实施，办公室负责保管。公司享有本制度最终解释权。 　　第三条 各部门负责人须根据本部门工作需要逐步制订具体的操作流程，报经副总经理批准后，作为本制度附件颁布实施。 　　第四条 本制度执行期间，员工如有修改建议，可直接向办公室说明。办公室经过汇总后以书面形式呈报总经理。总经理负责对建议的适宜性、充实性和有效性进行评审，并作为参考资料用于制度修订。 　　第五条 总经理因有特殊安排不受本制度考勤约束。其他工作人员因公不能经常按本制度考勤约束，须报由总经理批准。', 521, NULL, '[\"制度\", \"负责\", \"公司\", \"总经理\", \"办公室\", \"批准\", \"员工\", \"日\", \"期间\", \"违反\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:24', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:24', '0');
INSERT INTO `document_segments` VALUES ('1955803406865887234', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '总经理因有特殊安排不受本制度考勤约束。其他工作人员因公不能经常按本制度考勤约束，须报由总经理批准。 　　第六条 总经理外出时由副总经理姚林林代行其职权。 　　20xx年2月25日 员工手册范本 篇9 　　一、填空题，请将正确答案填写在空格上。（每题1分） 　　1、企业经营理念：( )。 　　2、团队精神：( )、( )、( )。 　　3、公司员工辞职，需提前( )天，向部门负责人递交( )。申请辞职期间，须按要求完成工作，在离职前填写( )办理离职手续。 　　4、公司网站地址：( )。 　　5、因各种原因与单位解除、终止劳动关系者，须在离职前填写 ( )，办理离职手续。 　　6、员工应牢记质量要求哪三不放过 ( )、( )、( ). 　　7、公司规定上班时间到岗的，( )分钟以内到达为迟到。 　　8、公司规定下班时间离岗的，( )分钟以内离开为早退。 　　二、选择题，请将正确的选项填写在括号内，（每题1分） 　　1、下班后未关好门、窗、电源开关的，是否属于过错（ ）。 　　A、严重过错 B、轻微过错 C、没有过错 　　2、在工作场所、工作时间吃零食，水果的，是否允许（ ）。 　　A、允许 B、不允许 C、以上都不是 　　3、 偷盗、私拿、侵占或有意损害公私财产，是否属于犯法（ ）。 　　A、正常 B、犯法', 561, NULL, '[\"公司\", \"员工\", \"填写\", \"是否\", \"离职\", \"工作\", \"要求\", \"A\", \"考勤\", \"总经理\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:24', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:24', '0');
INSERT INTO `document_segments` VALUES ('1955803406932996098', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, 'B、不允许 C、以上都不是 　　3、 偷盗、私拿、侵占或有意损害公私财产，是否属于犯法（ ）。 　　A、正常 B、犯法 C、不犯法 D、以上都不是 　　4、员工当月有迟到累计（ ）或早退（ ）累计多少时间需要处罚。 　　A、5分钟 B、10分钟 C、15分钟 D、20分钟 　　5、违反公司规章制度、员工手册规定、岗位职责或未按操作流程和规范进行工作，给公司造成重大经济损失的，是否属于过错（ ）。 　　A、轻微过错 B、严重过错 C、没有过错 D、以上都不是 　　6、员工在工作场所、集体宿舍擅自拉接电源、使用明火或大功率电器，尚未造成损失的，是否属于违反规章制度（ ）。 　　A、轻微违反 B、严重违反 C、没有违反 D、以上都不是 　　7、故意诋毁公司形象，情节较重的，是否属于过错（ ）。 　　A、轻微过错 B、严重过错 C、没有过错 　　8、对同事恶意攻击或诬陷、伪证，影响公司正常工作秩序，是否属于过错（ ）。 　　A、轻微过错 B、严重过错 C、没有过错 　　9、旷工半天（含）以内的，是否属于按旷工一天处理（ ）。 　　A、按半天 B、按一天 C、不按旷工 　　10、员工连续旷工2天以上，是否属于严重过错（ ）。 　　A、是 B、不是 C、没有过错 D、严重处罚', 540, NULL, '[\"是否\", \"属于\", \"公司\", \"C\", \"员工\", \"过错\", \"A\", \"B\", \"工作\", \"D\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:24', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:24', '0');
INSERT INTO `document_segments` VALUES ('1955803406983327745', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　10、员工连续旷工2天以上，是否属于严重过错（ ）。 　　A、是 B、不是 C、没有过错 D、严重处罚 　　11、不服从安排，拒绝接受有关部门检查的，是否属于过错（ ）。 　　A、是 B、不是 C、没有过错 　　12、恣意制造内部矛盾，影响公司内部团结和工作配合的，是否属于过错（ ）。 　　A、是 B、不是 C、没有过错 　　13、未按规定办理请假手续、上下班未按规定打卡（考勤）的，是否属于过错（ ）。 　　A、严重 B、轻微 C、不是 D、没有过错 　　14、对他人施以暴行，进行威吓或妨害他人工作的，是否属于过错（ ）。 　　A、严重 B、轻微 C、不是 D、没有过错 　　15、对领导交办的工作不说明理由即拖延不办的，是否属于过错（ ）。 　　A、严重过错 B、轻微过错 C、没有过错 D、以上都不是 　　16、工作中拾到他人遗失的财物，未立即如数上缴的，是否属于过错（ ）。 　　A、是 B、不是 C、没有过错 D、以上都不是 　　17、工作中不负责任，浪费公司原材料及物品、能源，情节较严重的或情节轻微但屡教不改的，是否属于过错（ ）。 　　A、严重过错 B、轻微过错 C、没有过错 D、以上都不是', 508, NULL, '[\"过错\", \"是否\", \"属于\", \"工作\", \"没有\", \"严重\", \"未\", \"D\", \"公司\", \"A\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:24', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:24', '0');
INSERT INTO `document_segments` VALUES ('1955803407050436609', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '）。 　　A、严重过错 B、轻微过错 C、没有过错 D、以上都不是 　　18、公司遭遇任何灾难或发生紧急事件时，负责人或在场员工未能及时全力加以挽救的，是否属于过错（ ）。 　　A、严重过错 B、轻微过错 C、没有过错 D、以上都不是 　　19、未按规定穿着服装、佩戴规定厂牌或穿拖鞋上班，是否属于过错（ ）。 　　A、严重过错 B、轻微过错 C、没有过错 D、以上都不是 　　20、玩忽职守，对于明显的事故隐患，管理人员未能及时发现、及时处理或回报的，是否属于过错（ ）。 　　A、严重过错 B、轻微过错 C、没有过错 D、以上都不是 　　21、未经批准，私自留宿非公司人员，是否属于过错（ ）。 　　A、是 B、不是 C、没有过错 D、以上都不是 　　22、违反公司保密制度，泄露客户机密、泄露公司属于机密、绝密的商业信息或重大经营项目（活动）决策的，是否属于过错（ ）。 　　A、严重过错 B、轻微过错 C、没有过错 D、以上都不是 　　23、值班人员当班饮酒或不按规定检查巡逻擅离职守发生火险、火灾或致使使工作受到影响 　　的，是否属于过错（ ）。 　　A、严重过错 B、轻微过错 C、没有过错 D、以上都不是', 509, NULL, '[\"过错\", \"属于\", \"是否\", \"D\", \"公司\", \"规定\", \"没有\", \"发生\", \"未能\", \"A\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:24', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:24', '0');
INSERT INTO `document_segments` VALUES ('1955803407100768257', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　的，是否属于过错（ ）。 　　A、严重过错 B、轻微过错 C、没有过错 D、以上都不是 　　24、违反安全操作规程，安全卫生管理规定，造成人员伤害或造成公司重大经济损失的，是否属于过错（ ）。 　　A、严重过错 B、轻微过错 C、没有过错 D、以上都不是 　　25、工作不负责任，浪费公司原材料、物品、能源，情节轻微的，是否属于过错（ ）。 　　A、严重过错 B、轻微过错 C、没有过错 D、以上都不是 　　三、判断题，请在括号里打“√”或“×”。（每题2分） 　　1、应聘人员所提供的证件、资历必须是真实的、完整的，凡伪造、欺诈骗取录用者，一经发现严肃处理。（ ） 　　2、离职书面申请需提前30天提交部门负责人。（ ） 　　3、公司坚持“以人为本”的宗旨，以服务求生存，以改革求发展，为员工提供全方位多层次的优质品牌服务。（ ） 　　4、上下班未按规定打卡、考勤的，是否属于过错。（ ） 　　5、未经批准，私自留宿非公司人员的，是否属于过错。（ ） 　　6、《员工手册》适用于公司所有正式录用及试用期员工。（ ） 　　四、问答题（每题5分） 　　1、工作中遇到纠纷如何处理？ 　　2、公司员工的处罚分哪几种？相应的处罚是什么？', 517, NULL, '[\"公司\", \"过错\", \"员工\", \"是否\", \"人员\", \"属于\", \"提供\", \"服务\", \"每题\", \"工作\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:24', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:24', '0');
INSERT INTO `document_segments` VALUES ('1955803407167877121', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　1、工作中遇到纠纷如何处理？ 　　2、公司员工的处罚分哪几种？相应的处罚是什么？ 　　3、某员工乘着天黑偷了一辆自行车，请问他触犯了几级过错？公司会给予什么处罚？ 　　4、谈谈你对《员工手册》的认识。 　　5、工作中遇到员工投诉如何处理？ 　　6、推行6S手册的宣言？ 　　7、何谓6S？ 　　8、6S的定义？ 　　9、整理、整顿、清扫、清洁、素养、安全各自的目的？ 　　10、推行修养的步骤? 　　11、推行6S能够达到的效果? 员工手册范本 篇10 　　目 录 　　序言 　　公司简介 　　组织架构图 　　第一章劳动关系管理 　　第二章员工福利 　　第三章规章制度 　　第四章奖惩条例 　　第五章安全守则 　　第六章附件 　　序言 　　本《员工手册》旨在为本公司在职或即将到职的员工提供有关我们公司概况、规章制度及员工福利等信息。每位员工都需要认真学习此手册，以适应我们金斧建筑装饰工程有限公司的工作环境和公司文化。 　　此手册并非有公司信息的唯一来源，每位员工都有义务熟悉公司及自己所在部门所规定的细则。此外，公司有权根据业务发展的需要及时调整员工手册中的有关条文。 　　第一章、劳动关系管理 　　一、招聘原则', 510, NULL, '[\"员工\", \"手册\", \"公司\", \"推行\", \"S\", \"工作\", \"处罚\", \"序言\", \"劳动\", \"需要\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:24', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:24', '0');
INSERT INTO `document_segments` VALUES ('1955803407264346113', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　第一章、劳动关系管理 　　一、招聘原则 　　装饰工程有限公司承诺于每位员工,不管在任何时间,皆以尊重、公开、公平、公正的态度对待每一位员工。员工的聘用、培训和晋升机会完全基于个人的能力和工作。 　　二、招聘程序 　　1、公司总经办结合公司发展的整体战略及公司人力资源成本目标制定《招聘计划书》(确定招聘职位、人数、岗位录用条件等),经总经理审批后开展招聘计划。 　　2、招聘一般通过报刊、招聘会和网络发布招聘信息,并同时将招聘信息在公司内部通知,以便于公司内部职员优先参加,或优先推荐公司外较合适人员参加。 　　3、公司招聘人员在对每位应聘人员的简历进行详细了解、并初步沟通后,选择符合公司招聘岗位录用条件和用人标准的应聘人员,通知其参加公司的第一轮面试 　　4、经公司部门主管或总经办第一轮面试结束后,各面试人将根据应聘人员的实际表现进行评估,从中选择合适人选 　　5、第一轮面试人应将通过人员的表现详细填写在《人事通知单》上报总经理,由总经理决定是否需要亲自进行第二轮面试', 440, NULL, '[\"招聘\", \"公司\", \"人员\", \"面试\", \"员工\", \"进行\", \"总经理\", \"应聘\", \"选择\", \"详细\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:24', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:24', '0');
INSERT INTO `document_segments` VALUES ('1955803407314677762', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　6、经总经理决定录用人员在接到公司总经办下达的入职通知后,应在通知中规定的时间到公司总经办报到。报到时应携带以下资料:身分证、学历证、婚育证、(女性) 、暂住证、职业资格证书、获奖证书等 　　7、公司总经办对新录用人员提供上述材料的原件与复印件进行审核无误后,由录用人员在上述证件的复印件上签名确认。弄虚作假获得录用者,应依法承担法律责任 　　8、新录用员工签阅《员工手册》以及公司其他规章制度后,由公司总经办移交所在部门主管,由部门主管安排介绍同事和相关的岗位培训,进面展开工作 　　9、公司总经办必须对员工进行档案资料的建立并归档,对隐瞒虚报或伪造个人资料的员工一经发现,应立即辞退 　　10、倾情在招用员工时,如实向其告知工作内容、工作条件、职业危害、安全生产、按劳付酬报酬及公司的其他规定。 　　11、应聘人员义务 　　(1) 应聘人员必须身体健康，应根据公司要求出家有效的身体健康证明。 　　(2) 有过工作经理的录用人员，若与原单位存在业务竞争的，应主动告知。若不存在，公司有权要求出具承若书。弄虚作假者，由此导致的一切责任，由其自身承担。 　　三、劳动合同', 487, NULL, '[\"公司\", \"人员\", \"经办\", \"录用\", \"工作\", \"员工\", \"应\", \"进行\", \"告知\", \"新\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:24', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:24', '0');
INSERT INTO `document_segments` VALUES ('1955803407365009410', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　三、劳动合同 　　根据《劳动法》相关法律规定，公司所录用的员工根据用工性质分为劳动合同制、劳务工制、聘用制，实习生等。 　　1、 新入职员工自入职之日起即与公司建立劳动关系，公司自新员工入职起1-3个月内雨员工签订固定期限劳动合同。 　　2、 根据公司实际工作需要，经双方协商一致，公司与员工签订无固定期限劳动合同或以完成一定工作任务为期限的劳动合同。 　　员工须仔细阅读合同内容并签字确认。劳动合同自签订之日起生效，具有法律效力，双方必须严格执行。 　　四、试用期、转正及续约 　　1、新录用员工徐经过1-3个月的试用期，特殊情况除外。试用期包括在劳动合同期限内。 　　2、试用期结束后，部门主管姜根据员工在试用期的工作情况填写《人事通知表》，经总经理审核后决定其是否转正。 　　3、员工在试用期内如有以下不符合录用条件或严重违反公司规定的，公司有权立即终止劳动合同接触与其的劳动关系并不作任何赔偿。 　　(1)伪造学历、证书及工作经历者; 　　(2)个人简历、求职登记表所列内容与自然情况不符合者; 　　(3)经体检发现患有传染性、不可治愈或其他严重疾病者; 　　(4)不能按时按量完成工作任务的或者经试用期表现评估不合格者;', 517, NULL, '[\"员工\", \"劳动合同\", \"试用期\", \"工作\", \"公司\", \"劳动\", \"情况\", \"录用\", \"签订\", \"内容\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:24', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:24', '0');
INSERT INTO `document_segments` VALUES ('1955803407415341058', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　(4)不能按时按量完成工作任务的或者经试用期表现评估不合格者; 　　(5)拒绝接受公司领导交办的来临时任务者; 　　(6)不愿与公司签订劳动合同者; 　　(7)非因工作无法在工作时间内提供正常劳动者; 　　(8)有任何违反公司规章制度规定行为者; 　　(9)其他不符合录用条件情形者。 　　5、晋升/加薪 　　(1)普通员工的晋升/加薪，由部门主管填写《人事通知表》，报总经办审核，经公司总经理批准后，报总经办备案，由总经办签发《人事通知表》; 　　(2)部门主管级以上的员工晋升/加薪，由总经办填写《人事通知表》，经总经理审批后再由总经办签发; 　　6、工作岗位与职务调整 　　(1)根据工作需要及员工的表现，公司有权合理调动员工工作部门及岗位，员工调换部门由总经办填写《人事通知表》，经部门主管批准，报总经理审核后由总经办签发《人事通知表》。 　　(2)如员工不能胜任本职工作的，公司有权根据公司的需要调动其工作岗位并对其薪资作相应调整，员工拒不配合的，属于严重违反公司规章制度，公司有权立即解除与其的劳动关系并不作任何赔偿。 　　(3)员工个人提出调职或调换岗位，必须在本岗位工作满一年以上;', 501, NULL, '[\"公司\", \"员工\", \"工作\", \"经办\", \"任务\", \"表\", \"权\", \"通知\", \"部门\", \"人事\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:24', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:24', '0');
INSERT INTO `document_segments` VALUES ('1955803407465672705', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　(3)员工个人提出调职或调换岗位，必须在本岗位工作满一年以上; 　　(4)新员工在试用期内一般不适用本调职条款，特殊情况除外。 　　7、劳动保护和劳动条件 　　(1)公司有对员工进行劳动安全卫生教育专门培训的义务，对可能产生职业病危害的岗位，应当向员工如实告知，并按照《职业病防治法》的规定保护员工的健康及相关权益。 　　(2)员工在劳动过程中必须严格遵守安全操作规程和劳动安全卫生制度，自觉预防事故和职业病的发生。 　　8、劳动合同的终止与续签 　　(1)劳动合同期满或其他法律规定的劳动合同终止条件出现时，劳动合同即行终止; 　　(2)劳动合同期满前，经双方协商一致，可续签劳动合同; 　　(3)劳动合同到期，除公司与员工双方经协商同意另外续订劳动合同外，原劳动合同即行终止; 　　9、辞职、辞退及离职手续 　　(1)辞职 　　a、试用期内，员工本人要求解除劳动关系的，需提前七天以辞职报告的形式通知公司， 　　否则以七天工资代为通知期： 　　员工试用期七天以内离职或被辞退，公司不予以发放工资 　　b、试用期满以后，员工离职需提前30天以辞职报告的形式通知对方。否则以30天工资代为通知期。', 500, NULL, '[\"员工\", \"劳动\", \"劳动合同\", \"公司\", \"试用期\", \"职业病\", \"终止\", \"离职\", \"岗位\", \"安全卫生\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:24', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:24', '0');
INSERT INTO `document_segments` VALUES ('1955803407511810049', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　b、试用期满以后，员工离职需提前30天以辞职报告的形式通知对方。否则以30天工资代为通知期。 　　部门主管应与辞职员工积极沟通，了解辞职原因。对表现较好，业绩突出的员工要努力挽留。 　　辞职报告需经部门主管签字同意，再层报总经办，总经理批准后，方可生效。 　　(2)辞退 　　员工因不服从工作分配及违反公司相关规章制度而被立即辞退者，公司不予以任何补偿。具体规定，参照员工手册第一章第四款第3条、第四章第十一款、第十二款第3条执行。 　　(3)辞职手续 　　辞职员工应填写《辞职申请》报相关主管审批后，办理好相关手续，清晰、完整移交工作： 　　a、物品移交：包括但不限于工作证、工作服、员工手册、劳动防护用品、钥匙、设备、工具等，属于自己领用的应归还总经办，属于部门配备的应直接交部门主管。交接完毕后由部门主管和总经办签字确认。物品丢失或损坏应按原价赔偿。', 380, NULL, '[\"员工\", \"主管\", \"应\", \"部门\", \"经办\", \"辞职\", \"相关\", \"辞退\", \"物品\", \"工作\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:24', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:24', '0');
INSERT INTO `document_segments` VALUES ('1955803407566336001', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　b、资料交接：与工作相关的文件包括但不限于客户或其他与公司具有业务关系人员的名片、内部往来文件、传真、合同、客户资料等;项目资料包括但不限于电子版本、电子版图纸、电脑程序、文本、图纸和工作(未完成的工作，须跟踪的客户等)等方面的交接工作。公司会安排相关人员接替，交接完毕后由双方签字确认。 　　c、结清与公司发生的所有个人借款、应收账款、预付款项和开支结算单等。 　　员工在上述手续办理完毕后将相关人员签字的《员工离职单》报总经理审批，并传达至总经办后方可离职，否则公司有权不予办理其他手续和发放工资及提成。 　　财务部凭《员工离职单》与其当月考勤核算其工资，总经办应在当月内为其办理档案和社会保险关系的转移和终止手续。 　　(4)辞退手续 　　公司辞退员工，应由部门主管向总经办事先沟通并报总经理审批，辞退主管及以上员工须由总经理直接传令。 　　备注：辞退工作由总经办负责执行，书面移交记录在总经办备案。 　　被辞退员工同样清晰、完整移交工作：归还所有公司财产、专用信息，预付款项和开支结算单等应用时结清，并获得相关部门签署移交证明。否则公司有权不予办理相关手续和发放工资及提成。', 493, NULL, '[\"公司\", \"工作\", \"员工\", \"相关\", \"经办\", \"辞退\", \"办理\", \"人员\", \"移交\", \"手续\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:24', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:24', '0');
INSERT INTO `document_segments` VALUES ('1955803407612473346', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　(4)离职(辞职、辞退或合同期满)员工最后一期工资以现金形式发放，原则上不得提前。其在获得最后工作月的薪金之前，必须确保： 　　a、相关表单已传至总经办; 　　b、所有工作、资料已经清晰、完整移交; 　　c、所有预付款和开支结算单都已经结清; 　　d、所有的电脑系统登录号已被删除，或密码被修改; 　　e、所有公司资产等已经退还; 　　f、如果员工由于以下原因需要向公司作赔偿，公司将暂时冻结薪金给有关员工，直至相关问题得到解决。如果必要，公司可要求员工赔偿相关损失。 　　下列情况下，公司有权不予办理相关手续和发放工资; 　　1员工没有完成工作或资产的移交; 　　2自动离职者; 　　3员工拒绝向公司偿还因违背培训契约而需偿付的培训费; 　　4重大渎职、徇私舞弊或触犯国家相关刑法的; 　　一、工作时间： 　　1、一周工作时间为六天，具体工作时间为： 　　5月份至9月份，早上8:30—11:30，下午13:00—17:30 　　10月份至次年4月份：早上8:30—11:30，下午12:30—17:00 　　2、平面设计部每周日休息，财务部和总经办员工可安排在周六或者周日轮休;', 493, NULL, '[\"员工\", \"相关\", \"公司\", \"工作\", \"已经\", \"经办\", \"移交\", \"薪金\", \"最后\", \"工资\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:24', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:24', '0');
INSERT INTO `document_segments` VALUES ('1955803407666999298', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　2、平面设计部每周日休息，财务部和总经办员工可安排在周六或者周日轮休; 　　员工公休原则上应在当月内休完，如有特殊情况未休完的以加班计算，并参照本章第六款处理。 　　4、如有因安排不当而造成工作失误或其他损失的，除对相关责任人作相应处罚外，部门负责人也应加倍处罚。 　　六、超时工作/加班 　　1、公司实施的是岗位责任制，原则上要求员工当日工作在当日内处理完毕，员工因个人原因不能完成工作内容而延长工作时间的不视为加班。 　　2、公司因特殊情况可适当安排员工加班。加班员工应详细填写《加班申请表》报部门经理签字、总经理审批后方能生效。如发现员工有弄虚作假行为，公司将予以记大过处分。 　　3、总经办每月末将《加班申请表》进行统计，各部门主管可根据本部门工作安排对加班员工给予相应调休。 　　当月加班调休应在次月底前完毕，过期不补。调休应提前申请(具体程序参照第五款)，具体时长《加班申请表》为准。 　　七、薪资 　　本公司依照兼顾公司的可持续发展和员工生活安定及逐步改善的原则，以贡献定报酬，按责任定待遇，给予员工河里报酬和待遇。 　　1、 劳动报酬的结构与结算方式：', 486, NULL, '[\"员工\", \"加班\", \"公司\", \"工作\", \"安排\", \"应\", \"申请表\", \"原则\", \"经办\", \"部门\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:24', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:24', '0');
INSERT INTO `document_segments` VALUES ('1955803407759273986', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　1、 劳动报酬的结构与结算方式： 　　公司按员工工作能力和工作岗位实际情况确定其劳动报酬及劳动报酬的结构与结算方式。 　　员工的月收入主要包括下列几部分：月收入=岗位工资+绩效工资+各类津贴+其他。 　　2、公司所有员工的基本工资在每月15号发放(节假日、双休日及特殊请假则自然顺延)。 　　3、公司有权根据企业的经营状况、规章制度、对员工的考核情况和员工的工作年限、奖惩情况、岗位变化、职务调整等内容调整员工的工资水平，但不得低于本地当时最低工资标准。 　　4、员工个人薪资情况为公司的保密资料，任何员工不得与同事或公司外无关人员谈论薪资问题。员工若对个人薪资存在疑问，必须由本人通过正式渠道向公司财务部或总经办了解。 　　5、薪资由总经办负责汇总及核算，经财务审核、总经理审批后由出纳负责转账计入员工个人工资账户。 　　6、员工每月社保和其他福利个人应缴纳部分以及个人所得税从个人当月工资中扣除。 　　7、员工每月津贴如按现金形式发放而涉及发票的，必须由本人提供。 　　第二章、员工福利 　　一.法定节假日 　　所有员工可享有下列国家规定的公众假日： 　　元旦：1天(1月1日) 　　春节：3天(农历除夕、正月初一、初二)', 515, NULL, '[\"员工\", \"公司\", \"个人\", \"薪资\", \"情况\", \"工资\", \"必须\", \"节假日\", \"负责\", \"岗位\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:24', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:24', '0');
INSERT INTO `document_segments` VALUES ('1955803407809605634', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　元旦：1天(1月1日) 　　春节：3天(农历除夕、正月初一、初二) 　　清明节：1天(农历清明当日) 　　劳动节：1天(5月1日) 　　端午节：1天(农历端午当日) 　　中秋节：1天(农历中秋当日) 　　国庆节：3天(10月1日、2日、3日) 　　因工作需要在法定节假日加班的，应给与相应的补偿，但加班人员必须提前申请(具体参照第一张第六款弟2、3条)。 　　二、病假 　　1、患慢性疾病的员工，应先向所属部门递交书面请假申请，同时提供医院病历、病假建议单等材料。病假申请经相关领导比准后，员工才能离岗休息。患急症的员工，应在就诊的当天口头通知公司相关领导，就诊后3个工作日内补交书面请假申请、医院病历、病假建议单、急诊挂号单等材料。 　　病假审批权限参照员工公出和事假。 　　2、员工如弄虚作假、未履行请假程序或请假未被批准即离岗休息、或假期满后未续假或续假但未或获批准而未复岗的，均按旷工论处并给予小记过一次。 　　3、凡因吵架、斗殴引起的伤、病，一律不作病假处理。', 437, NULL, '[\"病假\", \"员工\", \"申请\", \"请假\", \"农历\", \"日\", \"未\", \"相关\", \"领导\", \"参照\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:24', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:24', '0');
INSERT INTO `document_segments` VALUES ('1955803407893491714', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　3、凡因吵架、斗殴引起的伤、病，一律不作病假处理。 　　4、员工请病假3天以内(含三天)不扣发岗位工资;超过三天的，病假工资按日岗位工资60%计算;超过15天的，病假工资按本地当时月最低工资的80%计算。 　　三、请假和旷工 　　员工一个月内累计请假(包括事假、婚假、产假、丧假和其他)3天以上15天以下或旷工1天及以下者，当月所有津贴减半。累计请假15天以上或旷工1天以上者，当月所有津贴全部扣除。具体参照第三章第一款第2条、第3条和第4条执行。 　　四、婚假 　　凡符合国家法定结婚年龄的员工转正后可根据国家相关规定，持结婚证书原件申请有薪婚假。 　　1、 婚假3天(女未满23周岁，男未满25周岁)，不含法定节假日。 　　2、 晚婚假15天(女满23周岁，男满25周岁)，不含法定节假日。 　　婚假必须在结婚证书填发半年内使用，逾期无效。休婚假须提前30天申请，应一次性休完，不可累计或用其他方式代替。其中员工申请婚假的资格为必须在公司工作满半年以上。 　　六、产假及护理假 　　1、女员工正常分娩产假90天，难产的增加15天，多胞胎生育的，每多生一个婴儿，增加15天。', 490, NULL, '[\"婚假\", \"员工\", \"产假\", \"申请\", \"病假\", \"累计\", \"旷工\", \"结婚证书\", \"请假\", \"满\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:24', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:24', '0');
INSERT INTO `document_segments` VALUES ('1955803407943823361', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　1、女员工正常分娩产假90天，难产的增加15天，多胞胎生育的，每多生一个婴儿，增加15天。 　　2、妊娠三个月内自然(人工)流产的，给假15天，妊娠3个月以上7个月以下自然(人工)流产的，给假30天，7个月以上早产按第1条标准给假。 　　产假工资由用人单位到社保中心申领。请产假须附结婚证、准生证及有关政府相关单位核发之证明文件。 　　其中女员工产假的申请资格为必须在公司工作满一年以上，并在预产期7个月前填写 　　《请假单》交部门主管和总经理审批并送总经办备案，女员工在预产期两周前开始休假。产假包括公众假期及法定假在内，且必须一次连续使用。 　　3、妻子年满24周岁，分娩后的一个月内，男员工可享有七天有薪护理假，申请该假期须附相关出生证明。 　　七、丧假 　　1、员工直系亲属(即：配偶、父母、妻子)去世，给与三天丧假，工资照发。 　　2、员工的旁系亲属(即祖父母、外祖父母、兄弟姐妹或公婆、岳父母)去世、给与一天丧假，工资照发。 　　丧假必须于办理丧事时一次使用，不能保留或以其他方式代替。请假后七天内须提交死亡证明至总经办备案。', 471, NULL, '[\"产假\", \"员工\", \"假\", \"须\", \"必须\", \"丧假\", \"工资\", \"预产期\", \"申请\", \"妻子\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:24', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:24', '0');
INSERT INTO `document_segments` VALUES ('1955803407998349314', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　丧假必须于办理丧事时一次使用，不能保留或以其他方式代替。请假后七天内须提交死亡证明至总经办备案。 　　注：员工婚假、产假、护理假及丧假期间的基本工资照常发放，其他津贴按本章第三款执行。 　　八、社会保险 　　公司按国家规定为员工缴纳社会保险： 　　1、对于宁波籍的员工，按照国家规定缴纳宁波市社会保险，员工需缴纳部分由公司在其工资中代为扣缴。 　　2、员工户籍在宁波大市范围以外的，按宁波相关文件的规定，由公司申报与养老、医疗、失业、工伤、生育等社会保险的缴交，员工个人不缴费。 　　九、培训 　　为了促进公司可持续化发展，帮助员工在实现公司目标的同时实现自己的事业规划，公司将为员工提供相关培训，员工培训情况将记录在案，作为绩效考核和生殖的依据之一。 　　1、新员工入职培训 　　公司新员工应该获得入职培训以尽快认知公司与熟悉工作岗位。入职培训由用人部门负责业务部分，总经办负责基本行政、人力资源政策和流程的告知。 　　2、根据工作需要，部门可安排员工接受在职培训，由在职部门经理或业务骨干进行专业技能培训。 　　3、公司安排的其他培训', 471, NULL, '[\"员工\", \"公司\", \"培训\", \"社会保险\", \"经办\", \"部门\", \"规定\", \"宁波\", \"部分\", \"入\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:24', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:24', '0');
INSERT INTO `document_segments` VALUES ('1955803408048680961', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　3、公司安排的其他培训 　　根据管理需要和员工发展的需要，公司将在适当的时候组织需要外部培训或拓展培训(具体参照相关制度)。 　　第三章 规章制度 　　一、考勤 　　1、出勤 　　(1)打卡：公司员工每天上下班须做电子考勤记录(早晚两次)。员工应亲自打卡或者签到，帮助他人和接受他人帮忙打卡/签到者，无论迟到，均按迟到(10分钟以上)一次处理并罚款100元。 　　(2)因特殊情况忘记打卡/签到的员工应在下一工作日向部门经理或以上主管说明情况，由部门经理或以上主管签字确认并注明原因。如有主管签字却未注明原因、或有注明原因而未经签字确认的，同样以迟到/早退或旷工论处。 　　主管人员所有的未打卡或签到必须注明原因并由总经理签字确定，无总经理签字确认的一律以迟到/早退或旷工论处。 　　(3)总经办应定期检查员工考勤记录，如发现有未打卡/签到并且无部门经理或以上主管签字确认的，如部门经理或以上主管不能确定其正常在岗的，一律以旷工论处。 　　对于下属分公司员工考勤，总经办应不定期以电话或现场检查形式进行抽查，如有发现上班时间未在岗、也无因公外出情况的(以外出登记为准)，一律以迟到/早退或旷工论处。', 501, NULL, '[\"卡\", \"员工\", \"签到\", \"迟到\", \"情况\", \"未\", \"应\", \"签字\", \"公司\", \"旷工\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:24', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:24', '0');
INSERT INTO `document_segments` VALUES ('1955803408099012610', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　(4)如因迟到或早退而谎报为打卡有异常或忘记签到的员工，一经查实，以每次旷工1天处理。 　　(5)当月忘记打卡/签到或打卡有异常累积不得超过三次。有特殊情况需报总经理签字确认，无总经理签字确认的，没超过一次按记小过一次处分并视为迟到(10分钟以上)或早退。 　　2、公出、事假 　　(1)员工公出、事假应将相关领导所批的《公出审批单》或《请假单》报总经办备案登记后方可外出。 　　a、 普通员工1天以内公出的,应在《部门外出登记表》上详细记录 　　注：如有派车登记的(以登记名字为准)可不用另填外出登记 　　b、普通员工公出1天(含)以上3天以内、请假3天以内的,由部门经理签字后报总经办备案： 　　c、普通员工3天(含)以上或部门主管及以上人员请假,一律由总经理签字批准后报总经办备案 　　(2)员工在上班时间内未登记或未经批准而擅离工作岗位半小时以内的,按警告一次处理;超过半小时的按旷工半天处理;超过二小时的按旷工1天处理', 416, NULL, '[\"登记\", \"公出\", \"报\", \"员工\", \"超过\", \"以内\", \"外出\", \"经办\", \"普通员工\", \"备案\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:24', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:24', '0');
INSERT INTO `document_segments` VALUES ('1955803408153538561', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　如有紧急/特殊情况不能事先填写登记表、公出单或请假单的,应提前或在外出1上时内电话通知部门经理或总经理同意并在上班当日补办手续,否则以旷工论处。如发现有弄虚作假者,将对相关责任人予以记大过处理 　　事假工资按其具体请假天/时数和(岗位+绩效)工资计算扣发 　　3、迟到、早退和旷工的规定和处理 　　上班时间开始后10分钟(含)至30分钟内打卡者,按迟到论处;超过30分钟(含)以上者,按旷工半天论处;超过半天以上1天以内(含),以旷工1天论处 　　提前30分钟以内下班者,按早退论处;超过30分钟(含)以上者,按旷工半天论处;超过半天以上1天以内(含),以旷工1天论处 　　a、1个月内以迟到/早退1次,或迟到10分钟以内累计达3次(含)以上者,给予一次警告处分; 　　b、1个月内迟到/早退3次,或迟到10分以以内累计达5次(含)以上者,按旷工半天处理并给予记1次小过处分; 　　c、1个月内迟到/早退累计达3次以上5次以下,或迟到10分钟以内累计达10次者,按旷工一天处理并给予记1次大过处分; 　　d、1个月内迟到/早退累计达5次(含)以上,或迟到10分钟以内累计达10次以上者,予以除名', 499, NULL, '[\"旷工\", \"迟到\", \"早退\", \"处理\", \"论处\", \"含\", \"以上者\", \"提前\", \"以内\", \"达\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:24', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:24', '0');
INSERT INTO `document_segments` VALUES ('1955803408199675905', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　d、1个月内迟到/早退累计达5次(含)以上,或迟到10分钟以内累计达10次以上者,予以除名 　　如有员工在当月内同时有10分钟以内和10分钟(含)以上的迟到,则按照每2次10分钟以内迟到,折合成1次(10分钟以上(含)迟到进行累计) 　　4、旷工 　　(1)旷工半天者,扣发1天基本工资、并给予记1次小过处分; 　　(2)每月累计旷工1天者，扣发三天基本工资，并给于记1次大过处分; 　　(3)每月累计旷工2天者，作自动离职处理。 　　旷工半天及以上者均取消当月全勤奖。 　　注：员工全勤奖说明 　　公司每月全勤奖(主管及以上人员200元，普通员工100元)已计入员工岗位工资，目的在于加强考勤管理，维护工作秩序和提高工作效益。经相关领导批准的员工事假、病假及其他假期不扣除当月全勤奖。 　　5、考勤 　　(1)员工的考勤情况由各部门负责人进行监督、检查。部门负责人对部门的考勤要秉公办事，认真负责，如有弄虚作假、包庇袒护迟到、早退、旷工员工的，一经查实，按处罚员工的双倍予以处理。', 443, NULL, '[\"员工\", \"旷工\", \"考勤\", \"累计\", \"迟到\", \"当月\", \"奖\", \"全勤\", \"以上者\", \"进行\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:24', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:24', '0');
INSERT INTO `document_segments` VALUES ('1955803408308727809', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　(2)总经理办应在每周一对前一星期的员工考勤卡和《请假单》进行检查，到月底将所有考勤进行统计记录在《员工月考勤统计表》上，并由各个部门主管签字确认后报总经理审阅。 　　十、其它 　　参加公司组织的会议、培训、学习、考试或其它团队活动，如有事请假的，必须提前向组织者或带队者请假。在规定时间内未到或早退的，按照本制度第六款规定处理;未经批准擅自不参加的，视为旷工，按照本制度第七款规定处理。 　　二、工作牌 　　1、员工应妥善保管公司所发的工作牌，上班时间及公出均应佩戴工作牌。 　　2、工作牌若有遗失或被盗，应立即向所在部门申报，并到总经办按相关规定补办(须交纳成本费10元)。 　　3、离职时，应将所有证件交还总经办，证件遗失者按相关规定处理。 　　三.节约能源 　　1、节约能源是每位员工的义务。例如及时关掉电脑、空调、打印机、传真以及照明设备的电源，节约用纸，尽可能利用网络传送文件，减少私人电话时间等等。 　　第四章、奖惩条例 　　一、奖惩类别： 　　奖励分为：嘉奖、小功、大功三种。 　　惩处分为：警告、小过、大过、除名四种。', 470, NULL, '[\"规定\", \"员工\", \"牌\", \"工作\", \"处理\", \"时间\", \"公司\", \"参加\", \"经办\", \"相关\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:24', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:24', '0');
INSERT INTO `document_segments` VALUES ('1955803408363253761', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　一、奖惩类别： 　　奖励分为：嘉奖、小功、大功三种。 　　惩处分为：警告、小过、大过、除名四种。 　　二、将城市间在嘉奖/警告的，由部门主管或总经办签发《人事通知表》报常务副总审批后生效(主管级人员报总经理审批)。奖罚事件在小功/小过或以上的，由总经理调查核实后，签批《人事通知表》生效。 　　三、《人事通知表》生效后交由总经办存档。大功或大过以上者由总经理决定是否需张贴告示。 　　四、员工有以下情形之一者，予以嘉奖： 　　1、积极维护公司荣誉，在客户中树立良好公司形象和口碑者; 　　2、认真勤奋，承办、执行或督导工作得力者; 　　3、工作勤奋，超额完成工作任务者; 　　4、服务质量好，多次受到客户表扬者; 　　5、当月无违纪、违规现象，工作积极努力获部门主管及同事认可者; 　　6、为公司节约成本，合理利用电脑耗材、办公用品，充分利用废弃品，成绩显著者; 　　7、有良好团队协作精神，受本部门和其他部门一致好评者。 　　五、员工有以下情形之一者，予以记小功： 　　1、工作技能熟练，当月工作业绩突出者; 　　2、对工作流程或管理制度积极提出合理化建议，被采纳者;', 487, NULL, '[\"工作\", \"积极\", \"部门\", \"公司\", \"嘉奖\", \"总经理\", \"主管\", \"良好\", \"客户\", \"大功\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:24', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:24', '0');
INSERT INTO `document_segments` VALUES ('1955803408409391105', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　1、工作技能熟练，当月工作业绩突出者; 　　2、对工作流程或管理制度积极提出合理化建议，被采纳者; 　　3、积极研究改善工作方法，提高工作效率或降低陈本确有成效者; 　　4、策划、承办、执行重要事务成绩显著者; 　　5、圆满完成重大项目未出差错者; 　　6、检举违规或损害公司利益者; 　　7、发现职责外文体，予以报告或妥为防止损害足为嘉许者; 　　8、其他应给予记小功事迹者。 　　六、员工有下列情形之一者，予以记大功： 　　1、在一个季度内客户“很满意”率达80%以上或现场服务态度好给公司带来回头客并签单成功者; 　　2、在工作或技术上大胆创新，并取得显著经济益者; 　　3、对维护正常的工作秩序有显著功绩者; 　　4、举报私自签单，工队干私活以及其它营私舞弊之事,经查证核实者; 　　5、对公司发展有重大贡献，应记大功事者; 　　七、员工有下列情形之一者，予以警告： 　　1、因过失导致工作发生错误但未造成损失情节轻微者; 　　2、违反工作秩序或环境卫生制度，破坏安全者; 　　3、初次不听主管合理指挥者; 　　4、未按规定佩戴工作证者;', 475, NULL, '[\"工作\", \"公司\", \"予以\", \"损害\", \"未\", \"秩序\", \"单\", \"签\", \"员工\", \"情形\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:24', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:24', '0');
INSERT INTO `document_segments` VALUES ('1955803408459722753', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　3、初次不听主管合理指挥者; 　　4、未按规定佩戴工作证者; 　　5、不遵守考勤规定，1个月内迟到/早退10分钟或以上1次，10分钟以内累计达3次(含)以上者; 　　6、同事之间相互谩骂吵架情节尚轻者; 　　7、对各级主管的指示或有限期的命令，无正当理由而未如期完成处理不当者(第二次及以上加倍处罚); 　　8、在工作场所妨碍他人工作者; 　　9、在工作时间内睡觉，躺卧休息或擅离工作岗位、串岗者; 　　10、工作时间非执行客户或业务关系饮酒但无影响者; 　　11、上班时间骚扰同事者; 　　12、上班时间聊天，嬉戏或从事与工作无关事情者; 　　13、浪费公物，情节轻重者; 　　14、其他应予以警告者。 　　八、员工有下列情形之一者，予以记小过： 　　1、一个月内两次未完成工作任务，但未造成重大影响者; 　　2、因玩忽职守造成公司损失但影响不大者; 　　3、对同事恶意攻击，造成伤害但不大者; 　　4、捏造事实骗取休假者; 　　5、1个月内迟到/早退10分钟或以上累计达3次，10分钟以内累计达5次(含)以上或旷工半天者; 　　6、附和罢工，怠工者;', 479, NULL, '[\"工作\", \"未\", \"同事\", \"情节\", \"影响\", \"造成\", \"时间\", \"主管\", \"规定\", \"含\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:24', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:24', '0');
INSERT INTO `document_segments` VALUES ('1955803408505860098', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　6、附和罢工，怠工者; 　　7擅自变更工作方法使公司蒙受损害但影响不大的，初次罚款50元并作口头警告并承担损失的20%，第二次或以上记上过处理并承担由此引起的全部损失; 　　8与客户预约时，无故不到或晚到，造成不良影响，遭客户投诉，经调查属实的，第一次罚款50元并口头警告，第二次或以上的记小过处理; 　　9因图纸漏项或预算员报价漏项、低价等预算中出现较大偏差，预算员及审核人员审核失误，造成经济损失在3000元以下的，相关责任人及审核人员分别记过并共同承担所有损失的50%(第二次犯相同错误除记过外还应共同承担所有损失); 　　10图纸审核中，设计师犯相同错误三次的; 　　11因隐瞒不报引起施工无法进行造成损失的，除记小过以外另需要赔偿全部损失; 　　12其他应予以小过者; 　　九、员工有下列情形之一者，予以记大过： 　　1、撤离职守，导致公司蒙受损失者; 　　2、携带危险或违禁物品进入工作场所者; 　　3、故意撕毁公文者; 　　4、虚报工作成绩或伪造工作记录者; 　　5、对同事恶意攻击，造成较大伤害者; 　　6、损失(遗失)公司重要公文(物品)者;', 482, NULL, '[\"损失\", \"造成\", \"工作\", \"公司\", \"承担\", \"审核\", \"引起\", \"客户\", \"记\", \"中\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:24', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:24', '0');
INSERT INTO `document_segments` VALUES ('1955803408551997442', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　5、对同事恶意攻击，造成较大伤害者; 　　6、损失(遗失)公司重要公文(物品)者; 　　7、职务下所保管的公司财务短少、损坏、私用或擅送他人使用，造成损失较小者; 　　8、违反安全规定，使公司蒙受一定损失者; 　　9、一个月迟到/早退10分钟(含)以上累计达3次以上5次以下、10分钟以内累计达10次者; 　　10、一个月内累计旷工1天(含)以上者; 　　11、未完成工作任务，造成重大影响或损失者(并视情节轻重承担所有损失的20-50%作为赔偿) 　　12、工作时间，非执行客户或业务关系饮酒造成不良影响但不严重者; 　　13、在收取客户订金后不及时交到财务部，影响工程结算者; 　　14、签订合同时，因考虑不周造成损失，金额较小但给公司信誉造成不良影响，或对客户随意承诺权限范围之外的事宜，引发经济纠纷或严重后果的(除对相关责任人进行处罚外，并视损失情况给予其他处罚); 　　15、因工作拖拉被客户认为效率低下引起跑单的，责任人及其直接上级分别记过; 　　16、图纸审核中，设计师在图纸中犯相同错误三次以上的，每超过一次记一次大过处理;', 472, NULL, '[\"损失\", \"造成\", \"客户\", \"工作\", \"公司\", \"责任人\", \"影响\", \"不良影响\", \"含\", \"处罚\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:24', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:24', '0');
INSERT INTO `document_segments` VALUES ('1955803408598134786', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　16、图纸审核中，设计师在图纸中犯相同错误三次以上的，每超过一次记一次大过处理; 　　17、因图纸漏项或预算员报价漏项、低价等预算中出现较大偏差，预算员及审核人员审核失误，造成经济损失在3000元以上的，相关负责人及审核人员分别记过并共同承担所有损失的50%(第二次犯相同错误除记过外还应共同承担所有损失); 　　18、分段工程完工后项目经理未及时上报工人人工费，引起工人工资不能及时发放而造成的不良影响者(项目经理和工程部经理分别记过)。 　　19、工作不积极主动，得过且过，工作效率低下且上期无改进，经公司定期考核不合格者;(另视情况予以降级，直到辞退) 　　20、擅自变更工作方法是公司造成严重损失的，除记大过一次外另需视情况赔偿由此引起损失的30-50%,如有再犯出价被罚款外，个人还应承担由此引起的全部损失： 　　21、上班时间玩电脑游戏者(另罚200元)： 　　22、其他应予以大过者。 　　十、员工有下列情形之一者，予以除名并记大过。如有必要公司可要求员工赔偿相关损失： 　　1、拒不听从主官指挥监督，与主管发生冲突或无理取闹，扰乱工作秩序者; 　　2、在公司内酗酒滋事造成恶劣影响者;', 502, NULL, '[\"损失\", \"公司\", \"造成\", \"工作\", \"引起\", \"记过\", \"外\", \"犯\", \"承担\", \"审核\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:24', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:24', '0');
INSERT INTO `document_segments` VALUES ('1955803408648466434', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　2、在公司内酗酒滋事造成恶劣影响者; 　　3、在公司内聚众赌博者; 　　4、故意毁坏公物，金额较大者; 　　5、在公司闹事妨碍工作秩序者; 　　6、违反劳动合同或公司管理规定，情节严重者; 　　7、对同仁施以或重大侮辱猥亵行为者; 　　8、严重违反各种安全制度，导致重大人身或设备事故者; 　　9、1个月内迟到/早退10分钟以上累计5次(含)以上、10分钟以下累计达10次以上者。 　　10、1个月内累计旷工2天(含)以上、1年内累计旷工3天(含)以上者; 　　11、盗窃同事或公司财务、挪用公款者; 　　12、利用公司名义招摇撞骗，使公司蒙受损失者; 　　13、在公司内部有伤风败俗之行为者。 　　14、利用职权或以下不正当手段谋权利者。 　　15、年度内累计三次记大过行为者。 　　16、有重大泄密行为，使公司利益受到重大损失者。 　　17、弄虚作假、营私舞弊、虚报冒领或利用职务及工作之便行贿，谋权私利者; 　　18、利用职权对员工打击报复或包庇员工违法乱纪行为的; 　　19、经部门给予拘留、劳教、判刑处理者; 　　20、收买、贿赂其他人员，私下交易造成不良影响和经济损失，或利用职务之便，贪污，营私舞弊者;', 510, NULL, '[\"公司\", \"行为\", \"重大\", \"利用\", \"累计\", \"工作\", \"违反\", \"谋\", \"以下\", \"利用职权\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:24', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:24', '0');
INSERT INTO `document_segments` VALUES ('1955803408698798081', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　20、收买、贿赂其他人员，私下交易造成不良影响和经济损失，或利用职务之便，贪污，营私舞弊者; 　　21、敲诈勒索、损害客户利益造成不良影响者; 　　22、由于个人原因给公司造成较大损失，情节严重，造成极坏影响者(除承担赔偿责任外，公司保留向其追究法律责任的权利); 　　23、无故克扣工人工资，造成不良影响经查证属实者; 　　24、业务、设计、及工程部门人员相互串通接私活者(另扣除所有工资及提成); 　　25、在工作时间或利用公司资源制作私人业务或唆使其他同事共犯者(另扣除所有工资及提成); 　　26、未经公司许可，而到其他公司或个人处兼职者(另扣除所有工资及提成); 　　27、利用公司名义在外造谣生事或招摇撞骗，致使公司名誉及财务受到损害者 　　(另扣除所有工资及提成); 　　28、在公司服务期间受刑事处分者; 　　29、聚众要挟，妨碍工作秩序者; 　　30、其他应给予除名者; 　　十一、相关奖惩经副/总经理签字后生效： 　　1、每嘉奖一次，当月奖励20元，小攻奖励100元，大功奖励300元; 　　2、每警号一次，当月罚扣20元，小过罚扣100元，大过罚扣300元; 　　主管人员奖罚款加倍', 504, NULL, '[\"公司\", \"造成\", \"工资\", \"扣除\", \"不良影响\", \"利用\", \"提成\", \"工作\", \"业务\", \"当月\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:24', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:24', '0');
INSERT INTO `document_segments` VALUES ('1955803408782684161', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　2、每警号一次，当月罚扣20元，小过罚扣100元，大过罚扣300元; 　　主管人员奖罚款加倍 　　3、员工如在当月内警告4次，小过2次;当月季度内警告6次，小过3次，大过2次;当年内警告过8次，小过5次，大过3次者，公司将予以立即开除。 　　第五章、安全守则 　　一、所有公司员工必须遵守公司规定的安全措施，工作是必须遵守安全守则。 　　1、时刻注意防火灾、防盗窃、防破坏、防恶性事故发生。 　　2、员工上下班前就认真检查岗位水电设备、设施，即使将现金及重要票据、印章等锁入保险箱内，关好门窗，消除一切隐患。如发生本人不能解决的情况，应立即报告上级主管或大厦保安。 　　3、员工必须留意任何危险的工作环境或工作事故，一有发现，立即向上级主管汇报。 　　4、员工如发现可疑、不法行为的人或事，应立即汇报主管或大厦保卫处，并且在保证自身安全的条件下设法制止。 　　5、员工应学会使用灭火器、消防设备，熟悉紧急出口和通道。 　　注意：要小心与谨慎!任何员工在执行任务前，对安全方法有疑问时，应立即请示上级。 　　二、火警 　　当火患发生时，所有员工应遵照下列要点执行。 　　1、', 488, NULL, '[\"员工\", \"安全\", \"发生\", \"应立即\", \"上级\", \"主管\", \"注意\", \"小过\", \"前\", \"必须\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:24', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:24', '0');
INSERT INTO `document_segments` VALUES ('1955803408828821505', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　二、火警 　　当火患发生时，所有员工应遵照下列要点执行。 　　1、 立即拨打“119”告知正确的火患地点、燃烧物品、人员情况，并电话通知大厦物业处。如没有太大的危险性，应试图运用附近的灭火器扑灭火种。(因漏电引起的火灾，切勿用水扑救)。 　　2、 保持镇静，不要制造恐慌，应协作其他同事由适当的安全路线离开，万一火患无法控制，马上离开现场，避到安全的距离外，等候消防人员的到来。 　　注意：火患发生时，切勿使用电梯，所有员工应根据统一指示有序疏散，切勿拥挤以免发生踩踏事件。 　　第六章、附件 　　一、公司有权力根据国家法律及公司自身运营情况对《员工手册》作相应调整和修改。 　　二、《员工手册》中未尽事项，可按公司其他有关规章制度和管理措施实施。 　　三、《员工手册》若与公司其他管理措施或规章制度相抵触时，以《员工手册》为准。 　　四、《员工手册》的解释权属宁波顶艺装饰工程有限公司总经办。 　　五、《员工手册》须妥善保管，不得遗失，遗失必须补领，遗失补领需交制作费50元。 　　六、新入职员在领用《员工手册》后须仔细鉴阅(新入职员工在鉴阅后，公司将视其为已知晓《员工手册》内所有内容)。', 498, NULL, '[\"员工\", \"手册\", \"应\", \"公司\", \"患\", \"火\", \"切\", \"勿\", \"时\", \"发生\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:24', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:24', '0');
INSERT INTO `document_segments` VALUES ('1955803408879153154', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　七、本《员工手册》内所规定的所有条款及内容自20xx年05月22日起开始实施。 　　装饰工程有限公司 　　20xx年五月二十二日 员工手册范本 篇11 　　一、机构设置 　　二、经营管理 　　1、市场第一，力求客户满意，建立长期合作关系 　　我们将以顾客的满意度来评价我们的工作，每位员工直接或间接地对客户提供优质服务，对市场做出响应，顺应市场是公司成长的基础，真诚相待，建立信用。 　　公司及员工都要以自己的才能及真诚、建立公司及个人的信用，信用是为人之本、勤勉是进步之源，要发展需首先建立信用。所有员工的信用组成公司的信用。 　　2、关心员工，尊重个人 　　在国家规定和公司制度的有效范围之内，我们充分地尊重每一位员工的人格自由，开拓员工的创新精神。同时，我们相信每一位员工都能为公司辛勤工作，我们将不断创造出更多、更好的机会让员工接受更富有挑战性的工作，我们充分地接受和采纳每一位员工的意见和建议，尽可能理解每一位员工的想法。在公司不断取得效益的基础上尽可能给员工较佳的报酬。 　　3、以合为本，分享成功', 457, NULL, '[\"员工\", \"公司\", \"建立\", \"市场\", \"信用\", \"客户\", \"充分\", \"尽可能\", \"工作\", \"基础\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:24', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:24', '0');
INSERT INTO `document_segments` VALUES ('1955803408929484802', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　3、以合为本，分享成功 我们相信每一个夺冠的团队首先都应该是内部团结、合作有力的，公司要求所有员工在完成每一项工作时都要与有关方面充分有效地协调与沟通，我们希望每一位员工都支持关心公司的事业发展，将公司的发展与个人的成长进步，紧密联系起来，团结一致，拧成一股绳，形成我们的团队精神。公司的成功将与员工分享。 　　4、立足本职，科学创新 　　公司将不断致力于技术创新、管理创新，逐步建立起适合本公司发展要求的简捷、有效的科学规范管理体系，从而达到更高的工作效率。公司将不断于新技术及产品开发，强化市场竞争力，适应及满足市场需求。 　　三、人事管理 　　1、新入公司的员工必须无条件接受一周培训后进入试用期，其试用期一般要经过1至3个月，按学历、职称享受试用期工资标准。试用期间重点考查工作态度和敬业精神，实际能力和潜在能力，道德素质和责任心。对于表现突出，工作成绩优异者可以提前结束试用期。 　　2、试用期满由部门经理提出意见，经行政人事部研究和总经理批准，决定是否聘用。 　　3、确定正式聘用者，按《劳动法》的有关条款签订正式劳动合同。合同期限一般为3年。合同期满可以续签。', 489, NULL, '[\"公司\", \"员工\", \"工作\", \"试用期\", \"团结\", \"有效\", \"新\", \"发展\", \"要求\", \"正式\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:24', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:24', '0');
INSERT INTO `document_segments` VALUES ('1955803408975622145', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　4、签订正式劳动合同者应将学历证书、职称证书交行政人事部保存。 　　5、员工分到部门后，由部门经理管理，安排工作岗位，确定工作职责，履行工作义务。 　　6、工龄津贴，员工进公司满两年起每年递增20元。每年元月份统一递增。 　　7、员工要求提前解除劳动合同，应有充足理由，并提前一个月写出书面申请，由部门负责人审批，交行政人事部。主动与部门办好工作交接手续，交还公司财物，结清财务手续后方可批准离职。经考查，若无工作遗留问题，且对公司无利益损害者，3到6个月后退还个人证件等。凡参与工程项目负责或责任者要求辞职必须待工程竣工验收合格工程款收回后(不包括包修款)再办理相关手续，否则，由此造成的后果需承担责任，公司也有权扣留当月工程工资及有关奖金有追究责任的权力。未结清以上手续而离职者，公司将按劳动合同及公司相关制度执行。 　　8、养老保险，按养老金基数10%予以补贴，签订劳动合同工作满2年者，公司办理养老保险。公司负担10%，个人负担8%，签订劳动合同并工作5年以上者，补发一年10%养老补贴。 　　9、对有能力、有实力、有贡献、有责任心的员工，给予提前晋级加薪，优先提拔重用。', 492, NULL, '[\"公司\", \"工作\", \"员工\", \"劳动合同\", \"手续\", \"提前\", \"部门\", \"工程\", \"%\", \"要求\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:24', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:24', '0');
INSERT INTO `document_segments` VALUES ('1955803409025953794', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　9、对有能力、有实力、有贡献、有责任心的员工，给予提前晋级加薪，优先提拔重用。 　　10、违反公司纪律、贻误商机影响工作或造成经济损失者，视情况分别予以警告、经济处罚、记大过或解聘。 　　11、公司行政人事部负责对员工的全面考核、工资、奖金的审核、人事档案管理等以及员工奖惩情况的记载。 　　12、根据公司年度效益，对下列人员实行年终奖励： 　　A、经济效益好的部门经理、副经理; 　　B、圆满完成本职工作、出勤好、责任心强的员工; 　　C、有突出贡献的员工。 　　13有下列情况之一者不实行年奖金： 　　A、全年经济效益不好的部门; 　　B、出现重大质量事故的责任人; 　　C、拖延时间，贻误工作，造成重大经济损失和社会影响者。 　　D、违反公司纪律，工作自由散慢，不听从指挥者。 　　E、个人全年病事假超过20天者。 　　14、除行政后勤人员外，其它部门均实行承包制，即部门经理竞争上岗，人员优化组合，工资上不封顶，下不保底。如每年四月份以前无业绩、无工程创收，只发给该部门负责人基本工资70%。六月份以前无业绩、无工程创收，该部门全体拿70%工资。如年终核算后属于完成指标任务的部门可补齐扣发的`工资额。', 507, NULL, '[\"部门\", \"员工\", \"公司\", \"工资\", \"情况\", \"实行\", \"工作\", \"完成\", \"行政\", \"全年\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:24', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:24', '0');
INSERT INTO `document_segments` VALUES ('1955803409076285442', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　四、请假和休假 　　1、本公司员工实行每周天工作制。作息时间有夏、冬季之分。 　　2、聘用离退休人员每月累计工作20天，缺勤按平均月工资扣除。 　　3、员工考勤实行工作量制，由行政人事部及部门经理负责考核。 　　4、员工因病请假需有医院证明，月内超过两天者，从第三天起工资减半发放。 　　5、员工有事请假者，应提前一天书面申报，部门经理审批交行政人事部备案，未经批准者视为旷工，无故旷工一日扣发三天基本工资。 　　6、国家规定的节假日，本公司员工带薪休假。 　　7、享有婚、产假政策的员工，按国家及公司规定带薪休假，因工作需要提前上班人员，按日工资补贴发放。 　　8、员工在本公司工作满一年后，每年可享受天公休假，并随着工龄增加，每年递增一天，但最多不超过天。公休假年度内因工作紧张无法休假者，按日工资于年底补贴发放。 　　五、工资政策 　　公司工资实行：基本工资(年薪工资)+工龄工资+岗位工资 　　六、用车制度 　　1、杜绝公司员工用公车办私事。 　　2、各部门员工在市区办事，在交通方便、无紧急事务之时，应搭乘公共汽车，公司不另行安排车辆。', 475, NULL, '[\"员工\", \"公司\", \"工作\", \"工资\", \"实行\", \"日\", \"休假\", \"应\", \"超过\", \"提前\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:24', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:24', '0');
INSERT INTO `document_segments` VALUES ('1955803409126617090', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　2、各部门员工在市区办事，在交通方便、无紧急事务之时，应搭乘公共汽车，公司不另行安排车辆。 　　3、业务部由于陪同客户的需要，非工作时间用车的，由业务部经理提出申请，经证实后，由行政人事部批准后方能出车。 　　4、司机出车返回后，应在派车单上填写行驶公里、出车费用，并由出车人证明后，司机凭车单报销出车费用。 　　5、司机应爱护车辆，保持车辆内外清洁，经常检查车辆。司机于下班后，将车钥匙交给行政人事部保管。 　　6、司机应及时对车辆进行维修保养，所有车辆的维修由司机凭车辆委托维修单于指定的汽车修理厂维修。车辆加油亦需在指定的油站加油。 　　7、对因司机或驾车人不慎造成的车辆损坏或交通违规，公司将视情况给予行政或经济处罚。 　　8、公司将对所有车辆建立管理档案，登记车辆事故及维修的情况。 　　七、物品领用 　　入职员工的文具物品、通讯设备、办公用品均于行政人事部办理领用手续后使用，员工应本着爱护公物、节约的原则。 　　八、报销须知 凡报销出差费用、业务定额费用、宴请费用、采购费用、广告费用、通讯设备费用等均应参照公司现有费用报销办法及程序。 员工手册范本 篇12', 488, NULL, '[\"车辆\", \"司机\", \"应\", \"行政\", \"费用\", \"员工\", \"公司\", \"报销\", \"人事部\", \"维修\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:24', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:24', '0');
INSERT INTO `document_segments` VALUES ('1955803409172754433', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '员工手册范本 篇12 　　收银员是顾客对超市服务行为最直接感受的来源，收银员的热情程度、工作态度、为顾客解决问题的程度都是顾客直接感受到的超市的形象。 　　收银员职责： 　　一、给顾客优质高效热情的服务：代表良好的重庆工商职业学院超市营销实训室形象。 　　二、收银员在结算时须唱收唱付(不要将钱扔给顾客,应将钱和小票一起交给顾客)： 　　1、唱收唱付，收顾客钱款时，要唱票 “您的商品多少钱”，“收您多少钱”找零钱时唱票 “找您多少钱”。 　　2、对顾客要保持亲切友善的笑容。 　　3、耐心的回答顾客的提问、解决顾客问题。 　　4、在营业高峰时间，听从当日值班店长(助理)安排其它工作。.例如：查价格，清理手推车，兑换零用金。 　　三、确保商品正确销售： 　　1、超市在促销活动中所发的广告或赠品确认后放入袋内。 　　2、装袋时避免不是同一位顾客的商品放在同一购物袋中的现象。 　　3、正确扫描条码，正确找零。 　　4、提醒顾客带走所有商品，防止遗忘在收银台上的事情发生。 　　四、保持收银台时刻整洁干净：保证收银台无除顾客商品外其他杂物。', 470, NULL, '[\"顾客\", \"收银\", \"商品\", \"超市\", \"正确\", \"钱\", \"工作\", \"保持\", \"时\", \"热情\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:24', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:24', '0');
INSERT INTO `document_segments` VALUES ('1955803409260834817', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　四、保持收银台时刻整洁干净：保证收银台无除顾客商品外其他杂物。 　　五、仔细检查特殊商品：如值班收银台上的吸管、纸巾、口香糖、热柜里的饮品是否有缺货的情况，如有缺货情况，在非营业高峰期迅速补齐货品。 　　工作班次及工作流程： 　　1. 早一班(7：30~10：20)值班员工在店长(助理)开门后进入超市营销实训室办公室，刷指纹签到——穿工作服，佩戴工作证——于7:30准时打开卖场大门——将饮水机装满饮水后搬至微企创业实训点大门右侧——将欢迎光临地毯放置于进门处表示迎接顾客——将卖场内大型杂物处理掉，收银台整理整洁——在店长(助理)处领取零钱，记清所领金额——打开收银机(如插线板没开应先开插线板)，点击收银系统，登录自己个人账号——开钱箱，按照大面额在左小面额在右原则将零钱置于pos机钱箱内——(pos机1号收银员开启音响，放轻柔音乐表示正式营业)——开始收银。 　　2. 早二班(10:20~12:15)打指纹签到——穿工作服，佩戴工作证——与上一班收银员共同确认早一班收银金额无误后，留下零钱(请准确确认，一旦出现错误将由两人共同承担责任)——开始收银 　　3. 中午值班(12:15-13:30)', 506, NULL, '[\"收银\", \"零钱\", \"班\", \"值班\", \"早\", \"机\", \"表示\", \"营业\", \"卖\", \"打开\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:24', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:24', '0');
INSERT INTO `document_segments` VALUES ('1955803409311166466', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　3. 中午值班(12:15-13:30) 　　由早二班留下一名员工值班或者两名员工轮换(值班员工注意保重身体)保证中值期间至少一台pos机有员工值班。 　　4. 中班(13:30-17:30)打指纹签到——穿工作服，佩戴工作证——与上一班收银员共同确认早一班收银金额无误后，留下零钱(请准确确认，一旦出现错误将由两人共同承担责任)——开始收银 　　5. 晚班(17：30-20:45)打指纹签到——打指纹签到——穿工作服，佩戴工作证——与上一班收银员共同确认早一班收银金额无误后，留下零钱(请准确确认，一旦出现错误将由两人共同承担责任)——开始收银——当天最后一班收银结束后，晚班工作人员打扫卖场及超市营销实训室办公室清洁，并讲饮水机、欢迎地毯放回卖场内部，待店长/助理关上卖场大门后，方可结束工作。 　　收银流程： 　　(1)顾客走至收银台付款时首先对每位顾客轻声面带微笑讲出欢迎用语：”你好，欢迎光临。”同时接过顾客手中准备付款的商品。 　　(2)扫描商品条码，确认无误后，念出应收金额，如：”一共12元谢谢。”接过顾客付的现金。 　　(3)顾客付钱后念出找零金额，如：”收您20元，找您8元，谢谢。”同时递上找零金额及小票。', 517, NULL, '[\"收银\", \"顾客\", \"卖\", \"班\", \"金额\", \"确认\", \"机\", \"欢迎\", \"员工\", \"值班\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:25', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:25', '0');
INSERT INTO `document_segments` VALUES ('1955803409357303810', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　(3)顾客付钱后念出找零金额，如：”收您20元，找您8元，谢谢。”同时递上找零金额及小票。 　　(4)顾客拿取已付款商品离开时应讲出：”欢迎再次光临。” 　　收银流程细则： 　　先扫描顺着条形码方向扫描商品，如果无条形码的商品(如纸巾、早点、文具)，则按照柜台所贴资料条扫描条码或输入相应的货品代号。如果是多次扫描失败的商品，则在收银机输入该商品后六位的货品条码按“Ente”结束。 　　(1) 在每位顾客的选中的商品扫描完成确认无误后，向顾客报出收银机显示的合计应付款金额，敲击键盘最右侧的“+”键而后键入“Enter”，等待顾客付款，顾客付款后在付款金额栏内输入金额按“Enter”结束，等待钱箱弹出，取出屏幕显示应找零数量的现金，撕下小票，合并交付于顾客，结束本单。 　　(2) 如顾客选择校园一卡通方式付款，则在屏幕显示的方框内输入顾客消费额，并用鼠标点击屏幕左下方的“收款方式”选择“一卡通”，在校园一卡通刷卡器上输入金额，敲击结账，待顾客将卡置于刷卡器上，刷卡器发出“滴滴”提示音表示成功刷卡后，在pos机上按敲击“Enter”结束本单。 　　(3)', 483, NULL, '[\"顾客\", \"金额\", \"输入\", \"商品\", \"扫描\", \"付款\", \"结束\", \"屏幕\", \"敲击\", \"显示\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:25', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:25', '0');
INSERT INTO `document_segments` VALUES ('1955803409407635458', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　(3) 如顾客选择校园卡与现金结合的方式付款，则在屏幕右侧方框内输入现金金额，校园卡需刷卡金额，收取顾客应付现金后，在校园一卡通刷卡器上输入金额，敲击结账，待顾客将卡置于刷卡器上，刷卡器发出“滴滴”提示音表示成功刷卡后，在pos机上按敲击“Enter”结束本单。 　　(4) 如果顾客在小票打出前要求退回此前已输入在收银机的商品，则按键盘最右列“-”再“Enter”，输入所退商品在购物列表中所在的行数。如果小票已打出则依次按出“1”“6”“Enter”，再在上面的方框内输入小票编号，在下面的方框内输货品代号。 　　Ps：(1)如若出现收银机硬件问题无法正常操作，导致无法开展收银工作时： 　　首先应告知顾客具体原因，在顾客接受解释的情况推荐顾客至另一台POS机结账，然后自行查看收银机问题发生原因，在自身无法修缮的情况下告知店长(助理)及时解决问题。 　　(2)商品无条码问题、库存不足等数据问题：应及时告知顾客并向顾客提出解决办法(换一种商品、等解决问题后再购买等解决方式)，在顾客理解的情况下完成收银， 并在收银高峰期结束后将问题反馈至店长(助理)及时解决问题。', 487, NULL, '[\"顾客\", \"问题\", \"输入\", \"商品\", \"卡\", \"收银机\", \"Enter\", \"情况\", \"再\", \"方框\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:25', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:25', '0');
INSERT INTO `document_segments` VALUES ('1955803409457967105', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '并在收银高峰期结束后将问题反馈至店长(助理)及时解决问题。 　　(3)顾客要的产品本超市没有等产品问题时：应向顾客道歉，委婉解释原因，记录下欠缺商品，及时告知店长(助理)解决问题。 　　交接班注意事项： 　　(1) 做交班准备前必须保证下班员工已经到卖场，首先交pos2，然后交pos1，分开时间段交接班，。 　　(2) 交班的收银员与当班收银员须共同清点好所收现金、所刷校园卡金额，确认无误后到办公室签字，交大额纸币至值班店长(助理)处，将金额填写至超市营销实训室账簿，签上本人名字，店长(助理)签名确认后方可离开。 　　(3) 在填表后，将所填表格交由店长/助理审核。在交接班人员、店长/店长助理签字后，交班收银员方可离开。 　　(4) 在不可逆特殊情况下，有可能出现要求代班，继续上班或临时性要求到场的情况，请所有员工理解工作，服从当班店长(助理)安排。 　　收银员工作考核标准： 　　1、有强烈的工作责任心，遵守考勤制度，超市的收银工作能够无误完成; 　　2、严格按照规定穿着工服，保持个人仪表仪容的整洁大方。以良好的仪表、仪容，饱满的精神向客人提供准确、快捷、礼貌的优质服务;', 493, NULL, '[\"店\", \"收银\", \"长\", \"助理\", \"工作\", \"超市\", \"交班\", \"问题\", \"员工\", \"交接班\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:25', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:25', '0');
INSERT INTO `document_segments` VALUES ('1955803409508298754', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　3、按时到岗，备足营业用零钞、发票做好营业前的准备及清洁工作。保持收银台的整齐、干净，保证收银台临时性需求商品的货品摆放量足够。 　　4、掌握现金、一卡通、挂帐等结帐程序;准确打印台号的各项收费帐单，熟记特殊商品价格及电脑号码账号等有关收银程序; 　　5、收银员在操作过程中，如遇错单作废必须由店长/助理签字方能认可，否则一切损失由承接责任人承担。 　　6、严格遵守财务制度，每天的大额现金(100元整)收入在交班时必须及时上交至店长(助理)处，特殊情况需向店长(助理)汇报，做到款帐相符; 　　7、周转备用金必须每班核对，具有表格记录，每天的营业收入现金未经店长(助理)批准，不得以任何借口借出给任何人，或私自挪用; 　　8、收银员不得在收银工作中挪用现金，除校方、院办等可记账单位外私自给予其他个人或单位记账行为，损害超市利益，如经发现给予开除并赔偿经济损失。 　　9、收银员不得在上班时间中途离开岗位。如必须暂离岗位，要经过经店长(助理)同意，应注意钱款安全，随时锁好抽屉和钱柜，; 　　10、严禁在收银台存放酒水或与工作无关的私人物品，严禁在卖场吃东西。', 483, NULL, '[\"收银\", \"助理\", \"现金\", \"长\", \"必须\", \"工作\", \"营业\", \"店\", \"商品\", \"程序\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:25', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:25', '0');
INSERT INTO `document_segments` VALUES ('1955803409558630401', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　10、严禁在收银台存放酒水或与工作无关的私人物品，严禁在卖场吃东西。 　　11、在收款中做到快、准、礼貌，不错收、漏收客人款项，对签单及挂帐者，必须依据充足方可; 　　12、熟练掌握面额现钞的鉴伪技术及验钞机的使用方法，防止伪钞收入;认真识别现金真伪，发现假钞应立即退还该顾客解释并调换其他现钞。 　　13、收银员应严格遵守财务保密制度，不得向无关人员和外界泄露超市的营业收入情况、资料、程序及有关数据;必须严格按指定的收银折扣、管理人员店长(助理)签字权限操作(如有超出及时提醒)，否则给超市带来的经挤损失由收银员赔偿。 　　14、熟练掌握收银、输单、操作过程及退单、挂单的程序，每班负责填写营业日报表，做到及时上交; 　　15、不得在收银台前与任何人闲谈，非工作人员不许进入收银台;不得使用电脑做其它与收银无关的工作; 　　16、认真填写营业后的交款单据，须做到帐物相符。', 390, NULL, '[\"收银\", \"做到\", \"无关\", \"必须\", \"现钞\", \"及时\", \"认真\", \"填写\", \"收入\", \"超市\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:25', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:25', '0');
INSERT INTO `document_segments` VALUES ('1955803409604767746', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　16、认真填写营业后的交款单据，须做到帐物相符。 　　17、收银员在营业结束后，应认真核对好当日营业收入款，必须认真核对报表数与实收数是否一致，如出现短(长)款，应及时查明原因，如属收银员自身造成短款，由当日收银员全额赔偿，属其他原因造成的或未查明原因的，报当班店长(助理)处，经店长(助理)查明后处理. 　　18、准确、快速地做好收银结算工作。严格按照各项操作规程办事，在收款时自觉遵守财经纪律和财务制度，对于违反财经纪律和财务制度的要敢于制止和揭发，起到有效的监督作用。 　　19、爱护及正确使用各种机械设备(如电脑、打票机、计算器、验钞机等)，并做好清洁保养工作。 　　20、积极完成店长(助理)分配的其他工作。 员工手册范本 篇13 　　1.收银归财务部管，是财务部派到楼面工作的部门。 　　2.收银部在楼面上班，员工纪律归楼面管，若因工作与楼面发生矛盾，由楼面负责协调，特殊情况由财务部、楼面部共同解决。 　　3.收银员不得利用工作之便挪用、抽取营业款，也不得代人签单、模仿签单、涂改单据。一经发现，公司将会严重处罚，并按贪污处理，若需涂改单据必须经总经理签字。', 488, NULL, '[\"收银\", \"工作\", \"单据\", \"长\", \"款\", \"楼\", \"查明\", \"营业\", \"助理\", \"财务\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:25', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:25', '0');
INSERT INTO `document_segments` VALUES ('1955803409655099393', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　4.收银员收到签单时，务必核对有否总经理或董事批示方可接收 　　5.营业收入款每晚收工后巴点清并交总经理点清，若有任何差错由收银员自己赔偿，如钱多则将多出之数交回公司归入基金。 　　6.收工前点清银头数，交财务部存放，不得挪用银头数，否则按贪污处罚 　　7.收银部要配合财务部随时检查银头数，不得阻拦刁难，否则立即开除 　　8.收银员每晚收场后必须整理好单据，交审核处复核，如发现单钱不符，照价赔偿，当天必须结清 　　9.按规定做每日报表，交财务部复核制毛利表 　　10.收银部有责任完成董事局、总经理要求做的营业收入分析资料。 　　11.现金银头交接务必点清，避免发生误会 　　12.认真检查真伪币，尽量杜绝错收假币。如收回假币，收银员负责赔偿 　　13.听从财务部的安排，不得讨价还价，不得将手袋及其他私自人物品放收银处 　　14.收银繁忙时段不得离开收银处，宵夜由服务员送，节假日不得安排休假，上班时间不得离开本公司营业范围，特殊情况由经理批准。 　　15.收银员上班时间为晚上7：00～早上6：00一班制，务必准时上班，迟到按公司制度处理。', 476, NULL, '[\"收银\", \"交\", \"财务\", \"务必\", \"清\", \"公司\", \"营业\", \"总经理\", \"头数\", \"检查\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:25', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:25', '0');
INSERT INTO `document_segments` VALUES ('1955803409726402561', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　15.收银员上班时间为晚上7：00～早上6：00一班制，务必准时上班，迟到按公司制度处理。 　　16.不管总经理及一切管理人中都不能在收银处借支营业款及银头数，如有特殊情况属公司事宜，可按情况处理 　　17.服务态度要认真、细心、准确、互相配合，共同做好工作，完成任务 员工手册范本 篇14 　　1、收银员每天应提前5分钟到所在收银机，进行班前准备工作，欲期不到者，按迟到论处。 　　2、收银员在营业场内，身上不能带有现金，以免引起不必要的误解和可能产生的公款私挪现象。违者罚款5—10元。 　　3、收银员在进行收银工作时，不可擅自离开收银台，以免造成钱币损失，或引起等候结算的顾客不满与抱怨。如每发现一次者，纳入当月考核，对情节严重者罚款5—10元。 　　4、收银员不能为自己的亲朋好友结算收款，以免造成不必要的误会和可能产生的，收银员用收银职务的方便以低于原价的收款登录到收银机，以企业利益来图利于他人私利，或可能产生的内外勾结的“盗窃”。违者除补尝损失的5倍外，罚款20—50元，情节严重者，予以辞退。', 456, NULL, '[\"收银\", \"不能\", \"工作\", \"产生\", \"可能\", \"班\", \"迟到\", \"收银机\", \"损失\", \"处理\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:25', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:25', '0');
INSERT INTO `document_segments` VALUES ('1955803409776734210', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　5、收银台上除茶水外，收银员不能放置其他任何私人物品，因为收银台上随时都有临时决定不要的孤儿商品，如有私人物品也放在收银台上，容易与这些商品混淆，以免他人误会，违者除纳入当月考核外，罚款5元。 　　6、收银员不能任意打开收银机抽屉查看数字和清点现金，因随意打开收银机抽屉，既引人注目造成不安全因素，也会使人产生对收银机营私舞弊的怀疑，或造成不安全的事故发生。如有此类现象发生者纳入当月考核。造成安全隐患者，追究其经济责任。 　　7、不启用的收银通道须用链条连接，以免顾客混出卖场，从而造成不必要的商品损失，如有此现象者，纳入当月考核，对造成经济损失者除陪偿所有经济损失外，罚款5—10元。 　　8、在备用金的留放方面：多次因备用金留错而造成长短款现象者，根据次数多少纲入当月考核。 　　9、除两名收银组长外，其它收银员一律不能进行退货业务，否则按违纪论处，情节严重者罚款5元;对于商品打折业务，须经相关领导签字许可，不可私自打折，若发现，除对折让金额个人承担外，并处以折让金额1—5倍的罚款。 　　收银员引起顾客投诉处罚制度 　　1、因操作失误，造成多扫而引起顾客投诉者，除纳入当月考核外，即每次扣5分。', 504, NULL, '[\"造成\", \"收银\", \"外\", \"罚款\", \"商品\", \"考核\", \"当月\", \"纳入\", \"顾客\", \"收银机\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:25', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:25', '0');
INSERT INTO `document_segments` VALUES ('1955803409827065857', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　1、因操作失误，造成多扫而引起顾客投诉者，除纳入当月考核外，即每次扣5分。 　　2、收银员因工作责任心不强，造成漏扫商品者，除按漏扫商品售价2倍金额陪偿外，每次罚款5—10元。 　　3、因收银员态度原因而引起顾客轻微抱怨者，每次扣分5分;引起顾客强烈不满者，每次依据情节轻重处罚10—20元;造成不良影响的，即被媒体报道者，当月下浮基本工资的10%。 　　4、收银员因吃饭倒班不合理，造成因顾客排队抱怨者，根据情节纳入当月考核。 　　收银员日常纪律考核标准及处罚制度 　　1、对激励机制、倒班不满，但又不当面指出不满原因而在背地乱说者，每次扣5分。 　　2、收银员工作区域即收银台脏、乱、差者，依据对超市危害严重性，对其纳入当月考核。 　　3、收银员因请假手续不清，而造成前台无人收款现象者，对收银组长。纳入当月考核。对当事人处以5—10元的处罚。 　　4、收银员未严格按照收银工作流程及服务用语操作和接待顾客者，每次每人扣5分，对类教不改者处以5—10元的罚款。 　　5、在微机硬件维护方面，由于违规操作或误操作而造成POS机无法正常工作，从而影响正常销售者，纳入当月考核，对情节严重者给予5元的经济处罚。', 506, NULL, '[\"收银\", \"造成\", \"当月\", \"纳入\", \"顾客\", \"考核\", \"工作\", \"扣\", \"处罚\", \"引起\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:25', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:25', '0');
INSERT INTO `document_segments` VALUES ('1955803409877397506', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　6、收银员不配合收银组长安排吃饭时间而造成脱岗现象者，每人每次给予5元的经济处罚。 员工手册范本 篇15 　　1、遵守国家政策，法令和公司一切规章制度，爱护公共财物认真执行岗位责任制。 　　2、应按公司规定的工作时间上下班，不得迟到、早退、不得擅离岗位，不得无故旷工。工作时间内不许闲谈作乐，不许吵嘴打闹，不许串岗位和离岗，不许做与生产无关的事。 　　3、服从生产工作安排、调动、努力钻研生产技术，提高自身素质水平，做好本职工作。 　　4、请病假、事假要有正当的理由，并写请假条办理审批手续，由公司经理审批。违者作旷工处理。 　　5、工作时间内，因事或因看病要离开岗位的，要向生产主管请假同意后方能离开，否则作早退处理。 　　6、不得带任何食品杂物入车间，不得在车间吃食物，不准在车间乱丢杂物及随地吐痰，违反本条例之一者要批评处理。 　　7、进入规定要穿工作服的工作间一定要穿工作服，严禁携带手表、首饰等个人物品进入生产区、接触产品的人员不得留长指甲或涂指甲油。 　　8、防蝇、防虫纱窗不得随意打开，发免影响生产环境卫生。 　　9、爱护公司财产，不得私带厂内任何物品出厂，违者则按物品价值的十倍罚款，重则开除。', 507, NULL, '[\"生产\", \"公司\", \"工作\", \"岗位\", \"处理\", \"物品\", \"时间\", \"进入\", \"安排\", \"规定\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:25', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:25', '0');
INSERT INTO `document_segments` VALUES ('1955803409927729153', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　9、爱护公司财产，不得私带厂内任何物品出厂，违者则按物品价值的十倍罚款，重则开除。 　　10、运送产品，物资要小心轻放，不得乱掉重摔。造成损坏的由违纪者负全部责任（包括搬运工。） 　　11、吸烟要到吸烟区。仓管员岗位责任制一、仓管人员验收实物必须亲自过目，物品名称、规格一定要核对无误，数量一定要点清（包括点数、称斤、计量等）精确，对不符合规格、质量低劣的.物品，不得验收入库。遇有争议提交有关部门研究处理。（非定量包装和大宗材料验收数量增加胡汝昆、验收质量刘钦光）。 　　二、生产部门领用物品必须先填写领料单（一式三份），一份自存、一份生产部门存、一份交财会记帐，内容（领料部门、领料人、数量等）必须清楚、完整和准确无误。 　　三、仓库管理要保持清洁卫生，物品堆放合理，发料采用先进先出、后进后出的原则，对易燃、易爆、易潮、易腐、易损物品或贵重物品要特殊保管，保证做到不霉、不烂。严防失火、失窃等事故发生。', 406, NULL, '[\"物品\", \"验收\", \"部门\", \"数量\", \"必须\", \"包括\", \"领料\", \"规格\", \"质量\", \"生产\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:25', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:25', '0');
INSERT INTO `document_segments` VALUES ('1955803409990643714', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　四、仓管员对所保管的物品，平时做到勤抽查、勤核对，保证做到帐物相符、帐帐相符。如有盘盈，要提出书面材料，说明原因。属于正常耗损、经主管负责人批准转财会部门核销出帐；属于非常亏损、追究保管人员责任。 员工手册范本 篇16 　　目 录 　　第一章 公司简介及企业文化(略) 　　第二章 入职指引 　　第三章 员工守则与行为规范 　　第四章 薪酬与福利 　　第五章 请假及休假制度 　　第六章 奖惩办法 　　第七章 员工关系与沟通 　　附件1：《员工手册》使用说明 　　第一章 公司简介及企业文化 　　一、公司简介 　　(略) 　　二、企业文化 　　(略) 　　第二章 入职指引 　　一、报到 　　员工被录用时，按公司要求出示有关证件或证明原件，经核对无误后公司有权留存相关证件或证明的复印件，此等证件或证明包括但不限于：离职证明、居民身份证复印件、应聘登记表、毕业证书(包括学位证书)、相关资质证书、婚姻状况证明、照片、医疗检查文件及推荐书等。 　　以确保员工的相关权益，请在以下个人资料发生变更后一个月内向公司出示相关证明的原件并保留下复印件： 　　1、姓名或身份证; 　　2、户籍; 　　3、婚姻状况; 　　4、职称、从业资格; 　　5、培训结业或进修毕业。', 531, NULL, '[\"员工\", \"证明\", \"相关\", \"属于\", \"复印件\", \"公司\", \"婚姻状况\", \"说明\", \"核对\", \"保管\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:25', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:25', '0');
INSERT INTO `document_segments` VALUES ('1955803410040975361', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　2、户籍; 　　3、婚姻状况; 　　4、职称、从业资格; 　　5、培训结业或进修毕业。 　　二、新进员工培训 　　员工进入公司后，公司将安排相关人员对新进员工进行入职培训。 　　三、试用期与转正 　　劳动合同期限三个月以上不满一年的，试用期为一个月：劳动合同期限一年以上不满三年的，试用期为二个月;三年以上固定期限和无固定期限的劳动合同，试用期为六个月，试用期工作表现合格者的，将被正式聘用为公司正式员工。 　　试用期内，如果员工休长病假，复工后未完成部分的试用期将相应顺延。 　　第三章 员工守则与行为规范 　　一、员工守则 　　1、忠于职守，服从领导，不得有敷衍塞责的行为。 　　2、不得经营与本公司类似或职务上有关的业务，不得兼任其它公司的职务。 　　3、全体员工必须不断提高自己的工作技能，强化品质意识，圆满完成各级领导交付的工作任务。 　　4、不得携带违禁品、危险品或公司规定其它不得带入工作场所的物品进入公司工作场 所。 　　5、爱护公物，未经许可不得私自将公司财物携带出公司。 　　6、工作时间不得中途任意离开岗位，如需离开应向主管人员请准后方可离开。 　　7、员工应随时注意保持作业地点、宿舍及公司其它场所的环境卫生。', 519, NULL, '[\"公司\", \"员工\", \"工作\", \"试用期\", \"培训\", \"完成\", \"领导\", \"离开\", \"新进\", \"携带\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:25', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:25', '0');
INSERT INTO `document_segments` VALUES ('1955803410087112705', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　7、员工应随时注意保持作业地点、宿舍及公司其它场所的环境卫生。 　　8、员工在作业时不得怠慢拖延，不得干与本职工作无关的事情。 　　9、员工应团结协作，同舟共济，不得有吵闹、斗殴、搭讪樊谈、搬弄是非或其它扰乱公共秩序的行为。 　　10、不得假借职权贪污舞弊，收受贿赂，或以公司名义在外招摇撞骗。 　　11、员工对外接洽业务，应坚持有理、有利、有节的原则，不得有损害本公司名誉的行为。 　　12、各级主管应加强自身修养，领导所属员工，同舟共济，提高工作情绪和满意程度，加强员工安全感和归属感。 　　13、按规定时间上下班，不得无故迟到、早退。 　　二、工作时间及考勤 　　1、上班时间为：上午8:00至12:00，下午14:30至17:30(具体休息时间以公司通知为准)。员工每天须在上午、下午上班之前和下班之后各刷卡一次，每个工作日共计四次。 　　2、因公外出或出差不能按时刷卡或忘记刷卡，请在月底的刷卡记录中写明原因并由部门负责人签字。未刷卡，又未请部门负责人签字的，将被视做旷工。 　　3、不得代他人刷卡。发现一次，代人刷卡者将从当月工资中扣除50元，被刷卡者按旷工处理。', 490, NULL, '[\"员工\", \"卡\", \"刷\", \"公司\", \"应\", \"行为\", \"同舟共济\", \"工作\", \"加强\", \"下午\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:25', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:25', '0');
INSERT INTO `document_segments` VALUES ('1955803410137444354', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　3、不得代他人刷卡。发现一次，代人刷卡者将从当月工资中扣除50元，被刷卡者按旷工处理。 　　4、迟到(早退)10分钟以内，按事假2小时处理;迟到(早迟)10分钟以上1小时以内，按事假半天处理;迟到一小时以上，按事假一天处理。 　　三、礼仪仪表 　　员工应注意遵守下列要求： 　　1、 工作期间，应保持精神振作、彬彬有礼、高效敏捷。 　　2、 上班时，应注意衣着整洁、大方、得体。男职员不可留长发，蓄胡须，女职员不可浓妆艳抹。有公司工作服的，要着工作服上班。 　　3、 同事间应互相尊重，互助互爱，语言文明，任何时候不谩骂对方。 　　4、 对外交往应有礼有节，不卑不亢，礼貌大方，简朴务实。 　　四、保密 　　每个员工都负有保守公司秘密的义务。这种保密的义务，不仅限于员工在公司工作的合同期内，而且还应注意无论是退休或离职后，都将承担这种义务： 　　1、 务必保管好自己持有的公司涉密文件。 　　2、 未经公司事先书面授权或批准，不得对外提供有密机的公司文件或其他未公 　　开的经营状况、财务数据等。 　　3、 对非本人职权范围内的公司机密，应作到不打听、不猜测、不传播。 　　4、 发现了有可能导致公司秘密泄漏的现象应立即向有关上级报告。 　　五、旷工和迟到', 531, NULL, '[\"公司\", \"应\", \"注意\", \"员工\", \"大方\", \"对外\", \"处理\", \"迟到\", \"义务\", \"文件\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:25', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:25', '0');
INSERT INTO `document_segments` VALUES ('1955803410225524737', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　4、 发现了有可能导致公司秘密泄漏的现象应立即向有关上级报告。 　　五、旷工和迟到 　　1、未经请假或假满后擅自不到职构成旷工。 　　2、员工旷工期间，公司不向其发放在此期间的薪资、奖金及相关津贴。 　　3、连续旷工三日或全月累计旷工六日或一年累计旷工达十二日者，公司有权立即解除 　　劳动合同，且不支付经济补偿金。 　　4、员工一个月内迟到或早退两次扣一天工资。 　　第四章 薪酬与福利 　　一、薪资 　　1、薪资构成 　　员工工资构成为：基本工资+绩效工资。 　　在公司工作满一年(包括一年)的员工，公司将根据其工作表现及公司效益决定发放相应数额的年终奖。 　　2、发薪日 　　工资按月发放，发放时间为次月 日，年终奖金发放时间为农历春节前。 　　3、薪资调整 　　每年 月份，公司对员工进行绩效考核，并根据考核结果对员工薪资进行调整。 　　二、社会保险 　　公司为正式聘用的员工缴纳养老、失业、医疗、生育等国家法定社会保险。 　　三、福利 　　公司可根据员工的职位及工作性质提供相应数额的交通补贴、通讯补贴、节假日津贴。 　　第五章 请假及休假制度 　　一、请假 　　1、事假', 493, NULL, '[\"公司\", \"员工\", \"旷工\", \"薪资\", \"发放\", \"工资\", \"请假\", \"日\", \"迟到\", \"工作\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:25', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:25', '0');
INSERT INTO `document_segments` VALUES ('1955803410275856386', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　第五章 请假及休假制度 　　一、请假 　　1、事假 　　请事假应事先填写请假单，经相关负责人审批后交人备案，事假超过一天的，还应经总经理审批。事假获准后，应在离开工作岗位之前安排好工作，临时外出超过四小时的，视为请假半天。 　　2、病假 　　员工须于上班前或不迟于上班后30分钟内告知相关负责人请假事宜，于病假后上班的第一天填写请假单，并附区(县)级以上医院出具的病休证明。未能在上述规定时间内提供病休证明的，按事假处理。 　　3、婚假 . 　　达到法定婚龄者婚假为3天，晚婚者(男年满25周岁初次结婚者为晚婚;女年满 　　23周岁初次结婚者为晚婚)为1 0天，限一次用完。不在本公司申办开具结婚证明 　　手续的员工在本公司不享有婚假。员工应在结婚登记之日起一年内提出婚假申请， 　　事先填写请假单，并附结婚证明，员工在试用期内办理结婚登记的，待试用期届满 　　并转正后，方可向公司提起婚假申请。婚假不包括法定假日，但包括法定休息日，员工不休或未休满婚假的，公司不另行给予经济上的补偿。 　　4、产假/陪产假 　　4.1、女员工产假90天;晚育(女24周岁以上初育为晚育)的，增加产假30天;非顺', 500, NULL, '[\"员工\", \"婚假\", \"事假\", \"公司\", \"证明\", \"填写\", \"请假单\", \"请假\", \"结婚\", \"应在\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:25', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:25', '0');
INSERT INTO `document_segments` VALUES ('1955803410326188034', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　4.1、女员工产假90天;晚育(女24周岁以上初育为晚育)的，增加产假30天;非顺 　　产的，增加产假15天;多胞胎生育的，每增加一胎，增加产假15天。 　　4.2、产假原则上为产前15天，产后75天，产前产假超过15天部分者，应于产后可请假天数中扣除，产前产假不足15天部分者，产后可补请。 　　4.3、男员工可请陪产假1天，以一次为限;配偶为晚育的，陪产假为3天。 　　5、丧假 　　如员工的直系亲属(包括配偶、父母、子女)不幸亡故，公司给子3天的假期。 　　二、休假 　　1、年假 　　1.1凡在公司连续工作满一年以上的员工，自第二年开始享有至少5天的年假。以后每满一年增加1天，最多不超过10天，休假之前应先规划，以不影响现行工作，并经核准为限。 　　1.2当年年假应在当年年度一次性休完，经相关负责人批准，可延长至次年二月份之前休完。因员工个人原因未休年假者，公司不另行给予经济上的补偿。 　　三、请假及休假待遇 　　1、事假 　　事假期间工资应全额扣除，当月实发工资=月工资—(月工资/当月工作日总数事假天数)。一年之内，员工累计事假天数不得超过10天，超过者，公司可酌情决定不向其发放年终奖直至解聘。', 509, NULL, '[\"员工\", \"产假\", \"公司\", \"年假\", \"超过\", \"休假\", \"休\", \"增加\", \"事假\", \"天数\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:25', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:25', '0');
INSERT INTO `document_segments` VALUES ('1955803410372325377', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　2、病假 　　病假期间工资按原工资的60%(即扣除40%)计发，当月实发工资=月工资—(月工 资/当月工作日总数事假天数40%)。一年之内，员工累计病假天数超过20天，公司可酌情决定不向其发放年终奖。 　　3、产假 　　产假期间由生育保险基金按照公司上一年度该员工月平均工资向该员工支付生育津贴。 　　4、其他 　　婚假、丧假、年假、法定假日期间员工工资全额发放。 　　第六章 奖罚办法 　　一、一般规定 　　本奖惩办法系公司奖励和处罚员工的依据与规定。员工具有以下奖惩之情形者，应由直 　　属主管或管理部门依事实呈报，经总经理核准后公告，并列入员工个人记录。有关奖惩 　　措施于年底相抵之后将给予：加/减薪、升/降级、加/扣奖金等奖励或处罚。 　　二、奖励 　　1、嘉奖 　　员工有下列行为之一的，可授予嘉奖一次： 　　1.1品行端正、工作努力、有具体成效并能及时完成任务者; 　　1.2热心服务，表现积极，有优良具体事实者; 　　1.3爱护团体荣誉，足为同仁表率者; 　　1.4协调或促进内部团结表现特佳者; 　　1.5有其它功绩者。 　　2、记功 　　员工有下列行为之一的，可授予记功一次：', 500, NULL, '[\"员工\", \"奖惩\", \"公司\", \"期间\", \"事实\", \"具体\", \"表现\", \"%\", \"发放\", \"生育\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:25', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:25', '0');
INSERT INTO `document_segments` VALUES ('1955803410422657025', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　1.5有其它功绩者。 　　2、记功 　　员工有下列行为之一的，可授予记功一次： 　　2.1工作效率特高，大幅提前完成重大任务者; 　　2.2对业务开发有特殊贡献者： 　　2.3对于公司经营或管理制度建议改进，经采纳施行后，卓有成效者; 　　2.4遇有突变，勇于负责，，处置得宜者; 　　2.5举发舞弊、违规、盗窃、泄密、浪费、损毁公物或其它有关本公司权益者; 　　2.6有其它较大功绩者。 　　3、记大功 　　员工有下列行为之一的，可授予记大功一次： 　　3.1遇紧急事故，奋不顾身，不避危难，处置得宜，保全人身或财物之安全，因而减少损害者; 　　3.2维护公司重大利益，避免重大损失者; 　　3.3有其它重大功绩者。 　　4、奖金或晋级 　　员工有下列行为之一的，可授予奖金或晋级—次： 　　4.1一年内记大功三次者; 　　4.2对于公司业务有特殊贡献，足为全公司表率者; 　　4.3有其它特殊功绩者。 　　三、惩罚 　　1、申戒 　　员工有下列行为之一且经查证确实者，课4以申戒一次： 　　1.1 工作经常落后，未按规定作业或作业不详、不实者; 　　1.2 未按规定穿著服装，经警告不听劝告者; 　　1.3 无故不参加公司各种集会或活动者; 　　1.4 与同事争执不听劝阻者; 　　1.5', 548, NULL, '[\"公司\", \"功绩\", \"员工\", \"行为\", \"特殊\", \"宜\", \"处置\", \"记大功\", \"听\", \"授予\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:25', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:25', '0');
INSERT INTO `document_segments` VALUES ('1955803410468794370', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　1.2 未按规定穿著服装，经警告不听劝告者; 　　1.3 无故不参加公司各种集会或活动者; 　　1.4 与同事争执不听劝阻者; 　　1.5 办公场所内随地乱丢果皮纸屑、吐痰、制造脏乱者; 　　1.6 在禁烟区内吸烟者; 　　1.7 在工作场所喧哗、嬉戏、吵闹，妨害他人工作;在工作现场吃零食;在上班时间玩游戏或从事其他娱乐活动者; 　　1.8 上班时间从事非业务有关之私事者; 　　1.9 有轻微旷工现象或多次上班迟到且无正当理由者;或 　　1.10 其它违反公司各种规定或工作规则应予申戒。 　　2、记小过 　　员工有下列行为之一经查证确实或有具体事证者，课以记小过： 　　2.1 因疏忽导致公司财物遭受损害或伤及他人者; 　　2.2 上班时间擅离职守怠忽工作者; 　　2.3 言行轻浮或其它违反善良风俗行为者; 　　2.4 担任主管，对属下不良行为知情不报者; 　　2.5 未经许可携带公司物品外出者; 　　2.6 未经许可擅自带外人进入公司者; 　　2.7 担任主管，滥用职权，恶意辱骂员工或谋取不当利益者; 　　2.8 不听上级指挥，违抗命令或恶意辱骂主管者; 　　2.9 主管值班未到岗，且事先未说明并安排替补者; 　　2.10 任职期间被申戒达三次者;或 　　2.11 其它违反公司各种规定或工作规则应予记小过者。 　　3、记大过 　　员工有下列行为之一经查证确实者或有具体事证者，课以记大过一次： 　　3.1', 613, NULL, '[\"公司\", \"听\", \"工作\", \"主管\", \"违反\", \"上班时间\", \"场所\", \"行为\", \"员工\", \"记\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:25', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:25', '0');
INSERT INTO `document_segments` VALUES ('1955803410519126018', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　3、记大过 　　员工有下列行为之一经查证确实者或有具体事证者，课以记大过一次： 　　3.1 因个人过失或失职或不依公司规定作业，导致错误，使公司蒙受损失者; 　　3.2 在工作场所饮酒、赌博及其它不良行为者; 　　3.3 撕毁公告，破坏公物者; 　　3.4 搬弄是非，制造谣言，影响同仁和谐或情绪者; 　　3.5 遗失经管之重要文件、机件、对象或工具者; 　　3.6 托人打卡或代打卡或伪造出勤记录者; 　　3.7 未经许可擅自带外人进入工作现场者; 　　3.8 使用非法软件及非因产品开发需要玩电子游戏者; 　　3.9 对上级人员有关职务上之查询，故意隐藏或报告不实者; 　　3.10 主管值班未到，经提醒仍未补值班者; 　　3.11 任职期间记小过达三次者;或 　　3.12 其它违反公司各种规定或工作规则应予记大过者。 　　4、解聘 　　员工有下列行为之一经查证确实或有具体事证者，公司有权立即解聘(即解除合同关系)，可根据情况要求赔偿经济损失，并依违反劳动合同规定处理，行为严重者报送公安机关处理： 　　4.1 在录用时或劳动合同期间出具虚假证明、提供不实信息、遗漏重要事实或存在其他情形，致使公司做出的意思表示违背其真实意愿的; 　　4.2 盗用或滥用公司图章印鉴，伪造不实工作记录、文件、单据，或者对外签署相关合同等文件，损害公司权益或对公司造成不良影响的; 　　4.3', 593, NULL, '[\"公司\", \"工作\", \"不实\", \"规定\", \"记大过\", \"记录\", \"解聘\", \"劳动合同\", \"违反\", \"伪造\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:25', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:25', '0');
INSERT INTO `document_segments` VALUES ('1955803410569457665', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　4.3 滥用职权或利用职务或所从事工作之便，营私舞弊，私收贿赂及或商业回扣、介绍费、佣金、好处费等，经查证属实者; 　　4.4 未经公司事先书面同意，在外从事与公司利益相冲突的工作，或者与任何第三方通谋，损害公司利益的或经公司多次批评仍未改正的; 　　4.5 多次违反公司的规章制度，经多次批评教育仍未改正的; 　　4.6 侵占、私藏公司财物，或者故意或因重大过失损坏公司财物，财物价值(包括一次或累计)达到或超过人民币20xx元的; 　　4.7 挑拨离间导致公司人员离心分裂的; 　　4.8 染有不良嗜好(包括但不限于：酗酒、赌博、吸毒)，严重影响其正常工作的; 　　4.9 在公司办公场所或在工作时间内从事违法犯罪活动或有伤风化活动的; 　　4.10 从事某些行为，严重干扰公司正常经营的; 　　4.11 未经许可进入公司网络系统的管理员帐号或他人信箱者; 　　4.12 窃取他人计算机中的资料，或未经当事人或其主管同意复制当事人计算机中的资料; 　　4.13 有意在公司网络或信箱里传播含计算机病毒的档案或信件者; 　　4.14 在网络上观看、下载、传播有损国家利益或不健康之内容者; 　　4.15 任何期间累计记大过达三次者; 　　4.16 其它违反国家法纪及公司各种规定或工作规则，情节严重者，应予解聘者。 　　第七章 辞职及劳动合同续签 　　一、员工辞职', 585, NULL, '[\"公司\", \"工作\", \"从事\", \"利益\", \"网络\", \"计算机\", \"国家\", \"累计\", \"未经\", \"包括\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:25', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:25', '0');
INSERT INTO `document_segments` VALUES ('1955803410661732353', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　第七章 辞职及劳动合同续签 　　一、员工辞职 　　1、日期限内，经提前至少30天以书面形式向公司提出辞职申请后，可以要求解除劳动合同。 　　2、员工无正当理由连续旷工超过15天，或一年内累计旷工超过30天，经批评教育无效，视为自动辞职，劳动合同自前述条件满足时即行解除。 　　二、辞职手续 　　主动提出离职的员工，须得前三十日提交员工辞职申请书，经核准后，凭员工辞职申请书到向公司领取员工辞职手续表，办理以下辞职手续： 　　2.1工作业务交接; 　　2.2缴回各项工作用品及文件资料; 　　2.3人事、资产、财务、咨讯物品缴验; 　　2.4工资福利结算; 　　2.5转调人事关系、档案、党团关系、保险关系。 　　三、劳动合同续签 　　根据员工的工作表现和公司需要，公司可与员工协商在原合同期满前1个月内协商续签事宜，并签署新的劳动合同。如无相反规定，新劳动合同自原来劳动合同终止之日起正式生效。如未续签，劳动合同将在到期日自行终止。 　　第八章 员工关系与沟通 　　一、员工活动 　　为了加强员工之间的沟通及令员工长期保持身心舒畅，公司会不定期举行各类康乐及聚会活动，例如：郊游、公司周年庆、生日会、春节联欢会等。 　　二、员工投诉', 518, NULL, '[\"员工\", \"劳动合同\", \"辞职\", \"公司\", \"续签\", \"工作\", \"手续\", \"关系\", \"解除\", \"活动\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:25', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:25', '0');
INSERT INTO `document_segments` VALUES ('1955803410712064001', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　二、员工投诉 　　如果员工希望就有关工作事宜作出正式投诉，应首先口头或书面向部门主管提出，相关负责人会于一个星期内向投诉员工了解及讨论有关投诉。对于所有匿名的信件，公司将不予受理及跟进。 　　三、员工咨询 　　员工如因工作或私人生活问题要寻求协助，可向相关负责人提出，如合理正当将得到公司的积极协助。 　　《员工手册》使用说明 　　1、本《员工手册》中，所称“员工”系指X有限公司。 　　2、本《员工手册》适用于所有与公司签订劳动合同的员工。 　　3、公司将根据国家法律、法规和规章的有关规定以及公司经营发展的需要对本《员工手册》不时进行修订。 　　4、在本《员工手册》实施过程中，员工可对其提出任何意见、建议和疑问，经协商可予修改或完善。 　　员工确认声明 　　X有限公司： 　　本人已收到并阅读《X有限公司员工手册》(以下称“《员工手册》”)，已充分理解并明白《员工手册》中各条款及规定的意义与内涵。基于此，本人愿意接受并遵守《员工手册》及公司其他规章制度的有关规定，自觉维护公司利益。如未遵守或如有违反，愿意无条件承担相关法律责任。 　　签署员工： 　　日期： 　　X有限公司 　　员工手册 　　20xx年四月 　　目 录', 516, NULL, '[\"员工\", \"手册\", \"公司\", \"提出\", \"相关\", \"投诉\", \"规定\", \"中\", \"有限公司\", \"X\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:25', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:25', '0');
INSERT INTO `document_segments` VALUES ('1955803410762395650', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　签署员工： 　　日期： 　　X有限公司 　　员工手册 　　20xx年四月 　　目 录 　　第一章 公司简介及企业文化(略) 　　第二章 入职指引 　　第三章 员工守则与行为规范 　　第四章 薪酬与福利 　　第五章 请假及休假制度 　　第六章 奖惩办法 　　第七章 员工关系与沟通 　　附件1：《员工手册》使用说明 　　第一章 公司简介及企业文化 　　一、公司简介 　　(略) 　　二、企业文化 　　(略) 　　第二章 入职指引 　　一、报到 　　员工被录用时，按公司要求出示有关证件或证明原件，经核对无误后公司有权留存相关证件或证明的复印件，此等证件或证明包括但不限于：离职证明、居民身份证复印件、应聘登记表、毕业证书(包括学位证书)、相关资质证书、婚姻状况证明、照片、医疗检查文件及推荐书等。 　　以确保员工的相关权益，请在以下个人资料发生变更后一个月内向公司出示相关证明的原件并保留下复印件： 　　1、姓名或身份证; 　　2、户籍; 　　3、婚姻状况; 　　4、职称、从业资格; 　　5、培训结业或进修毕业。 　　二、新进员工培训 　　员工进入公司后，公司将安排相关人员对新进员工进行入职培训。 　　三、试用期与转正', 512, NULL, '[\"员工\", \"相关\", \"证明\", \"公司\", \"复印件\", \"手册\", \"培训\", \"婚姻状况\", \"职\", \"入\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:25', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:25', '0');
INSERT INTO `document_segments` VALUES ('1955803410833698818', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　员工进入公司后，公司将安排相关人员对新进员工进行入职培训。 　　三、试用期与转正 　　劳动合同期限三个月以上不满一年的，试用期为一个月：劳动合同期限一年以上不满三年的，试用期为二个月;三年以上固定期限和无固定期限的劳动合同，试用期为六个月，试用期工作表现合格者的，将被正式聘用为公司正式员工。 　　试用期内，如果员工休长病假，复工后未完成部分的试用期将相应顺延。 　　第三章 员工守则与行为规范 　　一、员工守则 　　1、忠于职守，服从领导，不得有敷衍塞责的行为。 　　2、不得经营与本公司类似或职务上有关的业务，不得兼任其它公司的职务。 　　3、全体员工必须不断提高自己的工作技能，强化品质意识，圆满完成各级领导交付的工作任务。 　　4、不得携带违禁品、危险品或公司规定其它不得带入工作场所的物品进入公司工作场 所。 　　5、爱护公物，未经许可不得私自将公司财物携带出公司。 　　6、工作时间不得中途任意离开岗位，如需离开应向主管人员请准后方可离开。 　　7、员工应随时注意保持作业地点、宿舍及公司其它场所的环境卫生。 　　8、员工在作业时不得怠慢拖延，不得干与本职工作无关的事情。', 494, NULL, '[\"员工\", \"公司\", \"工作\", \"试用期\", \"完成\", \"领导\", \"离开\", \"作业\", \"携带\", \"场所\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:25', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:25', '0');
INSERT INTO `document_segments` VALUES ('1955803410879836162', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　8、员工在作业时不得怠慢拖延，不得干与本职工作无关的事情。 　　9、员工应团结协作，同舟共济，不得有吵闹、斗殴、搭讪樊谈、搬弄是非或其它扰乱公共秩序的行为。 　　10、不得假借职权贪污舞弊，收受贿赂，或以公司名义在外招摇撞骗。 　　11、员工对外接洽业务，应坚持有理、有利、有节的原则，不得有损害本公司名誉的行为。 　　12、各级主管应加强自身修养，领导所属员工，同舟共济，提高工作情绪和满意程度，加强员工安全感和归属感。 　　13、按规定时间上下班，不得无故迟到、早退。 　　二、工作时间及考勤 　　1、上班时间为：上午8:00至12:00，下午14:30至17:30(具体休息时间以公司通知为准)。员工每天须在上午、下午上班之前和下班之后各刷卡一次，每个工作日共计四次。 　　2、因公外出或出差不能按时刷卡或忘记刷卡，请在月底的刷卡记录中写明原因并由部门负责人签字。未刷卡，又未请部门负责人签字的，将被视做旷工。 　　3、不得代他人刷卡。发现一次，代人刷卡者将从当月工资中扣除50元，被刷卡者按旷工处理。', 456, NULL, '[\"员工\", \"卡\", \"刷\", \"公司\", \"行为\", \"应\", \"同舟共济\", \"工作\", \"加强\", \"下午\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:25', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:25', '0');
INSERT INTO `document_segments` VALUES ('1955803410925973506', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　3、不得代他人刷卡。发现一次，代人刷卡者将从当月工资中扣除50元，被刷卡者按旷工处理。 　　4、迟到(早退)10分钟以内，按事假2小时处理;迟到(早迟)10分钟以上1小时以内，按事假半天处理;迟到一小时以上，按事假一天处理。 　　三、礼仪仪表 　　员工应注意遵守下列要求： 　　1、 工作期间，应保持精神振作、彬彬有礼、高效敏捷。 　　2、 上班时，应注意衣着整洁、大方、得体。男职员不可留长发，蓄胡须，女职员不可浓妆艳抹。有公司工作服的，要着工作服上班。 　　3、 同事间应互相尊重，互助互爱，语言文明，任何时候不谩骂对方。 　　4、 对外交往应有礼有节，不卑不亢，礼貌大方，简朴务实。 　　四、保密 　　每个员工都负有保守公司秘密的义务。这种保密的义务，不仅限于员工在公司工作的合同期内，而且还应注意无论是退休或离职后，都将承担这种义务： 　　1、 务必保管好自己持有的公司涉密文件。 　　2、 未经公司事先书面授权或批准，不得对外提供有密机的公司文件或其他未公 　　开的经营状况、财务数据等。 　　3、 对非本人职权范围内的公司机密，应作到不打听、不猜测、不传播。 　　4、 发现了有可能导致公司秘密泄漏的现象应立即向有关上级报告。 　　五、旷工和迟到', 531, NULL, '[\"公司\", \"应\", \"注意\", \"员工\", \"大方\", \"对外\", \"处理\", \"迟到\", \"义务\", \"文件\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:25', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:25', '0');
INSERT INTO `document_segments` VALUES ('1955803410972110850', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　4、 发现了有可能导致公司秘密泄漏的现象应立即向有关上级报告。 　　五、旷工和迟到 　　1、未经请假或假满后擅自不到职构成旷工。 　　2、员工旷工期间，公司不向其发放在此期间的薪资、奖金及相关津贴。 　　3、连续旷工三日或全月累计旷工六日或一年累计旷工达十二日者，公司有权立即解除 　　劳动合同，且不支付经济补偿金。 　　4、员工一个月内迟到或早退两次扣一天工资。 　　第四章 薪酬与福利 　　一、薪资 　　1、薪资构成 　　员工工资构成为：基本工资+绩效工资。 　　在公司工作满一年(包括一年)的员工，公司将根据其工作表现及公司效益决定发放相应数额的年终奖。 　　2、发薪日 　　工资按月发放，发放时间为次月 日，年终奖金发放时间为农历春节前。 　　3、薪资调整 　　每年 月份，公司对员工进行绩效考核，并根据考核结果对员工薪资进行调整。 　　二、社会保险 　　公司为正式聘用的员工缴纳养老、失业、医疗、生育等国家法定社会保险。 　　三、福利 　　公司可根据员工的职位及工作性质提供相应数额的交通补贴、通讯补贴、节假日津贴。 　　第五章 请假及休假制度 　　一、请假 　　1、事假', 493, NULL, '[\"公司\", \"员工\", \"旷工\", \"薪资\", \"发放\", \"工资\", \"请假\", \"日\", \"迟到\", \"工作\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:25', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:25', '0');
INSERT INTO `document_segments` VALUES ('1955803411022442497', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　第五章 请假及休假制度 　　一、请假 　　1、事假 　　请事假应事先填写请假单，经相关负责人审批后交人备案，事假超过一天的，还应经总经理审批。事假获准后，应在离开工作岗位之前安排好工作，临时外出超过四小时的，视为请假半天。 　　2、病假 　　员工须于上班前或不迟于上班后30分钟内告知相关负责人请假事宜，于病假后上班的第一天填写请假单，并附区(县)级以上医院出具的病休证明。未能在上述规定时间内提供病休证明的，按事假处理。 　　3、婚假 . 　　达到法定婚龄者婚假为3天，晚婚者(男年满25周岁初次结婚者为晚婚;女年满 　　23周岁初次结婚者为晚婚)为1 0天，限一次用完。不在本公司申办开具结婚证明 　　手续的员工在本公司不享有婚假。员工应在结婚登记之日起一年内提出婚假申请， 　　事先填写请假单，并附结婚证明，员工在试用期内办理结婚登记的，待试用期届满 　　并转正后，方可向公司提起婚假申请。婚假不包括法定假日，但包括法定休息日，员工不休或未休满婚假的，公司不另行给予经济上的补偿。 　　4、产假/陪产假 　　4.1、女员工产假90天;晚育(女24周岁以上初育为晚育)的，增加产假30天;非顺', 500, NULL, '[\"员工\", \"婚假\", \"事假\", \"公司\", \"证明\", \"填写\", \"请假单\", \"请假\", \"结婚\", \"应在\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:25', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:25', '0');
INSERT INTO `document_segments` VALUES ('1955803411068579841', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　4.1、女员工产假90天;晚育(女24周岁以上初育为晚育)的，增加产假30天;非顺 　　产的，增加产假15天;多胞胎生育的，每增加一胎，增加产假15天。 　　4.2、产假原则上为产前15天，产后75天，产前产假超过15天部分者，应于产后可请假天数中扣除，产前产假不足15天部分者，产后可补请。 　　4.3、男员工可请陪产假1天，以一次为限;配偶为晚育的，陪产假为3天。 　　5、丧假 　　如员工的直系亲属(包括配偶、父母、子女)不幸亡故，公司给子3天的假期。 　　二、休假 　　1、年假 　　1.1凡在公司连续工作满一年以上的员工，自第二年开始享有至少5天的年假。以后每满一年增加1天，最多不超过10天，休假之前应先规划，以不影响现行工作，并经核准为限。 　　1.2当年年假应在当年年度一次性休完，经相关负责人批准，可延长至次年二月份之前休完。因员工个人原因未休年假者，公司不另行给予经济上的补偿。 　　三、请假及休假待遇 　　1、事假 　　事假期间工资应全额扣除，当月实发工资=月工资—(月工资/当月工作日总数事假天数)。一年之内，员工累计事假天数不得超过10天，超过者，公司可酌情决定不向其发放年终奖直至解聘。', 509, NULL, '[\"员工\", \"产假\", \"公司\", \"年假\", \"超过\", \"休假\", \"休\", \"增加\", \"事假\", \"天数\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:25', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:25', '0');
INSERT INTO `document_segments` VALUES ('1955803411156660225', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　2、病假 　　病假期间工资按原工资的60%(即扣除40%)计发，当月实发工资=月工资—(月工 资/当月工作日总数事假天数40%)。一年之内，员工累计病假天数超过20天，公司可酌情决定不向其发放年终奖。 　　3、产假 　　产假期间由生育保险基金按照公司上一年度该员工月平均工资向该员工支付生育津贴。 　　4、其他 　　婚假、丧假、年假、法定假日期间员工工资全额发放。 　　第六章 奖罚办法 　　一、一般规定 　　本奖惩办法系公司奖励和处罚员工的依据与规定。员工具有以下奖惩之情形者，应由直 　　属主管或管理部门依事实呈报，经总经理核准后公告，并列入员工个人记录。有关奖惩 　　措施于年底相抵之后将给予：加/减薪、升/降级、加/扣奖金等奖励或处罚。 　　二、奖励 　　1、嘉奖 　　员工有下列行为之一的，可授予嘉奖一次： 　　1.1品行端正、工作努力、有具体成效并能及时完成任务者; 　　1.2热心服务，表现积极，有优良具体事实者; 　　1.3爱护团体荣誉，足为同仁表率者; 　　1.4协调或促进内部团结表现特佳者; 　　1.5有其它功绩者。 　　2、记功 　　员工有下列行为之一的，可授予记功一次：', 500, NULL, '[\"员工\", \"奖惩\", \"公司\", \"期间\", \"事实\", \"具体\", \"表现\", \"%\", \"发放\", \"生育\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:25', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:25', '0');
INSERT INTO `document_segments` VALUES ('1955803411202797569', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　1.5有其它功绩者。 　　2、记功 　　员工有下列行为之一的，可授予记功一次： 　　2.1工作效率特高，大幅提前完成重大任务者; 　　2.2对业务开发有特殊贡献者： 　　2.3对于公司经营或管理制度建议改进，经采纳施行后，卓有成效者; 　　2.4遇有突变，勇于负责，，处置得宜者; 　　2.5举发舞弊、违规、盗窃、泄密、浪费、损毁公物或其它有关本公司权益者; 　　2.6有其它较大功绩者。 　　3、记大功 　　员工有下列行为之一的，可授予记大功一次： 　　3.1遇紧急事故，奋不顾身，不避危难，处置得宜，保全人身或财物之安全，因而减少损害者; 　　3.2维护公司重大利益，避免重大损失者; 　　3.3有其它重大功绩者。 　　4、奖金或晋级 　　员工有下列行为之一的，可授予奖金或晋级—次： 　　4.1一年内记大功三次者; 　　4.2对于公司业务有特殊贡献，足为全公司表率者; 　　4.3有其它特殊功绩者。 　　三、惩罚 　　1、申戒 　　员工有下列行为之一且经查证确实者，课4以申戒一次： 　　1.1 工作经常落后，未按规定作业或作业不详、不实者; 　　1.2 未按规定穿著服装，经警告不听劝告者; 　　1.3 无故不参加公司各种集会或活动者; 　　1.4 与同事争执不听劝阻者; 　　1.5', 548, NULL, '[\"公司\", \"功绩\", \"员工\", \"行为\", \"特殊\", \"宜\", \"处置\", \"记大功\", \"听\", \"授予\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:25', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:25', '0');
INSERT INTO `document_segments` VALUES ('1955803411253129217', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　1.2 未按规定穿著服装，经警告不听劝告者; 　　1.3 无故不参加公司各种集会或活动者; 　　1.4 与同事争执不听劝阻者; 　　1.5 办公场所内随地乱丢果皮纸屑、吐痰、制造脏乱者; 　　1.6 在禁烟区内吸烟者; 　　1.7 在工作场所喧哗、嬉戏、吵闹，妨害他人工作;在工作现场吃零食;在上班时间玩游戏或从事其他娱乐活动者; 　　1.8 上班时间从事非业务有关之私事者; 　　1.9 有轻微旷工现象或多次上班迟到且无正当理由者;或 　　1.10 其它违反公司各种规定或工作规则应予申戒。 　　2、记小过 　　员工有下列行为之一经查证确实或有具体事证者，课以记小过： 　　2.1 因疏忽导致公司财物遭受损害或伤及他人者; 　　2.2 上班时间擅离职守怠忽工作者; 　　2.3 言行轻浮或其它违反善良风俗行为者; 　　2.4 担任主管，对属下不良行为知情不报者; 　　2.5 未经许可携带公司物品外出者; 　　2.6 未经许可擅自带外人进入公司者; 　　2.7 担任主管，滥用职权，恶意辱骂员工或谋取不当利益者; 　　2.8 不听上级指挥，违抗命令或恶意辱骂主管者; 　　2.9 主管值班未到岗，且事先未说明并安排替补者; 　　2.10 任职期间被申戒达三次者;或 　　2.11 其它违反公司各种规定或工作规则应予记小过者。 　　3、记大过 　　员工有下列行为之一经查证确实者或有具体事证者，课以记大过一次： 　　3.1', 613, NULL, '[\"公司\", \"听\", \"工作\", \"主管\", \"违反\", \"上班时间\", \"场所\", \"行为\", \"员工\", \"记\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:25', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:25', '0');
INSERT INTO `document_segments` VALUES ('1955803411303460866', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　3、记大过 　　员工有下列行为之一经查证确实者或有具体事证者，课以记大过一次： 　　3.1 因个人过失或失职或不依公司规定作业，导致错误，使公司蒙受损失者; 　　3.2 在工作场所饮酒、赌博及其它不良行为者; 　　3.3 撕毁公告，破坏公物者; 　　3.4 搬弄是非，制造谣言，影响同仁和谐或情绪者; 　　3.5 遗失经管之重要文件、机件、对象或工具者; 　　3.6 托人打卡或代打卡或伪造出勤记录者; 　　3.7 未经许可擅自带外人进入工作现场者; 　　3.8 使用非法软件及非因产品开发需要玩电子游戏者; 　　3.9 对上级人员有关职务上之查询，故意隐藏或报告不实者; 　　3.10 主管值班未到，经提醒仍未补值班者; 　　3.11 任职期间记小过达三次者;或 　　3.12 其它违反公司各种规定或工作规则应予记大过者。 　　4、解聘 　　员工有下列行为之一经查证确实或有具体事证者，公司有权立即解聘(即解除合同关系)，可根据情况要求赔偿经济损失，并依违反劳动合同规定处理，行为严重者报送公安机关处理： 　　4.1 在录用时或劳动合同期间出具虚假证明、提供不实信息、遗漏重要事实或存在其他情形，致使公司做出的意思表示违背其真实意愿的; 　　4.2 盗用或滥用公司图章印鉴，伪造不实工作记录、文件、单据，或者对外签署相关合同等文件，损害公司权益或对公司造成不良影响的; 　　4.3', 593, NULL, '[\"公司\", \"工作\", \"不实\", \"规定\", \"记大过\", \"记录\", \"解聘\", \"劳动合同\", \"违反\", \"伪造\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:25', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:25', '0');
INSERT INTO `document_segments` VALUES ('1955803411349598209', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　4.3 滥用职权或利用职务或所从事工作之便，营私舞弊，私收贿赂及或商业回扣、介绍费、佣金、好处费等，经查证属实者; 　　4.4 未经公司事先书面同意，在外从事与公司利益相冲突的工作，或者与任何第三方通谋，损害公司利益的或经公司多次批评仍未改正的; 　　4.5 多次违反公司的规章制度，经多次批评教育仍未改正的; 　　4.6 侵占、私藏公司财物，或者故意或因重大过失损坏公司财物，财物价值(包括一次或累计)达到或超过人民币20xx元的; 　　4.7 挑拨离间导致公司人员离心分裂的; 　　4.8 染有不良嗜好(包括但不限于：酗酒、赌博、吸毒)，严重影响其正常工作的; 　　4.9 在公司办公场所或在工作时间内从事违法犯罪活动或有伤风化活动的; 　　4.10 从事某些行为，严重干扰公司正常经营的; 　　4.11 未经许可进入公司网络系统的管理员帐号或他人信箱者; 　　4.12 窃取他人计算机中的资料，或未经当事人或其主管同意复制当事人计算机中的资料; 　　4.13 有意在公司网络或信箱里传播含计算机病毒的档案或信件者; 　　4.14 在网络上观看、下载、传播有损国家利益或不健康之内容者; 　　4.15 任何期间累计记大过达三次者; 　　4.16 其它违反国家法纪及公司各种规定或工作规则，情节严重者，应予解聘者。 　　第七章 辞职及劳动合同续签 　　一、员工辞职', 585, NULL, '[\"公司\", \"工作\", \"从事\", \"利益\", \"网络\", \"计算机\", \"国家\", \"累计\", \"未经\", \"包括\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:25', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:25', '0');
INSERT INTO `document_segments` VALUES ('1955803411395735554', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　第七章 辞职及劳动合同续签 　　一、员工辞职 　　1、日期限内，经提前至少30天以书面形式向公司提出辞职申请后，可以要求解除劳动合同。 　　2、员工无正当理由连续旷工超过15天，或一年内累计旷工超过30天，经批评教育无效，视为自动辞职，劳动合同自前述条件满足时即行解除。 　　二、辞职手续 　　主动提出离职的员工，须得前三十日提交员工辞职申请书，经核准后，凭员工辞职申请书到向公司领取员工辞职手续表，办理以下辞职手续： 　　2.1工作业务交接; 　　2.2缴回各项工作用品及文件资料; 　　2.3人事、资产、财务、咨讯物品缴验; 　　2.4工资福利结算; 　　2.5转调人事关系、档案、党团关系、保险关系。 　　三、劳动合同续签 　　根据员工的工作表现和公司需要，公司可与员工协商在原合同期满前1个月内协商续签事宜，并签署新的劳动合同。如无相反规定，新劳动合同自原来劳动合同终止之日起正式生效。如未续签，劳动合同将在到期日自行终止。 　　第八章 员工关系与沟通 　　一、员工活动 　　为了加强员工之间的沟通及令员工长期保持身心舒畅，公司会不定期举行各类康乐及聚会活动，例如：郊游、公司周年庆、生日会、春节联欢会等。 　　二、员工投诉', 518, NULL, '[\"员工\", \"劳动合同\", \"辞职\", \"公司\", \"续签\", \"工作\", \"手续\", \"关系\", \"解除\", \"活动\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:25', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:25', '0');
INSERT INTO `document_segments` VALUES ('1955803411450261505', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　二、员工投诉 　　如果员工希望就有关工作事宜作出正式投诉，应首先口头或书面向部门主管提出，相关负责人会于一个星期内向投诉员工了解及讨论有关投诉。对于所有匿名的信件，公司将不予受理及跟进。 　　三、员工咨询 　　员工如因工作或私人生活问题要寻求协助，可向相关负责人提出，如合理正当将得到公司的积极协助。 　　《员工手册》使用说明 　　1、本《员工手册》中，所称“员工”系指X有限公司。 　　2、本《员工手册》适用于所有与公司签订劳动合同的员工。 　　3、公司将根据国家法律、法规和规章的有关规定以及公司经营发展的需要对本《员工手册》不时进行修订。 　　4、在本《员工手册》实施过程中，员工可对其提出任何意见、建议和疑问，经协商可予修改或完善。 员工手册范本 篇17 　　第一章劳动条例 　　一、招聘 　　酒店以任人唯贤为基本原则，凡有志于酒店服务工作的各界人士，都可对照酒店招工简章，报名参与。酒店将通过考核面试体检等必要的程序择优招聘员工。被录用者需按不同工种交纳相应的工作及生活用品保证金。 　　二、试用期 　　员工需经过三至六个月的试用期，试用期满后经考核合格后正式聘用，不符合录用条件者将终止试用。 　　三、劳动合同', 513, NULL, '[\"员工\", \"手册\", \"公司\", \"工作\", \"酒店\", \"提出\", \"投诉\", \"正式\", \"需\", \"协助\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:25', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:25', '0');
INSERT INTO `document_segments` VALUES ('1955803411496398850', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　三、劳动合同 　　凡被正式录用者，酒店将签订聘用合同，通常为二年。 　　四、个人档案 　　A所有职工在应聘前及时交出有关简历、学历证明等。填写包括个人简历、家庭成员情况等在内的登记表。 　　B对于家庭住址、婚姻状况等情况的变更应在五天内告知人事部门。 　　五、工作时间 　　A参照有关法规，结合本地情况和酒店工作特点编排工作日和工作时间。 　　B对加班超时的员工给予合理的补偿。 　　六、发薪方式 　　每月未发放工资。如遇周未或法定假期，工资将提前一天发放。 　　七、岗位变更 　　根据工作需要，酒店有权在内部调整员工岗位。 　　八、员工辞职： 　　员工辞职必须(试用期提前7天，正式聘任后担前30天)向所在部门负责人提出书面申请，经酒店批准方可离岗。 　　九、解聘： 　　(1)员工无任何过失而自动辞职，符合酒店规定程序，获准后，酒店将退还保证金并发给当月工资。 　　(2)发生下列情况之一者，酒店有权解除合同，不再退还受聘员工保证金。 　　A不遵守劳动纪律，玩忽职守，严重违反酒店规章制度。 　　B旷工3天以上，伪造病假、事假。 　　C服务态度恶劣，责任心不强，营私舞弊，给酒店信誉带来严重影响者。 　　D被依法追究刑事责任。', 517, NULL, '[\"酒店\", \"员工\", \"情况\", \"A\", \"B\", \"工作\", \"前\", \"工资\", \"严重\", \"变更\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:25', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:25', '0');
INSERT INTO `document_segments` VALUES ('1955803411588673538', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　C服务态度恶劣，责任心不强，营私舞弊，给酒店信誉带来严重影响者。 　　D被依法追究刑事责任。 　　E违反计划生育规定，造成不良后果者。 　　第二章有关权益 　　一、假期。 　　1、国定假： 　　按国务院规定，员工享有十天法定有薪假期(元旦一天、春节三天、五一三天、国庆节三天)。如法定定假日需要员工加班，酒店将按《劳动法》规定给予假期或薪金补偿。 　　2、病假： 　　员工生病必须在市级以上的医院就诊，凭医院出具的病情证明请假，并于当日通知所在部门主管(病情严重者，可由家属代请)方属有效。病假期间的工资将工资考勤制度执行。 　　3、事假： 　　无充分理由，员工不得请事假。事假不发薪。如有特殊情况需要无薪请假，必须提前二天申请，经部门主管、人事部、总经理批准。 　　4、店内培训： 　　店内培训主要有：业务技巧、工作态度、语言训练等。员工必须根据安排参加培训，课程结束时要进行考试，成绩合格，将发给结业证书，成绩在分数线以下要扣浮动工资或奖金，无故缺课，按失职处分。 　　二、业余学校学习： 　　A目的', 454, NULL, '[\"员工\", \"必须\", \"规定\", \"假期\", \"薪\", \"酒店\", \"培训\", \"主管\", \"病假\", \"请假\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:25', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:25', '0');
INSERT INTO `document_segments` VALUES ('1955803411643199490', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　二、业余学校学习： 　　A目的 　　酒店采用报销学费的方法来鼓励员工参加外语学习或与工作有关的业余学习，以便他们提高与宾客的会话技能或为担负起更大的责任、获得更好职位作准备。 　　B执行方法： 　　不能占用工作时间。部门主管在编制上班时间表时，在工作允许的情况下，应适当照顾员工的学习时间。 　　申请人必须报名前经部门经理和人事部经理批准。 　　要求报销学费的员工应在学习结束后三个月内把学费收据、结业证书或有关证件呈交人事审核。 　　选择课程范围： 　　1、任何得到承认的电大、夜大。 　　2、商校、技术学院、中等专业学校、专业团体或类似团体主办的符合本方案的文化或职业课程。 　　3、培训部认可的函授学校。 　　C报销： 　　学费报销金额最高不超过150元/学年。 　　考试成绩在80分以上的员工或报销150年。 　　考试成绩在60-79分的员工可报销75元。 　　考试成绩在60分以下的不予报销。 　　受到严重违纪处分、停职、请长病假或旷工的员工一律不予报销。 　　三、员工餐厅： 　　1、每个工作日酒店负责免责供应员工一餐工作餐，只准员工本人用膳。 　　2、未经部门经理许可，员工不得把工作餐食口和餐具带出员餐厅。', 513, NULL, '[\"员工\", \"报销\", \"学习\", \"学费\", \"工作\", \"课程\", \"时间\", \"方法\", \"工作餐\", \"酒店\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:25', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:25', '0');
INSERT INTO `document_segments` VALUES ('1955803411706114050', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　2、未经部门经理许可，员工不得把工作餐食口和餐具带出员餐厅。 　　3、工作餐时间为半小时，用膳时间表由人事部门经理统筹制订。 　　4、员工凭餐券用膳，加班加点员工将由人事部另外发给餐券。 　　5、不准在员工餐厅内喝酒和浪费饭菜。 　　6、餐券不得转让，不退钱，过期作废。送、借餐券给别人的，将受到失职处分。 　　第三章员工守则 　　一、工作态度： 　　1、按酒店操作规程，准确及时地完成各项工作。 　　2、员工对上司的安排有不同意见但不能说服上司，一般情况下应先服从执行。 　　3、员工对直属上司答复不满意时，可以越级向上一级领导反映。 　　4、工作认真，待客热情，说话和气，谦虚谨慎，举止稳重。 　　5、对待顾客的投诉和批评时应冷静倾听，耐心解释，任何情况下都不得与客人争论， 　　解决不了的问题应及时告直属上司。 　　6、员工应在规定上班时间的基础上适当提前到达岗位作好准备工作。工作时间不得擅离职守或早退。在下一班员工尚未接班前当班员工不得离岗。员工下班后，无公事，应在30分钟内离开酒店。', 450, NULL, '[\"员工\", \"工作\", \"上司\", \"餐券\", \"情况\", \"时间\", \"餐厅\", \"用膳\", \"及时\", \"应在\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:25', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:25', '0');
INSERT INTO `document_segments` VALUES ('1955803411752251394', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　7、员工不得在任何场所接待亲友来访。未经部门负责人同意，员工不得使用客用电话。外线打入私人电话不予接通，紧急事情可打电话到各部门办公室。 　　8、上班时严禁串岗、闲聊、吃零食。禁止在餐厅、厨房、更衣室等公共场所吸烟，不做与本职工作无关的事。 　　9、热情待客，站立服务，使用礼貌语言。 　　10、未经部门经理批准，员工一律不准在餐厅做客，各级管理人员不准利用职权给亲友以各种特殊优惠。 　　二、制服及名牌： 　　1、员工制服由酒店发放。员工有责任保管好自己的制服，员工除工作需要外，穿着或携带工作衣离店，将受到失职处分。 　　2、所有员工应佩戴作为工作服一部分的名牌。不戴名牌扣人民币10元，员工遗失或损坏名牌需要补发者应付人民币20元。 　　3、员工离职时须把工作服和名牌交回到人事部，如不交回或工作服破损，须交付服装成本费。 　　三、仪表、仪容、仪态及个人卫生： 　　1、员工的精神面貌应表情自然，面带微笑，端庄稳重。 　　2、员工的工作衣应随时保持干净、整洁。 　　3、男员工应修面，头发不能过耳和衣领。 　　4、女员工应梳理好头发，使用发夹网罩。', 479, NULL, '[\"员工\", \"应\", \"名牌\", \"使用\", \"工作服\", \"工作\", \"部门\", \"餐厅\", \"未经\", \"亲友\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:25', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:25', '0');
INSERT INTO `document_segments` VALUES ('1955803411798388737', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　3、男员工应修面，头发不能过耳和衣领。 　　4、女员工应梳理好头发，使用发夹网罩。 　　5、男员工应穿男色皮鞋、深色袜，禁穿拖鞋或凉鞋。女员工应穿黒鞋，肉色统补袜其端不得露于裙外。 　　6、手指应无烟熏色，女员工只能使用无色指甲油。 　　7、只允许戴手表、婚戒以及无坠耳环。厨房员工上班时不得戴戒指。 　　8、工作时间内，不剪指甲、抠鼻、剔牙、打哈欠、喷嚏应用手遮掩。 　　9、工作时间内保持安静，禁止大声喧哗。做到说话轻、走路轻、操作轻。 　　四、拾遗： 　　1、在酒店任何场所拾到钱或遗留物品应立即上缴保安部作好详细的记录。 　　2、如物品保管三个月无人认领，则由酒店最高管理当局决定处理方法。 　　3、拾遗不报将被视为从偷窃处理。 　　五、酒店财产： 　　酒店物品(包括发给员工使用的物品)均为酒店财产，无论疏忽或有意损坏，当事人都必须酌情赔偿。员工如犯有盗窃行为，酒店将立即予以开除，并视情节轻重交由部门处理。 　　六、出勤。 　　1、员工必须依照部门主管安排的班次上班，需要变更班次，须先征得部门主管允许。 　　2、除4级以上管理人员外，所有员工上、下班都要打工卡。', 490, NULL, '[\"员工\", \"酒店\", \"应\", \"物品\", \"处理\", \"使用\", \"部门\", \"时间\", \"外\", \"工作\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:25', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:25', '0');
INSERT INTO `document_segments` VALUES ('1955803411865497602', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　2、除4级以上管理人员外，所有员工上、下班都要打工卡。 　　3、员工上班下班忘记打卡，但确实能证明上班的，将视情节，每次扣除不超过当月5%效益工资。 　　4、严禁替他人打卡，如有违反，代打卡者及持卡本人将受到纪律处分。 　　5、员工如有急事不能按时上班，应征得部门主管认可，补请假手续，否则，按旷工处理。 　　6、如因工作需要加班，则应由部门主管报总经理批准。 　　7、工卡遗失，立即报告人事部，经部门主管批准后补发新卡。 　　8、员工在工作时间未经批准不得离店。 　　七、员工衣柜： 　　1、员工衣柜的配给由人事部负责，必要时，可两个或两个以上的员工合用一个衣柜。 　　员工衣柜不能私自转让，如有违反，将受纪律处分。 　　2、员工须经常保持衣柜的清洁与整齐，柜内不准存放食物、饮料或危险品。 　　3、人事部配给衣柜时，免费发给一把钥匙。如遗失钥匙，须赔人民币10元。 　　4、如有紧急情况或员工忘带钥匙，可向人事部借用备用钥匙，但须部门主管同意，故意损坏衣柜，则须赔偿，并予纪律处分。 　　5、不准在衣柜上擅自装锁或配钥匙，人事部和保安部可随时检查衣柜，检查时两个以上人员在场。', 492, NULL, '[\"员工\", \"衣柜\", \"人事部\", \"主管\", \"部门\", \"须\", \"纪律处分\", \"卡\", \"上班\", \"钥匙\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:25', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:25', '0');
INSERT INTO `document_segments` VALUES ('1955803411920023553', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　5、不准在衣柜上擅自装锁或配钥匙，人事部和保安部可随时检查衣柜，检查时两个以上人员在场。 　　6、不准在更衣室内睡觉或无事逗留，不准在更衣室吐痰、抽烟、扔垃圾。 　　7、员工离店时，必须清理衣柜，并把钥匙交回人事部，不及时交还衣柜，酒店有权清理。 　　八、员工通道： 　　1、员工上下班从指定的员工通道入店，不负重情况下不得使用服务电梯，禁止使用客用电梯。 　　2、后台员工非工作关系不得任意进入店内客用公共场所、餐厅、客房，使用酒店内客用设施。 　　3、员工在工作时间要离开酒店时，应填写出门单，经部门主管签字后方能离店。 　　九、酒店安全： 　　1、员工进出酒店，保安人员保留随时检查随带物品的权利。 　　2、员工不得携带行李、包裹离店，特殊情况必须部门主管签发出门许可证，离店时主动将出门许可单呈交门卫，由保安部存案。 　　十、电梯故障： 　　当电梯出故障，客人关在梯内时，一般来说，里面的客人会按警铃。当前厅主管/行李员听到铃声时，应采取下列措施： 　　(1)通知工程部，立即采取应急措施，设法解救电梯内客人。 　　(2)和关在里面和客人谈话，问清楚以下事项： 　　A关电梯里多少人; 　　B如可能，问一下姓名;', 512, NULL, '[\"员工\", \"时\", \"店\", \"电梯\", \"酒店\", \"衣柜\", \"主管\", \"客人\", \"检查\", \"客\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:25', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:25', '0');
INSERT INTO `document_segments` VALUES ('1955803411966160898', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　(2)和关在里面和客人谈话，问清楚以下事项： 　　A关电梯里多少人; 　　B如可能，问一下姓名; 　　C有无消息要带给(领队/队里的成员)同伴。 　　值班人员无法解救客人，立即通知总工程师。 　　第四章消防安全 　　酒店配有标准的消防控制和报警系统。每一位员工都必须熟悉并了解正确使用火器和消防设备，熟记酒店消防楼梯和疏散通道。 　　一、火灾预防： 　　遵守有关场所禁止吸烟的规定。 　　严禁把烟蒂或其它燃烧留在电梯内、棉织品运送处或字纸篓里。 　　酒店内任何地方都不得堆积堆积废纸、脏毯、脏棉织品或其它易燃物品，以杜绝易燃源。 　　不准在灶台或高瓦数电灯附近放置燃易爆物品。 　　盛有易燃、易爆物的容器，不得存放在大楼内。 　　任何员工发现还在冒烟的烟头都应该立即把它熄灭。 　　如果发现电线松动、磨损、折断、电源插座和电器的破损等情况，应立即报告工程部，以便及时修复。 　　厨师上班前必须检查燃油管道、燃烧器、开关等设施的安全状况。发现泄漏，应该关闭阀门，报告工程部。 　　厨师下班前必须检查所有厨房设备，关掉所有阀门的开关。 　　二、志愿消防委员会： 　　包括下列人员： 　　1、副总经理;2、安全部经理;3、行政管家;', 515, NULL, '[\"酒店\", \"里\", \"必须\", \"发现\", \"易燃\", \"问\", \"电梯\", \"员工\", \"棉织品\", \"阀门\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:25', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:25', '0');
INSERT INTO `document_segments` VALUES ('1955803412012298241', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　二、志愿消防委员会： 　　包括下列人员： 　　1、副总经理;2、安全部经理;3、行政管家; 　　4、消防主管;5、工程部经理;6、前厅部经理;7、餐饮部经理。 　　消防委员会要定期召开会议专项检查消防设备，确保消防工作落实。 　　三、火警程序： 　　当消控室火警报警时，消控中心值班员要立即查明火警指示方位板，并采取下列措施： 　　1、通知巡逻安全员找出起火位置，并立即报告安全部经理和值班经理。 　　2、与楼面服务员保持紧密联系，随时准备提供帮助。 　　楼面服务员将采取下列措施： 　　1、检查楼面指示板，确定哪一间房间发出火警。 　　2、检查有没有起火，起火时，通知接线员拨119报火警。 　　3、如查明是假火警，巡逻安全员要立即报告安全部经理(白天)、值班经理(晚间)，以便找出原因及时复位，解除警报。 　　四、灭火程序： 　　发生为灾后，在立即通知119的同时，由总工程师/安全部经理指挥灭火。 　　酒店参与灭火的有关员工须按以下程序进行： 　　1、水工到维修中心报到，密切注意消防泵和供水系统工作。 　　2、电工到大厅报到，按指令切断电源。', 477, NULL, '[\"经理\", \"火警\", \"立即\", \"安全部\", \"程序\", \"通知\", \"检查\", \"灭火\", \"报到\", \"楼\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:25', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:25', '0');
INSERT INTO `document_segments` VALUES ('1955803412096184321', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　1、水工到维修中心报到，密切注意消防泵和供水系统工作。 　　2、电工到大厅报到，按指令切断电源。 　　3、安全部人员到大厅报到，并接受总工程师/安全部经理的指示，协助灭火和人员疏散工作。 　　4、电梯将停止使用，消防队来到后，由他们接替指挥灭火，直到火灭。 　　五、疏散： 　　由酒店总经理发布决定疏散，总工程师、安全部经理(白天)、值班经理(晚间)组织实施。 　　1、客房服务员要敲门通知所有的客人并进行检查，通知客人立即离开房间。 　　2、阻止任何人使用电梯。 　　3、客房服务员带领客人从楼梯疏散、撤离建筑物，到指定地点集合。 　　4、楼层主管/员工要快速检查并关掉所有客房的门、窗、走廊门、边门，然后离开现场。 　　第五章奖惩条例 　　一、优秀员工： 　　酒店每月按照各员工的岗位职责进行考核，年终进行评比，被评为优秀员工者，将受到酒店的荣誉及物质奖励。 　　二、嘉奖、晋升： 　　酒店对改进管理，提高服务质量和经济效益有突出贡献，或者在酒店日常的工作中，创造出优异成绩者将进行嘉奖或晋升。 　　三、纪律处分/失职的种类：', 467, NULL, '[\"酒店\", \"疏散\", \"工作\", \"进行\", \"客房\", \"报到\", \"安全部\", \"员工\", \"离开\", \"经理\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:25', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:25', '0');
INSERT INTO `document_segments` VALUES ('1955803412146515969', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　三、纪律处分/失职的种类： 　　1、纪律处分为口头警告、纠正面谈、书面警告、辞退警告、停职停薪、辞退、解除合同或开除。纪律处分由部门经理发失职表，失职表交失职的员工签收，副本送人事部归档。 　　2、失职行为分为甲、乙、丙三类，犯有其中任何一条都要填写职工失职表，并据此扣发浮动工资。 　　3、凡第四次发生甲类失职时将会受到三天停职停薪的处分，受到二次以上停职停薪处分时将被辞退。每次失职将扣除10%的浮动工资。 　　4、凡第三次发生乙类失职时会受到三至五天停职停薪的处分，受到二次停职停薪处分将会被辞退。 　　5、凡犯丙类失职，将视情节轻重，分别给予停职停薪、辞职警告直到辞退。 　　6、员工违反酒店规章制度停职停薪处分时其当月50%的效益工资将被扣除，另按日扣除部分底薪。 　　7、因违反酒店规章制度受停职处分的员工在停职期间不得进入酒店，对员工的停职、解除合同、开除处分，应由部分主管或人事部提出，经总经理批准。 　　甲类失职 　　1、上班迟到; 　　2、不使用指定的职工通道; 　　3、仪表不整洁; 　　A留长发; 　　B手脏; 　　C站立姿势不正; 　　D手插口袋; 　　E衣袖、裤脚卷起; 　　F不符合仪表仪容规定;', 515, NULL, '[\"失职\", \"停职\", \"处分\", \"辞退\", \"停薪\", \"甲\", \"员工\", \"手\", \"仪表\", \"职工\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:25', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:25', '0');
INSERT INTO `document_segments` VALUES ('1955803412201041922', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　B手脏; 　　C站立姿势不正; 　　D手插口袋; 　　E衣袖、裤脚卷起; 　　F不符合仪表仪容规定; 　　4、擅离工作岗位或到其它部门闲荡; 　　5、不遵守打电话的规定; 　　6、损坏工作服或把工作服穿出酒店之外; 　　7、培训课旷课; 　　8、违反员工餐厅规定; 　　9、进入酒店舞厅、酒吧或其它客用公共场所; 　　10、工作时听收音机、录音机或看电视(培训或工作需要例外); 　　11、上班做私事，看书报和杂志; 　　12、不经许可带妻子、丈夫、男女朋友等进入酒店; 　　13、使用客用公共休息室和厕所; 　　14、穿工作服进入商店(为客人买东西例外); 　　15、使用客用电梯(经同意例外)、客用设备; 　　16、将酒店文具用于私人之事; 　　17、在公共场所大声喧哗或在客人可以看到和听到的地方作不雅的习惯动作; 　　18、在公共场所和酒店其它地方聚众讨论个人事情; 　　19、违反更衣室规定。 　　乙类失职 　　1、上下班不打卡或唆使别人为自己打卡和替别人打卡; 　　2、对客人和同事不礼貌; 　　3、因粗心大意损坏酒店财产; 　　4、隐瞒事故; 　　5、拒绝安全检查包裹、手提包或员工身份证; 　　6、拒绝执行管理员/部门主管的指示;', 525, NULL, '[\"酒店\", \"规定\", \"客\", \"客人\", \"公共场所\", \"进入\", \"例外\", \"员工\", \"培训\", \"工作服\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:25', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:25', '0');
INSERT INTO `document_segments` VALUES ('1955803412247179265', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　5、拒绝安全检查包裹、手提包或员工身份证; 　　6、拒绝执行管理员/部门主管的指示; 　　7、上班时打瞌睡; 　　8、涂改工卡; 　　9、违反安全规定; 　　10、在酒店内喝酒; 　　11、进入客房(工作例外); 　　12、说辱骂性和无礼的话; 　　13、未经同意改换班次、休息天或休息时间; 　　14、超过工作范围与客人过分亲近; 　　15、在除了员工食堂指定位置以外的其它场所吸烟; 　　16、不报告财产短缺; 　　17、在酒店内乱丢东西; 　　18、不遵守消防规定; 　　19、损坏公物; 　　20、工作表现并差或工作效能差; 　　21、不服从主管或上司的合理合法命令; 　　22、擅自配置酒店范围内任何钥匙; 　　23、发表虚假或诽谤言论，影响酒店、客人或其他员工的声誉。 　　丙类失职 　　1、在酒店内危害任何人员; 　　2、殴打他人或互相打架; 　　3、向顾客索取小费或其它报酬; 　　4、作不道理交易; 　　5、泄露酒店机密情况; 　　6、私换外汇; 　　7、调戏或欺侮他人; 　　8、行贿; 　　9、偷窃酒店、客人或其他人的财物或拿用酒店、客人的食物、饮料; 　　10、违犯店规，造成重大影响或损失; 　　11、在酒店内赌博或观看赌博;', 528, NULL, '[\"酒店\", \"工作\", \"员工\", \"客人\", \"主管\", \"规定\", \"范围\", \"影响\", \"安全\", \"差\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:25', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:25', '0');
INSERT INTO `document_segments` VALUES ('1955803412301705217', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　10、违犯店规，造成重大影响或损失; 　　11、在酒店内赌博或观看赌博; 　　12、故意损坏消防设备; 　　13、触犯国家任何刑事罪案; 　　14、故意损坏告示栏或公共财物或他人物品; 　　15、遗失、复制、未经许可使用总钥匙; 　　16、旷工。 　　第六章其它 　　一、员工告示栏： 　　各部门在显著的位置集中设有告示栏，在告示栏上将张贴大家感兴趣的最新信息、酒店新闻和通知、体育活动、规章制度、安全事项和备忘录等。告示栏是传播信息的重要媒介，员工应经常观看。一般情况下，酒店只授权人事部、安全部签发、张贴。 　　二、员工建议： 　　员工如有任何有助于改善服务，加强安全;增加收入，降低成本，改进员工和公共关系的意见或建议请以书面形式递交给人事部。人事部欢迎你的建议，并会对建议进行仔细研究。一旦采纳，有关员工将会得到酒店的.奖励。 　　第七章修订 　　酒店员工手册的修订可按照业务需要，修订或更新内容。 　　如果本手册中有任何与酒店正式公告相异之处，以酒店正式公告为准。 　　4、员工凭餐券用膳，加班加点员工将由人事部另外发给餐券。 　　5、不准在员工餐厅内喝酒和浪费饭菜。', 491, NULL, '[\"员工\", \"酒店\", \"告示\", \"栏\", \"建议\", \"人事部\", \"安全\", \"信息\", \"观看\", \"张贴\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:25', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:25', '0');
INSERT INTO `document_segments` VALUES ('1955803412352036865', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　4、员工凭餐券用膳，加班加点员工将由人事部另外发给餐券。 　　5、不准在员工餐厅内喝酒和浪费饭菜。 　　6、餐券不得转让，不退钱，过期作废。送、借餐券给别人的，将受到失职处分。 员工手册范本 篇18 　　员工手册旨在使你了解你的责任、利益与义务。并作为在本店就职期间的行为指南。这不仅是酒店现代化管理所必需的规章制度，而且也是你切身利益之所在。因此，希望全体员工都有责任、义务维护它的尊严，保证它的实施。 　　一、员工录用 　　根据国家劳动部门的有关规定，本酒店面向社会公开招收员工。按照岗位工作要求及体格检查和政审结果全面考核，择优录用。新招收的员工须通过岗前培训，经考试合格后上岗，上岗后试用期一个月;试用期满酒店可根据员工的工作表现确定是否正式录用，并签订劳动合同。 　　录用的员工全部实行合同制，通过签订劳动合同与酒店确定劳动关系。需续签合同的员工必须由员工本人在劳动合同期满一个月前向酒店提出申请，由双方协商进行。 　　合同到期即自然终止，酒店与员工之间的劳动关系自动解除。员工要求辞职须提前一个月向酒店提出书面辞呈，否则，按合同规定向酒店交付违约金。', 483, NULL, '[\"员工\", \"酒店\", \"餐券\", \"录用\", \"义务\", \"劳动合同\", \"须\", \"招收\", \"工作\", \"合同\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:25', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:25', '0');
INSERT INTO `document_segments` VALUES ('1955803412398174209', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　员工在合同期内离开本单位，按一切合同、协议规定执行。 　　员工离店必须按酒店规定办理离店手续，交还酒店配发的一切物品，相关部门会签认可后，方可离店。 　　因酒店营业条件变化而富余的员工，又不能在内部安排，将按劳动部门的有关规定执行。 　　二、员工考勤 　　(一)考勤 　　1、所有员工都不得迟到、早退，上下班均要打卡记录其工作时间。任何员工都不允许让别人替代打卡或替代别人打卡。如果考勤卡有误、损坏或丢失，必须立即报告管理员，不得随意涂改或更改。 　　员工上下班除按规定打卡外，仍要到岗位签到、签退，班中离开岗位要填写离、回岗表。 　　2、员工在休息或下班前不得擅离职守，在工作时间内如有事要离开，须向领导请示，经批准后方可离开。 　　(二)病事假 　　1、员工休病假须持特约医院证明(急诊例外)向所在部门申请，经批准后方可休假。部门经理级以上管理人员请病假需总经理批准。员工因急诊不能上班，应由本人或亲属在4小时内电话通知所在部门，并在痊愈上班后8小时内持急诊证明补办请假手续。 　　2、事假要提前填写请假条，写明事由和请假的时间，经有关领导批准后，方可休假。 　　三、员工生活 　　(一)员工住宿', 502, NULL, '[\"员工\", \"方可\", \"规定\", \"离开\", \"批准\", \"部门\", \"急诊\", \"卡\", \"酒店\", \"时间\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:25', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:25', '0');
INSERT INTO `document_segments` VALUES ('1955803412448505858', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　三、员工生活 　　(一)员工住宿 　　住酒店单身宿舍的员工要服从酒店的安排，不准擅自调换房间或床位。宿舍内一律使用酒店统一配备的物品。保持床铺整洁，不得占用空床和使用空床上的物品。住宿员工必须服从管理，爱护宿舍内的各种设施和物品。工作时间不准在宿舍逗留。不准擅自留外人住宿。店外住宿员工未经批准不准进入宿舍。 　　不准将酒店设施及客用品搬(带)入宿舍使用，不准将烟酒带入宿舍。 　　保持室内清洁卫生，不准在墙上或窗外晾挂衣物。 　　节约能源，不准开长明灯，不准有长流水。 　　不准在宿舍内使用电炉子、电褥子等电器。 　　不准在宿舍内放置易燃易爆及有毒物品、易腐烂食品及小动物。 　　晚间10：00后员工不得互相串宿舍。 　　任何时间不准在宿舍喧哗、喝酒、吸烟、玩牌、打闹或做影响他人休息的事情。 　　(二)员工餐厅 　　员工应按规定时间在员工餐厅就餐，服从管理，并自觉遵守员工餐厅的规定，按顺序凭卡就餐;餐卡只准本人使用不得转让，未经许可不得将食物、餐具带出员工餐厅。就餐时保持餐厅卫生，餐后自觉冲洗餐具，爱护餐厅设施。不准私自在餐厅会餐喝酒。不允许浪费粮食及食品、用品。不允许大声喧哗，说笑打闹。', 501, NULL, '[\"宿舍\", \"不准\", \"员工\", \"餐厅\", \"物品\", \"使用\", \"保持\", \"住宿\", \"酒店\", \"就餐\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:25', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:25', '0');
INSERT INTO `document_segments` VALUES ('1955803412515614721', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　(三)员工娱乐及阅览 　　遵守娱乐、阅览室等管理规定，服从管理，保持室内卫生，不允许着工装进入娱乐室、阅览室，不允许大声喧哗，阅览室内应保持肃静。爱护各类娱乐设施，未经许可不允许将任何娱乐用品和书刊带出室外。 　　(四)员工医务室 　　自觉遵守医务室就诊规定，如遇客人时应先请客人就诊，遵听医嘱，医务室内应保持肃静，保持卫生，爱护医务室设备设施。 　　(五)员工班车 　　员工乘坐班车要服从管理，并按要求在发车前十分钟到位(站)，按顺序上车。 　　员工乘坐班车要讲文明礼貌，要尊老扶弱，不得争抢座位。 　　员工在车厢内不准大声喧哗、打闹、与司机交谈。不得将身体任何部位伸出窗外，车辆没有停稳，不准上、下车。 　　讲究公共卫生，车内不准吸烟、不准向车内外乱扔果皮、纸屑或吐痰。 　　爱护车辆的设备设施。 　　(六)员工更衣室 　　自觉遵守员工更衣室管理规定，服从管理，严禁携带酒店物品、食品进入更衣室，讲究公共卫生和社会公德。 　　四、员工仪表仪容 　　员工在班中，按以下要求做好个人修饰。 　　服装：一律穿戴酒店配发的制服和饰物。制服应整洁合体，鞋子合脚，西裤有裤线，佩戴胸牌，扣好钮扣，拉好拉链。不能有破损、缺扣、污迹。', 513, NULL, '[\"员工\", \"卫生\", \"管理\", \"娱乐\", \"不准\", \"医务室\", \"保持\", \"规定\", \"允许\", \"要求\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:25', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:25', '0');
INSERT INTO `document_segments` VALUES ('1955803412607889409', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　指甲：保持清洁，不得超过指甲床0、5mm，不可涂指甲油(非接触食品者可涂无色指甲油)。 　　饰物：不得佩带手表以外的其它饰物且手表款式不能夸张。 　　鞋：穿着酒店按岗位配发的工鞋，清洁(皮鞋光亮)。酒店未配发的，一律穿着黑色皮鞋(款式参照酒店配发给一线的皮鞋)，清洁光亮。男鞋后跟不能高于3公分。女鞋后跟不能高于6公分。 　　男员工： 　　头发：前不过眉，侧不遮耳，后不盖领，鬓角不过中耳线，整齐、清洁、光亮(打发乳或摩丝)，无头屑，不留怪异发型，保持黑色，发长不得短于2公分。 　　面部：保持整洁，不得有胡须，无眼垢、耳垢。 　　袜子：黑色或深兰色袜。无破洞，裤角不露袜口 　　女员工： 　　头发：前不过眉，后不过肩，长发盘起，头饰颜色与发色反差小，整齐、清洁、光亮(打发乳或摩丝)，无头屑，不留怪异发型，头发保持黑色。发长不得短于12公分。 　　袜子：薄肉色袜。无脱丝、破洞，裙角或裤角不露袜口。 　　面部：应化淡妆，口红颜色为红色(浅不过粉红色，深不过朱红色)，无眼垢、耳垢。 　　香水：清新、淡雅。涂于耳背及手的脉膊部位。 　　个人卫生：', 475, NULL, '[\"黑色\", \"头发\", \"清洁\", \"光亮\", \"袜\", \"颜色\", \"酒店\", \"色\", \"鞋\", \"指甲油\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:25', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:25', '0');
INSERT INTO `document_segments` VALUES ('1955803412654026753', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　香水：清新、淡雅。涂于耳背及手的脉膊部位。 　　个人卫生： 　　身体清洁无异味，口腔清洁无异味，牙齿无残留物，双手清洁，鞋、袜清洁无异味，勤洗内衣，勤换工作服。 　　五、员工守则 　　1、热爱中国共产党，热爱祖国，热爱社会主义。 　　2、爱酒店、爱岗位、爱事业、甘于奉献。 　　3、尊重顾客，忠诚待客，热情服务。 　　4、遵守国家的法律法规，遵守酒店的各项规章制度。 　　5、钻研业务，提高技能，开拓创新。 　　6、虚心接受监督检查，随时纠正自身偏差。 　　7、保障客人人身财产安全，爱护酒店公共财产。 　　8、工作相互协作，发扬团队精神。 　　9、以客人利益和酒店声誉为重，维护酒店形象。 　　六、行为规范 　　(一)言谈 　　1、服务用语规范，讲普通话，音量适度，音质优美，话语清晰。 　　2、使用对方易懂的语言，善于倾听对方的讲话，留心对方的吩咐，不得漫不经心，合适的附和与接话，不能打断对方的谈话，不能忽略敬语。不能太谦卑，应使用请求、建议、劝告式的语言，谈话不能触及对方的弱点和短处，不能自夸、不能发牢骚、不能争论。 　　3、不要窃窃私语。 　　(二)礼貌用语 　　1、早上好、您好、晚上好 　　2、您好，欢迎光临', 514, NULL, '[\"酒店\", \"不能\", \"用语\", \"客人\", \"使用\", \"语言\", \"清洁\", \"无异\", \"方的\", \"味\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:25', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:25', '0');
INSERT INTO `document_segments` VALUES ('1955803412700164097', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　3、不要窃窃私语。 　　(二)礼貌用语 　　1、早上好、您好、晚上好 　　2、您好，欢迎光临 　　3、请、您请、请讲、请坐、请走好、请稍候 　　4、谢谢 　　5、不好意思 　　6、没关系 　　7、请稍等 　　8、很抱歉 　　9、对不起、请原谅、对不起打扰了、对不起让您久等了。真对不起，给您添麻烦了。 　　10、再见，欢迎再次光临、祝您一路平安。 　　11、询问、回答客人时均要使用敬语。 　　(三)走姿及行走 　　1、挺胸、收腹、肩平头正。两脚落地后跟所成夹角度数大于10度，小于30度。 　　2、在服务区内不能跑动，遇到客人应侧身礼让，并向客人点头示意。 　　3、院内行走每分钟不得少于106步。 　　4、院内两人行走要排竖队。 　　5、行走不得拉手、勾肩搭背，相互追逐。 　　(四)站姿 　　1、挺胸、收腹、昂首，头正肩平，目光自然平视。不得倚物，右手压左手交叉放于小腹部。 　　2、(男)脚后跟分开，呈“V”型，两脚前内侧距离不超过两拳。 　　(女)脚后跟并拢，呈“V”型，两腿自然并拢。 　　(五)坐姿 　　坐在椅面2/3的部位，保持上身挺直，坐姿端正，不前俯后仰。 　　(男)双腿自然分开，两脚前内侧距离不超过两拳，双手自然放于腿上。', 525, NULL, '[\"自然\", \"行走\", \"客人\", \"请\", \"脚\", \"走\", \"姿\", \"腿\", \"对不起\", \"肩\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:25', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:25', '0');
INSERT INTO `document_segments` VALUES ('1955803412746301442', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　(男)双腿自然分开，两脚前内侧距离不超过两拳，双手自然放于腿上。 　　(女)双腿并拢，右手搭左手交叉放于腿上。 　　(六)手式 　　1、五指自然并拢，手不要握拳，介绍说明指示方向时手臂自然弯曲。要用整个手，不要用食指。 　　2、与客人交谈时手式不要过多，幅度不宜过大。 　　3、手式运用要尊重客人风俗习惯。 　　(七)礼节 　　1、问候：遇客人、领导应主动问候，同事间应相互问候。当酒店人员与客人同行时，应先问候客人，后问候酒店人员，问候客人、上级忌用“你们好”，一客一问候;当客人或领导不便打扰或距离5米以外眼光相遇时，应点头以示问候。 　　2、进出客人用房、办公室：进入客人房间或办公室应按门铃或敲门三声，得到允许后方可进入，敲门声应适宜，不能过响。 　　离开客人房间或办公室时要面向对方后退1—2步，道别后方可离去，关门时仍要转身面向对方，轻声关门。 　　3、鞠躬：右手压左手交叉放于小腹，以臀部为轴，上身前倾15-30度，头、颈、上体保持一条线，目光注视受礼者;日、韩料岗位员工鞠躬右手压左手交叉放于小腹，以臀部为轴，上身前倾90度，头、颈、上体保持一条线，鞠躬时目光随头部自然下视。', 498, NULL, '[\"时\", \"客人\", \"应\", \"问候\", \"自然\", \"手\", \"鞠躬\", \"放于\", \"前\", \"式\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:25', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:25', '0');
INSERT INTO `document_segments` VALUES ('1955803412796633089', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　4、敬礼(保安)：头正颈直，五指自然并拢，大臂与肩平，手掌斜向前，中指触于帽沿。 　　(八)目光 　　说话时看着对方的眼睛或眼鼻之间的三角区。不要盯着客人或斜视;不要冷眼看着客人;不要东张西望。 　　(九)微笑 　　对客人要保持自然的微笑，不能大笑、嘲笑、冷笑、讥笑。 　　(十)接打电话 　　接打电话时，站(坐)姿端正，左手握听筒，右手自然下垂，需记录时右手执笔，仔细聆听，不能倚物，不玩弄文具或其它物品。 　　接听电话： 　　1、三声铃响内接听电话 　　2、直接对客服务岗位的员工用外语问好，用中文报部门和身份。 　　3、非直接对客服务岗位的员工用中文问好，报部门、身份。 　　打电话时： 　　当对方接起电话后，问候你好，用“请问”确认对方身份，如无误，应自报身份和事由。如有误应致歉“对不起，打扰了”。 　　通话： 　　1、声音欢悦，说话清晰，语调轻松。 　　2、用姓氏称呼对方：问候客人时，先用敬语;回答客人问题完毕后要用敬语。 　　3、等客人或领导先放电话后再挂电话。 　　4、接打电话时不允许背朝客人。 　　5、接打电话时，遇到客人从旁边走过应点头示意;遇到客人要求服务时，应兼顾需服务的双方客人。 　　七、保守秘密', 516, NULL, '[\"客人\", \"时\", \"自然\", \"服务\", \"打电话\", \"身份\", \"应\", \"说话\", \"不能\", \"电话\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:25', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:25', '0');
INSERT INTO `document_segments` VALUES ('1955803412842770433', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　七、保守秘密 　　1、对客人要求保密的事情做到守口如瓶。 　　2、对客人的隐私保密。 　　3、为客人在店内的消费情况和存入店内资金保密。 　　4、不向外人泄露酒店的商业机密。 　　5、不泄露酒店员工的收入及员工在店内受到处分的情况。 　　6、不泄露酒店员工的隐私。 　　7、不向外部门泄露本部门的有关工作情况。 　　8、其它不该泄露的信息情况等。 　　八、酒店规则 　　1、员工工牌： 　　员工工牌由酒店发给，只准本人使用，不得涂改或转让。员工工牌属制服的一部分，工作时间必须佩带在制服左上方。如有遗失应立即向人资部报告，并办理手续重新申领;员工调换部门时，须到人资部办理更换工牌手续。 　　2、工作服 　　员工上班时应按规定穿着工作服，保持平整清洁;下班不得穿着工作服离店，不允许私自改动服装或转借他人，不允许将工作服带出酒店私用。 　　3、员工物品(衣)橱', 382, NULL, '[\"员工\", \"酒店\", \"工作服\", \"店\", \"牌\", \"保密\", \"泄露\", \"情况\", \"资\", \"部门\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:25', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:25', '0');
INSERT INTO `document_segments` VALUES ('1955803412888907777', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　3、员工物品(衣)橱 　　员工须使用指定的物品(衣)橱，不得私自调换、转让;要保持橱内外整齐清洁。所有员工的物品(衣)橱，都应接受管理人员的检查。严禁私藏酒店的财物、食物和非法物品，员工不得私配钥匙，如有遗忘或遗失，不能强行打开橱柜，可与管理人员联系使用备用钥匙，如钥匙遗失须办理换锁手续。 　　4、携物品进、出店 　　员工上班时除携带的化妆品外，其它物品一律存放在保安部，不许携带个人物品进店。住店员工将物品带进宿舍时要经过保安部的检查并对与酒店相同的物品张贴标识加以区分，员工贵重物品应到保安部寄存。严禁携带易燃、易爆、有毒危险品及小动物进店。 　　员工携带物品出店，必须经有关部门签发出门证，出店时将出门证交保安部检查核实。 　　员工应无条件接受酒店管理(保安)人员对携带物品和物品(衣)橱的检查。 　　5、班前、班中、班后 　　班前：提前十分钟到岗，按照规定要求和标准作好班前准备工作。 　　班中：服从工作安排，服从管理，遵守工作程序、服务规范和服务程序，保证工作质量和服务质量，确保为客人提供合格的产品和优质的服务。', 465, NULL, '[\"物品\", \"员工\", \"携带\", \"检查\", \"保安部\", \"酒店\", \"工作\", \"店\", \"班\", \"橱\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:25', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:25', '0');
INSERT INTO `document_segments` VALUES ('1955803412956016642', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　班后：当日(当班)工作结束后，按规定要求作好日(班)清工作，填写相关表格，作好交接工作，经上级检查确认后方可下班。班后任何员工不允许无故在酒店停留，住店员工不得在面客区域和工作场所逗留。 　　6、员工通道 　　员工出入各部门和工作场所应走指定的员工通道，员工进出酒店时须走指定的店门，在院内行走必须走人行道(路边上沿)。员工不得使用客用通道和电梯。 　　7、拾遗 　　员工在酒店任何地方发现遗失的钱财物品等，须在第一时间上交部门领导或保安部，并讲清拾遗地点、时间，以便尽快物归原主，不得私自存放。 　　8、使用电话 　　员工在面客区域、工作场所不得接、传、打私人电话，员工有外线电话可由部门给予转达或留言。员工有急事需打电话必须经领导同意后到员工专用电话处拨打。 　　9、亲友探访 　　任何时间都不允许员工在面客区域、工作场所会见亲属好友。来访者应在酒店指定的场所等候，由相关人员通知员工所在部门，经本部门领导批准后方可会见。 　　10、酒店财产 　　员工必须高度爱护酒店的一切设备设施、一草一木及酒店配发的用品和工具。操作设备设施时，必须熟悉掌握其性能及操作规程，持证上岗，并定期进行检查、维护、保养。', 504, NULL, '[\"员工\", \"酒店\", \"工作\", \"部门\", \"必须\", \"电话\", \"场所\", \"领导\", \"客\", \"指定\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:25', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:25', '0');
INSERT INTO `document_segments` VALUES ('1955803413006348289', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　员工不得动用客用设施。 　　未经批准不得将任何酒店财产带出酒店。 　　11、岗位用品 　　酒店不允许将非酒店配发的用品带到岗位使用。 　　九、安全守则 　　(一)作好五防工作：防火、防盗、防触电、防交通事故、防食物中毒。 　　每个员工都要严格遵守酒店的安全规定，使每一位顾客和员工都认为在酒店住宿、餐饮、娱乐和工作是安全可行的。 　　员工要随时提高警惕，防止一切侵犯顾客、同事及酒店人身、财产安全的事件发生，如发现可疑的人或行为，应立即报告上级或保安人员。有关人员要严密观察，防止突发事件发生，一旦发生，每位员工都有责任、有义务挺身而出，保护客人、酒店的人身财产安全。 　　(二)员工必须十分重视防火，把防火工作看作是酒店安全的头等大事。 　　要有高度的防火意识，发现隐患与险情要以最快的速度报告、报警或消灭。 　　酒店消防电话—— 　　消防三会——会报警、会使用灭火器、会疏散逃生。 　　易燃易爆物——燃料、纸制品、棉毛、化纤制品、酒精类、家具类、乙炔、煤气、氧气瓶、氢气瓶等。 　　消防防范措施： 　　不准在酒店内及车辆上吸烟、不准在易燃品附近明火作业。明火作业时要作好防范措施。', 494, NULL, '[\"酒店\", \"安全\", \"员工\", \"防火\", \"财产\", \"工作\", \"报告\", \"发现\", \"发生\", \"防\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:25', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:25', '0');
INSERT INTO `document_segments` VALUES ('1955803413094428673', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　消防防范措施： 　　不准在酒店内及车辆上吸烟、不准在易燃品附近明火作业。明火作业时要作好防范措施。 　　发现烟蒂一定要熄灭，垃圾箱内要倒入一定数量的水。 　　所有消防通道、楼梯出口和走廊严禁放置障碍物，保证消防通道畅通。 　　易燃物品必须放置在指定的安全位置。 　　员工不得擅自动用消防设备设施。 员工手册范本 篇19 　　一、了解公司产品物资需求及各种物资的市场供应情况，经常了解及时掌握物资市场动态变动信息。 　　二、生龙活虎产经营急需的物品要优先采购，与仓库人员常沟通，检查物资库存量，防止物资积压、使用周期长、变质浪费等现象。 　　三、采购物品应做到价廉物美，季节性物品应及时提供样板信息，供有关责任人选用。 　　四、采购物品应严格把好质量关，对不符合质量要求的\'要坚决拒收。 　　五、需签订合同的必须严格审核合同条款，并上报主管人员审核方可实施 　　六、努力学习业务知识，提高业务水平，接待来访业务要热情有礼，外出采购时要注意维护公司的礼仪、利益和声誉。食品公司财务管理制度为适应公司管理要求，规范财务操作，根据公司财务工作现状，并结合公司今后发展需要和财务管理需要。特制定如下管理制度。 员工手册范本 篇20', 512, NULL, '[\"采购\", \"公司\", \"物资\", \"物品\", \"应\", \"必须\", \"员工\", \"严格\", \"要求\", \"及时\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:25', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:25', '0');
INSERT INTO `document_segments` VALUES ('1955803413144760321', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '员工手册范本 篇20 　　孕婴店员工手册 　　一、店面人员配备 　　1、店长1 名 　　2、销售主管1 名 　　3、收银员2 名 　　4、商务1 名 　　5、店面营业员若干名 　　二、店面人员职责： 　　1、店长工作职责 　　店长是店面的灵魂，主要负责连锁店面的日常管理(人、财、物)、组织、激励、培训工作，全面负责店内员工的管理工作，主要包括如下内容： 　　(1)员工管理 　　对员工日常工作进行监督和管理，包括迟到、早退、仪容仪表、待客礼仪、卫生等的全面管理; 　　a、帮助员工做好正确的职业规划、职业定位，帮助员工快速成长，为其创造晋升条件; 　　b、做好员工的激励工作，根据店面管理及考核制度，对员工工作进行准确评估，以鼓励先进，形成比、学、赶、帮、超的工作氛围; 　　c、经常与员工沟通，协调人际关系，努力创造积极、愉快的工作氛围。 　　(2)店务管理 　　对店内设备、货品、账目、安全措施等进行全面管理，具体为; 　　a、设备管理――对店内各种电器、收银机等设备的运作和安全情况进行检查，有问题及时解决; 　　b、账目管理――做到帐目清晰，钱账相符;', 481, NULL, '[\"管理\", \"员工\", \"店\", \"工作\", \"进行\", \"全面\", \"店面\", \"b\", \"账目\", \"做好\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:25', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:25', '0');
INSERT INTO `document_segments` VALUES ('1955803413190897665', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　b、账目管理――做到帐目清晰，钱账相符; 　　c、货品管理――认真做好产品的销售统计工作，保障合理库存，对各类赠品的领用严格把关，确保无破损、丢货现象; 　　d、安全管理――对门窗、电器开关进行检查后关店，消除安全隐患; 　　e、每日工作做到日清日结，日结日高。 　　2、销售主管 　　负责与客户信息沟通，维护和服务客户，处理客户反馈， 开发市场， 监控货款， 指导和考核下属工作，协助店长做好店面的各项管理工作。 　　(1)销售管理 　　根据店面的实际情况做好店内的业绩管理工作，具体工作为： 　　a、根据店面实际情况，制定合理的月、周、日销售计划及制定销售目标; 　　b、根据销售计划，制定相适应当的促销方案，并报股东会及代理商批准; 　　c、根据方案，实施销售计划及促销方案，结束后对以上两种方案进行最终总结，根据员工表现情况进行奖励。 　　d、对员工销售能力的管理，及时对员工在工作中出现的销售问题进行培训及解决; 　　(2)会员管理 　　对店内的顾客进行科学有效的管理，提高顾客对店面品牌的认知度，具体为; 　　a、根据店内会员管理制度，督促员工做好顾客信息的录入工作，确保会员信息真实准确;', 503, NULL, '[\"管理\", \"销售\", \"工作\", \"进行\", \"店\", \"做好\", \"员工\", \"情况\", \"会员\", \"顾客\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:25', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:25', '0');
INSERT INTO `document_segments` VALUES ('1955803413237035009', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　a、根据店内会员管理制度，督促员工做好顾客信息的录入工作，确保会员信息真实准确; 　　b、经常对顾客档案进行分析整理，将顾客进行等级区分，督促客服做好顾客的回访工作; 　　c、定期作顾客消费记录查询及分析，分析顾客的忠诚度、购买产品情况、到店情况等，针对不同顾客做针对性会员促销活动; 　　d、会员顾客的信息管理：给会员发生日、节日等各种问候、回访及促销信息，维护会员对品牌的忠诚度，从而提高会员到店次数，增加到店人数; 　　(3)培训管理 　　对新进员工及老员工做好日常的培训工作，帮助新老员工提高专业技能，具体为： 　　a、根据店面新老员工的实际情况制定有针对性的培训计划; 　　b、培训计划应充分考虑：店面企业文化、专业知识、产品知识、服务礼仪、销售技巧、顾客反对意见及疑议等。 　　c、根据店内销售存在的问题进行针对性培训，实际解决店内问题，从而提高店面业绩; 　　3、收银员 　　(1)岗位职责 　　1.快速、准确地收取货款 　　2.为顾客提供良好的服务，回答顾客咨询 　　3.严格遵守唱收唱付的原则 　　4.店面财产(收银机、验钞机、收银台、电脑等)的保养 　　5.负责收银区前台的清洁卫生 　　(2)主要工作', 513, NULL, '[\"顾客\", \"店\", \"会员\", \"店面\", \"培训\", \"员工\", \"信息\", \"工作\", \"提高\", \"收银\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:25', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:25', '0');
INSERT INTO `document_segments` VALUES ('1955803413287366657', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　5.负责收银区前台的清洁卫生 　　(2)主要工作 　　1.确保收银动作的规范化、标准化，提高收银速度和准确性 　　2.及时将货款存到银行，及时作出差异报告 　　3.保证前台区域的清洁卫生 　　4.对商业资料的保密 　　5.各种票据和文件的收集、保管和传递 　　6.确保现金的安全 　　7.保证充足的零用金 　　8.确保顾客所购的每一件商品均已收银，不得遗漏 　　9.及时拾零，避免影响正常收银，并将商品存在的问题作好记录 　　10.识别伪钞 　　11.严格遵循礼貌规范用语 　　(3)辅助工作 　　1.协助做好顾客服务 　　2.协助盘点和前区商品的理货、补货 　　3.提高警惕，注意防盗 　　4、商务采购 　　1、及时了解各店面商品的需求及各种商品的市场供应情况，掌握店面对各种商品采购成本及采购资金控制要求，熟悉各种商品采购计划。 　　2、店面急用的物品要优质采购，根据店面库存货情况，定出采购计划，对定型、常用商品按库存规定及时办理，与店长经常沟通，防止商品积压，做好商品销售的周期性计划工作。 　　3、采购商品应做到价廉物美、择优录取。时鲜、季节性商品要做到提前采购，不得耽误销售。', 496, NULL, '[\"商品\", \"采购\", \"及时\", \"收银\", \"工作\", \"确保\", \"保证\", \"店面\", \"货\", \"顾客\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:25', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:25', '0');
INSERT INTO `document_segments` VALUES ('1955803413354475522', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　3、采购商品应做到价廉物美、择优录取。时鲜、季节性商品要做到提前采购，不得耽误销售。 　　4、采购商品应严格把好质量关，对不符合质量要求的要坚决拒收，根据销售动向和市场信息，积极争取定购货源，根据“ 畅销多进、滞销不进” 的原则，保证货源充足。 　　5、经常了解商品销售情况，以销定购。积极组织适销对路的货源，防止盲目进货。尽量避免积压商品，提高资金周转率。及时了解库存情况，对库存商品要做到“ 了如指掌” 和“ 心中有数” ，有计划、有步骤地安排好日常工作。 　　6、努力学习业务知识，提高业务水平，接待来访业务要热情有礼，外出采购时要注意维护店面的礼仪、利益和声誉，不谋私利。 　　7、严格遵守财务制度、遵纪守法、不索贿、，在平等互利下开展业务活动。购进物资要尽量做到单据(发票) 随货同行，交仓管员验收，报账手续要及时，不得随意拖账挂账。 　　5、营业员 　　营业员是连锁店的基层工作人员，其仪容仪表代表了店面形象，其言谈举止处处显示了品牌及服务理念，具体工作职能为： 　　(1)严格遵守店面员工日常工作规范; 　　(2)努力学习专业及产品知识，全面提高专业技能及娴熟应用销售技巧;', 496, NULL, '[\"做到\", \"店面\", \"严格\", \"商品\", \"销售\", \"工作\", \"采购\", \"及时\", \"提高\", \"定购\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:25', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:25', '0');
INSERT INTO `document_segments` VALUES ('1955803413400612866', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　(2)努力学习专业及产品知识，全面提高专业技能及娴熟应用销售技巧; 　　(3)深入领会店面的服务理念，做好顾客的服务接待(售前、售中、售后)工作; 　　(4)服从店长工作安排，完成店长下达的销售指标; 　　(5)做好店内商品的整理及监控工作，防止偷盗，避免店内商品丢失破损。 　　孕婴用品店店面工作流程 　　店长一日工作流程 　　(一)营业前 　　1)组织晨会及交接-班会议的召开： 　　a、人员状况确认(出勤、休假、轮班、服装、仪容仪表及精神状况); 　　b、传达店面重要文件及通知; 　　c、上一班营业状况确认、分析; 　　d、针对营业问题，指示有关人员改善; 　　e、分配当日工作计划。 　　2)店内状况确认： 　　a、店面、展柜、试用装及试赠品的卫生清洁情况; 　　b、店内货品的陈列、补货、促销、订货等; 　　c、电器、灯光、宣传资料等准备情况; 　　d、畅销货品的储备及展示确认。 　　(二)营业期间 　　A、无顾客时的工作(有序的安排好员工的工作及其他准备工作，时刻为销售做好准备!) 　　1)记录当天晨会及交接-班会议日志; 　　2)顾客资料的整理、录入及POS 系统会员的分析管理;', 502, NULL, '[\"店\", \"工作\", \"店面\", \"状况\", \"营业\", \"确认\", \"顾客\", \"销售\", \"做好\", \"准备\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:25', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:25', '0');
INSERT INTO `document_segments` VALUES ('1955803413450944514', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　1)记录当天晨会及交接-班会议日志; 　　2)顾客资料的整理、录入及POS 系统会员的分析管理; 　　3)时刻检查货架上有无空缺商品，如有提醒店员及时补上 　　4)监督店员的工作情况，错误地方及时纠正; 　　5)监督促销活动的实施和进展，提醒店员及时向顾客做好宣传和介绍; 　　6)对新员工作出相应的指导和培训; 　　7)安排老员工对专业知识的巩固学习; 　　8)安排员工轮流在店面周围发宣传单，吸引顾客到店(针对人流量少的时候); 　　9)赠品的合理赠送，时刻维护顾客服务; 　　10)接收货品，准备清点并及时入库，与电脑POS 核对; 　　11)时刻维持店内的卫生状况; 　　12)合理及时的安排送货上门的服务; 　　13)排员工轮流用餐。 　　B、有顾客时的工作(时刻围绕销售，做好细节工作，提高业绩!) 　　1)准备记录进店面的每一位顾客，提供店面到店人数水平值; 　　2)随时帮助后进员工的销售，提高后进员工的销售能力; 　　3)激励和跟踪所有员工对自已销售目标的完成，及时调整销售计划; 　　4)紧盯每一个员工的成交能力，随时分析店面成交率及店面单笔成交金额的水平值;', 492, NULL, '[\"顾客\", \"及时\", \"员工\", \"时刻\", \"店面\", \"销售\", \"店\", \"工作\", \"安排\", \"店员\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:25', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:25', '0');
INSERT INTO `document_segments` VALUES ('1955803413497081858', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　4)紧盯每一个员工的成交能力，随时分析店面成交率及店面单笔成交金额的水平值; 　　5)时刻关注目前销售与计划的差距，将情况告知员工，激励员工再接再励，为店面总业绩目标的达成时刻努力; 　　6)处理营业中顾客投诉; 　　7)服务礼仪规范时刻监督提醒。 　　8)空缺商品再次检查并补货，提醒店员，严格防范货品丢失; 　　(三)营业结束 　　1)各项营业报表的填写，分析完成销售计划的情况并列出明日销售计划及目标; 　　2)叮嘱收银员及时将货款存到银行; 　　3)安排卫生的打扫; 　　4)收回店外物品; 　　5)关闭照明、灯箱、电器; 　　6)签退，离开卖场。 　　营业员一日工作流程 　　(营业员工作人员应提前10 分钟到达店内做好各项准备工作) 　　(一)营业前 　　1)参加晨会及交接-班会议： 　　a、向店长汇报前上一班的销售业绩以及重要信息反馈; 　　b、听从店长分配当日工作计划; 　　2)检查准备商品： 　　a、复点过夜的商品', 420, NULL, '[\"营业\", \"销售\", \"计划\", \"时刻\", \"店\", \"工作\", \"目标\", \"业绩\", \"前\", \"准备\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:26', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:26', '0');
INSERT INTO `document_segments` VALUES ('1955803413585162242', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　b、听从店长分配当日工作计划; 　　2)检查准备商品： 　　a、复点过夜的商品 　　参加完晨会及交接班会议后，营业员要做的第一件事，就是根据商品平时的摆放规律，将过夜商品进行过目清点和检查。不论实行的是正常的出勤还是两班倒，营业员对隔夜后的商品都要进行复点，以明确各自所负的责任;在复点商品时，如果发现疑问或问题，应及时地向店长汇报，请示处理。 　　b、补充商品 　　在复点商品的过程中，根据销售规律和市场变化，对款式品种缺少的或是货架出样数量不足的商品，要尽快地补充，做到库有柜有。续补的数量要在考虑货架商品容量的基础上，尽量保证当天的销量。 　　c、检查商品标签 　　在复点的同时，营业员还要对商品价格进行逐个检查。对于附带价格标签的商品，应检查价签有无脱落、模糊不清、移放错位的情况。有脱落现象的要重新制作，模糊不清的要及时更换，错位的要及时纠正。 　　d、辅助工具与促销用品的检查准备', 398, NULL, '[\"商品\", \"检查\", \"复\", \"营业员\", \"及时\", \"进行\", \"应\", \"货架\", \"规律\", \"数量\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:26', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:26', '0');
INSERT INTO `document_segments` VALUES ('1955803413631299585', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　d、辅助工具与促销用品的检查准备 　　营业时销售工具和促销用品的准备，是营业前准备工作的一项重要内容，没有完备的工具和用品，要做好营业工作和提高服务质量是不可能的。促销员事先要将工具与促销品放在固定的位置，并养成使用后归放原位的习惯;随时留意工具与促销品是否完好，如有污损破裂现象，要及时地向店长换领。 　　e、做好店内与商品的清洁整理工作 　　店内的地面、货架、商品以及每个卫生死角都必须清理干净。 　　(二)营业期间 　　A、无顾客(以做临时工作和学习为主，并时刻做好服务的准备!) 　　1)做好顾客资料登记工作; 　　2)柜台空缺产品及时申补; 　　3)维护营业区卫生; 　　4)将工作日志记录完整; 　　5)对销售中遇到的问题及时讨论总结，以便为下一个顾客做好更完善的服务。 　　B、有顾客(所有准备的结果是为了有更高的业绩) 　　1)积极地根据顾客需求介绍产品，并讲清会员可享受的优惠服务; 　　2)时刻明确自己的销售目标，了解完成计划的情况，对未完成的销售任务进行合理分析和调整; 　　3)随时了解自己接待顾客的成交率，及时分析并努力提高; 　　4)店面促销活动及时告知顾客，促进每单销售的达成;', 506, NULL, '[\"顾客\", \"工作\", \"及时\", \"销售\", \"促销\", \"准备\", \"服务\", \"工具\", \"做好\", \"营业\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:26', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:26', '0');
INSERT INTO `document_segments` VALUES ('1955803413681631233', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　4)店面促销活动及时告知顾客，促进每单销售的达成; 　　5)将销售过程中顾客未成交的原因及时分析，并告之店长，为提高员工销售总结好经验。 　　C、交接班 　　1)晚班接班的人没到，早班不允许下班; 　　2)早班人员要将工作日志的内容传达给晚班人员; 　　3)晚班接-班人员必须将货品认真清点，如有短少或毁损应立即向店长汇报; 　　4)做好顾客的销售服务工作，未接待完顾客不许下班，切忌因交接班对顾客服务怠慢，造成顾客不满情绪。 　　(三)营业结束 　　1)各项工作数据地整理、上报; 　　2)柜台货品整理; 　　3)打扫卫生包干区; 　　4)收回店外物品; 　　5)关闭照明、电器; 　　6)签退，离开卖场。 员工手册范本 篇21', 317, NULL, '[\"顾客\", \"店\", \"销售\", \"工作\", \"晚班\", \"货品\", \"人员\", \"员工\", \"及时\", \"交接班\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:26', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:26', '0');
INSERT INTO `document_segments` VALUES ('1955803413727768577', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　4)收回店外物品; 　　5)关闭照明、电器; 　　6)签退，离开卖场。 员工手册范本 篇21 　　疫情防控期间开学复课学校食堂食品48小时留样制度为贯彻执行党、认真落实省市和教育行政部门有关工作要求，全力做好我校师生返校上课期间的疫情防控和等工作，切实保障我校师生身体健康和生命安全，确保我校春季学期安全顺利上课，及时有效预防传染病的发生和蔓延，保障师生的身体健康和生命安全，根据《学校卫生工作条例》《传染病防治法》、《学校和托幼机构传染病疫情报告工作规范》及相关法律法规的要求，特制定学校疫情防控期间食堂食品48小时留样制度。 　　1、食堂提供的每样食品，由食堂分餐人员专人负责留样。 　　2、每餐留样的`食品，按规定留足100克，分别盛放在已消毒的餐具中。 　　3、留样食品取样后，立即存放在完好的食品罩内，以免被污染。 　　4、留样食品冷却后，用保鲜膜密封好，并在其外部贴上标签，标明留样日期、时间、品名、餐次、留样人。 　　5、将贴好标签的留样食品按秩序存放在恒温冰箱内保存。冰箱温度设定为0°C—4C。 　　6、做好每餐每样留样食品的记录，包括食品样源、食品名称、留样时间、目测样状等，以备检查。', 505, NULL, '[\"留\", \"食品\", \"工作\", \"餐\", \"疫情\", \"防控\", \"学校\", \"师生\", \"期间\", \"我校\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:26', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:26', '0');
INSERT INTO `document_segments` VALUES ('1955803413790683138', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　6、做好每餐每样留样食品的记录，包括食品样源、食品名称、留样时间、目测样状等，以备检查。 　　7、留样食品般保存48小时，进餐者如无异常，即可处理留样的食品；如有异常，立即封存，送食品卫生门查验。 　　8、食品留样冰箱为专用设备，严禁存放与留样食品无关的物品。 　　9、卫生监督小组及监督管理员不定期检查留样工作，发现未按要求留样，将对责任人进行工作失职处罚。 员工手册范本 篇22 　　1、主食、副食分库存放，食品与非食品不能混放，食品库内不得存放有毒有害物品，不得存放个人物品和杂物。 　　2、食品库内应定期清扫，保持仓库、货架清洁卫生，经常开窗或用机械通风设备通风，保持干燥。 　　3、做好食品数量、质量合格证明或检疫证明的检查验收工作。腐烂变质、发霉生虫、有毒有害、掺杂掺假、质量不新鲜的食品，无卫生许可证的\'生产经营者提供的食品、未索证的食品不得验收入库。 　　4、做好食品数量、质量入库登记，做到先进先出，易坏先用。禽蛋倒箱入库。 　　5、食品按类别、品种分架、隔墙、离地整齐摆放，散装食品及原料储存容器加盖密封，同时经常检查，防止霉变。 　　6、肉类、水产品、禽蛋等易腐食品应分别冷藏、冷冻贮存。', 507, NULL, '[\"食品\", \"留\", \"检查\", \"工作\", \"存放\", \"入库\", \"质量\", \"经常\", \"保持\", \"易\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:26', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:26', '0');
INSERT INTO `document_segments` VALUES ('1955803413836820481', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　6、肉类、水产品、禽蛋等易腐食品应分别冷藏、冷冻贮存。 　　7、用于保存食品的冷藏设备，必须贴有明显标识并有温度显示装置。生食品、熟食品、半成品去除外包装，使用盛放食品的容器分柜存放，杜绝生熟混放，并且各类食品留有空隙，不得堆放、挤放。熟食品、半成品覆盖保鲜膜。 　　8、冷冻设备定期除霜，保持霜薄（不得超过1cm），肉类、水产品去除外包装，使用盛放食品的容器分柜存放。 　　9、经常检查食品质量，及时发现和处理变质、超过保质期限的食品。 　　10、做好防鼠、防蝇、防蟑螂工作，安装符合要求的挡鼠板及防蚊蝇设施，定期开展除四害工 员工手册范本 篇23 　　物业公司的员工手册 　　一、加班工资计算方法 　　二、新进/离职工资计算 　　公司简介(略) 　　公司组织构架(略) 　　管理部：主管、房屋管理、中控值班、停车场管理、家政服务、投诉受理、协调 　　工程部：主管、共用维修、设备维护运行技术 　　保卫部：队长、班长、保安员 　　保洁部：主管、领班、保洁员 　　行政部：人力资源干事、行政管理员、文秘宣传员、资料管理员、监察督导员 　　经营部：对外发展、租赁中介服务、商业网点管理、经营服务 　　财务部：主管、会计、统计、出纳', 516, NULL, '[\"食品\", \"主管\", \"设备\", \"服务\", \"管理\", \"防\", \"经营\", \"定期\", \"超过\", \"冷冻\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:26', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:26', '0');
INSERT INTO `document_segments` VALUES ('1955803413887152130', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　经营部：对外发展、租赁中介服务、商业网点管理、经营服务 　　财务部：主管、会计、统计、出纳 　　绿化养护：主管 　　第一节 人 事 　　一、正式聘用及试用 　　1、新进员工必须通过公司行政管理中心人力资源部门及用人部门两次面试，并由行政管理中心人力资源部门通知上班。上班前必须先办理录用手续并签定合同(或劳动协议)。办手续时需填写各类个人资料供存档、需上交本人身份证复印件、最高学历证书复印件及其他培训资料证书复印件(如有)，个人资料应正确无误，如提供虚假资料，可招致辞退的严重后果。需携带好有关证件原件，有员工本人亲自到公司行政管理中心人力资源部门与公司签订正式合同或劳务协议后方能上班。 　　2、新进员工自上半之日起试用期为三个月(特殊部门除外)。 　　3、员工对于自己所担任之工作有任何问题，需先征询用人部门主管或经理意见。', 367, NULL, '[\"需\", \"部门\", \"员工\", \"主管\", \"管理\", \"个人资料\", \"正式\", \"上班\", \"公司\", \"先\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:26', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:26', '0');
INSERT INTO `document_segments` VALUES ('1955803413937483778', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　3、员工对于自己所担任之工作有任何问题，需先征询用人部门主管或经理意见。 　　4、凡与公司签定了正式合同的员工，请到原单位/社保中心将养老金、住房公积金帐户转至本公司，以便公司为您办理养老金、住房公积金等。若原单位/社保中心从未办过二金或从学校新毕业之员工，请书面向公司行政管理中心人力资源部说明并提出申请新开户头。到原单位转帐户之前必须先到公司行政管理中心人力资源部开具证明。 　　二、离职办法及手续 　　1、凡员工欲离职者，应按合同/劳务协议之规定，提前向用人部门提出书面离职申请;试用期间则于一周前提出书面申请即可。 　　2、凡员工未按合同书承诺提前离职者，公司将扣除相应的薪金作为通知期以赔偿公司损失(除非特殊情况，经用人部门主管或经理同意准予提前离职)。 　　第二节 福利待遇 　　公司按国家规定为员工缴纳养老保险、医疗保险、失业保险和住房公积金，具体如下： 　　一、养老保险 　　1、养老保险办法的适用范围。 　　与本公司签订正式劳动合同并将人士档案转至本公司的员工。 　　2、养老保险费的缴纳： 　　①公司缴纳部分：按本公司上一年全部在职人员工资总额的22.5%的比例缴纳养老保险费', 500, NULL, '[\"公司\", \"员工\", \"离职\", \"单位\", \"提出\", \"用人\", \"部门\", \"提前\", \"合同\", \"申请\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:26', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:26', '0');
INSERT INTO `document_segments` VALUES ('1955803413983621121', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　①公司缴纳部分：按本公司上一年全部在职人员工资总额的22.5%的比例缴纳养老保险费 　　②各人缴纳部分：在职人员应以本人上一年度月平均工资为缴费基数，目前按国家规定之比列7%缴纳。 　　3、进入个人账户的养老保险费： 　　①个人缴纳的养老保险费。 　　②单位缴纳的养老保险费进入个人账户的部分。 　　4、享受养老保险待遇具备的条件： 　　①退休： 　　达到国家、本市规定的退休年龄。 　　单位和个人按照规定缴纳养老保险费。 　　养老保险办法实施前参加工作、连续工龄(包括缴费年限)满十年或者养老保险办法实施后参加工作、缴费满十五年。 　　②退职： 　　养老保险办法实施前参加工作，到达退休年龄时连续工龄(包括缴费年限)满五年不满十年的人员，应属退职;连续工龄不满五年，因病或者非因公致残的在职人员，经劳动鉴定委员会确认完全丧失劳动能力的，可以退职。 　　退职人员按规定享受相应的养老待遇。 　　二、医疗保险 　　公司按国家规定比例为每位正式员工(人事关系转到公司)缴纳医疗保险。 　　具体标准如下： 　　公司——7%;个人——2% 　　三、失业保险', 476, NULL, '[\"规定\", \"缴纳\", \"国家\", \"缴费\", \"养老保险\", \"退职\", \"公司\", \"在职人员\", \"%\", \"工龄\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:26', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:26', '0');
INSERT INTO `document_segments` VALUES ('1955803414033952769', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　具体标准如下： 　　公司——7%;个人——2% 　　三、失业保险 　　按公司规定每月单位和个人各交纳2%和1%，全部进入社会统筹系统，不建立个人账户。 　　四、住房公积金 　　与公司签订正式合同的员工，人事关系一经转入公司，每月按照国家规定的比例为员工缴纳住房公积金。目前公司缴纳进入个人账户的比例为员工上一年度平均工资的15%，员工个人亦交付5%。 　　第三节 员工仪表、服装等规定 　　一、仪表、仪容 　　1、员工必须时刻保持衣冠、头发的整洁。不能涂抹气味浓重的护发用品及香水。男员工须经常理发，发长不盖耳、遮领，不准留大鬓角、烫发，不准蓄小胡须，且应做到每日剃胡须。 　　2、女员工应打扮适度，上下班换岗时不穿奇装异服，端庄大方。可淡妆上岗，不准浓妆艳抹。不得佩戴太多、太大、太醒目的饰物。 　　3、注意个人卫生，做到无汗味异味。上岗前及上岗时不得饮酒、不得吃葱蒜、韭菜等带异味的食品以保持口腔卫生。 　　4、员工上班时必须精神饱满，举止大方得体，严禁无礼待客。 　　二、员工服装规定 　　1、员工使用期满后，由公司统一配发工服(特殊岗位除外)。 　　2、员工上班时间必须穿着工服。', 496, NULL, '[\"员工\", \"公司\", \"个人\", \"时\", \"规定\", \"%\", \"必须\", \"不准\", \"上岗\", \"保持\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:26', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:26', '0');
INSERT INTO `document_segments` VALUES ('1955803414126227458', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　1、员工使用期满后，由公司统一配发工服(特殊岗位除外)。 　　2、员工上班时间必须穿着工服。 　　3、上班时必须佩带胸卡，无胸卡者须佩带工牌。遗失胸卡或工牌者将交纳违约金处理。 　　公司员工实行上下班随机抽查制度，由行政管理中心人力资源部负责组织实施。 　　3、公司员工外出办理业务，需提前办理《员工外出登记单》，并交至行政管理中心人力资源部，否则按迟到或旷工。 　　4、员工因公出差，须事先填写《出差申请单》并交至行政管理中心人力资源部留存。凡未填写《出差申请单》者扣发当月全勤奖，特殊情况须报总经理审批。 　　二、迟到、早退 　　1、迟到和早退的违约金标准如下： 　　副主管级以上(含副主管)迟到/早退，按此标准翻倍! 　　2、月累计迟到、早退3次(含3次)以上，取消当月全勤奖。 　　三、旷工 　　有下列情况之一者以旷工处理： 　　1、未办理请假手续而缺勤或未经准假而私自休假者，以及因各种假期逾期而无事先申请续假者。 　　2、不服从调配而不上班者。 　　3、打架斗殴致伤而不上班者。 　　4、一次迟到或早退60分钟以上者。 　　5、其他无正当理由缺勤者。', 483, NULL, '[\"员工\", \"迟到\", \"公司\", \"早退\", \"上班\", \"旷工\", \"管理\", \"特殊\", \"行政\", \"中心\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:26', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:26', '0');
INSERT INTO `document_segments` VALUES ('1955803414193336322', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　3、打架斗殴致伤而不上班者。 　　4、一次迟到或早退60分钟以上者。 　　5、其他无正当理由缺勤者。 　　6、凡旷工四小时以内的，按半天计算，严重警告扣100元，并扣半天工资;旷工超过四小时的，按一天计算，严重警告扣200元，并扣一天工资;旷工二天者扣四天工资，给予最后警告。 　　7、一个月内累计旷工三天及以上者，予以立即辞职。 　　第五节 请假办法 　　公司依各种不同之事由，分列以下假别并详列其范围 　　一、病假 　　1、员工因病休假，必须凭医院病假单方可病休，若当天无法交病假单，须在上班当天补交(须附病历证明)。但必须在病假当天电话告知部门主管或经理。员工一般情况下不得用上班时间去看病。若确属需要到医院就医，需先经部门主管或经理同意。就医时间若不超过3小时，不按病假处理。多于3小时部分按病假处理。每月不按病假处理的就医次数只限一次。 　　2、员工按请假手续休病假的，所扣工资=休假天数*日工资(日工资=全额工资/22)，并不享受当月全勤奖。 　　3、员工休病假天数超过40(含40天)天的，公司有权与其终止劳动关系。 　　二、事假', 474, NULL, '[\"病假\", \"员工\", \"工资\", \"超过\", \"休\", \"当天\", \"旷工\", \"就医\", \"小时\", \"公司\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:26', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:26', '0');
INSERT INTO `document_segments` VALUES ('1955803414239473665', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　3、员工休病假天数超过40(含40天)天的，公司有权与其终止劳动关系。 　　二、事假 　　员工因事确需本人处理，必须至少提前一天向部门主管或经理提出申请，并填写《休假申请表》，经批准后方可休假。因急事需当天休事假者，必须在本人应到岗的时间前用电话通知部门主管或经理，经同意后方可休假，事后补办请假手续。 　　1、服务期满半年者事假可用年休假抵冲，但必须在假单中特别注明扣抵年休假。否则一律以事假处理。 　　2、仍在试用期的员工，一般不予批准事假。有特殊情况者除外。 　　3、事假工资计发办法：(每月累计事假天数为D) 　　(全额工资/22)*(22 - D) 　　4、全年事假累计超过15天(含15天)，公司有权与其终止劳动关系。 　　三、年休假 　　1、凡正式员工在本公司连续服务满一年者(包括试用期)，可享受有薪年假，第一年为五天，第二年及以后每年七天。此年假不包括法定节假日。年假应以连续方式提取，需提前十五天申请，经部门负责人报请公司，经主管领导批准后方可提取，年假不准累计及预提。公司有权因业务工作更改申请者之日期及天数。 　　2、年休假以半天为计算单位。年休假可冲抵事假。 　　一、奖励的原则', 504, NULL, '[\"事假\", \"休假\", \"公司\", \"必须\", \"员工\", \"天数\", \"批准\", \"方可\", \"主管\", \"累计\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:26', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:26', '0');
INSERT INTO `document_segments` VALUES ('1955803414281416705', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　2、年休假以半天为计算单位。年休假可冲抵事假。 　　一、奖励的原则 　　1、多奖少罚，奖罚公平 　　2、及时奖励 　　3、物质奖励和精神奖励相结合 　　4、奖励程度与员工的贡献相当 　　二、奖励措施 　　1、员工贡献奖(不定期奖励) 　　①各类合理化建议，对提高管理工作质量确有成效。 　　②工作细致负责，经常获得客户的书面表扬。 　　③解决疑难杂症，降低成本，节约费用。 　　④拾金不昧，见义勇为(救火抢险等表现良好)。 　　⑤维护公司声誉，受委屈忍辱负重，不计较个人得失。 　　⑥其他应给予奖励的行为。 　　2、季度优秀员工 　　每个部门，每季度评选一次，并张贴红榜，以资鼓励。 　　3、年度最佳员工 　　按员工总人数的2%比例民主选举，投票选出年度最佳员工，附优秀事迹书面报告，上报行政管理中心人力资源部，审核同意后给予奖励，并颁发由总经理签署的获奖证书，并张贴红榜予以通报表彰。 　　4、其他奖励 　　①义务献血奖励 　　②获得各类荣誉的奖励 　　三、违约金的规定 　　有下列行为之一者，部门主管及大楼经理有权按情节轻重提出警告或并扣10元——200元不等的违约金。 　　1、迟到或早退。(详见第四节第三条)。', 511, NULL, '[\"奖励\", \"员工\", \"违约金\", \"给予\", \"张贴\", \"获得\", \"奖\", \"年度\", \"行为\", \"部门\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:26', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:26', '0');
INSERT INTO `document_segments` VALUES ('1955803414327554049', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　1、迟到或早退。(详见第四节第三条)。 　　2、服装、仪表、仪容、礼节礼貌不符合本守则的规定。 　　3、上班时间打私人电话聊天，不得使用公司电话拨打私人电话或收费台听取信息。 　　4、上班时间看与本职工作无关的书报，不得在办公区域内进食、吃零食、喝酒、抽烟嚼口香糖等。 　　5、上班时间未经主管同意私自外出逛街购物。 　　6、工作时间擅离本职岗位、串岗，上班后不到规定时间的岗位或扎堆聊天。 　　7、注意保持办公区域的卫生，不得随地吐痰，乱丢烟蒂、纸屑、杂物，不保持更衣柜内外及环境的整洁，在更衣柜内存放不应放的物品。 　　8、不爱护小区及办公区域内的一切公共设施，不得浪费公共物品，不得随意毁坏、涂抹，不得将公共设施及物品据为己有。 　　9、禁止高声喧哗、污言秽语、言语粗俗、骂人和进行骚扰客人的活动，不经同意擅自进入租户或业主单元内。 　　10、散步不利于团结的言论，发表有损公司声誉的言论。 　　11、对上级分派的工作无故迟缓拖延。 　　12、不经请求私自接待外人参观小区及所属区域。 　　13、在工作区域内(无论上下班)不得进行上网聊天、喝酒、聚赌、打牌、睡觉、下棋、玩电子游戏等。', 497, NULL, '[\"区域\", \"上班时间\", \"工作\", \"聊天\", \"办公\", \"物品\", \"喝酒\", \"同意\", \"不经\", \"保持\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:26', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:26', '0');
INSERT INTO `document_segments` VALUES ('1955803414377885697', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　13、在工作区域内(无论上下班)不得进行上网聊天、喝酒、聚赌、打牌、睡觉、下棋、玩电子游戏等。 　　14、对下属不管理、不批评，发现违纪行为不制止，不按规章惩罚处理。 　　15、工作时间打瞌睡，夜班当值睡觉。 　　16、工作时间没有按要求完成作业或完成任务。 　　有下列情况之一者，根据公司用人部门主管或经理批准，报公司行政管理中心人力资源部核准予以立即辞退，并不作任何补偿。 　　1、在试用期内证明不符合录用条件的。 　　2、符合《劳动合同书》中条款须辞退的。 　　3、严重违反劳动纪律或公司规章制度的。 　　4、因公司业务调整须减员的。 　　5、不能胜任工作的。 　　6、有偷窃租户、公司或他人财物的行为。 　　7、谩骂或袭击殴打租户、访客，工作态度恶劣。 　　8、上班时间酗酒、赌博。 　　9、侮辱、诽谤、殴打、恐吓、威胁、危害上级、同事或互相吵架斗殴。 　　10、卖淫或协助、唆使卖淫。 　　11、违反国家法律或治安条例的其他行为。 　　12、故意不服从上级指挥及合理指令，经多次警告无效。 　　13、故意损坏公物或利用工作之便贪污、挪用公款。监守自盗、收赂者。 　　14、擅自对外发表有关公司及所管小区的污蔑性言论。', 515, NULL, '[\"公司\", \"工作\", \"管理\", \"辞退\", \"上级\", \"须\", \"故意\", \"睡觉\", \"殴打\", \"行为\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:26', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:26', '0');
INSERT INTO `document_segments` VALUES ('1955803414424023041', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　14、擅自对外发表有关公司及所管小区的污蔑性言论。 　　15、有书写匿名诬告信的。 　　16、有严重损害公司及所管小区形象的行为，并造成后果的。 　　17、多次违反公司制定的规章、守则等行为，并经多次警告处罚仍不改过者。 　　18、一月中无故旷工三天以上的。 　　19、直接造成客户投诉三次，并经查实却系该员工责任的。 　　20、严重失职，营私舞弊，工作中出现责任事故，对公司造成重大损害的。 　　第八节 加班工资及其他形式的 　　工资的计算方法和公式 　　一、 加班工资计算方法： 　　1.5倍 平时加班 　　(额工资*70%)/22}*加班天数*}→ 2倍 本休加班 　　3倍 国定假加班 　　二、新进/离职(不足月)工资计算： 　　全额工资/22 * 当月实际工作天数 员工手册范本 篇24 　　第一章总则 　　第一条为了加强劳动管理、规范员工行为，提高员工整体素质，同时也为了使员工对本厂简况、工作要求、奖惩方法等规定的了解，在工作中能认真执行，以维护生产经营、工作、生活的正常秩序，保障员工的合法权益，特制订本手册。', 465, NULL, '[\"员工\", \"工作\", \"公司\", \"工资\", \"造成\", \"行为\", \"加班\", \"并经\", \"严重\", \"方法\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:26', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:26', '0');
INSERT INTO `document_segments` VALUES ('1955803414474354689', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　第二条制订本手册的指导思想：以生产经营为中心，坚持安全第一，预防为主的方针，把加强思想整治工作与必要的行整手段、经济手段结合起来，培养和造就一支有理想、有道德、有文化、有纪律的员工队伍，充分发挥他们的积极性和创造性，保证企业奋斗目标的实现。 　　第三条公司情况介绍(略) 　　第四条本手册仅适用本厂全体员工 　　第二章员工的权利和义务 　　第五条员工必须热爱祖国，自觉遵守国家的政策、法规、法令。 　　第六条员工必须有爱厂如爱家的意识，树立“我为公司，公司为我”的企业文化理念，关心和维护国家和企业的公共利益，忠于职守、快节奏、高质量地出色完成各项工作任务。 　　第七条员工必须努力学习整治，学习科学文化知识，不断提高整治、文化、技术、业务水平。 第八条员工必须遵守本厂制订的各项规章制度，对规章制度不同意见的建议，可以在执行制度的指令的前提下，向有关部门直至厂长提出。 　　第九条员工对企业工作的企业管理人员的工作有进行评议和提出批评、建议的权利，对管理人员的违法违章和失职行为有申诉、控告或检举的权利。 　　第十条员工可按本厂制度规定，享受劳动、工资、福利等各项权利的待遇。 　　第三章劳动合同', 501, NULL, '[\"员工\", \"企业\", \"必须\", \"权利\", \"文化\", \"工作\", \"整治\", \"本厂\", \"制度\", \"公司\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:26', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:26', '0');
INSERT INTO `document_segments` VALUES ('1955803414516297730', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　第十条员工可按本厂制度规定，享受劳动、工资、福利等各项权利的待遇。 　　第三章劳动合同 　　第十一条本厂实行劳动合同制度，凡本厂员工均应签订劳动合同。 　　第十二条劳动合同由厂长与员工本人签订，员工应仔细阅读和了解劳动合同文件内容，同意后方可签字。劳动合同一经签订产生法律效率。 　　第十三条新员工招聘，按招聘岗位的基本要求，坚持全面考核，择优采用，并执行3至6个月的试用期。试用期内发现不符合用工条件，可即时辞退。 　　第十四条员工要求辞退或企业解聘员工，除违规违纪、违法原因可即时辞退外，其余，均应提前一个月通知对方，并不折不扣地办好档案、财物、技术资料等的清理交接工作。 　　第十五条劳工合同期满，企业生产经营需要，员工本人同意，可以续签劳动合同。 　　第十六条家居外地员工，签订劳动合同时，应出具“身份证”，“外来员工务工”和“计划生育”证明。 　　第四章工作纪律 　　第十七条员工应自觉遵守劳动纪律，按时上下班，不准旷工、迟到、早退、工作时间不准擅离工作岗位和做与工作无关的事。 　　第十八条员工应无条件服从工作分配、调动的指挥。', 472, NULL, '[\"员工\", \"应\", \"工作\", \"劳动合同\", \"签订\", \"辞退\", \"同意\", \"即时\", \"要求\", \"企业\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:26', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:26', '0');
INSERT INTO `document_segments` VALUES ('1955803414625349633', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　第十八条员工应无条件服从工作分配、调动的指挥。 第十九条员工必须高度集中精力，认真负责地进行工作，把好工作质量关，节约原材料，爱护设备、工具等一切公共财物。 　　第二十条员工应自觉遵守文明生产、文明办公的制度规定，经常保持工作的环境的整洁，维护企业良好形象。 　　第二十一条员工应忠诚企业，保持本厂的技术、商务等机密。 　　第二十二条员工在对外营业窗口或其他对外交往中，应坚持热情礼貌的工作态度，接听电话用礼貌语：“您好，__公司”：客人来访时，笑脸向迎，请字在头，热情接待：客人辞行，以礼相送，须说“再见”，“欢迎再来”，“一路顺风”等：洽谈业务，说话和气，举止大方，处事慎重。 　　第五章考勤和请假制度 　　第二十三条上下班作息时间，根据生产经营实际需要和季节变换，由厂部作出决定，并发书面通知执行。 　　第二十四条考勤工作由各个部门自行负责进行。各部门负责人或负责人指定的考勤员，必须对考勤的正确性负责。 　　第二十五条考勤内容包括：出勤、病事假、迟到、早退、旷工、工伤、加班、公出等项目。', 450, NULL, '[\"工作\", \"员工\", \"应\", \"考勤\", \"客人\", \"负责\", \"保持\", \"制度\", \"生产\", \"进行\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:26', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:26', '0');
INSERT INTO `document_segments` VALUES ('1955803414667292674', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　第二十五条考勤内容包括：出勤、病事假、迟到、早退、旷工、工伤、加班、公出等项目。 　　第二十六条考勤记录表，由考勤员每天按时正点考勤，班中、班后考勤，并准确填好记录表，经部门负责人签字后，在次月二日前连同各种假条或有关证明，交财务作为核发资和扣罚款的考勤依据。 　　第二十七条员工因病、因事请假，必须先提出书面申请，经所在部门负责人审核批准(急病、急事可事后补办请假手续)，假期不发工资、午餐补贴。 　　第二十八条员工因工受伤，需要休息，必须由事故发生部门写出书面报告，经厂办公室审核，确定工伤性质和伤残程度，报请厂长同意签字后，方可按工伤有关规定处理。凡未按上规定办妥请假手续而不上班者，一概以旷工论处。 　　第六章工资福利 　　第二十九条员工工资按职务、职称、生产技能、业务水平，工作表现、贡献大小，由厂自行确定实施办法。实行计时工资(月薪制)的员工，工资多少在劳动合同中予以明确。实行计件工资(劳动分)的员工，工资多少按计件考核办法，与劳动效率或经济效益挂钩。 　　第三十条全厂的工资管理由厂办公室、财务部具体负责，每月依据个人和考勤实绩，由财务造册报厂长批准发放。公司的发工资日为次月五日。', 501, NULL, '[\"考勤\", \"员工\", \"工资\", \"工伤\", \"请假\", \"部门\", \"财务\", \"旷工\", \"厂\", \"确定\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:26', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:26', '0');
INSERT INTO `document_segments` VALUES ('1955803414713430018', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　第三十一条本厂将根据企业经济效益和个人实际表现。不定期地调整工资，工资水平坚持在企业经济发展的基础上逐步提高。 　　第三十二条本厂实行最低工资保障制度，最低工资的具体标准，按所在地整俯劳动部门规定执行。 　　第三十三条员工可离受每年七天法定有薪假日，元旦一天，春节三天，国际劳动节一天，国庆节二天。 　　第三十四条员工可享受午餐补贴，补贴以出勤天计发，每月与工资一起发放。 　　第三十五条本厂免费为员工提供宿舍，住宿员工必须遵守“员工宿舍管理规定”。 　　第三十六条本厂将随着经济发展，实力增强，在承受能力许可的前提下，逐步建立医疗保险制度，使员工在年老、患病、工伤、待业、生育情况下获得帮助和协助。 　　第七章培训 第三十七条所有员工需接受本厂整治和业务技术培训。 　　第三十八条凡经厂批准，受本厂指派赴厂外培训，进修的员工，占有的上班时间不计缺勤，取得合格证书后，学费给予报销。员工自行联系的培训、进修、不得占用工作时间，学费全部自负。 　　第三十九条经本厂培训的员工，如合同期未满，中途自动离职者，按员工培训后在本厂的工作年限，每年递减20%收回培训费(含工资、学费)。 　　第八章安全质量', 500, NULL, '[\"员工\", \"本厂\", \"培训\", \"工资\", \"学费\", \"规定\", \"受\", \"发展\", \"经济\", \"进修\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:26', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:26', '0');
INSERT INTO `document_segments` VALUES ('1955803414755373057', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　第八章安全质量 　　第四十条企业安全生产工作由厂长全面负责，对出现重大事故的部门，应根据情节和损失程度，严肃追究责任人和有关领导的责任，并予以必要的经济处罚或行整处分。 　　第四十一条员工在工作过程中，必须严格执行各项安全操作规程，爱护并正确使用劳动防护用品和安全灭火设施，不准违章指挥，不准违章作业。 　　第四十二条加强对易发事故的动火作业、起重作业、电线电器作业部位和工种的安全管理和安全教育，建立安全责任制度，开展定期的安全检查，发现事故苗头，必须立即查找原因并采取整改措施。 　　第四十三条加强现场生产全过程，包括作业准备过程，辅助生产过程的交付服务过程的产品质量管理。严格按工艺要求施工，发生产品质量事故，要坚持按照“四不放过”的原则(即事故原因不清不放过，事故责任不追责任未追究得理不放过，广大员工未得到教育不放过，防范整改措施未落实不放过)进行严肃处理。 　　第四十四条做好产品质量售后服务工作，建立货主要调查访问制度，对客户提出的意见，做到条条有着落，有答复、有整改、有记录。 第九章治安管理', 456, NULL, '[\"安全\", \"事故\", \"工作\", \"过程\", \"产品质量\", \"责任\", \"作业\", \"不放过\", \"生产\", \"原因\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:26', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:26', '0');
INSERT INTO `document_segments` VALUES ('1955803414805704705', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '第九章治安管理 　　第四十五条门卫值班应严守岗位，坚持夜间巡查，发现事故苗头或形迹可疑的人和事，应及时报告有关部门或厂部领导。 　　第四十六条加强财务现金、仓库和食堂物品、员工宿舍的.管理，切实做好安全防范工作。 　　第四十七条员工必须遵守国家法律法规，不准打架斗殴和辱骂他人：不准无理取闹，扰乱正常的工作和生活秩序：不准赌博;不准偷挪公物，损坏设备;不能偷挪他人财物或私拿拆他人信件、电报等邮件。 　　第十章卫生守则 　　第四十八条办公室、营业部、生产车间应做到布局合理。物品摆放整齐，地面洁净无杂物，通道无阻。 　　第四十九条禁止随地吐痰、乱扔果皮、烟蒂;禁止向水池内乱倒饭菜、茶叶、杂物;禁止在墙上和所有设备设施上乱写、乱画、乱涂、乱挂;禁止穿拖鞋，赤膊上班。 　　第五十条不准任意攀摘、损坏、挪用厂区周围的绿化带、花草、树木。 　　第五十一条各部门工作场所卫生，应由本部门员工负责包干，发现卫生包干区域内有不卫生、不整洁现象时，要立即清扫。 　　第十一章奖惩制度', 435, NULL, '[\"不准\", \"应\", \"禁止\", \"卫生\", \"工作\", \"员工\", \"部门\", \"乱\", \"物品\", \"杂物\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:26', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:26', '0');
INSERT INTO `document_segments` VALUES ('1955803414856036353', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　第十一章奖惩制度 　　第五十二条本厂对全体员工实行有功者奖，有过者罚，奖罚分明制度。奖励坚持精神鼓励和物质鼓励相结合的办法。对犯有过失的员工，坚持思想教育和处罚相结合的原则。 　　第五十三条对于有以下十个方面的有功员工，给予一次性奖励和经常奖励： 1、对本厂各方面工作能提出合理化有价值的意见建议，经审核评定，确能给企业生产经营，管理带来实际效益的，予以一次性奖励; 2、为本厂产品打开市场销路，对产品销售增长做出积极贡献的，予以一次性奖励; 　　3、为维护本厂利益，在对外经济活动中能一次性为公司节约资金3000元以上或换会经济损失5000元以上的，经核实却由此事后，予以一次性奖励; 4、提出并实施重大技术革新，经评定，确具有实用价值，能节约资金或提高效率的，予以一次性奖励。 　　5、为树立社会正气，企业形象，维护企业声誉，而身心受到伤害的，予以一次性奖励; 　　6、保护公共财产，防止或者抢救事故有功，使国家和本厂利益免受重损失的，予以一次性奖励; 　　7、对一贯忠于职守，积极负责，廉洁奉公，舍己为人，事迹突出的，予以一次性奖励;', 472, NULL, '[\"奖励\", \"一次性\", \"予以\", \"本厂\", \"员工\", \"企业\", \"有功\", \"维护\", \"评定\", \"确\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:26', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:26', '0');
INSERT INTO `document_segments` VALUES ('1955803414902173698', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　7、对一贯忠于职守，积极负责，廉洁奉公，舍己为人，事迹突出的，予以一次性奖励; 　　8、在完成生产任务或工作任务、提高产品质量或者服务质量方面，做出显著成绩的，予以一次性或经常性奖励; 员工手册范本 篇25 　　一、致公司全体员工 　　每次增添新人，我们都非常高兴。首先要祝贺我们的新员工，经过严格筛选，你们在激烈的竞争中脱颖而出，成为公司大家庭中的一员。公司董事会向你们表示热忱的欢迎，感谢你们选择了公司，感谢你们将自己的青春年华和为事业奉献的热望托付给了公司。 　　同时，感谢已经在公司工作的广大员工。你们中的许多人，为了公司的发展，兢兢业业，牺牲了很多个人的东西。正是由于众多公司人员的团结进取、忘我付出、艰苦拼搏，我们公司才有创业以来的由小到大、由弱到强，直至发展到今天这样的规模。正因为如此，公司每次在制定重大的发展战略时，每一位领导都非常审慎、凝重。因为我们都很清楚，员工选择我们公司，就是对公司的信任，就是把对生活、对事业和对人生理想的追求托付给了公司。公司只有不断发展，才能为我们广大员工提供一个施展才能、实现人生价值的舞台，才能让我们的员工找到自己理想的位置，获得应有的报酬、荣誉和尊严。', 505, NULL, '[\"公司\", \"员工\", \"发展\", \"理想\", \"予以\", \"一次性\", \"奖励\", \"感谢\", \"工作\", \"中的\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:26', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:26', '0');
INSERT INTO `document_segments` VALUES ('1955803414952505345', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　如果我们把企业比作一艘船，那么这艘船上承载的，就是员工的利益和追求;这艘船最根本的驱动力，就是我们的全体员工。从公司层面来讲，我们一直强调以人为本的管理理念，强调为员工的发展提供机会，创造舞台，并且已经开始着手建立一套科学公平的工作绩效评价体系。通过建立动力机制、激励机制、约束机制、保障机制和选择机制，达到人性化管理和理性化管理的完美结合。从另一个层面来讲，企业与员工的关系是相互依存的：没有全体员工的努力，企业就不可能持续发展;企业若不能持续发展，就不可能为员工提供发展的机会。我们将努力让企业进一步发展，让每一位员工都感到作为一个XX公司人的骄傲和自豪。同时，我们也要求公司的每一位员工都要时刻记住自己是一个XX公司人，你的一举一动，一言一行，都代表着公司的形象，你的每一件工作都直接关系着企业的盛衰存亡。每一个XX公司人都应该积极维护我们公司那种充满活力、健康向上、积极进取、富有使命感和责任感的企业形象。', 409, NULL, '[\"员工\", \"公司\", \"企业\", \"XX\", \"管理\", \"发展\", \"工作\", \"建立\", \"层面\", \"关系\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:26', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:26', '0');
INSERT INTO `document_segments` VALUES ('1955803415023808514', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　公司正在系统地进行经营变革，管理创新，重新整合我们的企业文化，每一位XX公司人都应当积极参与。只有参与才能更好理解，只有理解才能达致共识。公司的制度规范需要每个XX公司人自觉遵照执行。我们不能有任何违背公司利益(同样也是员工利益)的言行，这也是一种最基本的职业道德要求。我们大家都希望、也一定会看到，在全体员工的努力推动下，公司将一步步接近我们的目标，而公司的每一位员工，都会在公司这个朝气蓬勃、不断进取的现代化企业中，迅速成长! 　　过去的辉煌属于大家，美好的明天让我们共同去创造! 　　二、公司简介 　　XX公司的性质和行业属性。 　　公司产学研概况。 　　XX公司技术、销售概况。 　　XX公司扩大投资概况。 　　三、企业文化 　　企业宗旨： 　　企业理念： 　　管理理念： 　　经营理念： 　　质量理念： 　　发展理念： 　　企业吉祥物： 　　四、组织架构 　　略 　　五、员工行为准则 　　(一)基本准则 　　1、公司倡导“”的企业理念。 　　2、全体员工的一切工作行为，都须以“”为准则。 　　3、做每一件事、说每一句话之前，都应该先考虑一下是否符合我们企业的目标、宗旨和精神。', 497, NULL, '[\"公司\", \"企业\", \"员工\", \"XX\", \"理念\", \"文化\", \"目标\", \"经营\", \"概况\", \"管理\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:26', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:26', '0');
INSERT INTO `document_segments` VALUES ('1955803415111888897', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　3、做每一件事、说每一句话之前，都应该先考虑一下是否符合我们企业的目标、宗旨和精神。 　　4、每位公司员工都应该为公司的整体利益而进取和自律。 　　(二)职责权限 　　1、员工除本职日常工作外，未经公司法人代表授权或批准，不得从事下列活动： 　　(1)以公司名义考察、谈判、签约; 　　(2)以公司名义提供担保、证明; 　　(3)以公司名义对新闻媒介发表意见、消息; 　　(4)代表公司出席公众活动。 　　2、员工未获公司书面批准，不得在外兼任任何获取薪金的工作。 　　3、每位员工的工作必须对上级和下级负责，无下级的员工对手中的产品或服务负责。 　　4、员工可以在不与公司利益发生冲突的前提下，从事合法的投资活动。但禁止下列情形的个人投资： 　　(1)直接参与经营管理的; 　　(2)投资于公司的客户或商业竞争对手的; 　　(3)以职务之便向投资对象提供利益的; 　　(4)以直系亲属名义从事上述三项投资行为的。 　　(三)业务交往 　　1、员工在经营管理活动中，不准索取或者收受业务关联单位的酬金或回扣，否则将构成受贿。', 464, NULL, '[\"公司\", \"员工\", \"活动\", \"投资\", \"名义\", \"从事\", \"应该\", \"业务\", \"工作\", \"代表\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:26', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:26', '0');
INSERT INTO `document_segments` VALUES ('1955803415162220545', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　1、员工在经营管理活动中，不准索取或者收受业务关联单位的酬金或回扣，否则将构成受贿。 　　2、员工在与业务关联单位的交往中，应坚持合法、正当的职业道德准则，反对以贿赂及其他不道德的手段取得不正当利益。 　　3、员工不得挪用公款谋取个人利益或为他人谋取利益。 　　4、员工的直系亲属从事可能会与公司利益发生冲突的业务时，员工应向公司申报，并提出职务上的回避。 　　5、员工在对外业务联系活动中，业务关联单位按规定合法给予的回扣和佣金，应一律上缴公司作为营业外收入以冲抵成本。个人侵吞的，以贪污论处。 　　6、员工在公司以外的交际应酬活动，应本着礼貌大方、简朴务实的原则，不得铺张浪费。严禁涉及任何违法犯罪活动。 　　7、员工在与业务关联单位的联系过程中，对超出正常业务联系所需要的交际活动，尤其是涉及以下四点的，应谢绝参加： 　　(1)奢华的宴请及娱乐活动; 　　(2)具有赌博性质的活动; 　　(3)邀请方的目的明显是为了从我方取得不适当利益的活动;(4)违反国家法律和社会公德的活动。', 445, NULL, '[\"员工\", \"活动\", \"应\", \"公司\", \"业务\", \"利益\", \"中\", \"关联\", \"单位\", \"涉及\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:26', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:26', '0');
INSERT INTO `document_segments` VALUES ('1955803415204163586', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　(3)邀请方的目的明显是为了从我方取得不适当利益的活动;(4)违反国家法律和社会公德的活动。 　　8、所有员工都有义务保守公司的各种经营管理信息，务必妥善保管所持有的涉密文件及内部资料。机密文件和资料不得擅自复印，未经特许，不得带出公司。 　　9、员工未经公司授权或批准，不准对外提供标有密级的公司文件，以及其他未予公开的经营情况、业务数据及相关信息。 　　10、员工未经批准，不准将公司的资金、车辆、设备、房产、原材料、产品等擅自赠与、转让、出租、出借、抵押给其他公司、单位或者个人。 　　11、员工对因工作需要配发给个人使用的如交通工具、电子设备等，不准违反使用规定。 　　12、全体员工都有义务和权力对违反以上准则的行为向公司各级主管以至董事长投诉。 　　13、接受投诉的部门和员工，应当为投诉人严格保密，并及时做出处理和答复。 　　六、员工行为规范 　　共同行为 　　1、每位公司员工都有义务、有责任遵守此行为规范。 　　上班时间：由人力资源部和生产部根据生产经营需要制定的上班时间执行。 　　2、上班时，仪表以及衣着服饰应保持庄重、整洁、大方、得体。', 482, NULL, '[\"公司\", \"员工\", \"经营\", \"违反\", \"不准\", \"都有\", \"义务\", \"擅自\", \"文件\", \"信息\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:26', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:26', '0');
INSERT INTO `document_segments` VALUES ('1955803415258689537', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　2、上班时，仪表以及衣着服饰应保持庄重、整洁、大方、得体。 　　3、根据员工提供的个人资料统一制作工卡。员工在上班时间应佩戴工卡。 　　4、上班时间应坚守工作岗位，需暂时离开时应与同事交代;离开公司外出，应向主管说明。 　　5、请注意保持清洁、良好的工作环境，提高工作效率。不在工作区域进食或在非吸烟区吸烟，不高声喧哗。 　　6、使用电话应注意礼貌，语言要简明扼要。 　　礼貌待人 　　1、礼貌待人是对企业职工的基本要求。 　　2、尊重自己，尊重他人，团结互助，忠诚诚实，热情友好，说话亲切和蔼，举止稳重大方，处事礼貌谨慎。 　　3、在任何地方，碰到领导、同事、熟人都要主动打招呼，要诚恳;走路靠右边，遇见来客，要主动让路;遇见来客询问，要真诚接待，热情引导。 　　4、找领导、同事汇报、联系工作，应事前预约，轻声敲门，热情打招呼。 　　5、交谈中要尊重、耐心，眼睛看着对方，插话要在谈话间断时进行。讲话要诚恳，表述清晰，表达明确，语言精炼，使对方明明白白。不吞吞吐吐、词不达意。 　　6、工作或生活当中与人意见存在分歧时，尽量克制自己的情绪，尊重对方，摆事实讲道理。不武断，不争吵，不恶语伤人。 　　考勤与请假', 508, NULL, '[\"应\", \"工作\", \"尊重\", \"热情\", \"时\", \"同事\", \"礼貌\", \"大方\", \"诚恳\", \"打招呼\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:26', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:26', '0');
INSERT INTO `document_segments` VALUES ('1955803415300632577', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　考勤与请假 　　7、遵守公司的考勤制度，不迟到、不早退。如不能正常上班，需办理请假手续。 　　8、请假需填写请假单(请病假需附医院证明)，由部门主管签署意见，获得批准并安排好工作后，方可离开工作岗位。请假单应交人力资源部备案。 　　9、如因急事、急病或暂时无法通知单位的，应在事后及时补办请假手续。 　　建议与沟通 　　10、公司重视信息沟通，强调资源共享，提倡用沟通来促进管理，融洽关系，增进理解。 　　11、公司鼓励员工相互间积极公开的沟通交流，反对任何不负责任的私下传言和背后议论。 　　12、如果员工认为问题不能得到解决，可依次向所在部门直接上司直至公司领导投诉。公司设立董事长信箱，以接受员工的合理化建议和书面投诉。本着对当事人负责的精神，原则上不受理匿名信件。 　　13、作为公司的一员，员工有义务和责任主动向公司提出有关业务、生产、管理工作的意见和建议。 　　14、请经常留意公告栏上的信息。未经批准，禁止擅自张贴或更改公告栏上的通告。 　　奖励和处分 　　15、公司积极提倡热爱公司的行为，并将对以下行为予以奖励： 　　(1)为公司创造显著经济效益的; 　　(2)为公司挽回重大经济损失的;', 505, NULL, '[\"公司\", \"员工\", \"建议\", \"请假\", \"批准\", \"部门\", \"意见\", \"请假单\", \"需\", \"提倡\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:26', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:26', '0');
INSERT INTO `document_segments` VALUES ('1955803415346769921', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　(1)为公司创造显著经济效益的; 　　(2)为公司挽回重大经济损失的; 　　(3)为公司取得重大社会荣誉的; 　　(4)为公司改进管理取得显著成效的; 　　(5)建议得到公司重视并有直接或间接效益的。 　　16、奖励分为年度特别奖和不定期奖，奖励方式为授予荣誉称号、颁发奖状和奖金等。年度特别奖包括： 　　(1)董事长特别奖; 　　(2)管理成就奖; 　　(3)科技创新奖; 　　(4)敬业精神奖; 　　(5)合理化建议奖。 　　17、有下列过失行为之一者，公司将视情节轻重、后果大小、认识态度等的不同，给予不同的处分或经济处罚。 　　A、严重过失： 　　(1)盗窃公司财物，滥用或蓄意破坏公司财产; 　　(2)违反公司规定屡教不改; 　　(3)玩忽职守造成事故使公司蒙受较大的经济损失; 　　(4)涂改帐单，伪造帐目欺骗公司; 　　(5)利用工作职权，收受他人金钱或实物，造成恶劣影响或损害公司利益; 　　(6)严重违法乱纪受刑事处分; 　　(7)蓄意煽动员工闹事或怠工; 　　(8)盗窃同事财物; 　　(9)在公司内从事破坏活动、窥探公司业务秘密或泄漏任何不利于公司的机密消息。 　　B、重大过失：', 503, NULL, '[\"公司\", \"奖\", \"受\", \"特别奖\", \"管理\", \"蓄意\", \"严重\", \"造成\", \"过失\", \"盗窃\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:26', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:26', '0');
INSERT INTO `document_segments` VALUES ('1955803415388712961', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　(9)在公司内从事破坏活动、窥探公司业务秘密或泄漏任何不利于公司的机密消息。 　　B、重大过失： 　　(1)未经公司许可，在外从事兼职工作; 　　(2)工作轻率或疏忽，导致严重损害员工身心健康和工作积极性; 　　(3)故意填报不正确的个人资料; 　　(4)在工作时间内睡觉或从事私人工作; 　　(5)不服从上司的命令或拒绝接受工作调派; 　　(6)涂改请假单，呈交伪造的医院证明书或其他证明文件欺骗公司。 　　C、一般过失： 　　(1)无故迟到、缺勤、旷工、早退; 　　(2)在工作时间内或当班时醉酒或行为不检，例如嬉戏，互相追逐或喧哗吵闹; 　　(3)在非吸烟区内吸烟，随地吐痰; 　　(4)对上司或同事作出不礼貌之举动; 　　(5)不向人力资源部报告有关个人资料的变动。 　　18、对三种过失，除追究经济损失外，将按照情节轻重做如下处理： 　　严重过失：开除或交公安机关处理 　　重大过失：初犯——通报批评、书面检讨 　　再犯——开除或辞退 　　一般过失：初犯——口头警告 　　再犯——通报批评、书面检讨 　　三犯——开除或辞退', 468, NULL, '[\"工作\", \"过失\", \"公司\", \"从事\", \"个人资料\", \"上司\", \"重大过失\", \"严重\", \"时间\", \"开除\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:26', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:26', '0');
INSERT INTO `document_segments` VALUES ('1955803415455821825', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　一般过失：初犯——口头警告 　　再犯——通报批评、书面检讨 　　三犯——开除或辞退 　　19、部门负责人在处理员工过失时，要本着实事求是、治病救人的原则，与当事员工一起分析过失的原因，并提出今后改正的方法。 　　20、部门负责人在处分犯有过失的员工时，要作深入细致的调查研究，提出一份精简、准确的事实报告，由其上一级部门主管签署处理意见。该报告的正本由人力资源部备案，副本由当事者本人保存。 　　21、对违纪现象的检查和处理，由人力资源部按公司制定的规章制度予以实施;如有异议，由审计督查委员会复议确定。 　　22、每一位员工，除必须遵守此行为规范外，还必须遵守企业制定的其它各项规章制度。 　　七、部门主管以上员工行为规范 　　基本准则 　　1、部门主管以上员工对企业生产经营负有更大的责任，每一项职务行为和经营决策都将直接影响到上级、下级及企业整体，因此必须严格遵守法律法规和公司章程，忠实履行职责，对公司负责、对员工负责、对社会负责。 　　2、各级主管应模范执行员工行为准则和行为规范，遵守社会公德，做到廉洁、公平、进取。言行与职务相一致，为员工树立良好的榜样。', 486, NULL, '[\"员工\", \"部门\", \"过失\", \"遵守\", \"企业\", \"主管\", \"人力资源部\", \"必须\", \"提出\", \"处理\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:26', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:26', '0');
INSERT INTO `document_segments` VALUES ('1955803415501959169', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　3、各级主管不仅在任职期间，而且在与公司约定的辞职后一定时间、范围内，都不得利用任职期间所取得的公司资源和客户资料，自营或为他人经营对原任职企业构成直接竞争的业务。 　　经营管理 　　4、各级主管必须坚持依法经营，就本企业资产的完整与安全对公司全面负责。 　　5、各级主管必须贯彻公司及其直接上级制定的经营方针，准确反映经营管理情况，及时提供数据报表，确保完成公司下达的各项经营任务。 　　6、各级主管理解和执行上级职能部门的指示时，如认为该指示有明显不当，有责任及时指出，并提出自己的建议;如建议未获采纳而执行上级指示最终造成损失时，责任由其作出指示的上级承担。 　　财务及考核管理 　　7、各级主管必须亲自指导和监督涉及自身工作范围中的财务及考核事宜，并在其职权范围内对本企业财务经营成果和考核状况全面负责。 　　8、各级主管必须遵守财经法规，遵从考核制度，完善本企业财务管理，提升考核体系。 　　9、各级主管应将本企业所有财务活动置于公司财务部及直接上级的监督之下。禁止回避监督，私设帐外帐、小金库;禁止向公司外机构或个人出借资金、提供担保、抵押或者其他财务承诺。', 487, NULL, '[\"公司\", \"经营\", \"主管\", \"上级\", \"财务\", \"管理\", \"考核\", \"必须\", \"企业\", \"直接\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:26', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:26', '0');
INSERT INTO `document_segments` VALUES ('1955803415585845250', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　10、各级主管不得私自利用公款进行股票投资或其它未经董事长批准的金融活动。 　　人事管理 　　11、企业根据经营管理的需要，制定人事政策，决定对职员的录用、晋升和奖惩。 　　12、各级主管对其下属员工负有指导培训、考核监督以及准确评价的责任。 　　13、各级主管应秉公处理各项人事调整，不得基于任何私人目的来处理下属员工的录用、晋升、奖惩等事项。 　　监督监察 　　14、各级主管的一切职务行为，都必须接受公司的监督。 　　15、各级主管应主动接受公司各职能部门及其直接上级在职权范围内进行的监督检查。 　　16、各级主管遇到下列情形之一时，应迅速向其直接上级和公司企管办乃至董事长报告。 　　(1)员工人身遭受严重伤害，或者被司法机关拘传、拘留、逮捕、收审或者采取其他刑事强制措施的; 　　(2)企业财产遭受较大损失的; 　　(3)企业被政府部门批评、处罚以及采取其他不利措施的; 　　(4)企业被传媒曝光或者出现其他严重公关危机的; 　　(5)发生或者可能发生严重劳动纠纷的; 　　(6)其他经营活动中发生的重大意外事件。', 465, NULL, '[\"主管\", \"企业\", \"监督\", \"严重\", \"员工\", \"应\", \"活动\", \"董事长\", \"人事\", \"遭受\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:26', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:26', '0');
INSERT INTO `document_segments` VALUES ('1955803415627788289', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　(5)发生或者可能发生严重劳动纠纷的; 　　(6)其他经营活动中发生的重大意外事件。 　　17、各级主管的行为规范执行情况，受全体公司员工的监督。全体员工也都有权利和义务向各级主管当面提出或向上级部门反映责任人违反制度规范的错误行为。 　　八、培训考核发展 　　培训与发展 　　1、公司以向全体员工提供理想之终身职业为己任。在公司工作的员工，除以勤奋的工作获得薪酬及其它福利以外，还可以享有相应的培训及晋升的机会。 　　2、公司将适时地为员工提供培训机会，通过一系列与工作实际相结合的培训，来协助员工规划未来的发展。 　　3、新员工入职培训 　　为尽快熟悉环境、开展业务，新加入公司的员工必须履行入职手续。通过入职手续了解公司概况、经营理念、管理模式、XX公司人应有的职业道德、社会责任感以及其他内容。 　　4、在职培训 　　在工作过程中，为使员工具备完成工作所需的知识、技能、态度，公司将开展一系列的培训课程。 　　5、晋级培训 　　员工在晋升为上一级职务之前，需要参加晋级培训，学习企业管理的基础知识，以转换角色，担当起管理责任。 　　6、专项短期培训', 480, NULL, '[\"培训\", \"员工\", \"公司\", \"工作\", \"主管\", \"经营\", \"中\", \"晋升\", \"发展\", \"职\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:26', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:26', '0');
INSERT INTO `document_segments` VALUES ('1955803415678119938', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　6、专项短期培训 　　为使中高层管理人员开拓思维，进一步提高管理水平，同时也为了加强企业内外交流，公司将在适当的时机，选送中高级管理人员到有关专门机构、企业选择专业课程进行短期培训。 　　7、业务培训 　　(1)公司除安排各级主管参加各类培训外，还将不定期地为各业务岗位的员工安排相关专业的业务培训。 　　(2)公司会在不同范围内组织交流，具体形式包括实地考察、专题研讨等，以便将成果提炼推广，实现资源共享。 　　8、专题讲座 　　公司将在不同时期根据不同业务的发展需求，邀请公司内外的专业人士就业务、管理的最新动态以及研究成果举行专题讲座，以不断吸收新的知识、提高自身的综合管理及业务水平。 　　双向交流 　　9、为增强工作实感，公司的管理人员有可能被指定到一线生产岗位去学习锻炼1—2个月。 　　10、生产岗位负责人员，也有可能被指定到公司相应职能部门工作1一2个月，以便总结提炼丰富的实际操作经验，以利于在公司范围内形成广泛交流，同时进一步系统了解公司的整体运作。 　　进修', 442, NULL, '[\"公司\", \"交流\", \"管理人员\", \"业务\", \"提炼\", \"管理\", \"岗位\", \"不同\", \"企业\", \"专题讲座\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:26', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:26', '0');
INSERT INTO `document_segments` VALUES ('1955803415728451586', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　进修 　　11、公司除举办各种培训班来提高员工素质外，在有利于工作的前提下，鼓励员工到大专院校或专业培训单位进修学习与本职工作相关的专业，形式包括脱产进修和业余进修等。 　　12、参加各类形式的学习后，将结业(毕业)证、成绩单及学籍档案材料报公司人力资源部备案，并作为调配、选拔及任免的参考依据。 　　13、脱产进修的申请条件：在公司服务满两年以上。 　　14、脱产进修的审批程序： 　　(1)个人提出书面申请; 　　(2)由所在部门负责人根据申请内容和工作需求签署意见，公司人力资源部审核学习内容，签署意见后，报董事长审批; 　　(3)获得批准后与公司签署进修协议。 　　15、脱产进修获批准后的有关待遇： 　　(1)保留职务，逾期不归，视为自动离职; 　　(2)进修期间的薪资及福利待遇，按照《进修协议》执行; 　　(3)脱产进修半年以上，进修期间原则上不予晋升职务和调整薪金; 　　(4)在进修结束后，凭结业(毕业)证，学习内容和学习成绩报人力资源部审核，报董事长审批，学员可根据学习成绩领取一定的进修资助。 　　16、业余进修(包括攻读学位、上岗培训、职称及其他资格证书考试、培训等)申报程序：', 503, NULL, '[\"进修\", \"公司\", \"脱产\", \"学习\", \"审批\", \"报\", \"申请\", \"职务\", \"工作\", \"人力资源部\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:26', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:26', '0');
INSERT INTO `document_segments` VALUES ('1955803415774588929', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　16、业余进修(包括攻读学位、上岗培训、职称及其他资格证书考试、培训等)申报程序： 　　(1)个人提出书面申请; 　　(2)由所在部门负责人根据申请内容和工作需求签署意见，由公司人力资源部审核学习或培训内容，报董事长审批。获得批准后，与公司签署进修协议。 　　17、业余进修获批准后的有关待遇：在进修结束后凭结业(毕业)证、资格证书等，经公司人力资源部审核其学习成绩后，经董事长批准，可报销一定的进修费用。 　　考核评价 　　18、为帮助员工总结个人工作得失，明确未来工作目标和工作要求，有针对性地进行改进和提高，公司人力资源部每年将根据公司的目标和任务，对各部门的负责人和员工进行考核。员工的工作表现将被鉴定为优秀、良好、称职、基本称职、不称职五个等级。 　　19、考核结果将与薪酬和职务升迁机会等相结合，并与年终奖金挂钩。凡被评为“基本称职”及以下等级者将失去加薪、晋升和评奖机会，并将被要求参加岗位培训或进行岗位调整;经培训或进行岗位调整后仍连续两次被评为“不称职”者将有可能被公司辞退或要求下岗。 　　内部调动', 461, NULL, '[\"公司\", \"工作\", \"培训\", \"进修\", \"要求\", \"考核\", \"进行\", \"人力资源部\", \"批准\", \"机会\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:26', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:26', '0');
INSERT INTO `document_segments` VALUES ('1955803415824920578', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　内部调动 　　20、工作调动将有利于发挥员工的潜质，如有需要，公司将可能根据员工能力和工作表现，调至公司内合适的部门及岗位工作。 　　21、公司内部调动是一种组织行为，必须经过正式批准正当手续。任何私人之间进行协议调动都是不允许的，违者将作自动离职处理。晋升机制 　　22、公司鼓励员工敬业、协同、创新，并为工作敬业、进取创新、业绩出色、能力出众的员工提供晋升和发展的机会。 　　23、如果员工在工作期间连续两年年度考核结果在“良好”以上或三年考核结果在“称职”以上，将有机会获得晋升，薪酬亦会相应增加。 　　九、入公司指引 　　报到程序 　　1、接到录用通知后，应在指定日期到录用部门报到。报到程序包括： 　　(1)到人力资源部办理报到登记手续，领取考勤卡、工作用品和资料等; 　　(2)与部门负责人见面，接受工作安排。 　　2、加入公司时，员工须向公司人力资源部提供身份证、相关学历证明原件和免冠近照，特殊工种同时出具相关上岗证，并亲笔填报准确的个人资料。 　　3、当个人资料有以下更改或补充时，应及时通知人力资源部，以确保与你有关的各项权益： 　　(1)姓名; 　　(2)家庭地址和电话号码; 　　(3)婚姻状况;', 512, NULL, '[\"公司\", \"工作\", \"员工\", \"人力资源部\", \"晋升\", \"调动\", \"部门\", \"报到\", \"通知\", \"相关\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:26', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:26', '0');
INSERT INTO `document_segments` VALUES ('1955803415887835137', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　(1)姓名; 　　(2)家庭地址和电话号码; 　　(3)婚姻状况; 　　(4)出现事故或紧急情况时的联系人; 　　(5)培训结业或进修毕业。 　　4、公司保留审查你所提供的个人资料的权利。如有虚假，一经核实，公司保留开除的权力。 　　员工体检 　　5、凡被聘的员工，须经公司指定的医院进行体检。公司定期或不定期安排员工体检，遵循职业病防治规范。对因病无法胜任岗位者，公司有权视其病情劝其停职治疗或调换工作岗位。 　　试用与转正 　　6、试用期根据劳动合同签订期限为依据。试用开始时，人力资源部和所在部门主管有责任介绍本部门职能、人员情况，讲解本职工作内容和要求，帮助新进员工了解公司有关规章和规范。任何有关工作的具体事务，如确定具体工作岗位、领取工作用品、使用工作设备、用餐等等，尽可咨询本部门负责人。 　　7、如在试用期内请假，试用期结束时间将会被顺延;原则上请假时间不得超过一周。如超假则作自动离职处理。 　　8、在此期间，如果感到公司实际状况、发展机会与预期有较大差距，或由于其它原因而决定离开，可提出辞职申请，并按规定办理辞职手续。相应的，如果试用期员工工作表现无法达到要求，公司也将会终止试用，解除劳动合同。', 511, NULL, '[\"公司\", \"员工\", \"试用期\", \"工作\", \"部门\", \"试用\", \"时\", \"体检\", \"要求\", \"工作岗位\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:26', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:26', '0');
INSERT INTO `document_segments` VALUES ('1955803415933972481', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　9、试用期满后由所在部门负责人出具是否录用的意见，报人力资源部备案。 　　全员劳动合同制 　　10、为确立公司与员工的劳动关系，明确双方的权利与义务，公司实施全员劳动合同制管理。 　　薪 金 　　11、员工薪金由基本工资、考核工资、补贴等。 　　12、公司将根据员工工作经验和工作能力确定工作岗位，并按工作岗位确定薪金级别。 　　13、具体标准按公司《工资管理办法》精神执行。 　　福 利 　　14、公司将按照员工实际情况，安排住宿。 　　15、休息日 　　休息日按各部门工作需要进行安排。 　　16、其它假期(婚假、丧假、病假、事假) 　　(1)公司正式员工，可凭结婚证书向直属部门负责人请婚假，经人力资源部核实，可享有三天有薪婚假，按X元/天计算。 　　(2)员工领取结婚证后，须于半年内申请有薪婚假，否则会丧失享有该假期的权力。 　　(3)丧假需本人直系亲属(指配偶、父母、配偶父母、子女、兄弟姐妹)去世，公司给予三天有薪丧假，按X元/天计算。 　　(4)其它假期需经部门主管同意核准后，人力资源部保留核查的权力。 　　17、宿舍与饭堂管理 　　员工享有公司提供的宿舍和用膳，但必须遵守《宿舍管理规定》和《食堂管理规定》。', 516, NULL, '[\"公司\", \"员工\", \"部门\", \"薪\", \"婚假\", \"人力资源部\", \"管理\", \"丧假\", \"假期\", \"享有\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:26', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:26', '0');
INSERT INTO `document_segments` VALUES ('1955803415980109825', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　员工享有公司提供的宿舍和用膳，但必须遵守《宿舍管理规定》和《食堂管理规定》。 　　18、伤残 　　(1)凡因工受伤，公司将参照国家有关规定办理。 　　(2)员工因工受伤应立即送往公司指定的医院治疗，同时填写《工伤事故报告表》报企管办。 　　(3)员工患非职业病或非因工负伤，医疗期不能从事原工作、也不可改调其它部门工作的，将被解除劳动合同。 　　19、公司员工有机会参加公司为全体员工举办各类活动。 　　辞职与辞退 　　20、公司按劳动合同规定办理辞职与辞退手续。 　　21、辞职获批准或收到辞退通知后，当事人应到公司人力资源部领取《员工离(辞)职申请表》，办理离职手续。 　　(1)办理工作交接手续，归还公司有关资料、文件、工作用品及其它公物; 　　(2)退还所借公司公款; 　　(3)退还公司宿舍及房内公物，向企管办办理退房手续; 　　(4)如工作期限未满合同规定，则须按合同规定缴纳有关费用，如培训费用等。 　　22、从公司离职后，若重新进入公司工作，工龄将从最后一次进入公司时起计。 　　23、员工离职前，公司人力资源部可安排面谈。 　　24、各级主管或重要岗位管理人员离职时，公司将安排离职审计。', 505, NULL, '[\"公司\", \"员工\", \"工作\", \"离职\", \"办理\", \"手续\", \"工\", \"规定\", \"宿舍\", \"企管\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:26', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:26', '0');
INSERT INTO `document_segments` VALUES ('1955803416068190210', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　24、各级主管或重要岗位管理人员离职时，公司将安排离职审计。 　　本手册由人力资源部负责解释，并按照实际情况进行补充修订。 　　XX公司 　　XX年X月 员工手册范本 篇26 　　水果店员工守则3 　　一、每天早上提前二十五分钟正常开门营业。 　　二、开门时，必须经理或主管、当值日人员至少二人以上在场方可开门。 　　(衣服整洁、严禁披头散发、留海须齐眉毛，严禁穿高跟鞋、拖鞋、短裤、裙子)，(违反规定给以经济处罚10元)，必须提前做好营业时的准备，到岗位后应认真、迅速的上货、擦货，拉架，保证商品货架的整齐，干净卫生和货架的丰满，(违反规定给以经济处罚5—50元)。 　　三、上班时间必须站立规范，严禁坐、手插口袋、抱肩、靠货架，(违反规定给以经济处罚10元)，严禁在营业场内吃东西，嚼口香糖、哼歌、吸烟、聚堆聊天、嘻笑打闹、看书看报，(违反规定给以经济处罚5—50元)。', 389, NULL, '[\"严禁\", \"违反规定\", \"时\", \"营业\", \"给以\", \"经济\", \"必须\", \"开门\", \"货架\", \"处罚\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:26', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:26', '0');
INSERT INTO `document_segments` VALUES ('1955803416114327553', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　四、文明用语、热情为顾客服务，不准与顾客顶嘴、吵架、不得以貌取人，(违反规定给以经济处罚5—50元)。如遇顾客来店退换货、质量问题或其它税费部门来店，热情告之对方稍等，立即通知主管，若主管不在，可电话联系，不允许不报告主管或经理擅自处理来店顾客退换货或质量问题等事情。(违反规定给以经济处罚50元/次)。 　　五、严禁私自倒班，若确需要倒班者应提前给经理或主管说明原因，以便及时安排、调整.请事假者，应提前一天递交假条，主管批准后，方可休假。请假一天(35元/天)，加班一天(35元/天加提成)，旷工(50元/天)。 　　六、各街区员工要及时在各管辖区内巡视，及时拉架并为顾客导购，同时应提防盗窃行为，保证商品安全。 　　七、凡遇供货商来货(或进货)，必须先核查售价、进价再订价，方可标价，再上架，如若不按规定标价谁标错价由谁补齐标错差价。过期商品及被损商品要及时下架，如不及时下架而给超市造成损失者，由区域负责理货员承担一切责任。', 418, NULL, '[\"顾客\", \"及时\", \"主管\", \"应\", \"商品\", \"店\", \"方可\", \"遇\", \"经理\", \"提前\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:26', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:26', '0');
INSERT INTO `document_segments` VALUES ('1955803416160464898', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　八、服装、鞋柜组销售严禁。内部营业员收顾客钱单独到收银台为顾客交钱。必须带实物商品协助顾客到收银台交款。(营业员违反规定给以10元/次经济处罚，收银员违反规定给以1元/次经济处罚，严重不按规定，按当次收顾客实际钱数处罚) 　　九、上班时间员工不得购物，早班员工须在下班时间购物，晚班员工必须在下班前五分钟购物，若未吃(用)完者，必须与当日下班时间带离超市。带离超市必须让主管查看实物和电脑小票才可下班离开超市，(违反规定给以经济处罚10元/次)。 　　十、上班期间，不得干与工作无关事情.不准携带手机，携带手机必须关机(违反规定给以经济处罚5-50元;如：接、打手机处以50元/次;私会亲朋友处以5元/次;等等)。 　　十一、每天上班前10分钟要签到，迟到五分钟处罚5元，迟到半小时扣除当天工资并参加当日工作，如不参加工作者视为旷工计算(50元/天)。 　　十二、全体员工偷、吃、用行为一经发现，给以此商品十倍经济处罚，情节严重者，追究其法律责任.上班期间卖错商品价钱，谁出错由谁补齐卖错差价，少收卖出商品钱数，谁出错由谁补齐少收钱数，可按店内规定最低价补齐。', 482, NULL, '[\"处罚\", \"必须\", \"商品\", \"经济\", \"上班\", \"员工\", \"顾客\", \"收\", \"违反规定\", \"钱\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:26', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:26', '0');
INSERT INTO `document_segments` VALUES ('1955803416202407937', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　十三、损坏任何设施(打价枪、条码称、等等)、任何商品照价赔偿。 　　十四、各早班营业员每天上班必须各自负责区域货架地面及门外玻璃、门外地面清扫一遍，各营业员下班后必须把各自负责区域商品整理整齐，门内外清扫干净并进行卫生签到才可签到下班，(违反规定给以经济处罚10元/次) 　　十五、在工作方面全体员工必须无条件服从主管的一切安排管理;在纪律方面严格遵守规章制度(初次进行提醒，严重批评警告，展教不改报之经理签单处罚)。 员工手册范本 篇27 　　第一章 酒店简介', 233, NULL, '[\"必须\", \"商品\", \"方面\", \"员工\", \"处罚\", \"进行\", \"清扫\", \"下班\", \"营业员\", \"区域\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:26', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:26', '0');
INSERT INTO `document_segments` VALUES ('1955803416248545282', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '员工手册范本 篇27 　　第一章 酒店简介 　　成都嘉云置业有限公司某某酒店是由四川某某集团按照四星级标准倾力打造的豪华主题酒店。酒店位于郫县西大街309号，地处城市商贸黄金地段，交通便捷，距离成都双流国际机场和成都市中心为30分钟和45分钟。酒店客房有“欧式、地中海、东南亚”三种风格，共有豪华舒适套房、标准、单间110间，环境幽雅，设施豪华，为八方宾客提供温馨、舒适的商务、旅行环境。酒店还配有简洁雅致的茶坊，大厅可容纳40人，配有专属贵宾茶室5间，麻将室11间，可提供品茗、咖啡、棋牌服务，典雅、个性化的休闲空间是娱乐、商务洽谈、私人聚会的完美场所。某某酒店全体管理人员及服务人员本着“以客为尊、礼行天下”的服务宗旨，热忱欢迎广大宾客莅临。 　　第二章 组织机构图 　　成都嘉云置业有限公司某某酒店实行总经理负责制，实行从上至下垂直管理模式。现主要由：总经理、副总经理、财务部、综合管理部、销售部、前厅部、客房部、茶餐部、保卫工程部组成。 　　某某酒店组织机构图 　　董事长 总经理 财 务 营销副总 副总经理 行政综管部 出 纳 销售部 客房部 工程物管部 前厅部 采 购 茶餐部 厨 房 　　第三章 企业文化 　　企业宗旨：诚信立业 回报社会务实严谨', 530, NULL, '[\"酒店\", \"豪华\", \"服务\", \"总经理\", \"间\", \"副总经理\", \"环境\", \"舒适\", \"宾客\", \"提供\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:26', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:26', '0');
INSERT INTO `document_segments` VALUES ('1955803416311459842', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '纳 销售部 客房部 工程物管部 前厅部 采 购 茶餐部 厨 房 　　第三章 企业文化 　　企业宗旨：诚信立业 回报社会务实严谨 开拓创新 共同发展 同创辉煌 　　服务理念：“以客为尊、礼行天下” 　　用人原则：“能者上、庸者下” 　　第四章 劳动管理 　　一、 招聘 　　1、某某酒店实行公开招聘，自愿报名，择优录取。具有高中以上(含高中)文化程度，有一定专业知识，身体健康、五官端正的求职者，符合某某酒店招聘与录用标准的，经过严格的审查和业务考核，均可于相应岗位受聘或录用; 　　2、员工招聘事宜由某某酒店综管部统一负责. 　　二、 入职 　　1、员工录用采取逐层审核：一般员工由相关部门负责人及综管部审核;主管及以上人员由总经理审核。凡被某某酒店录用的员工，应当真实地填写《员工登记表》; 　　2、新员工一经录用，需按要求办理入职手续，并领取工装等工作物品; 3、某某酒店提供工作服给员工使用，但是在聘用期间若人为造成服装毁损的，员工应予以赔偿，希望员工对某某酒店财物认真爱惜;', 441, NULL, '[\"员工\", \"酒店\", \"录用\", \"招聘\", \"管部\", \"文化\", \"职\", \"审核\", \"综\", \"高中\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:26', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:26', '0');
INSERT INTO `document_segments` VALUES ('1955803416378568705', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　4、新员工入职后，应按规定向某某酒店综管部提交区级以上疾控中心出据的本人“健康证”;财务会计人员应提供“会计证”、“会计电算化证”等证明文件，以及职能部门规定的其它相关证件。 　　三、试用期 　　1、员工经培训合格后上岗，并在规定时间内办理入职手续。 　　2、员工需经过一至三个月试用期，三个月(试用期)后经考核确定转正或辞退。对工作表现优秀的人员，经总经理同意，可缩短试用期。 　　3、在试用期内，双方均可以书面形式提前7天通知对方终止劳动关系。 　　四、工作期 　　1、某某酒店按国家有关规定与员工签订劳动合同。劳动合同的签订应遵循合法、公平、平等自愿、协商一致、诚实信用的原则。员工不得以失实、蒙骗、隐瞒等手段与某某酒店签订劳动合同，否则其所签订的劳动合同无效，并由当事人承担相应的法律责任; 　　2、新员工入职后在劳动合同签订的试用期内，必须参加酒店入职培训及考核，培训期限原则上不超过三个月 ;', 404, NULL, '[\"员工\", \"试用期\", \"规定\", \"酒店\", \"职\", \"应\", \"签订\", \"劳动合同\", \"工作\", \"人员\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:26', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:26', '0');
INSERT INTO `document_segments` VALUES ('1955803416428900354', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '; 　　3、新员工培训期满，酒店以书面形式进行综合考核。考核合格者，经综合部门审核和总经理审批，方可转为酒店正式员工;考核不合格者，或者经过再次培训，在试用期内进行第二次考核，合格者办理转正手续;或者直接解除劳动合同; 　　4、新员工在试用期内至少工作一个月以上、综合表现优异者，考核合格，经某某酒店综管部审核并报请公司领导审批通过后，可酌情缩短试用期; 　　5、酒店有权根据工作需要和员工的专长、工作能力及表现，调整员工的工作岗位;所有在店工作的员工应无条件服从工作安排，不得以任何理由、任何方式不服从安排。 五、工作安排 　　1、酒店所有工作岗位和工种，均按工作需要进行安排，员工必须服从; 2、为有利于酒店的长远发展，对于有潜力的员工，酒店将着力培养，酒店会对有进取心、工作能力强及表现良好的员工适时地采取职务调整、岗位调动等方式进行培养，以实现人力资源优化配置。 六、晋升 　　1、酒店的基本政策，是尽可能从内部提拔合适的人选，所有员工均有升职的机会。升职考察的主要依据是员工在岗的工作能力和职业道德状况。升职与否还须视职位是否空缺而定;', 473, NULL, '[\"员工\", \"酒店\", \"工作\", \"进行\", \"考核\", \"试用期\", \"表现\", \"能力\", \"合格\", \"职\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:26', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:26', '0');
INSERT INTO `document_segments` VALUES ('1955803416475037697', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　2、管理人员的任免、晋降职应在已核定的部门管理人员编制数额内进行。部门管理人员的任免由运营经理提出申请，经总经理审批后实施; 　　3、新晋职人员均有一个月至三个月的见习期。见习期结束后，须经用人部门负责人提出书面考核意见，上报经总经理核准后转正。 七、解除劳动合同(离职) 　　1、员工工作期间，如遇酒店因经营状况发生变化或因裁减工作岗位而必须解除与员工的劳务关系，酒店将以《员工辞退表》的形式提前七天通知被辞退员工; 　　2、试用期内，酒店和试用员工都有选择对方的权利，应提前七天向对方提出解除试用合同。 　　3、对于不服从工作安排、严重违反劳动纪律和规章制度、严重失职、营私舞弊给酒店造成重大损失、被依法追究刑事责任者等，酒店将以《员工辞退表》的形式立即对其予以辞退。表上将注明辞退时间及理由; 　　4、员工单方面要求离职的，应提前30天(试用期员工应提前7天)以书面形式向酒店提出离职申请，并按规定办理离职手续;如未按规定办理离职手续，提前离岗而给酒店造成损失，员工应给予酒店相当于本人七天工资的现金赔偿，并按矿工处理。 　　5、员工离职流程', 476, NULL, '[\"员工\", \"酒店\", \"提出\", \"离职\", \"应\", \"提前\", \"解除\", \"部门\", \"辞退\", \"总经理\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:26', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:26', '0');
INSERT INTO `document_segments` VALUES ('1955803416516980738', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　5、员工离职流程 　　(1)离职时间：辞退以酒店综管部书面通知的签发日期为准;自动离职以离开工作岗位之日的考勤记录为准; 　　(2)离职人员将填妥的《员工离职申请表》报部门审批，经直属领导签字批准后，至综管部退还《员工手册》、工牌、考勤卡、车牌、更衣柜钥匙、员工服装等，在结清有关手续后，由酒店综管部填写《离职手续单》与各部门签字确认后，离职人员将在下月酒店正常发放工资之日至财务部领取其离职工资; 　　(3)工作未交接清楚者，不予批准离职。离职人员若损坏酒店物品，由酒店综管部按《赔偿标准》的规定从离职人员工资中扣除赔偿金; 　　(4)离职员工领取离职工资时间为酒店下月正常发放工资时间。 　　6、赔偿金及其它 　　(1)如因某某酒店原因辞退已签订劳动合同并且合同未到期的正式员工，工作时间每满一年支付一个月个人基本工资的经济补偿金，最多不超过12个月;自动离职人员、试用期人员及因违纪违规被酒店劝退的人员，酒店不予支付任何经济赔偿; 　　(2) 员工凡有本手册提及的严重过失行为或违反酒店其它规章制度的行为，酒店有权立即终止劳动关系，不给予任何补偿，并按相关规定处罚; 　　(3)', 494, NULL, '[\"离职\", \"酒店\", \"员工\", \"人员\", \"综\", \"时间\", \"管部\", \"工资\", \"补偿\", \"经济\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:26', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:26', '0');
INSERT INTO `document_segments` VALUES ('1955803416655392769', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　(3) 员工离职后，一般情况下六个月内无资格参加酒店招聘活动。 　　第五章 薪资与福利制度 　　一、 薪资确定： 　　酒店本着以岗定职、以职定薪、按劳付酬的原则，根据《员工岗位级别及薪资结构》的规定，结合员工承担的责任和工作业绩，确定工资报酬的结构和数额。 　　二、薪资组成：由基本工资+考核工资+全勤奖+绩效奖+工龄工资等部分组成。 　　1、基本工资：参照社会平均收入水平，根据员工的学历、资历、所在岗位等，在规定的岗位级别内确定; 　　2、考核工资：根据不同职位，不同级别，从个人工资总额中拿出一定比例的工资，依据基本经营指标任务、工作职责进行考核(详见每月考核细则); 　　3、绩效工资：以经营指标完成情况为基础，结合工作业绩、工作效率、纪律性、协调性、责任心等方面进行考核后确定，并上下浮动。(绩效奖根据员工工作情况进行评定，原则上员工不超过50-100元/月，领班级员工以上(含领班)原则上不超过100-200元/月); 　　4、工龄工资：入职满一年的正式员工，不受级别限制均进行工龄工资增长。具体增长办法为：', 462, NULL, '[\"工资\", \"员工\", \"进行\", \"确定\", \"工作\", \"考核\", \"级别\", \"薪资\", \"工龄\", \"原则\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:26', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:26', '0');
INSERT INTO `document_segments` VALUES ('1955803416701530113', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　4、工龄工资：入职满一年的正式员工，不受级别限制均进行工龄工资增长。具体增长办法为： 　　◆服务员级：员工转正之日(入职之日)起，连续工作满一年，增长一次工龄工资，工龄工资可连续增长三年，每年增长100元，累积增加金额最高为300元; 　　◆主管级别职员以上：员工转正之日(入职之日)起，连续工作满一年增长一次工龄工资，工龄工资可连续增长三年，每年增长100元，累积增加金额最高为300元; 　　◆工龄工资单独核算，员工级别变化，岗位工资调整时不影响工龄工资的增长; 　　4、岗位津贴：员工所在岗位的补贴，将根据员工职别及工作状态进行补贴：原则上：员工级岗位津贴：50-100元/月，领班级以上员工(含领班)：100-200元/月; 　　5.全勤奖：员工出正常公休外，在无任何形式的休假。奖励金额：50元/月。 　　三、说明 　　1、 新进员工均以所在岗位初级计薪，试用期为双方考察期，酒店和试用员工都有选择对方的权利，应提前七天向对方提出解除试用合同。 　　2、 员工薪资级别升降，以酒店业绩考核制度和《员工手册》规定进行综合考评的结果为依据; 　　3、 特殊岗位上的技术工人薪资按技付酬，数额参考就近相应级别的标准; 　　4、', 517, NULL, '[\"员工\", \"级别\", \"岗位\", \"工资\", \"工龄\", \"进行\", \"增长\", \"金额\", \"薪资\", \"试用\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:26', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:26', '0');
INSERT INTO `document_segments` VALUES ('1955803416747667458', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　3、 特殊岗位上的技术工人薪资按技付酬，数额参考就近相应级别的标准; 　　4、 正式人员因酒店原因被辞退时，工作每满一年，可获补发一月工资做 　　为经济补偿金;六个月以上不满一年的，按一年计算。不满六个月补发半个月工资。处于试用期内，或因严重违反国家法律法规及酒店规章制度而被辞退者，酒店不予补发工资。 　　四、所得税及其它应缴交费用 　　员工工资标准的额度概为税前薪资数额。员工收到薪资后，应交纳个人所得税和国家规定的其它税金及社会保险费的个人应付部分等。该税费每月由酒店从员工工资中扣除代缴。 　　五、劳动保障 　　某某酒店按照有关规定为员工办理社会保险，因工受伤致残致死，按国家劳动保险条例执行。 　　第六章 　　一、 工作时间 　　规章制度 　　1、每周工作不超过48小时，工作时间之编排由酒店制定。因酒店运行的需求，某些岗位会超时、加班工作。超时、加班工作部分将由企业予以补休，不计发超时及加班工资。 　　2、排班 　　各部门根据工作需要进行员工排班。每月29日前为排班时间，每月1日前各部门将本月排班表(注明班次)交至酒店综管部。排班表覆盖时间为每月1日至月31日(按当月实际天数排制)。 　　3、休息日', 510, NULL, '[\"酒店\", \"工作\", \"排\", \"国家\", \"应\", \"工资\", \"补发\", \"员工\", \"时间\", \"薪资\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:26', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:26', '0');
INSERT INTO `document_segments` VALUES ('1955803416789610498', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　3、休息日 　　(1)员工每周可享有一天全薪休息日(包括试用期，不影响全勤奖金)，但必须由部门负责人根据部门运营需要做出编排，实行轮换休息制度; 　　(2)每月30日前部门主管、领班需将次月的排班表向员工公布，排班确认后，任何员工不得擅自修改，如因特殊原因换班或调休，须提前申请，填写“员工换班调休单”，经部门负责人签名同意后方可换班，私自调休一律作旷工处理。 　　4、换班 　　员工因故需换班或调休，必须提前一天填写换班(调休)表，报部门主管/领班批准(经理、主管/领班需报总经理批准)方可换班。员工换班、调休，每人每月限两次。 　　5、加班 　　(1)员工应在工作时间内完成工作，酒店原则上不提倡加班; 　　(2)如需加班，必须事先填写“加班申请单”注明加班理由，报部门负责人签字确认方可有效; 　　(3)加班(不含用餐时间)统计由部门主管/领班每月26日进行，统计结果交综合部确认; 　　(4)主管及以上人员不填报加班申请; 　　(5)对加班人员，酒店给予同等时间的补休，如因工作需要无法补休的，支付相应的金额补助，加班时间可冲抵相同时间病、事假，员工加班时未打卡、未做加班登记或事先未审批的，其加班不予承认。', 510, NULL, '[\"加班\", \"员工\", \"部门\", \"换班\", \"调休\", \"主管\", \"时间\", \"确认\", \"需\", \"负责人\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:26', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:26', '0');
INSERT INTO `document_segments` VALUES ('1955803416835747842', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　二、考勤管理 　　1、指纹打卡 　　(1)员工每日上下班须亲自在指定地点打卡; 　　(2)员工打卡时必须着制服、佩工牌，着装不规范者，按照有关规定处理; 　　(3)因特殊情况未打卡，当事人应填写《漏打卡单》经部门负责人签字后两日内交综管部。 　　2、迟到及早退 　　(1)、迟到：凡超过上班时间5—30分钟未到工作岗位者，视为迟到，将被扣罚5—30元; 　　(2)、早退：凡未向主管领导请假，提前5-30分钟离开工作岗位者，视为早退，将被扣罚5-30元; 　　(3)无故缺勤一天，视为旷工，并记小过一次;旷工两天计大过一次。一月内累计或连续旷工两天，视为严重违纪，予以开除。 　　3、请假 　　(1)请假手续：员工因事、因病请假，需事先填写《请假申请单》并确 　　定本岗位职务代理人，呈上级主管批准;未经批准休假、超假不续及续假未获批准者，将视为旷工。如因特殊原因无法事前请假，需通知部门负责人，事后补办手续。事假每月累计不能超过3天; 　　(2)请假核定权限：所有请假须先经部门负责人批准，再依核定的批准 　　权限上报，请假获批后，将相关请假资料交综管部存档。核定批准权限为： 　　部门主管/领班 权限：1日 运营经理', 512, NULL, '[\"请假\", \"视为\", \"卡\", \"批准\", \"部门\", \"员工\", \"主管\", \"旷工\", \"负责人\", \"权限\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:26', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:26', '0');
INSERT INTO `document_segments` VALUES ('1955803416890273794', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　部门主管/领班 权限：1日 运营经理 权限：2日 总经理 权限：3日以上 　　(3)请假工资计扣标准 　　假类 病假(非工/ 伤) 以旷工论处 事先请假，无全勤奖;事假 以天计 全工资 100% 事先没请假以旷工处理 缺勤30分钟旷工 以上(不含30分钟) 以次数计迟到 (5-30分钟以内) 以次数计早退 (5-30分钟以内) 　　三、有薪假 工伤假 　　1、员工工伤的认定，需凭酒店认可的医院证明。部门负责人应在工伤事 　　时段 计扣基础 扣计标准 要求 市级医院证全勤奖 50元 明,无证明日全工资 150% 一月内累计迟到或早退5次或连续 每次5-30元 迟到3次，另按旷工一天扣罚，无 每次5-30元 全勤奖 　　故发生后5小时内向某某酒店综管部提交工伤事故书面报告。综管部调查并确认后，方可按工伤处理。重大工伤事故的认定，以劳动部门出具的鉴定报告为准。工伤医疗期按国家有关规定执行; 　　2、经确认为因工负伤的员工，其休假期间，按酒店规定扣发补贴。 3、医疗期满后仍不能恢复健康的，或康复后不能从事原有工作、并拒绝酒店新安排工作的，可按国家有关规定解除合同或办理离职手续。 　　婚假', 499, NULL, '[\"工伤\", \"酒店\", \"规定\", \"计\", \"工资\", \"旷工\", \"奖\", \"全勤\", \"请假\", \"国家有关\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:26', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:26', '0');
INSERT INTO `document_segments` VALUES ('1955803416932216834', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　婚假 　　1、员工在酒店工作满一年者可按国家有关规定享受三天婚假;达到国家规定的晚婚年龄，即男25岁、女23岁以上结婚者，可享受八天晚婚假(不含法定假日和公休假); 　　2、婚假只能一次性使用。享受婚假需事先办理请假手续，超假者视情况按事假或旷工处理; 　　3、婚假期间基本工资不变，按酒店有关规定扣发补贴。 产假 　　1、酒店已婚女员工享有国家规定的产假期，享受产假的女员工须有准生证;产假只能一次使用。 　　2、本人分娩可请产假90天(不含法定假日和公休假日)，24岁以后初次分娩可增加产假30天，妊娠五个月以上流产者，可请产假40天;妊娠三至四月流产者，可请产假30天;妊娠三月内流产者，可请产假15天。因妊娠流产享受产假，需出具医院证明和结婚证明; 　　3、产假期间基本工资不变，按酒店有关规定扣发补贴。 　　丧假 　　1、员工遇有丧事，须向部门负责人请假; 　　2、员工的亲属(父母、配偶、子女、兄弟、姐妹)去世，准假三天(遇法定假日和公休日顺延)。死者在外地的，另加往返程时间。 　　3、符合以上规定的丧假，其间基本工资不变，按酒店有关规定扣发补贴。 　　年假', 488, NULL, '[\"产假\", \"婚假\", \"享受\", \"员工\", \"规定\", \"假日\", \"酒店\", \"请假\", \"需\", \"公休\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:26', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:26', '0');
INSERT INTO `document_segments` VALUES ('1955803416978354178', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　3、符合以上规定的丧假，其间基本工资不变，按酒店有关规定扣发补贴。 　　年假 　　员工转正(入职)工作年满一年以后，可申请休带薪年假3天，以后每工作满一年，每年递加一天，最高带薪年假不得高于5天。具体的休假办法由酒店制定。原则上年假应一次性休完，不得将年假积累至下一年度使用。年假之使用应按规定执行。申请年假需提前30天由本人书面申请。 　　四、员工通道及携带物品出入 　　1、员工须经指定通道进出酒店各工作区域(特殊情况除外)，保安人员有责任及权利做好监督，所有人员必须主动配合。 　　2、携带物品出入：员工若有私人物品带入酒店，须经保安人员登记。若有未登记物品带出酒店，需经部门负责人批准并签署书面意见后方可带出。 　　五、客用设施 　　除因工作需要，任何员工都不得使用客用设施，包括客用电梯、客用卫生间、餐厅、用茶坊等，未经管理人员许可使用客用设施，将依照规定予以处罚。 　　六、私人客访及电话 　　1、工作时间员工不得在工作区域内接见亲友，如遇特殊情况，需向部门负责人申请，经同意后方可; 　　2、除工作需要外，员工工作时间不得在工作区域以外的地点逗留;', 483, NULL, '[\"工作\", \"酒店\", \"员工\", \"年假\", \"客\", \"申请\", \"规定\", \"使用\", \"需\", \"物品\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:26', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:26', '0');
INSERT INTO `document_segments` VALUES ('1955803417028685825', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　2、除工作需要外，员工工作时间不得在工作区域以外的地点逗留; 　　3、员工不得在工作时间内拨打和接听私人电话，紧急情况时，需向部门负责人申请，经同意后方可;且应尽量简短，避免影响工作; 　　4、员工在工作时间、工作区域内，应将移动电话置于振动方式，并不得显露在外。 　　七、吸烟 　　员工不得在工作区域及营业区域内吸烟，只许在指定的区域内吸烟，违者将按相关规定予以处罚。 　　八、索取财物 　　员工不得以任何形式向他人索取财物，如：向供应商、客人等收取佣金、小费及物品，违者将立即开除。情节严重者酒店有权追究其法律责任。 　　九、失物及遗留物品 　　1、酒店区域内发现无主财物，应立即交至总台失物招领处，并按规定进行登记; 　　2、若失物在六个月内未被失主认领，失物由酒店有关部门按规定做出处理。 　　十、仪容仪表 　　员工外表整洁与衣着适当，是酒店重要的品牌标志之一，是酒店与客人保持良好关系的基础，酒店要求员工在工作期间始终保持如下状态： 　　1、头发应梳理整齐。男员工头发应盖不过耳部及衣领，不允许留胡须;女员工短发不过肩，长发应用黑色发夹或发带束扎; 　　2、制服应干净、平整、无污渍、钮扣齐全，无开线处;', 509, NULL, '[\"员工\", \"酒店\", \"工作\", \"区域\", \"应\", \"规定\", \"财物\", \"部门\", \"失物\", \"违者\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:26', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:26', '0');
INSERT INTO `document_segments` VALUES ('1955803417267761153', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　2、制服应干净、平整、无污渍、钮扣齐全，无开线处; 　　3、皮鞋应擦拭干净，保持光亮; 　　4、指甲应修剪整齐，保持干净，不得留长指甲、涂指甲油; 　　5、穿裙装女员工应着肉色丝袜，袜子不能有破洞或抽线;男员工应着黑色袜子; 　　6、化妆品与香水应使用恰当，女员工着淡妆上岗; 　　7、穿制服时不佩戴过多饰品(手表和结婚、订婚戒指除外); 　　8、注意个人卫生，应防止体味和口臭。 　　十一、保密制度 　　1、凡涉及酒店经营发展、直接影响酒店权益和利益的重要决策文件资料、酒店的规则、财务报表、统计资料、重要会议记录、酒店经营情况等，均纳入酒店保密范围，资料严格保管，禁止擅自外传;各类信息禁止擅自外泄; 　　2、酒店内部所发生的负面事件和消防、卫生事故等情况不得擅自外泄; 　　3、出现下列情况之一者，给予警告，并扣罚10元以上500元以下： 　　(1)泄露酒店秘密，未造成严重后果或重大经济损失的; 　　(2)已泄露酒店秘密但采取了有效补救措施的; 　　4、出现下列情况之一的，予以辞退并令其酌情赔偿经济损失： 　　(1)故意或过失泄露酒店秘密，造成严重后果或重大经济损失的;', 492, NULL, '[\"酒店\", \"应\", \"情况\", \"干净\", \"卫生\", \"泄露\", \"擅自\", \"穿\", \"资料\", \"袜子\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:26', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:26', '0');
INSERT INTO `document_segments` VALUES ('1955803417322287106', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　(1)故意或过失泄露酒店秘密，造成严重后果或重大经济损失的; 　　(2)违反保密制度规定，替他人或竞争对手窃取、刺探、收买或违章提供酒店秘密的; 　　(3)利用职权强制他人违反保密规定的。 　　第七章 公共设施 　　一、员工更衣室、更衣柜 　　1、为员工配备的更衣柜应保持清洁; 　　2、不得在更衣柜内放置贵重物品、易燃、易爆危险品及食品饮料; 　　3、更衣柜随时紧锁，如有物品丢失，应及时报保全部协助查找; 　　4、更衣柜不得私自换锁，不得占用他人更衣柜，或相互对换更衣柜，特殊情况下需员工合用更衣柜时应服从安排; 　　5、更衣柜钥匙忘带或遗失，不得私自撬柜、换锁，经酒店行政人事部批准方可设法打开更衣柜; 　　6、更衣柜若有人为损坏情形，需照价赔偿，并按规定给予当事人处罚; 　　7、员工有责任保持更衣室的清洁，严禁随地吐痰、乱扔垃圾或其它有碍卫生整洁的行为，严禁在更衣室内高声喧哗、娱乐或未经批准留宿; 　　8、当酒店出于管理工作需要授权有关部门检查员工更衣柜时，员工应给予支持和配合; 　　9、员工离职时须清理更衣柜，并将门锁打开。 　　二、员工用餐', 481, NULL, '[\"更衣柜\", \"员工\", \"酒店\", \"应\", \"规定\", \"更衣室\", \"锁\", \"秘密\", \"严禁\", \"违反\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:26', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:26', '0');
INSERT INTO `document_segments` VALUES ('1955803417385201666', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　9、员工离职时须清理更衣柜，并将门锁打开。 　　二、员工用餐 　　所有员工均在指定的区域就餐，员工每次用餐时间规定为30分钟，就餐时间根据各部门根据具体情况安排，轮换就餐。 　　三、员工工号牌(工号牌) 　　1、员工工作时间必须佩带工号牌; 　　2、若工号牌损坏或遗失，须立即上报酒店行政人事部，尽快予以修补或补发(按规定支付补发费用20元); 　　3、若发现上班未佩带工号牌或佩带非本人的工号牌，视为违纪，按相应规定处罚; 　　4、员工工号牌一律佩带在制服左前胸。 　　四、制服 　　1、酒店根据工作岗位为员工提供制服; 　　2、在员工离职时，须验证服装完好无损，如果出现破损，则按300元/套的标准进行扣除; 　　3、员工制服由个人保管，员工有责任保持制服的整洁完好，若因疏忽或恶意导致制服损坏，所发生的缝补、购置费用由员工按比例承担; 　　4、除非工作需要和获得特别许可，员工不得在酒店区域之外穿着制服; 　　5、员工应按要求穿着制服，制服上不得佩带任何规定之外的饰物，不得私自修改制服。 　　五、员工告示栏', 459, NULL, '[\"员工\", \"制服\", \"规定\", \"佩带\", \"工号牌\", \"酒店\", \"须\", \"损坏\", \"时间\", \"就餐\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:26', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:26', '0');
INSERT INTO `document_segments` VALUES ('1955803417431339009', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　5、员工应按要求穿着制服，制服上不得佩带任何规定之外的饰物，不得私自修改制服。 　　五、员工告示栏 　　1、酒店的通知、人事令、重要信息、文件刊物等，将通过员工告示栏发布，所有员工应留意并认真阅读。若因疏忽未能及时了解，责任自负; 　　2、未经许可，员工不得私自在员工告示栏内张贴任何通知或告示; 　　3、禁止任何针对员工告示栏的干扰或破坏行为，违者将按酒店相关规定予以处罚。 　　六、员工宿舍 　　1、员工申请住宿条件：若酒店所在区域内无寻求适当住所的条件或交通不便，在该酒店工作的员工，可以用书面形式申请住宿，由本人提交书面申请部门负责人签字，经酒店行政人事部同意后，可按照行政人事部安排的宿舍入住。入住期间，每月产生的水、电、煤气费用自理; 　　2、酒店为员工提供住宿，以居住人在酒店服务为先决条件，若员工离职，应立即搬离员工宿舍并办妥相关手续，否则酒店有权强行将其搬离宿舍。 　　第八章 安全守则 　　一、火灾 　　(一)、火灾发生时的应对办法 　　1、关掉电源、燃气源; 　　2、立即报警; 　　3、组织扑救(初期火灾); 　　4、疏散顾客; 　　5、保护现场; 　　6、协助消防部门调查起火原因。 　　(二)、疏散办法', 517, NULL, '[\"员工\", \"酒店\", \"宿舍\", \"栏\", \"告示\", \"火灾\", \"住宿\", \"部门\", \"规定\", \"疏散\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:26', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:26', '0');
INSERT INTO `document_segments` VALUES ('1955803417473282049', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　4、疏散顾客; 　　5、保护现场; 　　6、协助消防部门调查起火原因。 　　(二)、疏散办法 　　1、楼梯是疏散的唯一途径; 　　2、禁止乘坐电梯; 　　3、尽可能使用消防楼梯间; 　　4、走廊充满烟雾时，应注意“紧急出口”指示灯，向指示灯方向走; 　　5、当直立行走呼吸困难时，应弯腰前行或趴在地上爬行。 　　(三)、火灾的防范 　　1、对员工进行火灾安全防范教育，要求每一位员工均能“三懂三会”，即懂本岗位产生火灾的危险性、懂本岗位预防火灾的措施、懂本岗位扑救火灾的方法;会报警、会使用本岗位灭火器材、会扑救初起火灾; 　　2、定期对各岗位灭火器材、电线开关等进行全面检查，对压力不足或超过使用期的灭火器材进行更换，对自动喷淋装置不能正常使用的进行报修并落实跟进处理情况; 　　3、定期对天然气泄漏报警器进行检查维护，确保使用天然气的安全; 4、对库房进行专人管理，非工作人员严禁入内，更不得在库房使用明火吸烟，一经发现，将对管理人及库管员进行严肃处理。 　　二、火灾报警', 440, NULL, '[\"进行\", \"使用\", \"火灾\", \"器材\", \"岗位\", \"时\", \"应\", \"疏散\", \"灭火\", \"楼梯\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:26', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:26', '0');
INSERT INTO `document_segments` VALUES ('1955803417515225089', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　二、火灾报警 　　当火灾发生后，每位员工都有权力和义务报警;以最快的速度报告主管负责人、总经理;除非特别紧急的情况，都必须先向酒店内部报警，由总经理视情况决定是否向公安消防部门报警。 　　1、记住内部火警电话： 　　2、报告火情：将火情发生的位置、地点、燃烧物质、火势大小、有无人员被困、自己所在岗位及姓名报告主管负责人。 　　三、接警后的措施(火警报警电话设置的位置在) 　　1、要详细记录报警人姓名、部门; 　　2、冷静详细了解火情发生的位置、地点、燃烧物质、火势大小、有无人员被困以及报警人的姓名、所在岗位等情况; 　　3、由发现隐患者及时报告总经理、保安负责人等相关人员; 　　4、由总经理、部门负责人组成调查、甄别、确认小组，赶赴现场查清下列问题： 　　A、火情的具体位置、燃烧物品、燃烧范围及火势走向; 　　B、火源是电起火还是其他原因; 　　C、火场有无人员被困，有无贵重物品，有无易燃易爆危险物品等。 　　5、迅速组成火灾临时指挥部，指挥长为总经理，成员包括保安负责人、部门经理以及相关管理人员，由指挥长迅速做出是否119报警的决定; 　　6、派专人到酒店门口岔道迎接消防车，引导配合消防车抵达火灾现场。', 512, NULL, '[\"报警\", \"总经理\", \"负责人\", \"报告\", \"部门\", \"情况\", \"人员\", \"有无\", \"火情\", \"姓名\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:26', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:26', '0');
INSERT INTO `document_segments` VALUES ('1955803417582333954', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　6、派专人到酒店门口岔道迎接消防车，引导配合消防车抵达火灾现场。 　　四、部门措施 　　1、义务消防队 　　A、立即带好消防器材和工具赶赴现场，等候命令; B、按照指挥部的指令进行扑救。 　　2、酒店总经理与运营经理立即到过现场，根据火情大小，派专人迅速关闭燃气炉灶阀门、通风、抽风阀门、空调和有关电器设备; 　　3、由部门管理人员及男性员工组成人员疏散组，对女员工、客人进行疏散，疏散路径严格按照消防预演路径、消防疏散图的逃生路径执行 ; 　　4、妥善处理食用油脂，组织男性员工将部门内所有液化气瓶、可燃物搬离火灾现场，集中在火灾指挥部指定的安全地带由专人看管; 　　5、如火情发展，在工程部人员撤出前，配合将所有电源、燃气阀门、制冷设备和门窗全部关闭。 　　五、组织疏散 　　如无法控制火情，迅速按照酒店制定的疏散计划组织人员疏散。 　　1、二次报警(119报警)后，指挥部应立即做出疏散决定; 　　2、立即利用背景音响系统(消防广播系统)进行反复广播。内容主要是要求宾客听从工作人员的指挥，在工作人员的引导下，从最近的疏散通道撤离火场以及不要乘坐电梯等;', 482, NULL, '[\"疏散\", \"立即\", \"进行\", \"指挥部\", \"部门\", \"组织\", \"酒店\", \"火情\", \"人员\", \"专人\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:26', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:26', '0');
INSERT INTO `document_segments` VALUES ('1955803417632665601', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　3、广播的同时，员工迅速检查区域内有无客人，检查完毕将门窗关好，在房门上做出“已检查”标志; 　　4、疏散人员时走安全通道(安全梯)，绝对禁止乘坐电梯; 　　5、引导客人排成一路纵队，从安全梯疏散; 　　6、酒店财务部的现金和贵重物品需由专人在保安的护送下撤离; 　　7、疏散可能助燃的易燃物品和煤气罐、氧气瓶等危险品; 　　8、疏散前保安要认真检查安全出口、疏散楼梯、疏散通道、应急照明和安全指示标志等安全疏散设施，确保畅通; 　　9、疏散到安全地带后，要集中客人，由运营经理组织，各部门管理人员、保安员进行登记，核实人数。 　　六、灭火器适用范围 　　1、泡沫灭火器：用于油脂、木材、棉丝品着火; 　　2、二氧化碳(CO2)灭火器：用于600V以下电器、贵重设备、仪表仪器着火; 　　3、干粉灭火器：用于石油制品、可燃气体、易燃液体着火; 　　4、1211灭火器：用于易燃、可燃液体、气体、电器设备着火和初期火灾。 　　七、出现食物中毒事件的应急预案', 429, NULL, '[\"疏散\", \"灭火器\", \"安全\", \"客人\", \"着火\", \"检查\", \"用于\", \"安全梯\", \"保安\", \"标志\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:26', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:26', '0');
INSERT INTO `document_segments` VALUES ('1955803417674608641', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　七、出现食物中毒事件的应急预案 　　食物中毒多因食品、饮料贮存不当所致，其中毒症状多见于急性肠胃炎症状，如恶心、呕吐、腹痛、腹泻等。为保障的宾客以及酒店员工的人身安全，在发生食物中毒或疑似食物中毒事故后，能有效控制事态，蓝酒店损失及影响降低到最小，酒店特制定应急预案如下： 　　(一)、事故防范 　　1、采购人员严把采购关，收货人员严把验货关，仓库人员把好食品入库关，厨师严把制作关; 　　2、严格按照《食品卫生法》的要求，切实执行“五四”制度; 3、厨房员工个人卫生做到“四勤”：①勤洗手、剪指甲;②勤洗澡、理发;③勤洗衣服、被褥;④勤换工作制服; 　　4、用(食)具实行“四过关”：①一洗②二刷③三冲④四消毒，用(食)具清洗消毒完毕，必须将水渍擦拭干净放入保洁柜内，避免二次污染; 5、环境卫生采取“四定”办法：①定人②定物③定时间④定质量，划片分工，包干负责。 　　6、厨房操作人员在操作成品时，必须佩戴口罩，患有感冒、伤风等传染性疾病的员工，必须立即停工休息，不得带病上岗;', 443, NULL, '[\"必须\", \"员工\", \"酒店\", \"人员\", \"食物中毒\", \"卫生\", \"厨房\", \"勤\", \"关\", \"严\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:27', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:27', '0');
INSERT INTO `document_segments` VALUES ('1955803417724940289', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　7、员工上班期间做到“三要”――工作前后、大小便后要洗手，工作前要漱口;“五不”――在宾客面前不掏耳、不剔牙、不抓头皮、不打哈欠、不抠鼻子;“两个注意”――服务前注意不食韭菜、大蒜和大葱等有强烈气味的食;在宾客面前，咳嗽、打喷嚏须用手帕掩住口鼻，并转身背向宾客; 　　(二)、应急措施 　　1.及时逐级报告 　　一旦发生食物中毒，部门负责人应及时向总经理报告，总经理则向上级食品卫生监督检验所、医院和上级主管部门报告。报告内容有：发生中毒的单位、地址、时间、中毒人数及死亡人数，主要临床表现，可能引起 　　中毒的食物等。以利于有关部门积极采取措施、组织抢救、调查分析中毒原因和预防方法。若怀疑投毒则应向公安机关报告，并立即查找并控制嫌疑人，配合公安机关调查、侦破; 2.立即抢救中毒顾客 　　当总经理作出通知急救中心或送医院抢救时，应立即拨打“120”与急救中心或医院联系，讲清楚地点、中毒人数、中毒程度、症状等。待救护车到达后，派专人护送前往医院救治; 3.保护现场、保留样品', 441, NULL, '[\"中毒\", \"医院\", \"报告\", \"宾客\", \"抢救\", \"总经理\", \"面前\", \"部门\", \"前\", \"人数\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:27', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:27', '0');
INSERT INTO `document_segments` VALUES ('1955803417775271937', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '3.保护现场、保留样品 　　发生食物中毒后在向有关部门报告的同时要保护好现场和可疑食物，立即停止营业，疏散客人，做好解释工作。病人吃剩的食物不得倒掉，食品用工具、容器、餐具等不得冲洗，病人的排泄物(呕吐物、痰迹、血蹟等)要保留，以便卫生部门采样检验，为确定食物中毒提供可靠的情况。 4.如实反映情况 　　酒店负责人及与本次中毒有关人员，如厨房工作人员、部门经理及病人等应如实反映本次中毒情况。将病人所吃的食物，进餐总人数，同时进餐而未发病者所吃的食物，病人中毒的主要特点，可疑食物的来源、质量、存放条件、加工烹调的方法和加热的温度、时间等情况如实向有关部门反映; 　　5.对中毒食物的处理 　　在查明情况之前对可疑食物应立即停止食用。在卫生部门已查明情况，确定了食物中毒，既可对于引起中毒的食物及时进行处理。对中毒食物可采取煮沸15分钟后掩埋或焚烧。液体食品可用漂白粉混合消毒。食品用工具、容器可用1～2%碱水或漂白粉溶液消毒。病人的排泄物可用20%石灰乳或5%的来苏溶液进行消毒。 　　※如遇有意外伤亡发生，员工应保持冷静，立即将情况向上级汇报;', 474, NULL, '[\"食物\", \"病人\", \"情况\", \"中毒\", \"可疑\", \"食物中毒\", \"如实\", \"食品\", \"消毒\", \"可用\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:27', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:27', '0');
INSERT INTO `document_segments` VALUES ('1955803417825603585', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　※如遇有意外伤亡发生，员工应保持冷静，立即将情况向上级汇报; ※如遇火灾、水灾及其他人力所不可抗拒的自然灾害等紧急情况，员工将被要求作额外加时工作，员工必须无条件服从、听候指挥调度; 　　※加设警示标志，警告他人勿靠近危险; 　　※在紧急情况下，希望每位员工鼎立合作，确保酒店及员工的人身和财产安全。 　　第九章 奖惩条例 第一条 处罚 　　(一)处罚等级参照过失行为情节轻重及对酒店利益、声誉影响程度确定。具体对应如下： 　　1、口头警告：过失行为情节轻微，对酒店利益、声誉未造成不良影响; 　　2、记小过：过失行为情节严重，对酒店利益、声誉造成一定负面影响; 　　3、记大过：过失行为情节非常严重，对酒店利益、声誉造成严重消极影响; 　　4、辞退：过失行为情节恶劣，对酒店利益、声誉造成巨大伤害，若触犯国家相关法律、法规，酒店将移送司法机关处理; 　　5、违纪员工本月内累计警告三次，即视为记小过一次;凡本月内累计记小过两次，视为记大过一次;凡本年内累计记大过两次，即予以辞退。 　　(二)员工若有以下过失行为，酒店将按照不同处罚等级予以处罚： 口头警告 凡在工作期间有以下行为之一者，予以口头警告处分：', 506, NULL, '[\"员工\", \"酒店\", \"行为\", \"警告\", \"过失\", \"声誉\", \"利益\", \"造成\", \"紧急情况\", \"予以\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:27', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:27', '0');
INSERT INTO `document_segments` VALUES ('1955803417867546626', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '口头警告 凡在工作期间有以下行为之一者，予以口头警告处分： 　　1、工作期间，未经许可会见访客，处理私人事务的; 　　2、搬弄是非，诽谤他人，妨碍酒店工作秩序和团队和谐的; 　　3、不按岗位职责规定工作，违反操作程序，服务不规范的; 　　4、工作时不按规定着装、佩带工牌，及个人卫生、仪容仪表不符合酒店规范标准的; 　　5、考勤打卡前不着制服的; 　　6、随地吐痰或乱扔纸屑杂物，影响环境卫生的; 　　7、未经许可使用客用设施或非员工通道的; 　　8、无故迟到、早退、时间在10分钟以内的; 　　9、班前班后不清场、不打扫环境卫生的; 　　10、下班后无故逗留营业场所的; 　　11、不按时参加班会的; 　　12、未经批准，私自换班、替班的及工作期间私自离岗、串岗的; 　　13、未能保持更衣柜整洁、以及违反更衣柜、制服管理规定的; 　　14、未经许可，不在指定地点用餐的; 　　15、未按规定张贴、悬挂酒店、部门资料的; 　　16、工作时间聚众闲聊、打闹、高声喧哗，吃零食，睡觉，看书、报刊、杂志或从事其它与工作无关事情的; 　　17、逾期未办理、出具酒店所需手续的; 　　18、其它与上述情节、性质类似的违纪行为;', 509, NULL, '[\"工作\", \"酒店\", \"规定\", \"卫生\", \"未经许可\", \"期间\", \"时间\", \"未\", \"环境\", \"制服\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:27', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:27', '0');
INSERT INTO `document_segments` VALUES ('1955803417913683969', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　17、逾期未办理、出具酒店所需手续的; 　　18、其它与上述情节、性质类似的违纪行为; 凡工作期间有下列行为之一者，予以记小过处分： 　　1、脱岗、串岗20分钟以上1小时以下的; 　　2、私自处理宾客遗留财物、不上交的; 　　3、未经主管批准、私自外出的; 　　4、未经主管批准、使用酒店电话的; 　　5、在酒店告示栏或其它场所随意撕毁、更改洋蓝酒店张贴的布告通知的; 　　6、一月之内无故迟到、早退3次，时间在15分钟以内的; 　　7、不了解酒店开展的活动，对客人敷衍了事、待客不耐心的; 　　8、拒绝让保全检查衣柜、皮包等; 　　9、擅自在酒店区域内散发与酒店工作无关宣传品的; 　　10、行为不当有损酒店信誉，情节轻微的; 11、从第一次被警告之日起，一月内累计满两次的; 　　12、故意涂改、损坏工号牌、考勤卡等类似行为; 凡工作期间有下列行为之一者，予以记大过处分。被记大过者，必须下岗培训： 　　1、在工作时间、工作区域内与同事或宾客发生过分亲密或争执现象，造成不良影响的; 　　2、消极怠工，不服从上级工作安排，公开顶撞上司，影响工作开展的; 　　3、工作失职、失误、渎职，造成酒店利益受损的;', 506, NULL, '[\"酒店\", \"工作\", \"行为\", \"宾客\", \"一月\", \"造成\", \"开展\", \"情节\", \"时间\", \"私自\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:27', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:27', '0');
INSERT INTO `document_segments` VALUES ('1955803417959821314', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　3、工作失职、失误、渎职，造成酒店利益受损的; 　　4、违反消防、安全管理制度未造成严重后果的; 　　5、在更衣柜内发现酒店财物的; 　　6、偷吃、偷拿酒店食物、财物的; 　　7、一月内迟到5次以上(迟到5次算旷工一天)累计时间在30分钟以内的; 　　8、一月内被记小过两次。 　　9、怠慢客人，因服务态度、服务质量问题受到宾客口头批评或书面投诉的; 　　10、对酒店会议精神和文件、规章制度传达贯彻不及时的; 　　11、由于自身原因被电台、电视台、报刊等媒体曝光，对酒店造成不良影响的(曝光情况不属实者除外); 　　12、工作时间内赌博或围观赌博的; 　　13、遇事故发生，借故逃避，虚报、谎报案件、险情，造成酒店损失的; 　　14、擅自脱岗一小时以上的; 　　15、其它与上述情节、性质类似的违纪行为。 辞退 凡属下列范畴的员工，即作辞退处理： 　　1、再次培训后，考核仍不合格者; 　　2、在经营场所与他人争吵或谩骂、威胁、恐吓他人，打架闹事，影响恶劣者; 　　3、损毁、涂改酒店文件、资料者; 　　4、偷窃、侵占、挪用、破坏酒店、客户、同事财物，或擅自将酒店物品带离酒店区域者; 　　5、在上岗一年内受到记小过两次处分者;', 517, NULL, '[\"酒店\", \"造成\", \"财物\", \"时间\", \"文件\", \"一月\", \"记\", \"辞退\", \"擅自\", \"工作\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:27', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:27', '0');
INSERT INTO `document_segments` VALUES ('1955803418005958657', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　5、在上岗一年内受到记小过两次处分者; 　　6、伪造、盗用酒店印章、介绍信、营业执照、资料者; 　　7、弄虚作假，伪造证件、证明、记录，经查属实者; 　　8、散播损害酒店利益的谣言，引起严重后果者; 　　9、泄露酒店机密，导致酒店利益受损者; 　　10、利用酒店名义进行私下交易，收取好处费、回扣，损害酒店利益、影响酒店声誉者; 　　11、故意包庇违纪、违法行为，窝赃或作伪证者; 　　12、工作中利用职务之便，侵吞酒店财物者; 　　13、煽动或以暴力胁迫他人消极怠工、罢工或集体离职者; 　　14、年度内累计记大过两次未能依规定抵消者; 　　15、一般员工无故连续旷工2天者; 　　16、其它与上述情节、性质类似的违纪行为。 　　(三)处罚办法： 　　1、口头告诫：适用轻微过失行为; 　　2、罚款：为“辞退”以外所有级别的处罚形式。罚款须开处罚单; 　　(1)口头警告：罚款10-30元; 　　(2)记小过：罚款30-50元; 　　(3)记大过：罚款50-100元; 　　(四)处罚适用对象：全体员工。 　　第二条 奖励 　　(一)、奖励等级', 475, NULL, '[\"酒店\", \"处罚\", \"利益\", \"罚款\", \"员工\", \"利用\", \"口头\", \"记大过\", \"损害\", \"适用\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:27', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:27', '0');
INSERT INTO `document_segments` VALUES ('1955803418060484609', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　(四)处罚适用对象：全体员工。 　　第二条 奖励 　　(一)、奖励等级 　　对员工的奖励包括嘉奖、记小功、记大功三个等级。三个等级的奖励除给予精神荣誉、作为晋升参考外，并酌情发放奖金： 嘉奖：奖金50元; 　　记小功：奖金100元; 记大功：奖金200元; 　　(二)、嘉奖 　　员工有下列行为之一者，予以嘉奖： 　　1、维护集体荣誉，事实具体的; 　　2、工作勤奋、品行优良，有具体表现的; 　　3、整理编辑重要资料、报告，内容完善优异的; 　　4、拾金不昧的; 　　5、具有其它事迹，足以成为员工楷模的。 　　(三)、记小功 　　员工有下列行为之一者，予以记小功： 　　1、对经营或管理制度提出具体方案，经采用后确有成效的; 　　2、研究改善工作方法、提高工作效率或降低成本，确有成效的; 　　3、遇到火灾、勇于负责，并处理得当的; 　　4、对违反酒店规定或损害酒店利益之人和事，勇于检举揭发的; 　　5、防患于未然，在避免意外事故的发生方面起到突出作用的; 　　6、承办、执行、策划或督导重要事务成绩显著的; 　　7、具有其它先进事迹，足以表扬的; 　　(四)、记大功 　　员工有下列行为之一者，予以记大功：', 509, NULL, '[\"员工\", \"勇于\", \"嘉奖\", \"记\", \"重要\", \"荣誉\", \"具体\", \"成效\", \"确有\", \"记大功\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:27', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:27', '0');
INSERT INTO `document_segments` VALUES ('1955803418106621954', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　7、具有其它先进事迹，足以表扬的; 　　(四)、记大功 　　员工有下列行为之一者，予以记大功： 　　1、遇到意外事故或灾变，奋不顾身尽力抢救从而减轻酒店损失的; 　　2、对酒店有重大贡献或显著提升某某酒店荣誉的; 　　3、具有其它重要先进事迹，足以成为其他员工表率的。 　　第十章 附则 　　1、凡属酒店员工，均适用本《员工手册》; 　　2、本《员工手册》遇有不够详明之处，请参见《洋蓝酒店管理手册》; 　　3、本《员工手册》内容解释权归成都嘉云置业某某酒店; 　　4、酒店有权根据经营管理实际情况的变化，对本《员工手册》进行修订、增补; 　　5、本《员工手册》严禁涂写、损坏，离职时必须交回酒店综管部。 员工手册范本 篇28 　　员工 是公司最重要的财富,员工素质及专业知识水平的提高就是公司财富的增长, 　　员工的福利待遇及生活水平是公司经营业绩的具体体现 　　产品 不断创新的产品是公司发展的轨迹 　　质量 产品及服务质量是公司发展的生命线 　　品牌 是公司产品及服务的一面明镜 　　市场 寻找,开拓最适合我们的市场并力争取得最高占有率 　　管理 一切经营活动的基石方针 高科技,专业化,集团化,国际化口号 创新求是 　　第二部分 人事政策 　　2-1', 531, NULL, '[\"员工\", \"酒店\", \"手册\", \"公司\", \"经营\", \"管理\", \"产品\", \"重要\", \"水平\", \"市场\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:27', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:27', '0');
INSERT INTO `document_segments` VALUES ('1955803418156953602', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　管理 一切经营活动的基石方针 高科技,专业化,集团化,国际化口号 创新求是 　　第二部分 人事政策 　　2-1 员工招聘和录用 　　2-1-1 招聘和录用条件 　　- 根据本公司特点,按工作能力,业务水平,敬业精神择优 　　- 所招员工须通过专业知识及技能的测试(根据需要选择口头或书面两种方式) 　　2-1-2 招聘程序 　　根据公司发展需要,由部门经理提交用人方案由人事部转总经理批复决定 　　* 人事部通过各大院校及人才中心或其他渠道为部门经理提供初步人选的各类人才 　　资料 　　* 部门经理参考人才资料确定面试人员 　　* 人事部通知面试并将面试意见呈报总经理 　　* 总经理汇总各方面意见确定试用人员 　　* 人事部下发录用通知并办理试用手续 　　2-1-3 招聘人员要求 　　* 技术人员 　　高级技术人员:博士或高级职称,对电子信息工程或软件专业有丰富科研,开发 　　经验中级技术人员:具有电子信息,软件开发三年以上专业开发经验,硕士中级 　　职称以上技术人员: 具有电子信息,计算机专业本科以上学历 　　* 管理类人员 　　经 理 :管理或电子类专业院校本科以上,在大型算机专业公司从事经营管理工 　　作三年以上,有强烈的责任心和事业心.35岁以下 　　市场人员:电子类专业院校本科以上,1-3年工作经验,具有市场开拓能力', 572, NULL, '[\"-\", \"人员\", \"专业\", \"人事部\", \"管理\", \"院校\", \"技术人员\", \"部门经理\", \"招聘\", \"电子信息\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:27', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:27', '0');
INSERT INTO `document_segments` VALUES ('1955803418211479554', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　市场人员:电子类专业院校本科以上,1-3年工作经验,具有市场开拓能力 　　财务人员:财经类大学本科,熟悉会计电算化 　　文秘人员:文科类大学本科,办公管理经验三年以上,协调能力强 　　质管人员:熟悉ISO9000,至少有三年电子类质量管理工作经验 　　2-1-4 报到手续 　　经核定录用人员于报到日携带:一寸免冠照两张,学历证书及身份证复印件到人事 　　部报到办理就职手续 　　2-2 试用 　　新进员工试用期不超过三个月,试用期满由部门经理依据个人表现,提交是否转正,延期或辞退报告,由人事部报总经理审核批复 　　2-3 转正及合同签订 　　转正员工须与公司签订聘任合同.聘任合同一经签订,鉴证,双方必须严格执行. 　　2-4 离职 　　员工离职分为\"辞职,解雇,开除,自动离职\"四等(试用期内员工及公司双方均有权 　　提出辞职或解雇,而不负担任何补偿.离职前须与公司结清各项手续) 　　* 辞职:试用期过之后,职员辞职需提前一个月通知公司,到职日期结算工资,但不 　　结算任何福利 　　* 自动离职:凡无故擅自旷工三天以上者,均作自动离职论,不予结算任何工资,福 　　利 　　* 解雇: 工作期内,员工因工作表现,工作能力等因互不符合本公司要求,无法胜作 　　本职,公司有权解雇,', 545, NULL, '[\"公司\", \"-\", \"员工\", \"离职\", \"试用期\", \"经验\", \"能力\", \"辞职\", \"解雇\", \"手续\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:27', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:27', '0');
INSERT INTO `document_segments` VALUES ('1955803418257616898', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　* 解雇: 工作期内,员工因工作表现,工作能力等因互不符合本公司要求,无法胜作 　　本职,公司有权解雇, 届时结算工资及福利 　　* 开除: 员工因触犯法律,严重违犯公司规章制度或犯严重过失者,即予革职开除, 　　计薪到革职日止 　　2-5 内部调动 　　2-5-1 原则 公司根据工作需要,本着人尽其才发挥潜力的原则,鼓励合理的人才内 　　部流动 　　2-5-2 程序 　　* 员工填写《员工内部调动申请》 　　* 本部门及用人部门经理审批 　　* 人事部报总经理批准 　　2-6 晋升 　　2-6-1 依据 业绩突出,并具有进一步发展潜力及献身精神 　　2-6-2 程序 　　* 由上一级主管提名管理层审核总经理批准 　　* 发文任命由人事部备案通知各部门 　　2-7 培训 　　2-7-1培训政策:培训是一种人力资源的投资,公司将培训机会更多地给予工作表现 　　出色,具有较大潜力职员 　　2-7-2公司将不断培训职员,如英文,计算机专业培训等 　　2-7-3参加培训前提:工作表现出色,有进一步发展潜力,忠诚献身公司 　　2-7-4培训协议:若参加投资大的培训,应与公司签订培训协议,包括服务年限和服 　　务期未满需补偿条款等(具体参考聘任合同中的《培训协议》) 　　2-8 奖惩条例 　　2-8-1公司将根据员工工作业绩及表现于每季度末进行一次业绩评估,并分三等级(优', 591, NULL, '[\"-\", \"公司\", \"培训\", \"工作\", \"员工\", \"表现\", \"业绩\", \"协议\", \"开除\", \"潜力\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:27', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:27', '0');
INSERT INTO `document_segments` VALUES ('1955803418299559937', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　2-8 奖惩条例 　　2-8-1公司将根据员工工作业绩及表现于每季度末进行一次业绩评估,并分三等级(优 　　秀,良好,较差),并在经济上给予不同奖励,办法如下: 　　优秀 500元 　　良好 200元 　　较差 5元 　　具体评估由人力部及部门经理考核打分报总经理批复 　　2-8-2 对工作成绩持续不佳及违纪员工,视情况给以经济惩罚,留职查看直至解除 　　劳动合同处分,具体内容如下: 　　序 号 违 纪 内 容 处 罚 办 法 　　1 上班擅离职守,串岗 口头警告 　　2 上班时睡觉,吃零食,看无关书刊,洗澡 口头警告 　　3 未经批准,擅自变动一下班时间或缩短工作时间 口头警告 　　4 不服从主管指令,工作调动 书面警告 　　5 未经批准擅自休假 按旷工处理并书面警告 　　6 虚报冒领,似造证明(伙造病假单,发票及虚报加班等)隐瞒事故实情,谎 　　报情报,诬陷他人 书面警告,辞退,或开除并追究经济损失 　　7 请假期间在外谋他职 矢退,或开除并追究经济损失 　　8 破坏公物随地吐痰,乱扔纸屑 口头警告,并按公物价值和造成的损失价值 　　赔偿 　　9 公共场所吵闹,干扰正常工作 口头警告 　　10 打架斗殴,妨碍执行公务 书面警告或辞退 　　11 滥用职权报复处罚职员,对于犯有违纪行为的职员不作处理的 口头警告, 　　或辞退 　　12 渎职或因其它原因,严重损害公司声誉', 596, NULL, '[\"警告\", \"口头\", \"工作\", \"辞退\", \"员工\", \"报\", \"评估\", \"处理\", \"差\", \"良好\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:27', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:27', '0');
INSERT INTO `document_segments` VALUES ('1955803418345697281', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '口头警告, 　　或辞退 　　12 渎职或因其它原因,严重损害公司声誉 书面警告,或辞退 　　13 违犯外事纪委败坏国家和公司声誉利益 辞退,或开除并追究经济损失 　　14 违犯社会治安管理条例和国家政策 书面警告,或辞退 　　15 盗窃公司财物 开除并追究经济损失 　　16 触犯国家法律 开除,追究经济损失并依法惩处 　　第三部分 考勤制度 　　3-1公司统一实行每周五天工作制(星期六,日休息) 　　3-2公司作息时间: 　　夏季(5/1-----10/1) 　　早: 8:00-----12:00 　　下: 14:30-----18:00 　　冬季 (10/1---5/1) 　　早: 8:30-----12:00 　　下: 13:00-----17:30 　　3-3全体员工不得迟到,早退,旷工 　　3-4每月迟到不得超过两次,每次不得超过10分钟,凡超过10分钟,每分钟罚款两 　　元,依此类推,第三次起凡超过半小时,按旷工半天论处,早退与迟到处罚相同 　　3-5旷工一天倒扣三天基本工资,旷工三天以上者,从第四天起 视作自动离职,不予 　　结算任何工资福利 　　3-6全月按规定之工作日上班,无迟到,早退,旷工及加班缺勤 者为全勤,全勤奖金 　　100元 　　3-7未转正员工不享受全勤奖 　　3-8如因工作需要,公司要求员工于正常工作时间外超时工作时,各员工皆不得找藉 　　词推搪,应以工作为主,发扬良好服务精神', 613, NULL, '[\"-\", \"公司\", \"员工\", \"工作\", \"旷工\", \"辞退\", \"迟到\", \"国家\", \"早退\", \"警告\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:27', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:27', '0');
INSERT INTO `document_segments` VALUES ('1955803418404417537', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　词推搪,应以工作为主,发扬良好服务精神 　　3-9对经各部门经理批准安排超时工作员工,均给予调休或发加班费 　　3-10职员请假须由本人填写假条,经主管批准后方可离开,无特殊原因不可电话,捎 　　话请假 　　3-11职员请假三天之内由部门经理批准,三天以上由总经理批准,各部门经理请假, 　　一律由总经理批准 　　3-12公司设考勤员,员工上班须自觉到考勤员处签到,如不作签到视旷工处理 　　3-13月末财务部根据考勤记录核发工资 　　第四部分 薪资及福利 　　4-1薪资 　　4-1-1 原则 岗位职责 　　劳动力市场价格 　　教育背景 　　工作经验 　　业绩成果 　　司 龄 　　4-1-2 结构 　　月收入:基本工资+午餐补贴+全勤奖+效益奖金 　　(效益奖金:公司综合各部门月工作效益以各部门为单位提取比例) 　　年收入:12月收入+年终奖金 　　4-1-3 公司依岗位职责将工资划分五岗,每岗参考教育背景, 　　工作经验,业绩成果,司龄等分A,B,C三等级,具体标准如下: 　　岗位 职务 等级 基本工资 　　一岗 总经理 总工程师 　　副总经理 财务总监 　　其它董事会直接聘任人员 A 30-35档 　　B 25-30档 　　C 20-25档 　　二岗 总经理助理 高级顾问 　　副总工程师 部门总监 　　高级文秘 A', 568, NULL, '[\"-\", \"工作\", \"批准\", \"岗\", \"总经理\", \"公司\", \"部门\", \"A\", \"请假\", \"基本工资\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:27', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:27', '0');
INSERT INTO `document_segments` VALUES ('1955803418450554881', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　B 25-30档 　　C 20-25档 　　二岗 总经理助理 高级顾问 　　副总工程师 部门总监 　　高级文秘 A 25-30档 　　B 20-25档 　　C 15-20档 　　三岗 部门经理 高级(项目 　　主管程序员,系统分析员, 　　营销人员,会计,经济师等) A 20-25档 　　B 15-20档 　　C 10-15档 　　四岗 程序开发人员 　　工程技术人员 　　市场销售人员高级文员 会计 A 15-20档 　　B 10-15档 　　C 8-10档 　　五岗 文员 库管 物流 　　出纳司机 电工 A 10-15档 　　B 8-10档 　　C 6-8档 　　说明:每档以RMB100元计 　　A等: 　　* 博士,高工,五年以上工作经验,司龄不少于三年 　　* 本科以上学历或有中级职称,五年以上工作经验,司龄不少于五年 　　B等: 　　* 博士,高工,三年以上工作经验,司龄不少于一年 　　* 本科以上学历或有中级职称,三年以上相关工作经验.司龄不少于二年 　　* 专科以上学历,五年以上工作经验,司龄不少于五年 　　C等:专科学历以上,一年以上工作经验,司龄不少于一年 　　* 上述每岗各等级工资标准,如有特殊情况,一岗职员的工资由董事会决定,二, 　　三岗职员的工资由总经理决定并报董事会备案 ,四,五岗职员的工资由经理 　　办公会决定,报请总经 理批准后核发 　　*', 596, NULL, '[\"岗\", \"-\", \"A\", \"C\", \"高级\", \"B\", \"少于\", \"人员\", \"司龄\", \"经验\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:27', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:27', '0');
INSERT INTO `document_segments` VALUES ('1955803418496692225', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, ',四,五岗职员的工资由经理 　　办公会决定,报请总经 理批准后核发 　　* 公司新聘人员,试用期满后,原则上从各岗位起始档开始支付基本工资. 　　* 对于在公司各项考核中成绩优异,受到嘉奖的职员,工资可上浮一档,对于成 　　绩不合格,或受到公司处分的职员工资可下浮一档或重新试用 　　* 原则上对公司四,五岗的正式职工在公司工作每满一年工龄,重新审定一次工 　　资,由经理办公会决定是否给予升档.对于收入达到或超过本岗位平均档的职 　　员,其每年晋升与否由总 经理决定 　　* 对于试用期人员,无论资历或岗位一律定为4档(特殊情况经总经理批准例外) 　　* 本标准的解释权归经理办公室 　　4-1-4支付方式 　　每月5日现金支付 　　4-2福利 　　4-2-1住房: 　　4-2-1-1 租房(暂定) 　　* 条件:对现时经公司核实确需解决住房的正式职员(家在西安的单身职工,已婚 　　且一方有房职员或已有住所的职员均不在考虑之列)可申请集体租房,经 　　总经理批准后办理 　　* 租金支付:公司负担月租金的50%,个人负担月租金的50% 　　* 租房标准:城区标准单元套房,交通费自负 　　* 人员限制:每单间不超过2人 　　4-2-1-2 住房公积金 　　* 是职工及其所在单位按规定缴存的具有保障性和互助性的职工个人住房基金,归', 568, NULL, '[\"公司\", \"职员\", \"职工\", \"经理\", \"-\", \"人员\", \"租房\", \"岗位\", \"批准\", \"决定\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:27', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:27', '0');
INSERT INTO `document_segments` VALUES ('1955803418547023874', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　4-2-1-2 住房公积金 　　* 是职工及其所在单位按规定缴存的具有保障性和互助性的职工个人住房基金,归 　　职工个人所有,职工离职时本息余额一次结清,退还职工本人 　　* 住房公积金定向用于: 　　- 员工购买,建造,大修理自住住房抵押贷款 　　- 城市经济适用住房专项贷款 　　- 单位购买,建造员工住房专项贷款 　　* 公积金来源方式:员工每月交纳其基本工资的5%,公司付给员工月基本工资5%, 　　这笔积金将存入房产服务公司为个人所设的帐户中,按规定备用 　　* 与公司正式签约的正式职员有权申请参加此项计划 　　* 公司5%款项的提取按参加公积金计划的年限而定 　　参 加 年 限 提 取 比 例 　　0-----5年 5% 　　5-----20xx年 10% 　　10-----20xx年 15% 　　15-----20xx年 20% 　　20-----20xx年 25% 　　25-----30年 30% 　　4-2-2 医疗合作基金制度 　　* 基金来源:职员交纳月基本工资2.5%(由财务直接从职员工资中扣除),公司支 　　付职员月基本工资总额的2.5%作为公司职工月医疗合作基金.专项储备,专款专 　　用.用完为此. 　　* 基金管理:由职员选定代表成立基金管理委员会单设帐户统一管理,由财务部监 　　督执行 　　* 医疗费报销办法 　　-', 583, NULL, '[\"%\", \"职工\", \"-\", \"基金\", \"职员\", \"公司\", \"公积金\", \"住房\", \"员工\", \"基本工资\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:27', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:27', '0');
INSERT INTO `document_segments` VALUES ('1955803418597355522', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　* 基金管理:由职员选定代表成立基金管理委员会单设帐户统一管理,由财务部监 　　督执行 　　* 医疗费报销办法 　　- 医疗费用不论大小须经职工选定的基金管理委员会初步审核,报总经理签字由 　　财务部具体办理 　　- 职员报销时普通门诊必须持市级以上医疗病历,处方,发票等单据,经基金委 　　员会及总经理审批后方可报销,累计最高限额不得超过职工年交纳基金的3倍 　　- 除普通门诊外的医疗费,如职员住院等大额医疗费用按进入司年限长短承担比 　　例费用,标准如下: 　　年 限 医疗基金负担 个人负担 　　5年以下 60% 40% 　　5年以上 70% 30% 　　20xx年以上 80% 20% 　　20xx年以上 85% 15% 　　* 下列费用不予报销 　　- 各类滋补药品,保健药品,贵重药品等 　　- 因打架,斗殴,美容,及违犯计划生育政策所致费用 　　- 未经主管批准在市级以下医院就诊,住院者 　　- 未经批准自行外购药等 　　- 病历,处方,发票手续不全者 　　4-2-3 休假 　　* 可享受的带薪假日 　　- 法定假日(七天) 　　- 婚假三天 　　- 丧假:直系一天(配偶,子女,父母,公婆,岳父母) 　　非直系半天(兄弟,姐妹,姐夫,妹夫,兄嫂,弟媳, 　　祖父母,外祖父母,孙子女,外孙子女,儿媳) 　　- 产假:女方90天 男方2天 　　-', 585, NULL, '[\"-\", \"费用\", \"报销\", \"医疗\", \"基金\", \"职员\", \"子女\", \"管理\", \"总经理\", \"财务\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:27', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:27', '0');
INSERT INTO `document_segments` VALUES ('1955803418651881474', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　祖父母,外祖父母,孙子女,外孙子女,儿媳) 　　- 产假:女方90天 男方2天 　　- 哺乳假:每天有一小时的哺乳时间,可晚上班一小时或早下班一小时,工资,福利 　　及补贴按100%发给 　　- 年假:服务满一年的员工可享受10天年休假 　　- 工伤假:工伤期间工资及一切福利,补贴按100%发给 　　* 病假期间的工资支付:在国家规定的医疗期内福利补贴按100%发给 　　- 工龄满3年工资按70%发放 　　- 工龄满3---5年工资按80%发放 　　- 工龄满5年以上工资按90%发放 　　4-2-4 正式职员申请可享受公司每年提供的常规体检一次 　　4-2-5 全勤员工月午餐补贴120元 　　4-2-6 员工生日公司将为其订做贺卡一张,生日蛋糕一个以示祝福. 　　第五部分 差旅报销办法 　　5-1 原则: 　　差旅费用实行总额包干,节约归己,超支不补 　　5-2 标准: 　　级别 地区 交通费 住宿费 餐费 业务费 　　经理级以上 沿海城市 实支 实支 实支 实支 　　内陆城市 实支 实支 实支 实支 　　部门经理以上 沿海城市 实支 250元/天 实支 实支 　　内陆城市 实支 150元 　　/天 100元/天 实支 　　普通员工 沿海城市 实支 150元/天 80元/天 实支 　　内陆城市 实支 100元/天 80元/天 实支 　　说明: 　　* 职员出差前应填写出差申请单,出差期限由派遣主管视情况事先核准 　　*', 621, NULL, '[\"-\", \"工资\", \"补贴\", \"%\", \"职员\", \"福利\", \"员工\", \"享受\", \"公司\", \"出差\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:27', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:27', '0');
INSERT INTO `document_segments` VALUES ('1955803418698018818', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '100元/天 80元/天 实支 　　说明: 　　* 职员出差前应填写出差申请单,出差期限由派遣主管视情况事先核准 　　* 出差人员持标准的申请单可向财务部借相应数额的差费,出差回来后必须在一周内 　　填写出差报销单并结清手续.如无特殊情况又未能在一周内结清差费财务部有权暂 　　停支付其工资,等报销完再核付 　　* 出差人员可乖坐火车,轮船,飞机等交通工具,由派遣主管根据任务需要在出差申 　　请单中审定,费用实报实销 　　* 出差期间因公支出下列费用,可实报实销 　　-乖坐出租车按发票面值 　　-因公长途电话费按电信局收据为凭 　　-因公宴客费用,按正式发票为准 　　第六部分 安全卫生 　　6-1 公司内严禁吸烟 　　附: 公司禁烟通知 　　自 年 月 日起严禁在公司,办公场所,上班时间内吸烟.违者一次罚款人民币50元, 　　当场付清.如经理办,市场部,会议室有客户要求吸烟者,仅限在本部办公室内,公 　　司职员不得陪抽,如违反,按规定处罚! 　　6-2 非电气作业人员不得装拆修理电气设备 　　6-3 爱护公司公物,注重所有设备的定期维修保养,节约用水,用电,易耗品 　　6-4 养成卫生,不随地吐痰,不乱丢纸屑,烟头,杂物,如在公共场所发现有纸屑, 　　杂物等,应随时捡起放入垃圾桶,保持公司清洁 　　6-5 应急电话:', 566, NULL, '[\"-\", \"出差\", \"公司\", \"人员\", \"费\", \"费用\", \"吸烟\", \"办公\", \"因公\", \"职员\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:27', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:27', '0');
INSERT INTO `document_segments` VALUES ('1955803418748350465', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　杂物等,应随时捡起放入垃圾桶,保持公司清洁 　　6-5 应急电话: 　　市内触电急救:7215449 市内伤病急救:7213460 火警: 119 匪警: 110 　　第七部分 保密 　　7-1总则 　　7-1-1公司秘密是关系公司权力和利益,在一定时间内只限一定范围的人员知悉的事 　　项 　　7-1-2公司全体职员都有保守公司秘密的义务 　　7-2保密范围 　　7-2-1经营信息 　　* 公司重大决策中的秘密事项 　　* 公司尚未付诸实施的经营战略,经营方向,经营规划,经营项目及经营决策 　　* 公司内部掌握的合同,协议,意向书及可行性报告,主要会议记录 　　* 供销情报及客户档案 　　* 公司财务预决算报告及各类财务报表,统计报表 　　* 公司所掌握的尚未进入市场或尚未公开的各类信息 　　* 公司职员人事档案,工资,劳务性收入及资料 　　* 公司内部管理制度 　　7-2-2技术信息 　　* 各类技术资料 　　* 职员在工作期间完成的技术成果及著出的论文,著作,书籍或在工作期间 　　总结,觉察到信息均属公司 　　7-2-3其他经公司确定应当保密的事项 　　7-3公司秘级的确定 　　7-3-1公司经营发展中,直接影响公司权益的重要决策文件及技 术信息资料为绝密 　　级', 544, NULL, '[\"公司\", \"-\", \"信息\", \"经营\", \"职员\", \"决策\", \"秘密\", \"资料\", \"报告\", \"保密\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:27', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:27', '0');
INSERT INTO `document_segments` VALUES ('1955803418794487810', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　7-3-1公司经营发展中,直接影响公司权益的重要决策文件及技 术信息资料为绝密 　　级 　　7-3-2公司的规划,财务报表,统计资料,重要会议记录,客户资料,经营状况,管 　　理制度等为机密级 　　7-3-3公司人事档案,合同,协议,职员工资,尚未进入市场或尚未公开的各类信息 　　为秘密级 　　7-4保密措施 　　7-4-1属于公司秘密的文件,资料和其它物品的制作,收发,传递,使用,复制, 　　摘抄,保存和销毁,由经理办专人执行 　　7-4-2对于密级的文件, 资料和其他物品,必须采取以上保密措施: 　　* 非经总经理或主管副总经理批准,不得复制和摘抄 　　* 收发,传递和外出携带,由指定人员担任,并采取必要的安全措施 　　* 在设备完善的保险装置中保存 　　7-4-3属开公司秘密的设备或产品的研制,使用,保存,维修,销毁,由公司指定 　　专门部门负责执行,并采用相应的保密措施 　　7-4-4在对外交往与合作中需要提供公司秘密事项的,应当事先经总经理批准 　　7-4-5不准在私人交往和通信中泄露公司秘密,不准在公共场所谈论公司秘密,不 　　准通过其他方式传递公司秘密', 492, NULL, '[\"公司\", \"-\", \"秘密\", \"措施\", \"中\", \"保存\", \"密级\", \"保密\", \"文件\", \"传递\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:27', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:27', '0');
INSERT INTO `document_segments` VALUES ('1955803418844819458', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　准通过其他方式传递公司秘密 　　7-4-6公司工作人员发现公司秘密已经泄露或者可能泄露时,应当立即采取补救措 　　施并及时报告总经理办公室 　　7-5责任与处罚 　　7-5-1出现下列情况之一者,给予警告,并扣发工资10-500元 　　* 泄露公司秘密,尚未造成严重后果或经济损失 　　* 已泄露公司秘密但采取补救措施的 　　7-5-2出现下情况之一的,给予辞退并酌情赔偿经济损失直至追究法律责任 　　* 故意或过失泄露公司秘密,造成严重后果或重大经济损失 　　* 违反本保密制度规定,为他人窃取,刺探,收买,或违章提供公司秘密的 　　* 利用职权强制他人违反保密规定的 　　第八部分 行为规范 　　您的仪容: 　　衣着整洁 　　修饰大方 　　精神饱满 　　您上班时: 　　不迟到 不串岗 　　不怠工 不务私 　　您下班时: 　　不早退 不拖拉 　　关好水电门窗 　　保证安全 　　您打电话时: 　　不闲谈 　　不泄密 　　您接电话时: 　　先答\"您好,亚桥公司\" 　　您开会时: 　　准时到场 　　认真记录 　　积极参与 　　您与同事们: 　　不过问工资,奖金及其它机密事宜 　　不传递小道消息 　　主动关心和帮助别人的病痛疾苦及其它困难 　　第九部分 附则', 532, NULL, '[\"时\", \"公司\", \"秘密\", \"-\", \"泄露\", \"经济损失\", \"工资\", \"规定\", \"违反\", \"部分\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:27', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:27', '0');
INSERT INTO `document_segments` VALUES ('1955803418920316929', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　不传递小道消息 　　主动关心和帮助别人的病痛疾苦及其它困难 　　第九部分 附则 　　9-1《职员手册》为公司内部管理资料,属机密文件,职员只可借阅,不可抄袭,翻印,私存,泄露.如有泄密,公司将根据保密制度给予相应惩罚直至追究法律责任 　　9-2 本手册解释权归公司经理办公室 　　注:公司正式职员:指试用期满,与公司正式签订聘任合同5年以上的专职人员.(兼职,临时工,签约不足5年均为非正式职员) 员工手册范本 篇29 　　1、遵守国家政策，法令和公司一切规章制度，爱护公共财物认真执行岗位责任制。 　　2、应按公司规定的工作时间上下班，不得迟到、早退、不得擅离岗位，不得无故旷工。工作时间内不许闲谈作乐，不许吵嘴打闹，不许串岗位和离岗，不许做与生产无关的事。 　　3、服从生产工作安排、调动、努力钻研生产技术，提高自身素质水平，做好本职工作。 　　4、请病假、事假要有正当的理由，并写请假条办理审批手续。二天以下由生产主管批准，三天以上由公司经理审批。来不及自办手续的.要托人代办或打电话请假，并于上班后补办手续，批准后方能生效。否则违者作旷工处理，旷工一天扣款10元。', 488, NULL, '[\"公司\", \"职员\", \"生产\", \"工作\", \"岗位\", \"手续\", \"旷工\", \"不许\", \"-\", \"手册\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:27', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:27', '0');
INSERT INTO `document_segments` VALUES ('1955803418966454273', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　5、工作时间内，因事或因看病要离开岗位的，要向生产主管请假同意后方能离开，否则作早退处理，早退一次扣款5元。 　　6、不得带任何食品杂物入车间，不得在车间吃食物，不准在车间乱丢杂物及随地吐痰，违反本条例之一者扣款5元，严重者开除。 　　7、进入规定要穿工作服的工作间一定要穿工作服，违者扣款5元，严禁携带手表、首饰等个人物品进入生产区、接触产品的人员不得留长指甲或涂指甲油。 　　8、防蝇、防虫纱窗不得随意打开，发免影响生产环境卫生。 　　9、爱护公司财产，不得私带厂内任何物品出厂，违者则按物品价值的十倍罚款，重则开除。 　　10、运送产品，物资要小心轻放，不得乱掉重摔。造成损坏的由违纪者负全部责任（包括搬运工。） 　　11、吸烟要到后边的吸烟区。 员工手册范本 篇30 　　生鲜超市员工手册 　　第一章 总则 　　第一条 目的 　　为使本公司业绩蒸蒸日上，从而造就机会给每一位员工有所发展，严格的纪律和有效的规章制度是必要的。本手册将公司的员工规范、奖惩规定集一册，希望公司全体员工认真学习、自觉遵守，以为我们共同的事业取得成功的保证。 　　第二条 公司信念 　　2.1 热情一以热情的态度对待本职工作、对待客户及同事。 　　2.2', 521, NULL, '[\"员工\", \"公司\", \"款\", \"扣\", \"物品\", \"生产\", \"产品\", \"开除\", \"进入\", \"离开\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:27', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:27', '0');
INSERT INTO `document_segments` VALUES ('1955803419016785921', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　第二条 公司信念 　　2.1 热情一以热情的态度对待本职工作、对待客户及同事。 　　2.2 勤勉一对于本职工作应勤恳、努力、负责、恪尽职守。 　　2.3 诚实一作风诚实，反对文过饰非、反对虚假和浮夸作风。 　　2.4 服从一员工应服从上级主管人员的指示及工作安排，按时完成本职工作。 　　2.5 整洁一员工应时刻注意保持自己良好的职业形象，保持工作环境的整洁与美观。 　　第三条 生效与解释 　　3.1 本员工手册自公布之日起生效，由公司管理部门负责解释。 　　3.2 公司的管理部门有权对本员工手册进行修改和补充。修改和补充应通过布告栏内张贴通知的方式进行公布。 　　3.3 本员工手册印制成册，作为劳动合同的附件，并与劳动合同具有同等效力 　　第二章 录 用 　　第一条 录用原则 　　1.1 员工的招聘将根据公司的需要进行。 　　1.2 本公司采用公平、公正、公开的原则，招聘优秀、适用之人才，无种族、宗教、性别、年龄及残疾等区别。 　　1.3 本公司的招聘以面试方式为主。 　　第二条 录用条件 　　2.1 新聘员工一般实行试用期制度，试用期限按地方政府和劳动合同的有关规定予以确定。 　　2.2 试用期满考核 　　2.2.1新聘人员试用期满前，由各部门主管进行考核，考核合格者正式录用。试用期内如发现不符合录用条件的，可随时依法解除劳动合同。 　　2.2.2', 586, NULL, '[\"员工\", \"公司\", \"应\", \"试用期\", \"进行\", \"录用\", \"劳动合同\", \"招聘\", \"本职工作\", \"手册\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:27', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:27', '0');
INSERT INTO `document_segments` VALUES ('1955803419058728961', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　2.2.2 试用人员试用合格，其工龄自试用起始之日起计算。 　　2.3 以下情况均将被视为不符合录用条件： 　　曾经被本公司开除或未经批准擅自离职者; 　　判处有期徒刑，尚在服刑者; 　　被剥夺公民权力者; 　　通辑在案者; 　　经公司指定医院体检不合格者; 　　未满16周岁者; 　　有欺骗、隐瞒行为者; 　　患有精神病或传染病者; 　　酗酒、吸毒者; 　　不具备政府规定的就业手续者; 　　亏空、拖欠公-款尚未清偿者; 　　工作能力不符合要求者; 　　曾担任课长及以上职务因任何原因离开本公司者;(经中国区总裁特批除外) 　　第三条 录用程序 　　3.1 各部门主管可以根据本部门发展或职位空缺情况，协同人力资源部进行招聘。 　　3.2 公司指定应聘人员，实行体检制度。 　　3.2.1 公司指定应聘人员在试用期开始以前都必须在公司指定的医院进行指定项目的体检，并向人力资源部出示体检证明。只有经证明其健康状况适合工作者，才可依照劳动合同被公司录用。 　　3.2.2 公司指定的员工应当进行年度体检，以保证公司的全面卫生质量。如员工患传染病，将被调任其他职位或在治疗期间暂停工作。 　　3.2.3 公司指定体检的员工，可凭医院体检原始发票在试用期满后向公司报销其体检费. 　　3.3 新录用人员报到应先到人力资源部办理下列手续：', 568, NULL, '[\"公司\", \"体检\", \"指定\", \"录用\", \"人员\", \"人力资源部\", \"员工\", \"传染病\", \"符合\", \"情况\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:27', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:27', '0');
INSERT INTO `document_segments` VALUES ('1955803419104866305', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　3.3 新录用人员报到应先到人力资源部办理下列手续： 　　如实填写相关人事资料表格; 　　递交体检合格证明书原件; 　　核对并递交学历证书原件; 　　核对并递交身份证原件、当地政府规定的各类就业证件原件，各项社会保障的转移手续; 　　交一寸的半身照片3张; 　　需要办理的其他手续; 　　3.4 新录用员工报到后，公司凭其提供的合法用工证明与其签署劳动合同书。在试用期满之前，3.3条款所规定手续仍无法齐备的，将被视为不符合录用条件，依照政府相关规定，公司与其解除劳动关系，并不支付经济赔偿。 　　3.5 所有员工个人情况如住址、婚姻状况、生育状况、紧急情况通知人发生变化时，应于七日内通知人力资源部。 　　第四条 录用禁忌 　　4.1 本公司实行亲属回避制度。 　　4.1.1 凡在本公司有亲属关系的应当如实申报，否则将视为欺骗行为。 　　4.1.2 一般情况下员工的亲属(如父母、配偶、子女、兄弟姐妹等)不得被公司雇佣，但在特殊情况下，经店长或区经理批准可以雇佣。 　　4.1.3 如员工与公司另一名员工结婚，则管理部门可以调动任何一方的工作部门或工作地点。 　　4.2 公司是员工唯一的雇主。 　　4.2.1', 509, NULL, '[\"公司\", \"员工\", \"手续\", \"录用\", \"规定\", \"情况\", \"原件\", \"相关\", \"如实\", \"视为\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:27', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:27', '0');
INSERT INTO `document_segments` VALUES ('1955803419155197953', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　4.2 公司是员工唯一的雇主。 　　4.2.1 员工在为公司服务期间不得在其他任何公司或机构从事兼职或专职工作;未经批准，员工不得为其他任何公司或机构从事商业活动，即使是无偿的。 　　4.2.2 员工希望为其他个人、企业、各类机构临时工作，应该获得公司事先书面批准。公司有权随时撤销上述批准。 　　4.2.3 未经批准，职工首次接受其他报酬时，亦将被视为其主动向公司提出辞职。 　　第三章 服 务 　　第一条 服务原则 　　1.1 恪尽职守，勤奋工作，高质量地完成工作任务。 　　1.2 不仅从语言上，更从行动上向客户(公司外部及内部)表明：客户的需求就是我们的需求。 　　1.3认真听从上级主管人员的工作指示和教导。对于职务报告，应遵循逐级向上报告的原则，不宜越级呈报，但在紧急或特殊情况下不在此限。上下级之间应诚意相待，彼此尊重。 　　1.4 正确、有效、及时地与同事、与其它部门沟通意见看法。遇到问题不推卸责任，共同建立互信互助的团队合作关系 　　1.5 专精业务知识和技能，开发自身潜力，表现出主动参与、积极进取的精神。 　　第二条 遵循商业道德 　　2.1 公司永续健康的经营发展，取决于每位员工的态度和行为符合公司的期望。每位员工紧记自己代表公司，在任何地点、时间都注意维护公司的形象和声誉。 　　2.2', 560, NULL, '[\"公司\", \"工作\", \"员工\", \"主动\", \"原则\", \"应\", \"批准\", \"机构\", \"服务\", \"未经\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:27', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:27', '0');
INSERT INTO `document_segments` VALUES ('1955803419226501122', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　2.2 不论是销售公司产品或提供服务，或是向供应商购买产品或服务，应完全以品质、价格与服务为决策的依据，不得给予或接受个别客户或客户代表相关的报酬、赠品或其他特殊待遇。 　　第三条 日常行为规范 　　3.1 员工应礼貌待客、举止得体： 　　3.1.1 礼貌地对待客户及来访者; 　　3.1.2 与客人交谈应态度和蔼，注意使用礼貌用语，禁止工作时言语粗鲁; 　　3.1.3 对客人提出的询问和要求要耐心的解答，解答不了的问题，应及时请示汇报; 　　3.1.4 与客人相遇，要主动让路;与客人同行，应礼让客人先行; 　　3.2 员工应注重仪表整洁： 　　3.2.1 员工必须身着制服进入工作现场，制服必须保持清洁，熨烫平整; 　　3.2.2 员工的指甲必须修理好并保持清洁，女性除淡色指甲油外，不得涂指甲油; 　　3.2.3 男员工不得留胡须; 　　3.2.4 男员工不得佩带耳环，女员工佩带的耳环两侧须一致; 　　3.2.5 仪表不整的员工，不得进入工作现场，并做缺勤处理; 　　3.3 员工上班时必须佩带姓名卡： 　　3.3.1 姓名卡被视为制服的一部分，上班时必须佩带在制服的左上方; 　　3.3.2 如员工丢失姓名卡，必须立即向人力资源部报告; 　　3.3.3 员工不得佩带他人的姓名卡，否则立即受到违纪处分; 　　3.3.4 姓名卡是公司的财产，员工在结束雇佣时，必须交还人力资源部，否则将赔偿五十元人民币; 　　第四章 工 时 　　第一条 标准工时 　　1.1', 636, NULL, '[\"员工\", \"应\", \"必须\", \"时\", \"客人\", \"佩带\", \"工作\", \"制服\", \"客户\", \"礼貌\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:27', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:27', '0');
INSERT INTO `document_segments` VALUES ('1955803419272638466', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　第四章 工 时 　　第一条 标准工时 　　1.1 员工平均每周工作40小时。标准工作时间不包括用餐时间和加班时间。 　　1.2 由于公司的经营性质，周六和周日为正常工作日： 　　1.2.1 员工每周的休息日由部门主管根据本部门排班情况确定; 　　1.2.2 部门主管人应提前安排员工的休息日并通知员工; 　　1.3 员工应当按照部门主管制定的工作时间表进行工作和轮休，拒不遵守的员工将作旷职处理。 　　第二条 特殊工时 　　符合国家规定的，公司还可实行综合计算工时制和不定时工时制。 　　第三条 加班 　　3.1 根据<<劳动法>>有关规定，在不损害员工利益的前提下，公司有权根据工作和经营需要安排员工加班。 　　3.1.1 员工是否加班及加班时数须经由部门主管在”加班审核表”上签字后方可确认。 　　3.1.2 申报加班的最小单位为1小时。 　　3.2.员工加班，享受以下待遇： 　　3.2.1普通工作日员工加班的，公司安排调休或支付不低于工资百分之一百五十的工资报酬。 　　3.2.2 休息日员工加班的，公司安排调休或支付不低于工资百分之二百的工资报酬。 　　3.2.3 法定休假日员工加班的，支付不低于工资百分之三百的工资报酬。 　　3.2.4 员工本月加班的，公司应于下月月底前安排调休;如遇特殊情况无法调休的，将在3个月内安排调休。 　　3.3', 579, NULL, '[\"员工\", \"加班\", \"公司\", \"安排\", \"工作\", \"工时\", \"主管\", \"部门\", \"休息日\", \"规定\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:27', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:27', '0');
INSERT INTO `document_segments` VALUES ('1955803419322970114', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　3.2.4 员工本月加班的，公司应于下月月底前安排调休;如遇特殊情况无法调休的，将在3个月内安排调休。 　　3.3 实行不定时工时制的员工，不再执行加班制度。 　　3.4 以下情况不视为加班： 　　公司在节假日组织的郊游及其他娱乐活动; 　　公司在非节假日组织的下班后的娱乐活动; 　　出差时路途所花费的时间; 　　在非工作时间组织的培训; 　　办公室管理人员，未经上司指派或同意的日工作时间的延长。 　　第五章 考 核 　　第一条 考核的类型 　　1.1 本公司员工的考核可分为考勤与考绩。 　　1.2 考绩分为试用考核、年终考核。 　　1.3 员工考核记录将作为转正、升迁、调薪、核发年终奖金及惩处的依据。 　　第二条 考勤制度 　　2.1 员工应每天打卡以记录出勤时间。 　　2.1.1 员工在到达公司后或离开岗位前应着制服打卡。 　　2.1.2 员工如果未按规定打卡，将视为缺勤，并扣除相应工资。 　　2.1.3 任何员工不得代为其他员工打卡，否则将被视为较重违纪行为。 　　2.1.4 员工应对考勤卡妥善保管，如有遗失，应立即前往人力资源部申请补办。 　　2.1.5 员工因公司业务需要外出办事而不能进公司的，应该事先填写“外出工作时间表”并由部门主管签字，回公司后应即将“外出工作时间表”交人力资源部确认。 　　2.2 员工应准时上班，不得迟到、早退、旷职： 　　2.2.1', 595, NULL, '[\"员工\", \"公司\", \"应\", \"时间\", \"工作\", \"卡\", \"视为\", \"外出\", \"组织\", \"考核\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:27', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:27', '0');
INSERT INTO `document_segments` VALUES ('1955803419364913153', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　2.2 员工应准时上班，不得迟到、早退、旷职： 　　2.2.1 工作时间开始后15分钟内到班者为迟到; 　　2.2.2 工作时间终了前15分钟内下班者为早退; 　　2.2.3 工作时间开始后或结束前15分钟到4小时内到班或下班者，以旷职半天论;4个小时之外到班或下班者以旷职1天论; 　　2.2.4 员工当月内迟到、早退合计三次，即使累计时间不超过15分钟，也以旷职半天论; 　　2.2.5 未经请假或假满未经续假而擅自不到职，根据实际缺勤天数按旷职处理; 　　2.2.6 擅离工作岗位，按旷职处理; 　　2.2.7 旷职期间，工资不发; 　　2.3 公司将根据考勤纪录实行奖惩，具体办法参考第十三章 　　2.4 员工在年内的考勤记录将作为年终考核的依据。 　　第三条 考绩制度 　　3.1 考绩分为试用考核、年终考核。 　　3.1.1 试用考核：由部门主管考核试用人员，经评估合格后，报人力资源部审核予以正式录用。 　　3.1.2 年终考核：每年年底执行。由部门主管对部门员工先行考核后，呈人力资源部总评。 　　3.2 考绩内容包括(但不限于)员工的工作态度、工作能力、工作业绩、团队精神、遵纪情况等等。 　　3.3 考绩可分为以下等级： 　　杰出，工作成绩优异卓越，对组织、公司作出较大贡献; 　　优秀，全面完成工作成绩且在大多方面超出标准; 　　胜任，工作完成合乎要求，达到标准;', 595, NULL, '[\"工作\", \"旷职\", \"员工\", \"考核\", \"考绩\", \"早退\", \"公司\", \"人力资源部\", \"年终\", \"时间\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:27', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:27', '0');
INSERT INTO `document_segments` VALUES ('1955803419415244802', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　优秀，全面完成工作成绩且在大多方面超出标准; 　　胜任，工作完成合乎要求，达到标准; 　　需改善，尚有未达标准方面，但经努力可改进; 　　不合格、工作差等，经过提醒教导后仍未改善; 　　3.4 考绩结果为“需改善”或“不合格”的，均属“不能胜任工作”。 　　3.5 考绩工作由主管、经理根据员工的工作绩效，专业技能，工作态度以及全年的功过记录等以客观的态度予以评定。 　　第六章 薪 酬 　　第一条 工资构成 　　1.1 员工的工资总额由基本工资、奖金(其中出勤、表现、效益奖各占1/3)、津贴构成。 　　1.2 公司根据员工的职位性质、职责范围和个人表现确定员工的工资，员工的平均小时工资为其月基本工资除以167.4(员工平均每月工时)。 　　1.3 如果员工按时出勤，并能履行其工作职责，完成工作任务，遵守主管人员或其他上级的指示，则公司每年将根据公司当年效益情况，给予员工一定数额的奖金，是否给予奖金及奖金的具体数额将由部门主管决定。 　　第二条 工资支付 　　2.1 公司以货币形式按月支付员工的劳动报酬。 　　2.1.1 工资发放实行先做后付制度，即当月工资次月发放。 　　2.1.2 公司发薪日为每月5-7日，如遇公众假期，发薪日可提前或推后。 　　2.2', 536, NULL, '[\"员工\", \"工作\", \"工资\", \"公司\", \"标准\", \"改善\", \"职责\", \"奖金\", \"构成\", \"效益\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:27', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:27', '0');
INSERT INTO `document_segments` VALUES ('1955803419482353666', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　2.1.2 公司发薪日为每月5-7日，如遇公众假期，发薪日可提前或推后。 　　2.2 公司按规定从员工当月工资收入中扣除个人所得税，并代员工向政府税务部门缴纳。 　　2.3 本公司员工不得向他人泄漏自己月薪所得，亦不得询问本公司其他员工的月薪所得，违反此规定的员工应受到相应的警告，处分，情节严重者将导致解聘。 　　第七章 福 利 　　第一条 社会保险 　　1.1 公司依照国家和地方有关社会保险的规定为员工办理各项社会保险。 　　第二条 医疗福利 　　2.1 员工因工负伤或患职业病，患病或非因工负伤和在职期间因工、非因工死亡的待遇按国家和地方的有关规定执行。 　　2.2 员工患病或非因工负伤，公司可视具体情况，按当地有关政策执行。 　　2.3 员工享受国家规定的医疗期待遇。 　　2.4女职工在孕期、产期、哺乳期的待遇，按国家和地方有关规定执行。 　　2.5员工应享受的其他保险福利待遇按国家和地方有关规定执行。 　　第八章 假 期 　　第一条 假期类别 　　1.1公司的假期分为法定节假、婚假、丧假、年休假、补休假、病假、产假和事假。 　　1.2 除长病假外，公司给假以“工作日”计。 　　第二条 请假规则 　　2.1 所有休假应事先获得直接上级主管批准. 　　2.2 所有假别均应事先填写请假单， 按请假核准权限获批准后， 统一交人力资源部备存.', 580, NULL, '[\"公司\", \"员工\", \"规定\", \"假\", \"应\", \"国家\", \"地方\", \"工\", \"批准\", \"执行\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:27', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:27', '0');
INSERT INTO `document_segments` VALUES ('1955803419536879617', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　2.2 所有假别均应事先填写请假单， 按请假核准权限获批准后， 统一交人力资源部备存. 　　2.3 所有员工必须在休假完毕后立即至人力资源部办理销假手续。 　　第三条 法定节假日 　　3.1 员工每年享有共计十个工作日的法定休假： 　　元旦一天 　　春节三天 　　劳动节三天 　　国庆节三天 　　3.2公司可要求员工于法定节假日进行工作，并按照有关法律、本员工手册与劳动合同的规定支付报酬。 　　第四条 婚、丧假 　　4.1员工结婚给假3个工作日。符合计划生育晚婚的(男员工晚于25岁，女员工晚于23岁，或晚于政府规定的年龄)员工向公司提出申请，经批准后按当地政府有关规定执行。 　　4.1.1婚假工资照发，但须提前10个工作日向人力资源部提出书面申请并提供结婚证明。 　　4.1.2婚假只能在结婚日前或后1个月内使用。如遇特殊情况，须经店长或区经理特批。 　　4.2 如员工的父母、配偶或子女去世，凭医院《死亡通知书》，公司将给予员工最长三天的丧假。 　　4.2.1 员工如需请丧假，须提前通知人力资源部。 　　4.2.2 丧假期间工资照发。 　　第五条 年休假、补休假 　　5.1公司实行带薪年休假制度', 505, NULL, '[\"员工\", \"公司\", \"人力资源部\", \"休假\", \"工作日\", \"丧假\", \"规定\", \"结婚\", \"批准\", \"婚假\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:27', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:27', '0');
INSERT INTO `document_segments` VALUES ('1955803419583016962', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　4.2.2 丧假期间工资照发。 　　第五条 年休假、补休假 　　5.1公司实行带薪年休假制度 　　5.1.1员工为公司连续工作满一年以后，每年享有一次连续6个工作日的带薪年休假，年休假期间将支付基本工资、奖金和补贴。年休假允许拆零休假，年休假的休假时间按天计算，不足一天的按一天计算。 　　5.1.2普通员工需要年休，应当提前一周，向部门主管提出申请，获得2级批准后，方可休假;管理人员需年休，应当提前二周，向上级主管提出申请，获得2级批准后，方可休假。 　　5.1.3年休假需在一年内休完;它不予累计享用，也不折发酬金。 　　5.1.4为保证公司的日常有效运营，部门主管将提前为每位员工计划和安排休假日程。 　　5.1.5 员工在未得到公司事先同意情况下， 不得以年休假为理由离开工作岗位。 　　5.2公司实行补休假制度 　　5.2.1员工为公司连续工作满一年以后，每年享有6个工作日的补休假; 　　5.2.2员工请补休假需提前1周书面申请。 　　5.2.3补休假需在一年之内休完;它不予累计享用，也不折发酬金。补休假的休假时间按天计算，不足一天的按一天计算。 　　第六条 病假', 492, NULL, '[\"休假\", \"公司\", \"员工\", \"补\", \"提前\", \"休\", \"需\", \"主管\", \"部门\", \"申请\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:27', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:27', '0');
INSERT INTO `document_segments` VALUES ('1955803419650125825', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　第六条 病假 　　6.1员工每月可以享有一个工作日带薪病假。如果员工该月未休病假，则既不能累积，也无任何补偿。 　　6.1.1一个日历月中，员工请病假2个工作日及以上，自第2个工作日起，在扣除当月出勤奖后，按各地方政府规定计发病假工资。 　　6.1.2凡因重大病因须住院、手术者，工资按各地方政府规定发放，但须出具市级医院住院诊断证明。 　　6.2凡请病假，应在病假当天亲自或电话通知部门主管。并在病假结束返岗当天出具公司指定医院(急诊除外)的病假证明，由公司人力资源部予以审核归档。 　　第七条 产假 　　7.1女员工生育享有产假。 　　7.1.1单胎顺产休产假90天，从预产期前十五天至预产期后七十五天。配偶分娩给假1天。 　　7.1.2 24岁以上分娩头胎者，增加15天，其初婚配偶给假3天。 　　7.1.3难产多胎等根据各地方政府规定给假。 　　7.2所有女员工必须于孕后一个季度之内通知部门主管其怀孕状况。 　　7.2.1休产假必须于预产期前十周向人力资源部申请，并出示医院出具的妊娠证明。 　　7.2.2产假工资按各地方政府规定计发。 　　第八条 事假', 484, NULL, '[\"病假\", \"员工\", \"产假\", \"地方\", \"政府\", \"出具\", \"规定\", \"证明\", \"医院\", \"休\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:27', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:27', '0');
INSERT INTO `document_segments` VALUES ('1955803419696263169', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　7.2.2产假工资按各地方政府规定计发。 　　第八条 事假 　　8.1员工请事假应事先由部门主管批准，人力资源部审核，事先未得到批准的缺席，按旷职处理。 　　8.2事假期间工资不发。 　　第九章 培 训 　　第一条 培训目的 　　1.1通过培训，使员工达到并保持在本职工作岗位上进行规范服务的要求。 　　第二条 上岗培训 　　2.1上岗培训是指员工到岗后至试用期满前的业务培训。 　　2.2上岗培训内容主要包括： 　　部门职能与工作目标; 　　部门岗位结构和岗位职责; 　　岗位应知应会; 　　操作技能和工作程序; 　　本公司和本部门规章制度; 　　2.1.2上岗培训由各业务部门组织实施。 　　2.2上岗培训的考核结果与员工转正评定相结合。 　　第三条 在岗培训 　　3.1在岗员工业务培训由各部门按照年度培训计划实施。凡公司出资培训的，培训前员工应根据公司要求签订培训协议。 　　3.1.1在岗培训由各部门组织实施，人力资源部配合。必要时可委托有关单位来公司培训或组织有关员工参加公司外培训。 　　3.1.2在岗培训可采取岗位交叉培训、业务提高培训、新规范新技术培训等多种方式。', 493, NULL, '[\"培训\", \"员工\", \"部门\", \"公司\", \"岗位\", \"上岗\", \"在岗\", \"事假\", \"应\", \"组织\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:27', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:27', '0');
INSERT INTO `document_segments` VALUES ('1955803419742400514', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　3.1.2在岗培训可采取岗位交叉培训、业务提高培训、新规范新技术培训等多种方式。 　　3.2公司每年根据具体情况由人力资源部对现有主管以上人员进行培训。 　　3.2.1对管理人员的统一培训由人力资源部安排，组织实施。 　　3.2.2管理人员统一培训的内容包括管理理论、管理能力、管理技巧、新知识、新技能、等等。 　　3.2.3对管理人员的专项培训，由本部门或人力资源部提出专项申请，报店长或区经理批准执行。 　　3.3培训考核的资料应归档保存，作为晋升和奖惩的依据。 　　第四条 待岗培训 　　4.1待岗培训是指员工离开原岗位，列入编外，由人力资源部会同有关部门进行培训。 　　4.1.1待岗培训的内容为员工手册、规章制度、法律法规、业务技能等等。 　　4.1.2待岗培训期限一般为三个月，延长期限不得超过三个月。 　　4.2员工有下列行为之一，经教育无效，可列入待岗培训。 　　多次违反员工手册及公司和部门的规章制度，尚不足以辞退; 　　员工不能胜任本职工作，部门认为应待岗培训; 　　绩效考核中评定为不合格的; 　　4.3员工待岗培训按下列程序办理： 　　所在部门负责办理呈批手续;', 495, NULL, '[\"培训\", \"待岗\", \"员工\", \"部门\", \"人力资源部\", \"管理人员\", \"公司\", \"新\", \"应\", \"业务\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:27', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:27', '0');
INSERT INTO `document_segments` VALUES ('1955803419792732162', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　绩效考核中评定为不合格的; 　　4.3员工待岗培训按下列程序办理： 　　所在部门负责办理呈批手续; 　　由所在部门主管和人力资源部主管集体讨论决定; 　　店长或区经理批准执行。 　　4.4员工待岗培训期间待遇如下： 　　待岗期内，发基本工资，停发任何形式的奖金和津贴、补贴。 　　对延长待岗期三个月的，从延长期的当月起其基本工资逐月递减20%，但最低额不低于地方政府规定的最低生活费标准。 　　待岗培训员工不享有当年年休假。 　　4.5员工待岗培训考核合格，原则上安排回原部门，若原部门无法接收，公司将另行安排岗位，员工工资按新岗位重新确定，若员工不服从分配，公司可与员工终止合同。 　　4.6 待岗员工重新上岗后，若再次被列为待岗对象，可劝其辞职或作辞退处理。 　　第十章 调 动 　　第一条 调动种类与程序 　　1.1 调动是指在劳动合同规定的范围内的工作地点和职位级别的调整。 　　1.1.1 员工调动分为平行调动、晋升调动、降职调动和临时调动。 　　1.1.2 普通员工的调动主要是店内调动;管理人员的调动，除店内调动外也可以是店与店之间的调动。 　　1.1.3 员工没有可接受的理由，不得拒绝公司对其职位、工作地点的调动，否则以终止合同论。 　　1.2 任何调动必须按照规定的程序进行。 　　1.2.1', 558, NULL, '[\"员工\", \"待岗\", \"调动\", \"培训\", \"公司\", \"规定\", \"部门\", \"程序\", \"店\", \"基本工资\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:27', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:27', '0');
INSERT INTO `document_segments` VALUES ('1955803419838869506', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　1.2 任何调动必须按照规定的程序进行。 　　1.2.1 所有调动，都须经部门主管批准，交人力资源部备案，管理人员调动视级别不同须经店长或区经理批准。 　　1.2.2 公司对于进行内部转移的员工，给予相当于该员工在转出单位当月月工资2倍的搬家津贴，由转入单位承担。 　　第二条 平行调动 　　2.1平行调动是指在职位级别、薪酬不变情况下的职位变动。 　　2.2员工的调动取决于以下(但不限于)情况： 　　部门工作量的增减; 　　为员工职业生涯发展的需要，进行的职位轮换; 　　员工不能胜任现任职位; 　　工作急需; 　　新店开张; 　　其他原因; 　　第三条 晋升调动 　　3.1 晋升调动是指在职位级别或薪酬向上调整的职位变动。 　　3.2 员工同时具备下列条件的，有资格晋升到高职位： 　　员工在原职位表现优秀; 　　有担任高一级职位的能力和潜力; 　　完成晋升职位所必须的教育与培训; 　　诚实、正直、态度积极; 　　3.3 晋升调动可通过自荐或直接主管推荐，经2级批准，由经人力资源部的审核实施。 　　第四条 降职调动 　　4.1降职调动是指在职位级别或薪酬向下调整的职位变动。 　　4.1员工符合下列条件之一时，由上级主管建议，人力资源部批准，方可以降职。 　　4.1.1 不能胜任本职工作。 　　4.1.2', 561, NULL, '[\"员工\", \"调动\", \"职位\", \"批准\", \"晋升\", \"进行\", \"级别\", \"主管\", \"人力资源部\", \"变动\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:27', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:27', '0');
INSERT INTO `document_segments` VALUES ('1955803419889201153', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　4.1员工符合下列条件之一时，由上级主管建议，人力资源部批准，方可以降职。 　　4.1.1 不能胜任本职工作。 　　4.1.2 由于组织结构调整，相应职位被取消，没有合适的职位空缺。 　　4.2 降职人员从降职的次月起执行新职位的工资与福利标准。 　　4.3 降职调动应当从严掌握。 　　4.4 员工有权对降职调动提出异议，但公司一经决定，员工应当服从。 　　第五条 临时调动 　　5.1 如果一个部门的人员临时紧缺，经店长或区经理同意后，可以从其他部门临时调动人员。被临时调动的人员仍执行原职位的工资福利标准。 　　5.2 临时调动最长不超过一个月，否则该员工必须办理正式调转手续，工资福利按新职位标准执行。 　　第十一章 安 全 　　第一条 安全规则 　　1.1 禁止在仓库、卖场及其他工作场所吸烟。 　　1.2 禁止将任何东西堆放在安全门及安全通道前，以免阻塞。 　　1.3 未经保安部门允许，不得将非公司人员带入办公室或仓库。 　　1.4 所有员工必须保证自己及同事的安全，对任何可能引起危险的操作和事件要提出警告;严重的应报告部门主管。 　　1.5 员工必须熟悉本工作区内灭火装置的位置以及应急设备的使用方法。 　　1.6 员工在进行危险性工作或在危险地区工作，应佩带公司提供的防护服、防护工具。 　　1.7', 561, NULL, '[\"员工\", \"降职\", \"调动\", \"工作\", \"部门\", \"公司\", \"安全\", \"人员\", \"职位\", \"必须\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:27', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:27', '0');
INSERT INTO `document_segments` VALUES ('1955803419935338498', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　1.6 员工在进行危险性工作或在危险地区工作，应佩带公司提供的防护服、防护工具。 　　1.7 员工应遵守工具的安全操作说明;非工作执掌范围，不得擅自使用机器设备或机动车(叉车)。 　　1.8 公司禁止员工移动或拆除设备上的安全标识，禁止改装现有设备。 　　1.9 员工在各自的岗位区域内应积极参与处理意外事故，并服从统一调度。 　　1.10 员工有义务将任何安全事故上报。 　　第二条 火情处理 　　2.1 当火警发生时，应采取如下措施： 　　保持镇静，不要惊慌失措; 　　按动最近之火警报警器并通知值班人员和安全部门主管; 　　通知总机，说出火警发生的地点及火势大小; 　　呼唤最近的同事援助; 　　在安全的情况下，利用最近的灭火器材尽力将火扑灭; 　　切勿用水或泡沫灭火机扑灭因漏电而引起的火情; 　　把火警现场所有的门窗关闭，并关闭所有的电器开关; 　　2.2 如火势蔓延，应及时采取如下疏散措施： 　　疏散区按照防火区隔进行划分，由专人负责其所在区域的疏散工作; 　　听到广播后应立即组织撤离火警现场; 　　撤离火警现场时，切勿搭乘电梯，必须从消防梯疏散; 　　2.3 员工应参加火警演习，熟记火警讯号、火警通道、出入位置及灭火器具使用方法。 　　第三条 意外紧急事故 　　3.1 在紧急或意外情况下注意：', 559, NULL, '[\"火警\", \"应\", \"员工\", \"疏散\", \"安全\", \"最近\", \"使用\", \"工作\", \"公司\", \"灭火\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:27', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:27', '0');
INSERT INTO `document_segments` VALUES ('1955803419985670145', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　第三条 意外紧急事故 　　3.1 在紧急或意外情况下注意： 　　保持镇静，立即通知上级领导和保安部门; 　　协助维护现场; 　　与同事鼎力合作，务使公司业务保持正常进行; 　　3.2 如果员工在公司内受伤或发生事故，应当注意： 　　在场的员工应立即通知部门主管或值班经理; 　　协助救护伤病者; 　　自觉维护现场秩序; 　　3.3 如有人被关在电梯内，员工应立即电话通知安全部门和维修部门，由其操作电梯紧急程序。 　　第四条 及时汇报 　　4.1 为了保障安全操作，员工应当向部门主管或安全部门汇报所有不安全的实际操作或事故隐患。 　　4.2 员工如果在公司内发现任何可疑人员，应当立即向保安人员汇报，以便将其驱逐出商场。 　　第十二章 保 密 　　第一条 商业秘密的范围 　　1.1凡在本公司就职而产生的，而获取的文件、资料、稿件、表格等等业务信息，如有关客户名单、合作目的、价格、营业额、营销、员工薪酬，无论是口头、书面的或是电脑文件形式的，无论是客户的或是本公司的均属商业秘密。 　　第二条 保密规则 　　2.1公司员工务必遵守以下规则，否则视具体情况予以违纪处理： 　　所有机密文件必须妥善保管; 　　不得将公司文件用于不属于公司业务之用途; 员工手册范本 篇31 　　水果店员工守则2', 549, NULL, '[\"员工\", \"公司\", \"部门\", \"文件\", \"业务\", \"汇报\", \"应当\", \"通知\", \"立即\", \"合作\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:27', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:27', '0');
INSERT INTO `document_segments` VALUES ('1955803420036001793', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　不得将公司文件用于不属于公司业务之用途; 员工手册范本 篇31 　　水果店员工守则2 　　一、值日生需提前到岗，7：50前卫生打扫完毕，卫生包括室内、卫生间、室外门脸玻璃，柜台由个人负责，保持清洁明亮。 　　二、服从分配、服从管理，不得损毁店面形象，透露店面机密，精神饱满地进入工作状态，不得面带倦意，坐姿、立姿都要大方得体。 　　三、员工本着互尊互爱、齐心协力、吃苦耐劳、诚实本分的精神做好本职工作。 　　四、上班不得迟到早退、旷工;上班时间不得嬉笑、打闹、睡觉而影响本店面形象，迟到30分钟扣50元，30分钟后扣100元，当天未来者按旷工处理，早退人员扣100元，旷工一天扣除三天工资，旷工三天当自动离职处理，请假需提前一天申请，经过经理同意方可请假。 　　五、工作时接听私人电话不得超过1分钟，不许用店面电话打私人电话，如有违反1次罚款20元，下次再犯则罚款50元。 　　六、员工服务态度： 　　(1)热情接待每位顾客(您好!);微笑是每个销售人员的基本表情，面对顾客应表现出热情、真诚、亲切、友好、专业、不准不理不睬。 　　(2)了解各产品性能，向顾客合理的介绍，说话语气要轻。 　　七、员工奖罚规定：', 507, NULL, '[\"员工\", \"顾客\", \"店面\", \"旷工\", \"工作\", \"提前\", \"需\", \"人员\", \"请假\", \"形象\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:27', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:27', '0');
INSERT INTO `document_segments` VALUES ('1955803420094722049', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　(2)了解各产品性能，向顾客合理的介绍，说话语气要轻。 　　七、员工奖罚规定： 　　(1)全勤奖力60元，迟到、早退，每分钟扣罚1元;旷工一天扣罚120元，工作时间不允许请假，请假10分钟罚5元，请假一天扣除当日工资，未经批准按照旷工处理，周六日不得请假。 　　八、卫生区域不清洁扣罚5元一次，卫生未整理干净者扣罚5元一次。 　　九、上班时间接听私人电话不得超过1分钟，违者扣罚5元一次，工作时间不得玩微信、QQ等违者罚10元。 　　十、辞职条件 　　(1)员工合同期满后方可离职，离职将发放所有工资，合同期满后如继续续约者当次奖励100元。 　　(2)如需离职者须提前3个月提呈辞职报告，书写详细理由批准后方可离职，离职只发工资，不发提成。 　　公司宗旨：敏锐观察和自我创新，以时尚品质、温馨、潮流为产品风格，以信誉、创新、完美经营为理念，以包装精美、质量上乘、价格合理、服务优质、信誉良好为追求目标! 员工手册范本 篇32 　　一、工作态度 　　1、按公司及各酒店操作规程，准确及时地完成各项工作。 　　2、工作认真，待客热情，说话和气，谦虚谨慎，举止稳重。', 483, NULL, '[\"工作\", \"员工\", \"扣罚\", \"离职\", \"工资\", \"说话\", \"信誉\", \"元一次\", \"创新\", \"请假\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:27', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:27', '0');
INSERT INTO `document_segments` VALUES ('1955803420140859393', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　2、工作认真，待客热情，说话和气，谦虚谨慎，举止稳重。 　　3、对待顾客的投诉和批评时应冷静倾听，耐心解释，任何情况下都不得与客人争论。 　　4、员工应在规定上班时间的基础上适当提前到达岗位作好准备工作。工作时间不得擅离职守或早退。 　　5、上班时严禁串岗、闲聊、吃零食。禁止在餐厅、厨房、更衣室等公共场所吸烟，不做与本职工作无关的。 　　6、热情待客，站立服务，使用礼貌语言。 　　二、仪表、仪容、仪态及个人卫生 　　1、员工的精神面貌应表情自然，面带微笑，端庄稳重。 　　2、员工的工作衣应随时保持干净、整洁。 　　3、男员工应修面，头发不能过耳和衣领。 　　4、女员工应梳理好头发，使用发夹网罩。 　　5、工作时间内，不剪指甲、抠鼻、剔牙，打哈欠、喷嚏应用手遮掩。 　　6、工作时间内保持安静，禁止大声喧哗。做到说话轻、走路轻、操作轻。 　　三、拾遗 　　1、在任何场所拾到钱或遗留物品应立即上缴主管作好详细的记录。 　　2、拾遗不报将被视为从偷窃处理。 　　四、公司及其所工作酒店财产', 448, NULL, '[\"工作\", \"员工\", \"时间\", \"应\", \"禁止\", \"拾遗\", \"稳重\", \"作好\", \"使用\", \"说话\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:27', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:27', '0');
INSERT INTO `document_segments` VALUES ('1955803420191191042', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　2、拾遗不报将被视为从偷窃处理。 　　四、公司及其所工作酒店财产 　　公司及各个酒店物品（包括发给员工使用的物品）均为公司及各个酒店财产，无论疏忽或有意损坏，当事人都必须酌情赔偿。员工如犯有盗窃行为，我公司将立即予以开除，并视情节轻重交由公安部门处理。 　　五、公司出勤制度 　　一、公司员工必须自觉遵守劳动纪律，按时上下班，不迟到，不早退，工作时间不得擅自离开工作岗位，外出办理业务前，须经本部门负责人同意。 　　1、迟到：在列队或集合后点名开始时未到者记迟到，迟到一次罚款50元并记纪律单一张 　　2、早退：在未通知下班或可以自由安排活动之前离开，不经直接上司批准，在集合点到时不在者既早退，早退一次罚款50元并纪律单一张。 　　3、旷工：月累计两次以上迟到或早退，既算旷工一天。未经直接上司批准没来上班旷工一天，扣除当天工资的三倍，月累计两次或连续旷工两天计自动离职。 　　二、员工必须依照部门主管安排的班次上班，需要变更班次，须先征得部门主管允许。 　　1、病假 　　2、确因某种原因不能上班的员工，应事先请假，如有特殊情况，应设法于当日通知部门主管，并得到许可，否则视为旷工。 　　六、员工宿舍管理制度', 508, NULL, '[\"员工\", \"公司\", \"部门\", \"旷工\", \"早退\", \"迟到\", \"上班\", \"必须\", \"主管\", \"离开\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:27', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:27', '0');
INSERT INTO `document_segments` VALUES ('1955803420241522690', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　六、员工宿舍管理制度 　　一、员工宿舍应轮流负责清扫，保持良好、清洁、整齐的环境，以保证员工在工作之余得到充分的。 　　二、不得在宿舍内酗酒、斗殴、赌博、或从事其他不健康活动，宿舍不得留宿亲友。 　　三、贵重物品应避免携带，违反规定带入室内而致丢失者责任自负。 　　四、就寝后不得影响他人睡眠，如有在外留宿，请事先通知部门主管。由于在外留宿发生何意外，公司拒不负责任。 　　五、室内不得使用或存放危险及违禁物品；员工不得将宿舍转租或借给他人使用，一经发现，立即停止其居住权利。 　　七、公司工资管理制度 　　一、工资结构 　　工资包括：基本工资、岗位工资、业绩工资。 　　二、工资计算方法 　　1、实发工资=应发工资—扣除项目 　　2、业绩工资=应发工资—扣除项目 　　三、辞退离职工资计算 　　1、辞退：公司有权辞退任务不符合公司发展需要的人员，人员辞退后其工资按标准发放，有保证金给予退还。 　　2、自动离职：不按照程序辞工或月累计旷工两次，连续两天旷工按自动离职处理，公司不发房任务补偿、工资和保证金。 　　八、公司奖罚制度 　　一、奖金结构', 476, NULL, '[\"公司\", \"工资\", \"宿舍\", \"留宿\", \"员工\", \"离职\", \"室内\", \"辞退\", \"使用\", \"保证金\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:27', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:27', '0');
INSERT INTO `document_segments` VALUES ('1955803420296048641', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　八、公司奖罚制度 　　一、奖金结构 　　1、模范员工奖金每月由各个项目主管人员依工作敬业态度及考核成绩中，挑选一至两名工作表现优异的.从业人员进行评核（评核内容包括：工作勤奋，能适时完成重大或特殊任务，服务热情，为公司树立良好形象）于每月月初朝会中表扬并颁发100元，以激励员工士气。 　　2、考勤奖勤务满一年以上者，则支付半个月的本薪作为当期绩效奖金勤务半年以上者，奖励300元，以鼓励员工。 　　3、年终奖由各部门主管人员视整年各人勤务的表现，包括工作效率、服务态度、敬业精神、出勤率、突出成绩、贡献度等多项评核，并依据考核成绩核发年终奖。支付一个月的本薪作为嘉奖！ 　　二、员工罚款结构 　　缺勤：经常迟到、早退、旷工、消极怠工，没有完成生产任务或工作任务；罚款100元。 员工手册范本 篇33 　　第一条 为明确公司与员工双方的权利与义务，促进公司各项经营活动正常、健康、有序的开展，本着公司与员工之间互惠互利、平等协商的原则，依据《中华人民共和国劳动法》和公司实际情况制定本手册。 　　第二条 本手册所称员工系与公司建立劳动关系的所有员工。 　　第三条 一般规定', 488, NULL, '[\"员工\", \"公司\", \"工作\", \"勤务\", \"评核\", \"表现\", \"完成\", \"包括\", \"中\", \"主管人员\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:27', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:27', '0');
INSERT INTO `document_segments` VALUES ('1955803420342185985', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　第二条 本手册所称员工系与公司建立劳动关系的所有员工。 　　第三条 一般规定 　　一、公司经营管理者有权依照公司各项现行管理规定，指派或分配员工工作; 　　二、员工对于公司指派或分配的各项工作，均有义务履行，不得无故拒绝; 　　三、凡员工行为违反本《员工手册》的`规定，公司可视该行为情节轻重及对公司利益造成损害的程度给予相应处罚; 　　四、本《员工手册》载明的有关规定适用于公司全体员工。 　　第二章 员工聘用 　　第四条 公司根据发展需要聘用员工，由人力资源部依据实际需求情况编制定岗定编报告和人员聘用方案，呈总经理批准后，负责执行内部调配工作或实施公开招聘。 　　第五条 员工的聘用分首次进公司的招聘和续聘等情形。 　　第六条 公司采取逐层聘用的方式聘用员工，即部门负责人以上员工由总经理决定聘用;部门员工由部门负责人决定聘用。 　　第七条 凡应聘人员有下列情形之一者，公司不予录用或续聘： 　　一、《劳动法》规定不得雇佣者; 　　二、有违法、违纪行为者; 　　三、曾在本公司及相关企业工作，后被开除或未经批准而擅自离职者; 　　四、经审查认定学历和工作履历有故意欺骗行为者; 　　五、不符合公司规定的其他有关条件者。 　　第八条', 520, NULL, '[\"公司\", \"员工\", \"规定\", \"工作\", \"聘用\", \"批准\", \"行为\", \"人员\", \"手册\", \"劳动\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:27', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:27', '0');
INSERT INTO `document_segments` VALUES ('1955803420392517634', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　四、经审查认定学历和工作履历有故意欺骗行为者; 　　五、不符合公司规定的其他有关条件者。 　　第八条 首次进公司的招聘可采取公司自行招聘或委托中介方招聘等方式。自行招聘时公司须组织实施笔试和面试等考核录用程序;委托中介方招聘时，相关择录标准和程序等事项按双方约定执行。 　　第九条 公司对首次签订劳动合同的人员，均实行叁个月的试用期。试用期计入劳动合同年限。试用期间，公司将指定人员帮助新员工尽快了解公司概括，熟悉将从事的业务工作，具体内容主要以本《员工手册》为准。 　　第十条 员工试用期间，如果感到公司实际状况、发展机会与预期有较大差距，或由于其它原因而决定离开，可提出辞职，并按双方签订的《劳动合同书》办理解除劳动合同手续;相应的，如果员工无法达到公司要求，公司将按有关规定解除或终止劳动合同。 　　第十一条 员工试用期满，人力资源部将与试用部门负责人一起对员工进行考核，经有关程序考核合格者，于期满次日起转为正式员工;经考核不合格者，则依法解除劳动合同。 　　第十二条 员工的续聘工作按本《员工手册》和公司相关规章制度的规定执行。 　　第十三条', 478, NULL, '[\"公司\", \"员工\", \"劳动合同\", \"程序\", \"工作\", \"考核\", \"试用\", \"招聘\", \"规定\", \"解除\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:27', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:27', '0');
INSERT INTO `document_segments` VALUES ('1955803420442849282', '1449618464510685185', '1948214946256662529', '1955803393175678978', NULL, '　　第十二条 员工的续聘工作按本《员工手册》和公司相关规章制度的规定执行。 　　第十三条 公司有权依工作需要安排员工的岗位、岗位等级、考核、奖惩、解雇等事项，公司员工应积极给予配合。', 91, NULL, '[\"员工\", \"公司\", \"工作\", \"手册\", \"事项\", \"解雇\", \"岗位\", \"权\", \"应\", \"等级\"]', NULL, NULL, NULL, 1, NULL, NULL, 'waiting', NULL, '2025-08-14 09:27:27', NULL, NULL, NULL, NULL, NULL, NULL, '2025-08-14 09:27:27', '0');

-- ----------------------------
-- Table structure for documents
-- ----------------------------
DROP TABLE IF EXISTS `documents`;
CREATE TABLE `documents`  (
  `id` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT 'uuid()',
  `tenant_id` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL,
  `dataset_id` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `position` int(0) NULL DEFAULT NULL,
  `data_source_type` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL,
  `data_source_info` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL,
  `dataset_process_rule_id` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL,
  `batch` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL,
