-- ----------------------------
-- Table structure for model_provider
-- ----------------------------
DROP TABLE IF EXISTS `model_provider`;
CREATE TABLE `model_provider`  (
  `id` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `tenant_id` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `provider` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `type` varchar(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `declaration` json NULL,
  `created_time` datetime(0) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_time` datetime(0) NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP(0),
  `created_by` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL,
  `updated_by` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL,
  `delete_flag` varchar(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT '0',
  `description` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL,
  `icon` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of model_provider
-- ----------------------------
INSERT INTO `model_provider` VALUES ('1', '1', 'ollama', 'model', '{\"help\": {\"url\": {\"en_US\": \"https://docs.dify.ai/tutorials/model-configuration/ollama\"}, \"title\": {\"en_US\": \"How to integrate with Ollama\", \"zh_Hans\": \"如何集成 Ollama\"}}, \"label\": {\"en_US\": \"Ollama\"}, \"models\": [], \"provider\": \"ollama\", \"svg_icon\": \"icon_ollama\", \"background\": \"#F9FAFB\", \"icon_large\": {\"en_US\": \"https://ollama.com/public/ollama.png\"}, \"icon_small\": {\"en_US\": \"https://ollama.com/public/ollama.png\"}, \"description\": {\"en_US\": \"Ollama\"}, \"configurate_methods\": [\"customizable-model\"], \"supported_model_types\": [\"llm\", \"text-embedding\"], \"model_credential_schema\": {\"model\": {\"label\": {\"en_US\": \"Model Name\", \"zh_Hans\": \"模型名称\"}, \"placeholder\": {\"en_US\": \"Enter your model name\", \"zh_Hans\": \"输入模型名称\"}}, \"credential_form_schemas\": [{\"type\": \"text-input\", \"label\": {\"en_US\": \"Base URL\", \"zh_Hans\": \"基础 URL\"}, \"default\": null, \"options\": [], \"show_on\": [], \"required\": true, \"variable\": \"base_url\", \"max_length\": 0, \"placeholder\": {\"en_US\": \"Base url of Ollama server, e.g. http://192.168.1.100:11434\", \"zh_Hans\": \"Ollama server 的基础 URL，例如 http://192.168.1.100:11434\"}}, {\"type\": \"select\", \"label\": {\"en_US\": \"Completion mode\", \"zh_Hans\": \"模型类型\"}, \"default\": \"chat\", \"options\": [{\"label\": {\"en_US\": \"Completion\", \"zh_Hans\": \"补全\"}, \"value\": \"completion\", \"show_on\": []}, {\"label\": {\"en_US\": \"Chat\", \"zh_Hans\": \"对话\"}, \"value\": \"chat\", \"show_on\": []}], \"show_on\": [{\"value\": \"llm\", \"variable\": \"__model_type\"}], \"required\": true, \"variable\": \"mode\", \"max_length\": 0, \"placeholder\": {\"en_US\": \"Select completion mode\", \"zh_Hans\": \"选择对话类型\"}}, {\"type\": \"text-input\", \"label\": {\"en_US\": \"Model context size\", \"zh_Hans\": \"模型上下文长度\"}, \"default\": \"4096\", \"options\": [], \"show_on\": [], \"required\": true, \"variable\": \"context_size\", \"max_length\": 0, \"placeholder\": {\"en_US\": \"Enter your Model context size\", \"zh_Hans\": \"在此输入您的模型上下文长度\"}}, {\"type\": \"text-input\", \"label\": {\"en_US\": \"Upper bound for max tokens\", \"zh_Hans\": \"最大 token 上限\"}, \"default\": \"4096\", \"options\": [], \"show_on\": [{\"value\": \"llm\", \"variable\": \"__model_type\"}], \"required\": true, \"variable\": \"max_tokens\", \"max_length\": 0, \"placeholder\": null}, {\"type\": \"radio\", \"label\": {\"en_US\": \"Vision support\", \"zh_Hans\": \"是否支持 Vision\"}, \"default\": \"false\", \"options\": [{\"label\": {\"en_US\": \"Yes\", \"zh_Hans\": \"是\"}, \"value\": \"true\", \"show_on\": []}, {\"label\": {\"en_US\": \"No\", \"zh_Hans\": \"否\"}, \"value\": \"false\", \"show_on\": []}], \"show_on\": [{\"value\": \"llm\", \"variable\": \"__model_type\"}], \"required\": false, \"variable\": \"vision_support\", \"max_length\": 0, \"placeholder\": null}, {\"type\": \"radio\", \"label\": {\"en_US\": \"Function call support\", \"zh_Hans\": \"是否支持函数调用\"}, \"default\": \"false\", \"options\": [{\"label\": {\"en_US\": \"Yes\", \"zh_Hans\": \"是\"}, \"value\": \"true\", \"show_on\": []}, {\"label\": {\"en_US\": \"No\", \"zh_Hans\": \"否\"}, \"value\": \"false\", \"show_on\": []}], \"show_on\": [{\"value\": \"llm\", \"variable\": \"__model_type\"}], \"required\": false, \"variable\": \"function_call_support\", \"max_length\": 0, \"placeholder\": null}]}, \"provider_credential_schema\": null}', '2025-07-10 10:37:10', '2025-07-10 15:45:53', NULL, NULL, '0', NULL, NULL);
INSERT INTO `model_provider` VALUES ('2', '1', 'zhipu', 'model', '{\"help\": {\"url\": {\"en_US\": \"https://platform.deepseek.com/api_keys\"}, \"title\": {\"en_US\": \"Get your API Key from deepseek\", \"zh_Hans\": \"从深度求索获取 API Key\"}}, \"label\": {\"en_US\": \"deepseek\", \"zh_Hans\": \"深度求索\"}, \"models\": [{\"label\": {\"en_US\": \"deepseek-chat\", \"zh_Hans\": \"deepseek-chat\"}, \"model\": \"deepseek-chat\", \"pricing\": {\"unit\": \"0.000001\", \"input\": \"2\", \"output\": \"8\", \"currency\": \"RMB\"}, \"features\": [\"agent-thought\", \"tool-call\", \"multi-tool-call\", \"stream-tool-call\"], \"deprecated\": false, \"fetch_from\": \"predefined-model\", \"model_type\": \"llm\", \"parameter_rules\": [{\"max\": 2, \"min\": 0, \"help\": {\"en_US\": \"Control the diversity and randomness of generated results. The smaller the value, the more rigorous it is; the larger the value, the more divergent it is.\", \"zh_Hans\": \"控制生成结果的多样性和随机性。数值越小，越严谨；数值越大，越发散。\"}, \"name\": \"temperature\", \"type\": \"float\", \"label\": {\"en_US\": \"temperature\"}, \"default\": 1, \"options\": [], \"required\": false, \"precision\": 2, \"use_template\": \"temperature\"}, {\"max\": 8192, \"min\": 1, \"help\": {\"en_US\": \"Specifies the upper limit on the length of generated results. If the generated results are truncated, you can increase this parameter.\", \"zh_Hans\": \"指定生成结果长度的上限。如果生成结果截断，可以调大该参数。\"}, \"name\": \"max_tokens\", \"type\": \"int\", \"label\": {\"en_US\": \"max_tokens\"}, \"default\": 4096, \"options\": [], \"required\": false, \"precision\": 0, \"use_template\": \"max_tokens\"}, {\"max\": 1, \"min\": 0.01, \"help\": {\"en_US\": \"Control the randomness of generated results. The smaller the value, the weaker the randomness; the larger the value, the stronger the randomness. Generally speaking, you can adjust one of the two parameters top_p and temperature.\", \"zh_Hans\": \"控制生成结果的随机性。数值越小，随机性越弱；数值越大，随机性越强。一般而言，top_p 和 temperature 两个参数选择一个进行调整即可。\"}, \"name\": \"top_p\", \"type\": \"float\", \"label\": {\"en_US\": \"top_p\"}, \"default\": 1, \"options\": [], \"required\": false, \"precision\": 2, \"use_template\": \"top_p\"}, {\"max\": null, \"min\": null, \"help\": {\"en_US\": \"Whether to return the log probability of the output token. If true, returns the log probability of each output token in the content of message .\", \"zh_Hans\": \"是否返回所输出 token 的对数概率。如果为 true，则在 message 的 content 中返回每个输出 token 的对数概率。\"}, \"name\": \"logprobs\", \"type\": \"boolean\", \"label\": {\"en_US\": \"Logprobs\"}, \"default\": null, \"options\": [], \"required\": false, \"precision\": null, \"use_template\": null}, {\"max\": 20, \"min\": 0, \"help\": {\"en_US\": \"An integer N between 0 and 20, specifying that each output position returns the top N tokens with output probability, and returns the logarithmic probability of these tokens. When specifying this parameter, logprobs must be true.\", \"zh_Hans\": \"一个介于 0 到 20 之间的整数 N，指定每个输出位置返回输出概率 top N 的 token，且返回这些 token 的对数概率。指定此参数时，logprobs 必须为 true。\"}, \"name\": \"top_logprobs\", \"type\": \"int\", \"label\": {\"en_US\": \"Top Logprobs\"}, \"default\": 0, \"options\": [], \"required\": false, \"precision\": null, \"use_template\": null}, {\"max\": 2, \"min\": -2, \"help\": {\"en_US\": \"A number between -2.0 and 2.0. If the value is positive, new tokens are penalized based on their frequency of occurrence in existing text, reducing the likelihood that the model will repeat the same content.\", \"zh_Hans\": \"介于 -2.0 和 2.0 之间的数字。如果该值为正，那么新 token 会根据其在已有文本中的出现频率受到相应的惩罚，降低模型重复相同内容的可能性。\"}, \"name\": \"frequency_penalty\", \"type\": \"float\", \"label\": {\"en_US\": \"frequency_penalty\"}, \"default\": 0, \"options\": [], \"required\": false, \"precision\": 2, \"use_template\": \"frequency_penalty\"}, {\"max\": null, \"min\": null, \"help\": {\"en_US\": \"specifying the format that the model must output\", \"zh_Hans\": \"指定模型必须输出的格式\"}, \"name\": \"response_format\", \"type\": \"string\", \"label\": {\"en_US\": \"Response Format\", \"zh_Hans\": \"回复格式\"}, \"default\": null, \"options\": [\"text\", \"json_object\"], \"required\": false, \"precision\": null, \"use_template\": null}], \"model_properties\": {\"mode\": \"chat\", \"context_size\": 128000}}, {\"label\": {\"en_US\": \"deepseek-coder\", \"zh_Hans\": \"deepseek-coder\"}, \"model\": \"deepseek-coder\", \"pricing\": null, \"features\": [\"agent-thought\", \"tool-call\", \"multi-tool-call\", \"stream-tool-call\"], \"deprecated\": false, \"fetch_from\": \"predefined-model\", \"model_type\": \"llm\", \"parameter_rules\": [{\"max\": 1, \"min\": 0, \"help\": {\"en_US\": \"Controls randomness. Lower temperature results in less random completions. As the temperature approaches zero, the model will become deterministic and repetitive. Higher temperature results in more random completions.\", \"ja_JP\": \"温度はランダム性を制御します。温度が低いほどランダムな完成が少なくなります。温度がゼロに近づくと、モデルは決定論的で繰り返しになります。温度が高いほどランダムな完成が多くなります。\", \"pt_BR\": \"A temperatura controla a aleatoriedade. Menores temperaturas resultam em menos conclusões aleatórias. À medida que a temperatura se aproxima de zero, o modelo se tornará determinístico e repetitivo. Temperaturas mais altas resultam em mais conclusões aleatórias.\", \"zh_Hans\": \"温度控制随机性。较低的温度会导致较少的随机完成。随着温度接近零，模型将变得确定性和重复性。较高的温度会导致更多的随机完成。\"}, \"name\": \"temperature\", \"type\": \"float\", \"label\": {\"en_US\": \"temperature\"}, \"default\": 0.5, \"options\": [], \"required\": false, \"precision\": 2, \"use_template\": \"temperature\"}, {\"max\": 1, \"min\": 0, \"help\": {\"en_US\": \"Controls diversity via nucleus sampling: 0.5 means half of all likelihood-weighted options are considered.\", \"ja_JP\": \"核サンプリングを通じて多様性を制御します：0.5は、すべての可能性加权オプションの半分を考慮します。\", \"pt_BR\": \"Controla a diversidade via amostragem de núcleo: 0.5 significa que metade das opções com maior probabilidade são consideradas.\", \"zh_Hans\": \"通过核心采样控制多样性：0.5表示考虑了一半的所有可能性加权选项。\"}, \"name\": \"top_p\", \"type\": \"float\", \"label\": {\"en_US\": \"top_p\"}, \"default\": 1, \"options\": [], \"required\": false, \"precision\": 2, \"use_template\": \"top_p\"}, {\"max\": 4096, \"min\": 1, \"help\": {\"en_US\": \"Specifies the upper limit on the length of generated results. If the generated results are truncated, you can increase this parameter.\", \"ja_JP\": \"生成結果の長さの上限を指定します。生成結果が切り捨てられた場合は、このパラメータを大きくすることができます。\", \"pt_BR\": \"Especifica o limite superior para o comprimento dos resultados gerados. Se os resultados gerados forem truncados, você pode aumentar este parâmetro.\", \"zh_Hans\": \"指定生成结果长度的上限。如果生成结果截断，可以调大该参数。\"}, \"name\": \"max_tokens\", \"type\": \"int\", \"label\": {\"en_US\": \"max_tokens\"}, \"default\": 1024, \"options\": [], \"required\": false, \"precision\": 0, \"use_template\": \"max_tokens\"}], \"model_properties\": {\"mode\": \"chat\", \"context_size\": 128000}}, {\"label\": {\"en_US\": \"deepseek-reasoner\", \"zh_Hans\": \"deepseek-reasoner\"}, \"model\": \"deepseek-reasoner\", \"pricing\": {\"unit\": \"0.000001\", \"input\": \"4\", \"output\": \"16\", \"currency\": \"RMB\"}, \"features\": [\"agent-thought\"], \"deprecated\": false, \"fetch_from\": \"predefined-model\", \"model_type\": \"llm\", \"parameter_rules\": [{\"max\": 8192, \"min\": 1, \"help\": {\"en_US\": \"Specifies the upper limit on the length of generated results. If the generated results are truncated, you can increase this parameter.\", \"ja_JP\": \"生成結果の長さの上限を指定します。生成結果が切り捨てられた場合は、このパラメータを大きくすることができます。\", \"pt_BR\": \"Especifica o limite superior para o comprimento dos resultados gerados. Se os resultados gerados forem truncados, você pode aumentar este parâmetro.\", \"zh_Hans\": \"指定生成结果长度的上限。如果生成结果截断，可以调大该参数。\"}, \"name\": \"max_tokens\", \"type\": \"int\", \"label\": {\"en_US\": \"max_tokens\"}, \"default\": 4096, \"options\": [], \"required\": false, \"precision\": 0, \"use_template\": \"max_tokens\"}], \"model_properties\": {\"mode\": \"chat\", \"context_size\": 128000}}], \"position\": {\"llm\": [\"deepseek-chat\", \"deepseek-coder\", \"deepseek-reasoner\"]}, \"provider\": \"deepseek\", \"svg_icon\": \"icon_zhipu\", \"background\": \"#c0cdff\", \"icon_large\": {\"en_US\": \"49323fc47c82d3bf400280689f9ffa17708cfe465c7e1f3bbfb24f2a42ec0e2c.svg\"}, \"icon_small\": {\"en_US\": \"69f80e7dfe36e036321767f69cad4755fe162cf581b206a8290dce0629d2e4f6.svg\"}, \"description\": {\"en_US\": \"Models provided by deepseek, such as deepseek-reasoner、deepseek-chat、deepseek-coder.\", \"zh_Hans\": \"深度求索提供的模型，例如 deepseek-reasoner、deepseek-chat、deepseek-coder 。\"}, \"configurate_methods\": [\"predefined-model\"], \"supported_model_types\": [\"llm\"], \"model_credential_schema\": null, \"provider_credential_schema\": {\"credential_form_schemas\": [{\"type\": \"secret-input\", \"label\": {\"en_US\": \"API Key\"}, \"default\": null, \"options\": [], \"show_on\": [], \"required\": true, \"variable\": \"api_key\", \"max_length\": 0, \"placeholder\": {\"en_US\": \"Enter your API Key\", \"zh_Hans\": \"在此输入您的 API Key\"}}, {\"type\": \"text-input\", \"label\": {\"en_US\": \"Custom API endpoint URL\", \"zh_Hans\": \"自定义 API endpoint 地址\"}, \"default\": null, \"options\": [], \"show_on\": [], \"required\": false, \"variable\": \"endpoint_url\", \"max_length\": 0, \"placeholder\": {\"en_US\": \"Base URL, e.g. https://api.deepseek.com/v1 or https://api.deepseek.com\", \"zh_Hans\": \"Base URL, e.g. https://api.deepseek.com/v1 or https://api.deepseek.com\"}}]}}', '2025-07-10 10:37:10', '2025-07-10 15:51:11', NULL, NULL, '0', '智普AI', NULL);
