INSERT INTO `workflows` VALUES ('1962819962284072961', '22', '1962819962284072961', 'chat', 'draft', '{\"edges\": [{\"id\": \"e1-llm_757616c9a\", \"data\": {}, \"type\": \"custom\", \"label\": \"\", \"style\": {\"stroke\": \"#6366f1\", \"strokeWidth\": 2}, \"events\": {}, \"source\": \"1\", \"target\": \"llm_757616c9a\", \"sourceX\": 399.9998258331413, \"sourceY\": 158.64059707345518, \"targetX\": 475.9999878951122, \"targetY\": 161.68745269074054, \"animated\": true, \"sourceNode\": {\"id\": \"1\", \"data\": {\"id\": \"1\", \"mode\": \"WORKFLOW\", \"label\": \"开始\", \"output\": [{\"name\": \"query\", \"type\": \"string\", \"label\": \"用户查询\", \"value\": \"\"}], \"triggers\": {\"id\": \"1\", \"name\": \"email\", \"extId\": \"1\", \"label\": {\"en_US\": \"Email Address\", \"zh_Hans\": \"邮箱触发器\"}, \"certId\": \"1\", \"supportId\": \"1\"}, \"variables\": [{\"id\": 1756889905599, \"type\": \"text-input\", \"label\": \"用户名\", \"required\": true, \"variable\": \"userName\", \"maxLength\": \"40\", \"selectOptions\": []}], \"description\": \"工作流开始节点\", \"structOutput\": {\"data\": [{\"id\": \"0\", \"name\": \"triggers\", \"type\": \"object\", \"value\": \"\", \"hidden\": true, \"children\": [{\"name\": \"from\", \"type\": \"string\", \"description\": \"来自\"}, {\"name\": \"recipient\", \"type\": \"string\", \"description\": \"收件人\"}, {\"name\": \"subject\", \"type\": \"string\", \"description\": \"主题\"}, {\"name\": \"sentDate\", \"type\": \"datetime\", \"description\": \"发送日期\"}, {\"name\": \"content\", \"type\": \"string\", \"description\": \"文本内容\"}, {\"name\": \"contentHtml\", \"type\": \"string\", \"description\": \"Html内容\"}], \"description\": \"触发器输出\"}], \"schema\": {}}, \"sysVariables\": [{\"name\": \"sys.query\", \"type\": \"String\"}, {\"name\": \"sys.files\", \"type\": \"Array[File]\"}, {\"name\": \"sys.dialogue_count\", \"type\": \"Number\"}, {\"name\": \"sys.conversation_id\", \"type\": \"String\"}, {\"name\": \"sys.user_id\", \"type\": \"String\"}, {\"name\": \"sys.app_id\", \"type\": \"String\"}, {\"name\": \"sys.workflow_id\", \"type\": \"String\"}, {\"name\": \"sys.workflow_run_id\", \"type\": \"String\"}], \"triggersEnabled\": true}, \"type\": \"start\", \"events\": {}, \"dragging\": false, \"isParent\": false, \"position\": {\"x\": 96, \"y\": 96}, \"resizing\": false, \"selected\": true, \"dimensions\": {\"width\": 300, \"height\": 125}, \"initialized\": false, \"handleBounds\": {\"source\": [{\"x\": 291.99982583314124, \"y\": 56.64059707345517, \"id\": null, \"type\": \"source\", \"width\": 12, \"height\": 12, \"nodeId\": \"1\", \"position\": \"right\"}], \"target\": null}, \"computedPosition\": {\"x\": 96, \"y\": 96, \"z\": 1000}}, \"targetNode\": {\"id\": \"llm_757616c9a\", \"data\": {\"id\": \"llm_757616c9a\", \"label\": \"LLM\", \"model\": {\"mode\": \"chat\", \"modeId\": \"\", \"modelId\": \"1\", \"provider\": \"ollama\", \"modelName\": \"qwen2.5:7b\", \"completionParams\": {}}, \"memory\": {\"window\": {\"size\": 10, \"user\": \"0\", \"enabled\": false, \"assistant\": \"0\"}, \"role_prefix\": {\"user\": \"\", \"assistant\": \"\"}, \"query_prompt_template\": \"{{#sys.query#}}\"}, \"output\": [{\"name\": \"text\", \"type\": \"string\", \"label\": \"生成内容\", \"value\": \"\"}], \"prompt\": \"\", \"max_tokens\": 1000, \"userPrompt\": {\"id\": \"user_prompt_template\", \"role\": \"user\", \"text\": \"发件人：{{#1.triggers.from#}}\\n邮件内容：{{#1.triggers.content#}}\"}, \"description\": \"大语言模型节点\", \"temperature\": 0.7, \"structOutput\": {\"data\": [{\"id\": \"0\", \"name\": \"struct\", \"type\": \"object\", \"value\": \"\", \"hidden\": true, \"children\": [], \"description\": \"结构化内容\"}], \"schema\": {}}, \"systemPrompt\": {\"id\": \"prompt_template\", \"role\": \"system\", \"text\": \"**角色定位**：你是电商平台的“邮件接收与客服处理AI机器人”，需聚焦客户咨询、售后投诉、订单问题三类核心邮件，实现“快速响应+问题归类+工单生成”的闭环处理。\\n\\n**核心任务**：\\n1. 邮件内容精准识别：优先抓取邮件中与“订单号、商品ID、问题类型（退款/换货/物流/质量）、客户诉求、联系方式”相关的信息，忽略无关寒暄内容；\\n2. 问题分类与优先级排序：\\n   - 高优先级（1小时内响应）：含“订单拦截”“物流丢失”“商品破损拒签”“退款超72小时未到账”关键词的邮件；\\n   - 中优先级（4小时内响应）：含“换货申请”“尺寸不符”“赠品缺失”关键词的邮件；\\n   - 低优先级（24小时内响应）：含“商品使用咨询”“售后政策疑问”“发票补开”关键词的邮件；\\n3. 结构化工单生成：对每封有效邮件，生成标准客服工单（格式如下），并同步至电商售后系统：\\n   - 工单编号：自动生成（规则：日期+随机6位数字，如20240520123456）；\\n   - 客户信息：姓名（邮件署名）、手机号（正文提取/无则标注“需补充”）、邮箱（发件人地址）；\\n   - 订单信息：订单号、商品ID、购买时间（正文无则标注“需查询系统”）；\\n   - 问题描述：提炼核心问题（如“订单123456购买的A商品，收到后发现按键失灵，申请换货”）；\\n   - 客户诉求：明确需求（如“要求3天内寄出换货商品，运费由商家承担”）；\\n   - 附件情况：附件名称+用途（如“商品破损照片.jpg（证明商品问题）”）；\\n   - 优先级：按上述规则标注（高/中/低）；\\n4. 针对性自动回复：根据问题类型生成差异化回复，需包含“工单编号”以便客户查询进度：\\n   - 高优先级回复示例：“尊敬的客户，您好！已收到您关于订单【123456】的物流丢失反馈，工单编号【20240520123456】，我们将在1小时内联系物流公司核实，并同步您处理方案，感谢您的耐心等待！”\\n   - 中优先级回复示例：“尊敬的客户，您好！已收到您关于订单【123456】的换货申请，工单编号【20240520123456】，我们将在4小时内审核您的申请，审核通过后会发送换货地址，请注意查收！”\\n\\n**约束条件**：\\n- 回复中必须包含“工单编号”和“响应时限”，避免客户重复咨询；\\n- 若邮件未提供订单号，需在回复中引导客户补充（如“为更快处理您的问题，请回复本邮件提供对应的订单编号，感谢配合！”）；\\n- 涉及“退款金额”“赔偿诉求”的邮件，需在工单中特别标注“需财务部门协同”，并暂不承诺具体金额（回复中用“将根据平台规则与您协商解决方案”替代）。\"}, \"structOutputEnabled\": false}, \"type\": \"llm\", \"events\": {}, \"dragging\": false, \"isParent\": false, \"position\": {\"x\": 480, \"y\": 80}, \"resizing\": false, \"selected\": false, \"dimensions\": {\"width\": 300, \"height\": 163}, \"initialized\": false, \"handleBounds\": {\"source\": [{\"x\": 291.99982583314124, \"y\": 75.68745269074054, \"id\": null, \"type\": \"source\", \"width\": 12, \"height\": 12, \"nodeId\": \"llm_757616c9a\", \"position\": \"right\"}], \"target\": [{\"x\": -4.000012104887797, \"y\": 75.68745269074054, \"id\": null, \"type\": \"target\", \"width\": 12, \"height\": 12, \"nodeId\": \"llm_757616c9a\", \"position\": \"left\"}]}, \"computedPosition\": {\"x\": 480, \"y\": 80, \"z\": 0}}, \"sourceHandle\": null, \"targetHandle\": null}, {\"id\": \"ellm_757616c9a-end_765204hmo\", \"data\": {}, \"type\": \"custom\", \"label\": \"\", \"style\": {\"stroke\": \"#6366f1\", \"strokeWidth\": 2}, \"events\": {}, \"source\": \"llm_757616c9a\", \"target\": \"end_765204hmo\", \"sourceX\": 783.9998258331412, \"sourceY\": 161.68745269074054, \"targetX