-- View structure for v_u_user
-- ----------------------------
DROP VIEW IF EXISTS `v_u_user`;
CREATE ALGORITHM = UNDEFINED DEFINER = `root`@`%` SQL SECURITY DEFINER VIEW `v_u_user` AS select `u_user`.`id` AS `id`,`u_user`.`username` AS `username`,`u_user`.`mobile` AS `mobile`,`u_user`.`nick_name` AS `nick_name`,`u_user`.`org_Id` AS `org_id`,'user' AS `user_type` from `u_user` where (`u_user`.`DELETE_FLAG` = '0') union all select `u_user_admin`.`id` AS `id`,`u_user_admin`.`username` AS `username`,`u_user_admin`.`mobile` AS `mobile`,`u_user_admin`.`nick_name` AS `nick_name`,`u_user_admin`.`org_Id` AS `org_id`,'admin' AS `user_type` from `u_user_admin` where (`u_user_admin`.`DELETE_FLAG` = '0');

